const e="65 chapters",t=[{id:"chapter-35",number:35,title:"V/A-(으)ㄴ/는데 · V/A-잖아요",goal:"Open a sensitive topic with 사실은 and sentence-final -는데요.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 사실은~",cards:[{kind:"guess",word:{ko:"사실은",romanization:"sasireun",en:"actually; to be honest",pos:"adverb",nuance:"사실은 does not mean every sentence is a dramatic confession. It often simply prepares the listener for background or a correction."},sentence:{ko:"사실은 오늘 자료가 아직 안 끝났는데요.",en:"Actually, today's materials are not finished yet."},target:"사실은",options:["so; what you mean is","actually; to be honest","softly; gently; smoothly"],note:"Opens a sensitive update softly."},{kind:"guess",word:{ko:"그런데",romanization:"geureonde",en:"but; by the way",pos:"adverb",nuance:"그런데 (spoken: 근데) is the soft, all-purpose 'but' that also works as 'by the way' to glide into a new topic — this double life surprises English speakers most. As contrast it is far gentler than 하지만 or 그렇지만; it doesn't slam two ideas together, it just notes that something slightly different follows. As a topic-changer it carries no contrast at all: 그런데, 우리 언제 만나요? simply means 'So/Anyway, when shall we meet?'. It is closely tied to the mid-sentence ending -는데, which sets background before a turn (비싼데 살까? = it's pricey, but shall I buy it?). The everyday pitfall is over-translating it as a strong 'however'; if you mean a firm, contrastive 'however', reach for 하지만. And don't write the long form in chat — Koreans type 근데."},sentence:{ko:"알겠어요. 그런데 발표 전에 자료는 보내 줄 수 있어요?",en:"I understand. But can you send the materials before the presentation?"},target:"그런데",options:["but; by the way","so; what you mean is","softly; gently; smoothly"],note:"Shifts from accepting the situation to asking for the next action."},{kind:"guess",word:{ko:"근데",romanization:"geunde",en:"but; by the way (casual)",pos:"adverb",nuance:"근데 is common in speech, but it can sound too casual in a presentation, email, or formal announcement."},sentence:{ko:"근데 그건 조금 어려운데요.",en:"But that is a little difficult, though."},target:"근데",options:["so; what you mean is","softly; gently; smoothly","but; by the way (casual)"],note:"Casual version of 그런데 for spoken conversation."},{kind:"guess",word:{ko:"그러니까",romanization:"geureonikka",en:"so; what you mean is",pos:"adverb",nuance:"그러니까 means 'so / that's why' and presents what follows as the reason-driven result of what came before. It comes from 그렇다 + -(으)니까 ('because it is so'), and that -니까 root is the key to its flavor: -니까 is the 'because' that naturally leads into commands, requests, and urging, which is exactly why 그러니까 pairs so well with advice (일찍 자요) and 'I-told-you-so' lines. This is the sharp dividing line from near-synonym 그래서: 그래서 (from 그렇다 + -아서) merely REPORTS a result neutrally ('so, as a result'), and crucially 그래서 cannot head a command, while 그러니까 actively REASONS and PERSUADES and happily does. Beyond logic, 그러니까 is a heavy conversational filler — 그러니까 내 말이 means 'exactly, that's my point!' (strong agreement), and a trailing 그러니까... works like English 'I mean...' when you restate yourself. English speakers who treat it as a plain synonym of 그래서 miss both the urging nuance and these idiomatic uses."},sentence:{ko:"그러니까 먼저 회의를 시작해도 된다는 말이죠?",en:"So you mean we can start the meeting first, right?"},target:"그러니까",options:["so; what you mean is","actually; to be honest","but; by the way"],note:"Checks the implied meaning before moving on."},{kind:"guess",word:{ko:"잖아요",romanization:"janhayo",en:"you know; as you know",pos:"ending",nuance:"잖아요 is for shared information. For new background, use -거든요 instead."},sentence:{ko:"회의 시간이 짧잖아요.",en:"The meeting time is short, you know."},target:"잖아요",options:["you know; as you know","you see; the thing is","though; soft trailing ending"],note:"Use when the listener already knows the reason."},{kind:"guess",word:{ko:"거든요",romanization:"geodeunyo",en:"you see; the thing is",pos:"ending",nuance:"거든요 gives new background. It is softer than just dropping a reason, but it can sound defensive if the tone is too clipped."},sentence:{ko:"어제 갑자기 일이 생겼거든요.",en:"Something suddenly came up yesterday, you see."},target:"거든요",options:["you see; the thing is","you know; as you know","though; soft trailing ending"],note:"Use when the listener does not know the background yet."},{kind:"payoff",line:{speaker:"민서",ko:"사실은 오늘 자료가 아직 다 안 끝났는데요.",en:"Actually, today's materials are not finished yet."},hl:"사실은"}],canDo:"Lead with background before my real point using -(으)ㄴ/는데 (어제 못 왔는데...)",id:"chapter-35-b1",chapterId:"chapter-35",index:0},{kind:"pattern",title:"문법 Grammar · V/A-(으)ㄴ/는데",cards:[{kind:"hunt",name:"V/A-(으)ㄴ/는데",sub:"Giving Background Before Your Point",lines:[{tokens:[{pre:"시간이",mid:"",post:"",hit:!1},{pre:"없",mid:"는데",post:"",hit:!0},{pre:"택시",mid:"",post:"",hit:!1},{pre:"탈까요?",mid:"",post:"",hit:!1}],ko:"시간이 없는데 택시 탈까요?",en:"We don't have time, so should we take a taxi?",romanization:"sigani eomneunde taeksi talkkayo?"},{tokens:[{pre:"지금",mid:"",post:"",hit:!1},{pre:"밥",mid:"",post:"",hit:!1},{pre:"먹",mid:"는데",post:"",hit:!0},{pre:"이따가",mid:"",post:"",hit:!1},{pre:"전화할게요.",mid:"",post:"",hit:!1}],ko:"지금 밥 먹는데 이따가 전화할게요.",en:"I'm eating right now, so I'll call you later.",romanization:"jigeum bap meongneunde ittaga jeonhwahalgeyo."}],rule:{name:"V/A-(으)ㄴ/는데",rows:[{when:"Action verb stem",add:"-는데",ex:"먹다 → 먹는데, 가다 → 가는데"},{when:"Adjective stem ending in a vowel/ㄹ",add:"-ㄴ데",ex:"바쁘다 → 바쁜데, 멀다 → 먼데 (ㄹ drops)"},{when:"Adjective stem ending in a consonant",add:"-은데",ex:"작다 → 작은데, 좋다 → 좋은데"},{when:"Noun + 이다 / past tense",add:"인데 / -았/었는데",ex:"학생이다 → 학생인데, 먹다 → 먹었는데"}]},more:{func:'Use -(으)ㄴ/는데 to give a piece of background first, then say what you really mean (a question, a suggestion, or a request) in the next clause. It loosely links two ideas, a bit like English "so..." or "and...".',keyPoint:{label:"-는데 vs. -아서/어서",body:"-아서/어서 ties a clause as a tight cause ('because A, B'). -(으)ㄴ/는데 just sets the scene ('A, and now...') and feels softer. Only -는데 can lead naturally into a -ㄹ까요? or -ㄹ래요? question. The full contrast use of -는데 comes later."},pronunciation:"는데 sounds like [는데] with no change, but after a ㄷ/ㅅ/ㅈ-final stem like 받다, 받는데 becomes [반는데] (the ㄷ turns into ㄴ before 는)."}}],canDo:"Lead with background before my real point using -(으)ㄴ/는데 (어제 못 왔는데...)",id:"chapter-35-b2",chapterId:"chapter-35",index:1},{kind:"words",title:"단어 Words 2 · 는데요~",cards:[{kind:"guess",word:{ko:"는데요",romanization:"neundeyo",en:"though; soft trailing ending",pos:"ending",nuance:"는데요 is not only 'but'. It often sets up background and hands the next move to the listener."},sentence:{ko:"자료가 아직 안 끝났는데요.",en:"The materials are not finished yet, though."},target:"는데요",options:["you know; as you know","though; soft trailing ending","you see; the thing is"],note:"Leaves space for the listener to respond."},{kind:"guess",word:{ko:"자료",romanization:"jaryo",en:"materials; data; documents",pos:"noun",nuance:"자료 can mean data, but in daily work and study talk it often means the file, handout, or slide deck someone needs."},sentence:{ko:"회의 전에 자료를 보내 줄게요.",en:"I will send the materials before the meeting."},target:"자료",options:["the other person; conversation partner","materials; data; documents","atmosphere; mood"],note:"The actual file, handout, slide deck, or reference material."},{kind:"guess",word:{ko:"배경",romanization:"baegyeong",en:"background; context",pos:"noun",nuance:"배경 is broader than 이유. 이유 is the reason; 배경 is the surrounding context that makes the reason understandable."},sentence:{ko:"제가 먼저 배경을 설명할게요.",en:"I will explain the background first."},target:"배경",options:["background; context","the other person; conversation partner","atmosphere; mood"],note:"Context that helps the listener understand the situation."},{kind:"guess",word:{ko:"상대방",romanization:"sangdaebang",en:"the other person; conversation partner",pos:"noun",nuance:"상대방 is neutral. It is not necessarily an opponent; it can simply mean the other person in the interaction."},sentence:{ko:"상대방이 모르는 내용이면 거든요가 더 자연스러워요.",en:"If the other person does not know it, 거든요 is more natural."},target:"상대방",options:["materials; data; documents","background; context","the other person; conversation partner"],note:"The listener's knowledge decides the marker."},{kind:"guess",word:{ko:"부드럽게",romanization:"budeureopge",en:"softly; gently; smoothly",pos:"adverb",nuance:"부드럽게 is about manner or tone. It does not automatically make the content polite if the sentence itself is too direct."},sentence:{ko:"그 의견에는 부드럽게 반대하는 게 좋아요.",en:"It is better to disagree with that opinion gently."},target:"부드럽게",options:["actually; to be honest","softly; gently; smoothly","but; by the way"],note:"Names the tone this chapter is practicing."},{kind:"guess",word:{ko:"말을 꺼내다",romanization:"mareul kkeonaeda",en:"to bring up a topic",pos:"phrase",nuance:"말을 꺼내다 is about starting a topic, not physically taking words out. It often implies a little hesitation or tact."},sentence:{ko:"자료가 늦어진 이야기는 제가 먼저 말을 꺼낼게요.",en:"I will bring up the delayed materials first."},target:"말을 꺼낼",options:["actually; to be honest","to bring up a topic","but; by the way"],note:"말 means words or speech here."},{kind:"payoff",line:{speaker:"민서",ko:"사실은 오늘 자료가 아직 다 안 끝났는데요.",en:"Actually, today's materials are not finished yet."},hl:"는데요"}],canDo:"Remind someone of something we both know with -잖아요 (시험이 있잖아요)",id:"chapter-35-b3",chapterId:"chapter-35",index:2},{kind:"pattern",title:"문법 Grammar · V/A-잖아요",cards:[{kind:"hunt",name:"V/A-잖아요",sub:"Reminding Someone of What You Both Know",lines:[{tokens:[{pre:"그",mid:"",post:"",hit:!1},{pre:"식당은",mid:"",post:"",hit:!1},{pre:"비싸",mid:"잖아요",post:".",hit:!0},{pre:"다른",mid:"",post:"",hit:!1},{pre:"데",mid:"",post:"",hit:!1},{pre:"가요.",mid:"",post:"",hit:!1}],ko:"그 식당은 비싸잖아요. 다른 데 가요.",en:"That restaurant is expensive, you know. Let's go somewhere else.",romanization:"geu sikdangeun bissajanayo. dareun de gayo."},{tokens:[{pre:"오늘",mid:"",post:"",hit:!1},{pre:"일요일이",mid:"잖아요",post:".",hit:!0},{pre:"학교",mid:"",post:"",hit:!1},{pre:"안",mid:"",post:"",hit:!1},{pre:"가요.",mid:"",post:"",hit:!1}],ko:"오늘 일요일이잖아요. 학교 안 가요.",en:"It's Sunday today, remember? We don't have school.",romanization:"oneul iryoirijanayo. hakgyo an gayo."}],rule:{name:"V/A-잖아요",rows:[{when:"Any verb/adjective stem (present)",add:"-잖아요",ex:"비싸다 → 비싸잖아요, 가다 → 가잖아요"},{when:"Past tense",add:"-았/었잖아요",ex:"먹다 → 먹었잖아요, 보다 → 봤잖아요"},{when:"Noun + 이다",add:"-(이)잖아요",ex:"일요일이다 → 일요일이잖아요, 친구다 → 친구잖아요"},{when:"Casual (반말)",add:"-잖아",ex:"비싸잖아, 먹었잖아"}]},more:{func:'Use -잖아요 to remind the listener of something you both already know, or to point out something obvious as your reason. It carries the feeling of "you know..." or "remember...".',keyPoint:{label:"-잖아요 vs. -거든요",body:"-잖아요 points to OLD information the listener already knows ('you know that...'). -거든요 gives NEW information they don't know yet. Using -잖아요 for brand-new facts sounds odd, like 'you should have known this already'."},pronunciation:"잖아요 links across the syllable and sounds like [자나요], with the ㅈ and ㅇ flowing together. Don't break it into [잗-아요]."}}],canDo:"Remind someone of something we both know with -잖아요 (시험이 있잖아요)",id:"chapter-35-b4",chapterId:"chapter-35",index:3},{kind:"words",title:"단어 Words 3 · 설명하다~",cards:[{kind:"guess",word:{ko:"설명하다",romanization:"seolmyeonghada",en:"to explain",pos:"verb",nuance:"설명하다 is 說明(설명)하다, hanja 說 'speak' + 明 'bright/clear', so it literally means to 'speak something into clarity' — you talk about a thing so the listener understands it. The dividing line against 설득하다 and 말하다 matters: 설명하다 is to make something UNDERSTOOD (neutral, informational), 설득하다 is to PERSUADE (change someone's mind), and 말하다 is just to 'say/tell' without the goal of clarifying. So '설명해 주세요' = 'help me understand,' which is far more specific than '말해 주세요' = 'just tell me.' The thing explained takes 을/를 (이유를 설명하다), and for a broad topic Koreans add -에 대해(서): 그 사건에 대해 설명했어요. Natural adverbs are 자세히 (in detail), 쉽게 (simply), 간단히 (briefly). The English-speaker pitfall is the construction 'explain me' / 'explain to me' — Korean attaches the listener with 에게/한테, not the object slot, and very often just uses 설명해 주다 (explain as a favor) to imply the listener. It is a regular 하다 verb: 설명 + 해요, negating as 설명 안 해요 / 설명 못 해요."},sentence:{ko:"제가 배경을 설명할게요.",en:"I will explain the background."},target:"설명할",options:["to agree","to oppose; to disagree","to explain"],note:"A practical verb for giving context."},{kind:"guess",word:{ko:"동의하다",romanization:"donguihada",en:"to agree",pos:"verb",nuance:"동의하다 is 同意(동의, 'same-meaning/intent') + 하다 — literally to be of the same mind, i.e. to agree with an opinion or consent to terms. Its key grammar point is the particle 에: you agree 'to/with' something, so 의견에 동의하다, 약관에 동의하다 — never 을/를. Contrast it with 찬성하다 (贊成, 'approve/support'), which is voting in favor of a proposal or course of action ('그 계획에 찬성해요'), a public stance, whereas 동의하다 is sharing a viewpoint or giving consent; you can 동의하다 that a problem exists yet not 찬성하다 the proposed solution. Also contrast 인정하다 (concede a truth) — agreeing is positive alignment, acknowledging is conceding. As a 하다 verb: 동의해요 / 동의했어요. The English-speaker pitfall is twofold: the particle (don't say 의견을 동의해요 — use 에), and the structure 'I agree that...', which in Korean is ~다는 것에 동의하다 or simply ~다고 생각해요; a bare 'I agree' in casual reply is more often 맞아요 ('that's right') or 그러게요, with 동의하다 sounding a touch formal."},sentence:{ko:"저도 그 의견에 동의해요.",en:"I agree with that opinion too."},target:"동의해",options:["to agree","to explain","actually; to be honest"],note:"Pairs with 의견 and polite discussion."},{kind:"guess",word:{ko:"반대하다",romanization:"bandaehada",en:"to oppose; to disagree",pos:"verb",nuance:"반대하다 means to oppose, object to, or be against something (反 'reverse/anti' + 對 'face/oppose', literally 'to face in the opposite direction'). The single most important thing for intermediate learners is the PARTICLE: the thing you oppose takes 에, never 을/를 — 의견에 반대하다, 계획에 반대하다. English 'oppose X' treats X as a direct object, so learners overwhelmingly write 의견을 반대해요, which is wrong. As a 하다 verb it contracts to 반대해요. Its clean antonym is 찬성하다 (to be in favor), which shares the same 에 frame. Keep it apart from 거부하다 (to refuse): 반대하다 is taking a stance against an idea in discussion, while 거부하다 is actively turning down a concrete request or offer."},sentence:{ko:"그 의견에는 조금 반대하는데요.",en:"I disagree with that opinion a little, though."},target:"반대하",options:["to explain","actually; to be honest","to oppose; to disagree"],note:"Use -는데요 to make disagreement less abrupt."},{kind:"guess",word:{ko:"분위기",romanization:"bunwigi",en:"atmosphere; mood",pos:"noun",nuance:"분위기 (雰圍氣, 雰 'mist/vapor' + 圍 'surround' + 氣 'air/energy') is literally 'the air that surrounds you' — the collective mood of a place, gathering, or moment. The sharp contrast is 분위기 vs 기분: 분위기 is the SHARED vibe in the room (회식 분위기가 좋다), while 기분 is one person's INNER feeling (제 기분이 좋다 'I'm in a good mood'). Mixing them is the classic error: 'I'm in a good mood' is 기분이 좋아요, not 분위기가 좋아요 (which describes the room, not you). Habitual partners: 분위기가 좋다/편안하다/어색하다, 분위기를 띄우다/바꾸다, 분위기가 가라앉다, 분위기를 깨다 ('kill the mood'). 분위기 있다 colloquially means 'has a classy/romantic ambiance.' The English-speaker pitfall, beyond 기분 confusion, is the particle: 분위기를 좋다 ✗ → 분위기가 좋다 ✓."},sentence:{ko:"그렇게 말하면 분위기가 조금 딱딱해져요.",en:"If you say it like that, the mood becomes a little stiff."},target:"분위기",options:["materials; data; documents","atmosphere; mood","background; context"],note:"Discourse markers affect the mood of a conversation."},{kind:"guess",word:{ko:"상황",romanization:"sanghwang",en:"situation; circumstances",pos:"noun",nuance:"상황 (狀況, '狀 condition/form + 況 circumstances' — the configuration of circumstances) describes the overall set of conditions surrounding a moment or event, broader than a single 경우 (a specific case or instance — 이런 경우 = 'in this one case', vs 이런 상황 = 'in this whole situation'). The reflexive phrase 상황에 따라(서) 다르다 ('it depends on the situation') is one of the most useful hedges in Korean, and 이런/그런 상황에서 sets up advice or reactions. Register is neutral. Two pitfalls: keep 상황 (the circumstances around an event) distinct from 상태 (狀態, the state/condition of a single thing or body — 건강 상태 'health condition', 배터리 상태 'battery state'); you describe a person's mood with a 상태, but the events around them with a 상황. And use 에 따라 (not 으로) for 'depending on': 상황에 따라, never 상황으로."},sentence:{ko:"상황을 먼저 설명하면 상대방이 이해하기 쉬워요.",en:"If you explain the situation first, it is easier for the other person to understand."},target:"상황",options:["materials; data; documents","the other person; conversation partner","situation; circumstances"],note:"The larger situation tells you which marker fits."},{kind:"guess",word:{ko:"의견",romanization:"uigyeon",en:"opinion",pos:"noun",nuance:"의견 is Sino-Korean (意見, 意 'mind/intention' + 見 'view/seeing'), literally 'how your mind sees something' — a considered position or judgment you can defend, usually about a topic, plan, or issue. The crucial contrast is with 생각: 생각 is the broad word for any 'thought' that crosses your mind, while 의견 is specifically a stance offered for discussion or evaluation, so a meeting asks for 의견 (positions), not just 생각 (musings). It is register-neutral and very common in school and workplace settings; the polite request 의견을 여쭤봐도 될까요? raises it a notch. Natural collocations: 의견을 말하다/내다/제시하다 (state/put forward), 의견이 다르다/같다 (disagree/agree), 의견을 모으다 (gather opinions), 반대 의견 (an opposing view). The English-speaker pitfall is reaching for 의견 every time you'd say 'I think' — 'I think it's good' is 좋은 것 같아요 or 좋다고 생각해요, NOT 좋은 의견이에요; 의견 is the opinion itself as a thing, not the act of thinking. Also don't say 의견하다 — there is no such verb; you 의견을 말하다."},sentence:{ko:"그 의견도 좋은데 시간이 부족해요.",en:"That opinion is good too, but we are short on time."},target:"의견",options:["opinion","background; context","the other person; conversation partner"],note:"Natural noun for agreeing, disagreeing, or softening pushback."}],canDo:"Add a reason they didn't know with -거든요 (감기에 걸렸거든요)",id:"chapter-35-b5",chapterId:"chapter-35",index:4},{kind:"pattern",title:"문법 Grammar · V/A-지요/죠",cards:[{kind:"teach",name:"V/A-지요/죠",sub:"Checking Shared Understanding",rows:[{when:"Verb/adjective stem",add:"-지요? / -죠?",ex:"덥다 → 덥지요? / 덥죠?, 재미있다 → 재미있죠?"},{when:"Past tense",add:"-았/었지요? / -았/었죠?",ex:"봤다 → 봤지요? / 봤죠?, 먹었다 → 먹었죠?"},{when:"Noun + 이다",add:"-(이)지요? / -(이)죠?",ex:"학생이다 → 학생이지요? / 학생이죠?, 친구다 → 친구죠?"},{when:"Casual",add:"-지?",ex:"덥지?, 맞지?"}],examples:[{ko:"오늘 정말 덥죠?",en:"It's really hot today, isn't it?",romanization:"oneul jeongmal deopjyo?",note:"Weather small talk: the speaker expects agreement, not new information."},{ko:"민수 씨는 학생이지요?",en:"Minsu is a student, right?",romanization:"minsu ssineun haksaengijiyo?",note:"Noun + 이다 becomes 학생이지요; the speaker is confirming something they think is true."}],more:{func:`Use -지요? or its spoken contraction -죠? when you think you already know the answer and want the listener to confirm or agree. It is softer than a plain information question because it sounds like "right?" or "you know, don't you?" In everyday speech, -죠 is more common than the full -지요.`,keyPoint:{label:"-아요? asks; -지요?/죠? confirms",body:"Use -아요? when you do not know and need information. Use -지요?/죠? when you already have an idea and want confirmation, agreement, or shared footing. If you truly have no idea, plain -아요? is safer."},pronunciation:"The contracted 죠 is one quick syllable. After a stop consonant like the ㅂ in 덥죠, the ㅈ is always pronounced tense, so 덥죠 sounds like [덥쬬] at any speed — but keep the spelling 덥죠, not 덥쬬."}}],canDo:"Add a reason they didn't know with -거든요 (감기에 걸렸거든요)",id:"chapter-35-b6",chapterId:"chapter-35",index:5},{kind:"pattern",title:"문법 Grammar · V/A-거든요",cards:[{kind:"hunt",name:"V/A-거든요",sub:"Adding a Reason They Didn't Know",lines:[{tokens:[{pre:"오늘은",mid:"",post:"",hit:!1},{pre:"못",mid:"",post:"",hit:!1},{pre:"만나요.",mid:"",post:"",hit:!1},{pre:"할",mid:"",post:"",hit:!1},{pre:"일이",mid:"",post:"",hit:!1},{pre:"많",mid:"거든요",post:".",hit:!0}],ko:"오늘은 못 만나요. 할 일이 많거든요.",en:"I can't meet today. I have a lot to do, you see.",romanization:"oneureun mot mannayo. hal iri mankeodeunyo."},{tokens:[{pre:"저",mid:"",post:"",hit:!1},{pre:"요즘",mid:"",post:"",hit:!1},{pre:"한국어",mid:"",post:"",hit:!1},{pre:"배워요.",mid:"",post:"",hit:!1},{pre:"한국",mid:"",post:"",hit:!1},{pre:"친구가",mid:"",post:"",hit:!1},{pre:"많",mid:"거든요",post:".",hit:!0}],ko:"저 요즘 한국어 배워요. 한국 친구가 많거든요.",en:"I'm learning Korean these days. I have a lot of Korean friends, you see.",romanization:"jeo yojeum hangugeo baewoyo. hanguk chinguga mankeodeunyo."}],rule:{name:"V/A-거든요",rows:[{when:"Any verb/adjective stem (present)",add:"-거든요",ex:"바쁘다 → 바쁘거든요, 가다 → 가거든요"},{when:"Past tense",add:"-았/었거든요",ex:"먹다 → 먹었거든요, 자다 → 잤거든요"},{when:"Noun + 이다",add:"-(이)거든요",ex:"학생이다 → 학생이거든요, 친구다 → 친구거든요"},{when:"Casual (반말)",add:"-거든",ex:"바쁘거든, 먹었거든"}]},more:{func:`Use -거든요 to give the listener new information — usually a reason or background fact they didn't know — often answering a spoken or silent "why?". It feels like "...you see" at the end.`,keyPoint:{label:"-거든요 vs. -아서/어서",body:"Both can give a reason, but -아서/어서 joins two clauses inside one sentence ('A여서 B'). -거든요 ends the sentence and tacks the reason on afterward as a fresh follow-up — it signals 'here's something you didn't know'. -아서/어서 doesn't carry that 'news' feeling."},pronunciation:"거든요 keeps each syllable clear: [거든뇨] in fast speech as the ㄴ and ㅛ glide together. Don't soften it to [거더요]."}}],canDo:"Soften a reply and leave room to react with trailing -는데요",id:"chapter-35-b7",chapterId:"chapter-35",index:6},{kind:"pattern",title:"문법 Grammar · V/A-는데요",cards:[{kind:"hunt",name:"V/A-는데요",sub:"A Soft, Trailing Ending",lines:[{tokens:[{pre:"그건",mid:"",post:"",hit:!1},{pre:"잘",mid:"",post:"",hit:!1},{pre:"모르",mid:"는데요",post:".",hit:!0}],ko:"그건 잘 모르는데요.",en:"Hmm, I don't really know that...",romanization:"geugeon jal moreunde-yo."},{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"벌써",mid:"",post:"",hit:!1},{pre:"다",mid:"",post:"",hit:!1},{pre:"먹었",mid:"는데요",post:".",hit:!0}],ko:"저는 벌써 다 먹었는데요.",en:"But I already finished eating...",romanization:"jeoneun beolsseo da meogeonneunde-yo."}],rule:{name:"V/A-는데요",rows:[{when:"Action verb (present)",add:"-는데요",ex:"가다 → 가는데요, 먹다 → 먹는데요"},{when:"Adjective (present)",add:"-(으)ㄴ데요",ex:"바쁘다 → 바쁜데요, 작다 → 작은데요"},{when:"Past tense",add:"-았/었는데요",ex:"가다 → 갔는데요, 좋다 → 좋았는데요"},{when:"Noun + 이다",add:"인데요",ex:"학생이다 → 학생인데요"}]},more:{func:"Use sentence-final -는데요 to leave your statement gently open, inviting the other person to react or softening a reply. It often hints at an unspoken 'but...', which makes answers and mild objections sound polite instead of blunt.",keyPoint:{label:"-는데 vs. -는데요",body:"-는데 in the middle of a sentence sets up background for a following clause. -는데요 stands at the very END as a soft, open finish. Same shape, but here it's a complete reply that trails off, not a connector. The honorific 요 is what makes it a polite stand-alone ending."},pronunciation:"는데요 sounds like [는데요]; after a ㄷ/ㅅ/ㅈ-final stem the ㄴ-change still applies (먹었는데요 → [머건는데요]). Let the final 요 drift up slightly to keep the soft, open feel."}}],canDo:"Lead with background before my real point using -(으)ㄴ/는데 (어제 못 왔는데...)",id:"chapter-35-b8",chapterId:"chapter-35",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A team member brings up unfinished materials before a meeting starts.",lines:[{speaker:"민서",ko:"사실은 오늘 자료가 아직 다 안 끝났는데요.",en:"Actually, today's materials are not finished yet.",romanization:"sasireun oneul jaryoga ajik da an kkeunnanneundeyo."},{speaker:"지훈",ko:"그러니까 먼저 회의를 시작해도 된다는 말이죠?",en:"So you mean we can start the meeting first, right?",romanization:"geureonikka meonjeo hoeuireul sijakaedo doendaneun marijyo?"},{speaker:"민서",ko:"네. 어제 갑자기 일이 생겼거든요.",en:"Yes. Something suddenly came up yesterday, you see.",romanization:"ne. eoje gapjagi iri saenggyeotgeodeunyo."},{speaker:"지훈",ko:"알겠어요. 그런데 발표 전에 자료는 보내 줄 수 있어요?",en:"I understand. But can you send the materials before the presentation?",romanization:"algesseoyo. geureonde balpyo jeone jaryoneun bonae jul su isseoyo?"},{speaker:"민서",ko:"네, 그건 가능해요. 회의 시간이 짧잖아요.",en:"Yes, that is possible. The meeting time is short, you know.",romanization:"ne, geugeon ganeunghaeyo. hoeui sigani jjaljanhayo."},{speaker:"지훈",ko:"그럼 제가 먼저 배경을 설명할게요.",en:"Then I will explain the background first.",romanization:"geureom jega meonjeo baegyeongeul seolmyeonghalgeyo."}]},{kind:"order",prompt:"Build: 'Actually, the materials are late, you see.'",tokens:["사실은","자료가 늦었거든요"],correct:"사실은 자료가 늦었거든요",explanation:"사실은 prepares the listener for sensitive background. -거든요 explains new information rather than reminding them of something shared."}],canDo:"Lead with background before my real point using -(으)ㄴ/는데 (어제 못 왔는데...)",id:"chapter-35-b9",chapterId:"chapter-35",index:8},{kind:"reading",title:"읽기 Reading · 자료가 아직 안 끝났는데요",cards:[{kind:"read",title:"자료가 아직 안 끝났는데요",chunks:["팀 회의에서 자료가 늦어졌다면 바로 '못 했어요'라고만 말하면 조금 딱딱하게 들릴 수 있어요. 먼저 '사실은'으로 말을 꺼내고, '자료가 아직 안 끝났는데요'처럼 상황을 부드럽게 열어 주세요.","상대방이 모르는 이유를 설명할 때는 '어제 갑자기 일이 생겼거든요'가 자연스럽고, 이미 같이 아는 사실을 다시 짚을 때는 '회의 시간이 짧잖아요'가 자연스러워요. 그다음에는 '그런데 발표 전에 자료는 보내 줄 수 있어요?'처럼 다음 행동을 확인하면 대화가 멈추지 않아요."],translation:"If the materials are late in a team meeting, simply saying 'I did not do it' can sound stiff. Open the topic with 사실은, soften the situation with -는데요, use -거든요 for new background, and use -잖아요 for shared information. Then move the conversation to the next action.",qas:[{q:"자료가 늦어졌을 때 먼저 어떤 표현으로 말을 꺼낼 수 있어요?",a:"사실은으로 말을 꺼낼 수 있어요."},{q:"상대방이 모르는 이유를 설명할 때 어떤 표현이 자연스러워요?",a:"거든요가 자연스러워요."},{q:"이미 같이 아는 사실을 다시 짚을 때는 어떤 표현이 자연스러워요?",a:"잖아요가 자연스러워요."}]}],canDo:"Remind someone of something we both know with -잖아요 (시험이 있잖아요)",id:"chapter-35-b10",chapterId:"chapter-35",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"The listener does not know why the materials are late. Which ending fits best?",sentence:null,options:[{text:"어제 갑자기 일이 생겼거든요.",ok:!0},{text:"어제 갑자기 일이 생겼잖아요.",ok:!1},{text:"어제 갑자기 일이 생겼네요.",ok:!1}],explanation:"Use -거든요 for new background the listener does not know yet."},{kind:"drill",prompt:"Everyone knows the meeting time is short. Which sentence uses that shared fact naturally?",sentence:null,options:[{text:"회의 시간이 짧잖아요.",ok:!0},{text:"회의 시간이 짧거든요.",ok:!1},{text:"회의 시간이 짧네요.",ok:!1}],explanation:"Use -잖아요 when the reason is shared, visible, or already mentioned."},{kind:"drill",prompt:"Which sentence brings up bad news most softly?",sentence:null,options:[{text:"사실은 자료가 아직 안 끝났는데요.",ok:!0},{text:"자료 안 끝났습니다. 끝.",ok:!1},{text:"자료가 안 끝났잖아요, 왜 몰라요?",ok:!1}],explanation:"사실은 opens the topic and -는데요 leaves room for the next step."},{kind:"drill",prompt:"자료___ 아직 안 왔거든요. (The thing is, the materials have not arrived yet.)",sentence:null,options:[{text:"가",ok:!0},{text:"를",ok:!1},{text:"에",ok:!1}],explanation:"자료 is the subject of not arriving, so it takes 가. 거든요 adds new background the listener may not know."},{kind:"order",prompt:"Build: 'Actually, the materials are late, you see.'",tokens:["사실은","자료가 늦었거든요"],correct:"사실은 자료가 늦었거든요",explanation:"사실은 prepares the listener for sensitive background. -거든요 explains new information rather than reminding them of something shared."},{kind:"drill",prompt:"You need to bring up bad news softly. Which opener is best?",sentence:null,options:[{text:"사실은 문제가 좀 있는데요.",ok:!0},{text:"문제 있어요.",ok:!1},{text:"문제입니다.",ok:!1}],explanation:"사실은 and -는데요 soften the approach. The shorter alternatives can sound abrupt in a sensitive conversation."}],canDo:"Add a reason they didn't know with -거든요 (감기에 걸렸거든요)",id:"chapter-35-b11",chapterId:"chapter-35",index:10}]},{id:"chapter-36",number:36,title:"V/A-더라고요 · V/A-더니",goal:"Use 가 보니까 and -더라고요 to report firsthand observations.",biteCount:8,bites:[{kind:"words",title:"단어 Words 1 · 보니까~",cards:[{kind:"guess",word:{ko:"보니까",romanization:"bonikka",en:"when I saw/tried/checked",pos:"expression",nuance:"보니까 is evidence-based. It sounds odd if you did not actually see, try, or check the thing."},sentence:{ko:"가 보니까 생각보다 괜찮더라고요.",en:"When I tried going, it was better than I expected."},target:"보니까",options:["when I saw/tried/checked","I noticed; it turned out","I observed X, and then Y happened"],note:"Experience leads into a firsthand observation."},{kind:"guess",word:{ko:"더라고요",romanization:"deoragoyo",en:"I noticed; it turned out",pos:"ending",nuance:"더라고요 is not just past tense. It carries the speaker's evidence and realization."},sentence:{ko:"생각보다 사람이 많더라고요.",en:"There were more people than I expected, I noticed."},target:"더라고요",options:["I observed X, and then Y happened","I noticed; it turned out","when I saw/tried/checked"],note:"Reports what the speaker personally saw."},{kind:"guess",word:{ko:"더니",romanization:"deoni",en:"I observed X, and then Y happened",pos:"ending",nuance:"Plain -더니 has an eyewitness feel. For your own action causing a result, -았/었더니 is usually the safer form."},sentence:{ko:"처음에는 조용하더니 금방 붐비더라고요.",en:"It was quiet at first, and then it quickly got crowded, I noticed."},target:"더니",options:["I noticed; it turned out","when I saw/tried/checked","I observed X, and then Y happened"],note:"Observed before-and-after change."},{kind:"guess",word:{ko:"생각보다",romanization:"saenggakboda",en:"more/less than expected",pos:"adverb",nuance:"생각보다 naturally pairs with 더라고요 because both talk about what you found after experience."},sentence:{ko:"음식이 생각보다 빨리 나오더라고요.",en:"The food came out faster than expected, I noticed."},target:"생각보다",options:["more/less than expected","when I saw/tried/checked","I noticed; it turned out"],note:"Expectation compared with real experience."},{kind:"guess",word:{ko:"처음에는",romanization:"cheoeumeneun",en:"at first",pos:"adverbial phrase",nuance:"처음에는 points to the first stage. It needs a later stage to feel complete."},sentence:{ko:"처음에는 조용하더니 금방 사람이 많아졌어요.",en:"It was quiet at first, and then there were quickly more people."},target:"처음에는",options:["at first","when I saw/tried/checked","I noticed; it turned out"],note:"Sets the first stage before a change."},{kind:"payoff",line:{speaker:"민서",ko:"어제 새 식당에 가 보니까 어땠어요?",en:"How was it when you tried going to the new restaurant yesterday?"},hl:"보니까"}],canDo:"Report something I personally saw or felt, with mild surprise, using -더라고요 (붐비더라고요)",id:"chapter-36-b1",chapterId:"chapter-36",index:0},{kind:"pattern",title:"문법 Grammar · V/A-더라고요",cards:[{kind:"hunt",name:"V/A-더라고요",sub:"reporting what I noticed firsthand",lines:[{tokens:[{pre:"그",mid:"",post:"",hit:!1},{pre:"영화",mid:"",post:"",hit:!1},{pre:"정말",mid:"",post:"",hit:!1},{pre:"재미있",mid:"더라고요",post:".",hit:!0}],ko:"그 영화 정말 재미있더라고요.",en:"That movie was really fun (I saw for myself).",romanization:"geu yeonghwa jeongmal jaemiitdeoragoyo."},{tokens:[{pre:"어제",mid:"",post:"",hit:!1},{pre:"밖에",mid:"",post:"",hit:!1},{pre:"나갔는데",mid:"",post:"",hit:!1},{pre:"생각보다",mid:"",post:"",hit:!1},{pre:"춥",mid:"더라고요",post:".",hit:!0}],ko:"어제 밖에 나갔는데 생각보다 춥더라고요.",en:"I went outside yesterday, and it was colder than I thought.",romanization:"eoje bakke nagannneunde saenggakboda chupdeoragoyo."}],rule:{name:"V/A-더라고요",rows:[{when:"Verb stem (any ending)",add:"-더라고요",ex:"가다 → 가더라고요 / 먹다 → 먹더라고요"},{when:"Adjective stem (any ending)",add:"-더라고요",ex:"춥다 → 춥더라고요 / 좋다 → 좋더라고요"},{when:"Noun + 이다 / 아니다",add:"-더라고요",ex:"학생이다 → 학생이더라고요 / 아니다 → 아니더라고요"},{when:"Past tense (-았/었-)",add:"-더라고요",ex:"갔다 → 갔더라고요 / 끝났다 → 끝났더라고요"}]},more:{func:'Use -더라고요 to report something you personally saw, heard, or felt in the past, usually with a touch of mild surprise or fresh discovery. It means "I noticed / it turned out that..." — the information comes from your own direct experience, not from what someone else told you.',keyPoint:{label:"-더라고요 vs. plain -았/었어요",body:"Both talk about the past, but -았/었어요 just states a fact, while -더라고요 frames it as something YOU personally witnessed and are now reporting, often with mild surprise. '비가 왔어요' = it rained (fact); '비가 오더라고요' = I saw that it was raining."},pronunciation:"In casual speech -더라고요 is often said as -더라구요, but -더라고요 is the standard spelling. 많더라고요 sounds like [만더라고요]."}}],canDo:"Report something I personally saw or felt, with mild surprise, using -더라고요 (붐비더라고요)",id:"chapter-36-b2",chapterId:"chapter-36",index:1},{kind:"words",title:"단어 Words 2 · 예전에는~",cards:[{kind:"guess",word:{ko:"예전에는",romanization:"yejeoneneun",en:"in the past; before",pos:"adverbial phrase",nuance:"예전에는 is broader than 어제 or 지난주. It points to an earlier period, not one exact moment."},sentence:{ko:"예전에는 사람이 적었다고 들었어요.",en:"I heard there used to be fewer people."},target:"예전에는",options:["when I saw/tried/checked","I noticed; it turned out","in the past; before"],note:"Sets up an earlier state."},{kind:"guess",word:{ko:"요즘은",romanization:"yojeumeun",en:"these days; nowadays",pos:"adverbial phrase",nuance:"요즘은 is not just today. It means the recent/current period."},sentence:{ko:"요즘은 분위기가 많이 달라졌더라고요.",en:"These days, the atmosphere has changed a lot, I noticed."},target:"요즘은",options:["when I saw/tried/checked","I noticed; it turned out","these days; nowadays"],note:"Current state after a change."},{kind:"guess",word:{ko:"붐비다",romanization:"bumbida",en:"to be crowded",pos:"verb",nuance:"붐비다 describes the place or route becoming crowded. 사람이 많다 describes the number of people more directly."},sentence:{ko:"점심시간이 되니까 식당이 붐비더라고요.",en:"When it became lunchtime, the restaurant got crowded, I noticed."},target:"붐비",options:["to become different; to change","to be crowded","to increase"],note:"Place-focused crowding."},{kind:"guess",word:{ko:"조용하다",romanization:"joyonghada",en:"quiet",pos:"adjective",nuance:"조용하다 is the opposite of 시끄럽다 and covers both a quiet PLACE/sound and a calm, reserved PERSONALITY (성격이 조용하다 = soft-spoken, low-key). As a 하다-adjective it conjugates regularly: 조용하다 → 조용해요 → 조용한 → 조용히(adverb, note the special 히 form) → 조용해서. The most useful distinction for English speakers is the adverb: 'be quiet!' is 조용히 해! (using 조용히), not 조용하게 — Koreans overwhelmingly use 조용히 here, so memorize it as a set phrase. The near-synonym 고요하다 is more literary/poetic and means a deep, serene stillness (고요한 밤 'a serene night'), whereas 조용하다 is the everyday neutral word you'd actually speak. Pitfall: writing 조용하요 instead of the contracted 조용해요, and reaching for 조용하게 when 조용히 is the natural adverb. Register is neutral and extremely common."},sentence:{ko:"처음에는 식당이 조용하더라고요.",en:"At first, the restaurant was quiet, I noticed."},target:"조용하",options:["quiet","when I saw/tried/checked","I noticed; it turned out"],note:"Good first state before -더니."},{kind:"guess",word:{ko:"금방",romanization:"geumbang",en:"soon; quickly; in a moment",pos:"adverb",nuance:"금방 is a two-faced time word: with a FUTURE verb it means 'in a moment / very soon' (금방 올게요 'I'll be right back'), and with a PAST verb it means 'just now / a moment ago' (금방 갔어요 'left just now'). The tense of the verb decides which reading you get, so the same word swings both ways around the present — that's the thing to internalize. The sharp contrast is 금방 vs 방금: 방금 'just now' is strictly PAST (방금 도착했어요 'I just arrived') and cannot mean 'soon', whereas 금방 covers both directions. Origin-wise 금방 is Sino-Korean 今方 'now-just', and it's thoroughly casual, everyday speech. The classic English-speaker error is forcing 방금 into a future sentence or assuming 금방 only means 'soon' and missing its 'a moment ago' use. It takes no particle, sits before the verb, and habitually pairs with 오다/가다, 되다 ('be ready'), and 끝나다."},sentence:{ko:"처음에는 조용하더니 금방 사람이 많아졌어요.",en:"It was quiet at first, and then there were quickly more people."},target:"금방",options:["when I saw/tried/checked","soon; quickly; in a moment","I noticed; it turned out"],note:"Marks a fast change."},{kind:"payoff",line:{speaker:"지훈",ko:"처음에는 조용하더니 금방 붐비더라고요.",en:"It was quiet at first, and then it quickly got crowded, I noticed."},hl:"붐비"}],canDo:"Link 'I noticed X, and then Y followed' with -더니 (늘더니 붐비더라고요)",id:"chapter-36-b3",chapterId:"chapter-36",index:2},{kind:"pattern",title:"문법 Grammar · V/A-더니",cards:[{kind:"hunt",name:"V/A-더니",sub:"I saw X happen, and then Y followed",lines:[{tokens:[{pre:"동생이",mid:"",post:"",hit:!1},{pre:"아까",mid:"",post:"",hit:!1},{pre:"울",mid:"더니",post:"",hit:!0},{pre:"지금은",mid:"",post:"",hit:!1},{pre:"잘",mid:"",post:"",hit:!1},{pre:"놀아요.",mid:"",post:"",hit:!1}],ko:"동생이 아까 울더니 지금은 잘 놀아요.",en:"My little brother was crying earlier, and now he's playing happily.",romanization:"dongsaengi akka uldeoni jigeumeun jal norayo."},{tokens:[{pre:"아침에는",mid:"",post:"",hit:!1},{pre:"비가",mid:"",post:"",hit:!1},{pre:"오",mid:"더니",post:"",hit:!0},{pre:"오후에는",mid:"",post:"",hit:!1},{pre:"날씨가",mid:"",post:"",hit:!1},{pre:"좋아요.",mid:"",post:"",hit:!1}],ko:"아침에는 비가 오더니 오후에는 날씨가 좋아요.",en:"It was raining in the morning, but in the afternoon the weather is nice.",romanization:"achimeneun biga odeoni ohueneun nalssiga joayo."}],rule:{name:"V/A-더니",rows:[{when:"Verb stem (any ending)",add:"-더니",ex:"울다 → 울더니 / 먹다 → 먹더니"},{when:"Adjective stem (any ending)",add:"-더니",ex:"덥다 → 덥더니 / 좋다 → 좋더니"},{when:"Noun + 이다",add:"-더니",ex:"학생이다 → 학생이더니"},{when:"After a completed first action (-았/었-), often I-subject",add:"-더니",ex:"먹었다 → 먹었더니 / 갔다 → 갔더니"}]},more:{func:"Use -더니 to link two things you personally watched: 'I noticed X (in the past), and then Y happened.' The second part is often a change, a result, or a contrast that grows out of the first. The subject of the first part is usually someone else, not you.",keyPoint:{label:"-더니 vs. -았/었더니",body:"Plain -더니 reports what you watched someone else (or the world) do, then a follow-up. -았/었더니 usually has 'I' as the subject who finished an action, leading to a result you then found: '제가 밥을 먹었더니 졸려요' (I ate, and now I'm sleepy). Rule of thumb: 더니 → 'they...', 았/었더니 → 'I did..., and then...'."},pronunciation:"In -더니 the 더 is said clearly as [더], with no blending into the next part. With past -었더니, 었더 sounds like [얻떠] with a light tense ㄷ."}}],canDo:"Link 'I noticed X, and then Y followed' with -더니 (늘더니 붐비더라고요)",id:"chapter-36-b4",chapterId:"chapter-36",index:3},{kind:"words",title:"단어 Words 3 · 달라지다~",cards:[{kind:"guess",word:{ko:"달라지다",romanization:"dallajida",en:"to become different; to change",pos:"verb",nuance:"달라지다 spotlights the before-and-after gap: something is now clearly unlike how it used to be, which makes it the everyday verb for noticing change in a person's looks, mood, or a situation. It's the inchoative of the adjective 다르다 (to be different) — 다르 + -아지다 'become' — and that origin is the #1 pitfall: 다르다 states a static difference between two things (A는 B와 달라요 = A is different from B), while 달라지다 is the dynamic act of becoming different over time (분위기가 달라졌어요 = the mood changed). It overlaps with 변하다 and 바뀌다, but the dividing line is focus: 달라지다 = 'the result looks different now,' 변하다 = 'the inner nature transformed,' 바뀌다 = 'one thing got swapped for another.' Both 달라지다 and the thing changing take 이/가; the form 달라져요 comes from -지다 verbs taking 어 in the 요-form (지+어 → 져)."},sentence:{ko:"요즘은 분위기가 많이 달라졌더라고요.",en:"These days, the atmosphere has changed a lot, I noticed."},target:"달라졌",options:["to be crowded","to become different; to change","to observe"],note:"Useful for before-now observations."},{kind:"guess",word:{ko:"늘다",romanization:"neulda",en:"to increase",pos:"verb",nuance:"늘다 means an amount, number, or ability grows bigger, and it is the everyday word for skills improving — 실력이 늘다 is THE phrase for 'getting better at something'. It is a ㄹ-irregular verb: the final ㄹ drops before endings beginning with ㄴ, ㅂ, or ㅅ, which is why the formal present is 늡니다 (not *늘습니다) — the ㄹ vanishes before -ㅂ니다. Watch the synonym split: 늘다 is intransitive (the thing increases by itself — 실력이 늘어요), while its causative twin 늘리다 is transitive (you increase a thing on purpose — 시간을 늘려요 = I extend the time). Compare also 증가하다, the stiff Sino-Korean 'increase' used in reports and statistics (인구가 증가했다); 늘다 is the warm spoken equivalent. The English-speaker pitfall is two-fold: first, forgetting the ㄹ-drop and saying *늘습니다; second, saying 'I improved my Korean' as if you act on it — Koreans say 한국어가 늘었어요 (Korean increased) with the skill as the subject, not as an object you operate on."},sentence:{ko:"요즘은 사람이 많이 늘었더라고요.",en:"These days, the number of people has increased a lot, I noticed."},target:"늘었",options:["to be crowded","to increase","to observe"],note:"A natural observed-change verb."},{kind:"guess",word:{ko:"줄다",romanization:"julda",en:"to decrease",pos:"verb",nuance:"줄다 is the exact opposite of 늘다 — it means an amount, number, or size gets smaller — and the two are learned as a pair (늘다/줄다). Like 늘다 it is a ㄹ-irregular verb, so the ㄹ drops before -ㅂ니다, giving the formal 줍니다 (not *줄습니다). The crucial synonym contrast is 줄다 vs 줄이다: 줄다 is intransitive — the thing shrinks by itself (소리가 줄었어요 = the sound got quieter on its own), while 줄이다 is the causative — you deliberately reduce something (소리를 줄였어요 = I turned the sound down). Its formal report-style synonym is 감소하다 (Sino-Korean 減少, 'reduce-decrease'), used for statistics; 줄다 is the natural conversational word. The English-speaker pitfall mirrors 늘다: don't say *줄습니다 (the ㄹ drops to make 줍니다), and don't put an object with 줄다. 'I reduced my spending' needs the transitive 줄이다 (지출을 줄였어요); 'my spending decreased' uses 줄다 with the subject particle (지출이 줄었어요)."},sentence:{ko:"요즘은 기다리는 시간이 줄었더라고요.",en:"These days, the waiting time has decreased, I noticed."},target:"줄었",options:["to be crowded","to decrease","to observe"],note:"Opposite of 늘다 for observed change."},{kind:"guess",word:{ko:"알게 되다",romanization:"alge doeda",en:"to come to know; to find out",pos:"phrase",nuance:"알게 되다 emphasizes the process of finding out. 알다 simply states that you know."},sentence:{ko:"직접 가 보니까 왜 유명한지 알게 됐어요.",en:"After going there myself, I found out why it is famous."},target:"알게 됐",options:["to come to know; to find out","when I saw/tried/checked","I observed X, and then Y happened"],note:"Discovery through experience."},{kind:"guess",word:{ko:"관찰하다",romanization:"gwanchalhada",en:"to observe",pos:"verb",nuance:"관찰하다 is useful for deliberate observation. For a casual visit, 가 보니까 or 보니까 often sounds more natural."},sentence:{ko:"일주일 동안 분위기가 어떻게 변하는지 관찰했어요.",en:"I observed how the atmosphere changed over a week."},target:"관찰했",options:["to be crowded","to become different; to change","to observe"],note:"More deliberate than casually noticing."}],canDo:"Contrast before and after with 예전에는 / 요즘은",id:"chapter-36-b5",chapterId:"chapter-36",index:4},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A friend asks about a new restaurant after someone visited it.",lines:[{speaker:"민서",ko:"어제 새 식당에 가 보니까 어땠어요?",en:"How was it when you tried going to the new restaurant yesterday?",romanization:"eoje sae sikdange ga bonikka eottaesseoyo?"},{speaker:"지훈",ko:"처음에는 조용하더니 금방 붐비더라고요.",en:"It was quiet at first, and then it quickly got crowded, I noticed.",romanization:"cheoeumeneun joyonghadeoni geumbang bumbideoragoyo."},{speaker:"민서",ko:"음식은 어땠어요?",en:"How was the food?",romanization:"eumsigeun eottaesseoyo?"},{speaker:"지훈",ko:"생각보다 빨리 나오고 맛도 괜찮더라고요.",en:"It came out faster than expected, and the taste was good too.",romanization:"saenggakboda ppalli naogo matdo gwaenchandeoragoyo."},{speaker:"민서",ko:"예전에는 사람이 적었다고 들었는데요.",en:"I heard there used to be fewer people.",romanization:"yejeoneneun sarami jeogeotdago deureonneundeyo."},{speaker:"지훈",ko:"맞아요. 요즘은 분위기가 많이 달라졌더라고요.",en:"Right. These days, the atmosphere has changed a lot, I noticed.",romanization:"majayo. yojeumeun bunwigiga mani dallajyeotdeoragoyo."}]},{kind:"order",prompt:"Build: 'When I tried going there, it was quieter than expected.'",tokens:["가 보니까","생각보다 조용하더라고요"],correct:"가 보니까 생각보다 조용하더라고요",explanation:"가 보니까 sets up what you learned by trying it yourself. -더라고요 reports the firsthand observation."}],canDo:"Report something I personally saw or felt, with mild surprise, using -더라고요 (붐비더라고요)",id:"chapter-36-b6",chapterId:"chapter-36",index:5},{kind:"reading",title:"읽기 Reading · 가 보니까 생각보다 괜찮더라고요",cards:[{kind:"read",title:"가 보니까 생각보다 괜찮더라고요",chunks:["새 식당이나 카페에 다녀온 뒤에는 그냥 '좋았어요'라고 말할 수도 있지만, 직접 보고 느낀 느낌을 살리려면 '-더라고요'가 훨씬 자연스러워요. '가 보니까 생각보다 조용하더라고요'라고 하면 내가 직접 가서 알게 된 정보라는 느낌이 들어요. 시간이 지나면서 변한 모습을 말할 때는 '-더니'가 좋아요.","예를 들어 '처음에는 조용하더니 금방 붐비더라고요'라고 하면 처음 상태와 나중 상태가 한 장면처럼 이어져요. 하지만 내 행동 때문에 생긴 결과라면 '많이 먹었더니 졸렸어요'처럼 '-았/었더니'를 써야 해요."],translation:"After visiting a restaurant or cafe, -더라고요 lets you report what you personally noticed. -더니 links an observed first state to a later change. For the result of your own action, use -았/었더니 instead.",qas:[{q:"직접 보고 느낀 내용을 말할 때 어떤 표현이 자연스러워요?",a:"-더라고요가 자연스러워요."},{q:"처음 상태와 나중 상태를 이어 말할 때 어떤 표현이 좋아요?",a:"-더니가 좋아요."},{q:"내 행동 때문에 생긴 결과에는 어떤 형태를 써야 해요?",a:"-았/었더니를 써야 해요."}]}],canDo:"Link 'I noticed X, and then Y followed' with -더니 (늘더니 붐비더라고요)",id:"chapter-36-b7",chapterId:"chapter-36",index:6},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"You visited the restaurant yourself and noticed it was crowded. Which sentence fits best?",sentence:null,options:[{text:"사람이 많더라고요.",ok:!0},{text:"사람이 많대요.",ok:!1},{text:"사람이 많기로 했어요.",ok:!1}],explanation:"-더라고요 reports a firsthand observation."},{kind:"drill",prompt:"Which sentence shows an observed change over time?",sentence:null,options:[{text:"처음에는 조용하더니 금방 붐비더라고요.",ok:!0},{text:"처음에는 조용하기 위해 금방 붐볐어요.",ok:!1},{text:"처음에는 조용할 뿐이더라고요.",ok:!1}],explanation:"-더니 connects the observed first state with the later change."},{kind:"drill",prompt:"You ate a lot, so you became sleepy. Which form is correct?",sentence:null,options:[{text:"많이 먹었더니 졸렸어요.",ok:!0},{text:"많이 먹더니 졸렸어요.",ok:!1},{text:"많이 먹더라고요 졸렸어요.",ok:!1}],explanation:"Use -았/었더니 for your own action leading to a result."},{kind:"drill",prompt:"그 식당___ 가 보니까 생각보다 조용하더라고요. (When I tried going to that restaurant...)",sentence:null,options:[{text:"에",ok:!0},{text:"에서",ok:!1},{text:"를",ok:!1}],explanation:"가 보다 is movement/trying a place, so the destination takes 에. 에서 would mark an action happening at the place."},{kind:"order",prompt:"Build: 'When I tried going there, it was quieter than expected.'",tokens:["가 보니까","생각보다 조용하더라고요"],correct:"가 보니까 생각보다 조용하더라고요",explanation:"가 보니까 sets up what you learned by trying it yourself. -더라고요 reports the firsthand observation."},{kind:"drill",prompt:"You saw a shop get crowded over time. Which sentence fits?",sentence:null,options:[{text:"처음에는 조용하더니 금방 사람이 많아졌어요.",ok:!0},{text:"제가 조용하더니 사람이 많아졌어요.",ok:!1},{text:"조용할 리가 없어요.",ok:!1}],explanation:"-더니 fits the observed change from quiet to crowded. The other choices either misuse the subject or switch to a different grammar."}],canDo:"Contrast before and after with 예전에는 / 요즘은",id:"chapter-36-b8",chapterId:"chapter-36",index:7}]},{id:"chapter-37",number:37,title:"V/A-다고 했어요 · V/A-냐고 물어봤어요",goal:"Report statements with -다고 했어요 and recognize the spoken contraction -대요.",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · 다고 했어요~",cards:[{kind:"guess",word:{ko:"다고 했어요",romanization:"dago haesseoyo",en:"said that...",pos:"reported-speech ending",nuance:"다고 했어요 reports a statement, not a question or command. Match the inner ending to the sentence type."},sentence:{ko:"선생님이 금요일에 본다고 하셨어요.",en:"The teacher said we will take it on Friday."},target:"다고",options:["said that...","asked whether/if...","whether; what/when/where... inside a sentence"],note:"Reports a statement."},{kind:"guess",word:{ko:"냐고 물어봤어요",romanization:"nyago mureobwasseoyo",en:"asked whether/if...",pos:"reported-question ending",nuance:"냐고 is for reported questions. Do not switch to -다고 just because the whole sentence now ends like a statement."},sentence:{ko:"친구가 몇 시에 만나냐고 물어봤어요.",en:"My friend asked what time we are meeting."},target:"냐고 물어봤어요",options:["asked whether/if...","said that...","to tell someone to..."],note:"Reports a question."},{kind:"guess",word:{ko:"는지",romanization:"neunji",en:"whether; what/when/where... inside a sentence",pos:"embedded-question ending",nuance:"는지 is not reported speech by itself. It embeds a question so verbs like 알다, 모르다, 확인하다, and 궁금하다 can use it."},sentence:{ko:"시험이 언제인지 알아요?",en:"Do you know when the exam is?"},target:"인지",options:["said that...","to tell someone to...","whether; what/when/where... inside a sentence"],note:"Embeds a question inside 알다."},{kind:"guess",word:{ko:"라고 하다",romanization:"rago hada",en:"to tell someone to...",pos:"reported-command ending",nuance:"라고 하다 for instructions is separate from noun +(이)라고 하다, as in 학생이라고 했어요."},sentence:{ko:"선생님이 숙제를 제출하라고 하셨어요.",en:"The teacher told us to submit the homework."},target:"라고 하셨",options:["said that...","asked whether/if...","to tell someone to..."],note:"Reports an instruction."},{kind:"guess",word:{ko:"대요",romanization:"daeyo",en:"they say; I heard that",pos:"contracted reported ending",nuance:"대요 is common, but first learn what it expands from so you do not mix statements with questions."},sentence:{ko:"선생님이 시험은 금요일에 본대요.",en:"The teacher says the exam is on Friday."},target:"대요",options:["they say; I heard that","asked whether/if...","whether; what/when/where... inside a sentence"],note:"Spoken contraction of 본다고 해요."},{kind:"payoff",line:{speaker:"지훈",ko:"몇 시에 만나냐고 물어봤어요.",en:"They asked what time we are meeting."},hl:"냐고 물어봤어요"}],canDo:"Pass along what someone said with -다고 했어요 (어렵다고 했어요)",id:"chapter-37-b1",chapterId:"chapter-37",index:0},{kind:"pattern",title:"문법 Grammar · V/A-다고 했어요",cards:[{kind:"hunt",name:"V/A-다고 했어요",sub:"Reporting what someone said",lines:[{tokens:[{pre:"친구가",mid:"",post:"",hit:!1},{pre:"내일",mid:"",post:"",hit:!1},{pre:"학교에",mid:"",post:"",hit:!1},{pre:"안",mid:"",post:"",hit:!1},{pre:"온",mid:"다고",post:"",hit:!0},{pre:"",mid:"했어요",post:".",hit:!0}],ko:"친구가 내일 학교에 안 온다고 했어요.",en:"My friend said he won't come to school tomorrow.",romanization:"chinguga naeil hakgyoe an ondago haesseoyo."},{tokens:[{pre:"엄마가",mid:"",post:"",hit:!1},{pre:"밥을",mid:"",post:"",hit:!1},{pre:"다",mid:"",post:"",hit:!1},{pre:"먹었",mid:"다고",post:"",hit:!0},{pre:"",mid:"했어요",post:".",hit:!0}],ko:"엄마가 밥을 다 먹었다고 했어요.",en:"Mom said she finished eating.",romanization:"eommaga babeul da meogeottago haesseoyo."}],rule:{name:"V/A-다고 했어요",rows:[{when:"Action verb, present — stem ends in a vowel",add:"-ㄴ다고 했어요",ex:"가다 → 간다고 했어요"},{when:"Action verb, present — stem ends in a 받침",add:"-는다고 했어요",ex:"먹다 → 먹는다고 했어요"},{when:"Adjective, present",add:"-다고 했어요",ex:"바쁘다 → 바쁘다고 했어요 / 좋다 → 좋다고 했어요"},{when:"Any verb/adjective, past",add:"-았/었다고 했어요",ex:"먹었다 → 먹었다고 했어요 / 갔다 → 갔다고 했어요"},{when:"Noun + 이다",add:"N(이)라고 했어요",ex:"학생 → 학생이라고 했어요 / 친구 → 친구라고 했어요"}]},more:{func:'Use -다고 했어요 to report a statement someone made, like English "said that …". You report the meaning, not the exact words, so you drop the original ending (요/-어) and attach -다고 to the plain stem.',keyPoint:{label:"Verbs vs. adjectives in the present",body:"Only action verbs add -ㄴ다고/-는다고 (간다고, 먹는다고). Adjectives, and all past forms, just add -다고 (바쁘다고, 먹었다고). The common slips are 먹다고 (should be 먹는다고) and 바쁜다고 (should be 바쁘다고)."},pronunciation:"In 먹는다고 the ㄱ before ㄴ turns into an ㅇ sound, so it comes out [멍는다고]."}}],canDo:"Pass along what someone said with -다고 했어요 (어렵다고 했어요)",id:"chapter-37-b2",chapterId:"chapter-37",index:1},{kind:"words",title:"단어 Words 2 · 물어보다~",cards:[{kind:"guess",word:{ko:"물어보다",romanization:"mureoboda",en:"to ask; to ask and find out",pos:"verb phrase",nuance:"묻다 is the dictionary/base verb. 물어보다 is often the natural spoken choice for asking someone."},sentence:{ko:"친구한테 시험이 언제인지 물어봤어요.",en:"I asked my friend when the exam is."},target:"물어봤",options:["to say again; to repeat","to ask; to ask and find out","said that..."],note:"Everyday spoken verb for asking."},{kind:"guess",word:{ko:"다시 말하다",romanization:"dasi malhada",en:"to say again; to repeat",pos:"verb phrase",nuance:"다시 말하다 is not just the adverb 다시. It is a practical repair phrase when reported information is unclear."},sentence:{ko:"잘 못 들었으면 다시 말해 달라고 해요.",en:"If you did not hear it well, ask them to say it again."},target:"다시 말해",options:["to ask; to ask and find out","said that...","to say again; to repeat"],note:"Useful repair phrase when reported information is unclear."},{kind:"guess",word:{ko:"숙제",romanization:"sukje",en:"homework",pos:"noun",nuance:"숙제 is Sino-Korean 宿題 — 宿 'lodging/stay overnight' + 題 'topic/problem', literally a 'problem to take home overnight', i.e. work a teacher assigns to be done outside class. The verb is locked: Koreans say 숙제를 하다 'do homework', and 숙제를 내다 means a student turns it in (while a teacher 내다 a 숙제 means 'assign/set' it — context decides). Contrast 숙제 with 공부(工夫, 'study') and 과제(課題, 'assignment/coursework'): 공부하다 is the broad act of studying anything, whereas 숙제 is a specific assigned task, and 과제 is the more formal university word for a project or paper. The big English-speaker pitfall is translating 'do my homework' as 숙제를 만들다 'make homework' (✗ — that sounds like you created the assignment) or 숙제를 공부하다 (✗); the only natural pairing is 숙제를 하다."},sentence:{ko:"내일까지 숙제를 제출하라고 하셨어요.",en:"They told us to submit the homework by tomorrow."},target:"숙제",options:["exam","homework","content; details"],note:"Classroom reporting content."},{kind:"guess",word:{ko:"시험",romanization:"siheom",en:"exam",pos:"noun",nuance:"시험 is Sino-Korean 試驗 — 試 'try/test' + 驗 'examine', literally 'a trial examination'. The collocation English speakers must memorize is 시험을 보다 — Koreans 'see' an exam, they do not 'do' it, so 시험을 하다 is wrong. Passing and failing are vivid metaphors with the particle 에: 시험에 붙다 (literally 'stick to the exam') = pass, 시험에 떨어지다 ('fall off the exam') = fail — note these take 에, not 을. Contrast 시험 with 퀴즈(quiz, a small in-class test) and with 검사(檢査, an inspection/medical test like 건강 검사): a graded school test is always 시험, never 퀴즈 unless it is a tiny informal one. The classic 직역 trap is 'take an exam' → 시험을 가지다/취하다 ✗ (English 'take' never transfers); and learners often write 시험을 통과하다, which is understandable but bookish — the everyday word is 붙다."},sentence:{ko:"시험이 언제인지 알아요?",en:"Do you know when the exam is?"},target:"시험",options:["exam","homework","content; details"],note:"Natural embedded question noun."},{kind:"guess",word:{ko:"제출하다",romanization:"jechulhada",en:"to submit",pos:"verb",nuance:"제출하다 is Sino-Korean 提出 — 提 'lift/raise up' + 出 'out' — so 'put forward, hand out', i.e. formally submit a document, application, or assignment to an authority. Its register is the key point: 제출하다 is the formal, official word, while everyday speech often just uses 내다 'to put out/hand in' — students say 숙제를 냈어요 casually but write 과제를 제출했습니다 formally. The opposite side of the transaction is 받다 'to receive'/접수하다 'to accept (a submission)'. The English-speaker pitfall: 'submit TO the office' tempts an English-style structure, but the destination simply takes 에 (사무실에 제출하다) and the document is a direct object (서류를 제출하다). As a noun+하다 verb it conjugates on 하다 (제출해요, 제출했어요, formal 제출합니다); negative/impossible split the noun (제출 안 해요, 제출 못 해요). Note pronunciation [제출하다] is straightforward, but watch the polite request form 제출해 주세요."},sentence:{ko:"숙제를 제출했냐고 물어봤어요.",en:"They asked whether I submitted the homework."},target:"제출했",options:["to convey; to pass on","to submit","said that..."],note:"A practical school/work verb for reported questions."},{kind:"payoff",line:{speaker:"지훈",ko:"내일까지 숙제를 제출하라고 하셨어요.",en:"The teacher told us to submit the homework by tomorrow."},hl:"숙제"}],canDo:"Relay an order with -(으)라고 하다 (제출하라고 했어요)",id:"chapter-37-b3",chapterId:"chapter-37",index:2},{kind:"pattern",title:"문법 Grammar · V/A-냐고 물어봤어요",cards:[{kind:"hunt",name:"V/A-냐고 물어봤어요",sub:"Reporting a question",lines:[{tokens:[{pre:"친구가",mid:"",post:"",hit:!1},{pre:"저한테",mid:"",post:"",hit:!1},{pre:"밥",mid:"",post:"",hit:!1},{pre:"먹었",mid:"냐고",post:"",hit:!0},{pre:"",mid:"물어봤어요",post:".",hit:!0}],ko:"친구가 저한테 밥 먹었냐고 물어봤어요.",en:"My friend asked me whether I'd eaten.",romanization:"chinguga jeohante bap meogeonnyago mureobwasseoyo."},{tokens:[{pre:"선생님이",mid:"",post:"",hit:!1},{pre:"학생들한테",mid:"",post:"",hit:!1},{pre:"시간이",mid:"",post:"",hit:!1},{pre:"있",mid:"냐고",post:"",hit:!0},{pre:"",mid:"물어봤어요",post:".",hit:!0}],ko:"선생님이 학생들한테 시간이 있냐고 물어봤어요.",en:"The teacher asked the students whether they had time.",romanization:"seonsaengnimi haksaengdeulhante sigani innyago mureobwasseoyo."}],rule:{name:"V/A-냐고 물어봤어요",rows:[{when:"Verb or adjective, present",add:"-냐고 물어봤어요",ex:"가다 → 가냐고 / 좋다 → 좋냐고 물어봤어요"},{when:"Any verb/adjective, past",add:"-았/었냐고 물어봤어요",ex:"먹었다 → 먹었냐고 / 갔다 → 갔냐고 물어봤어요"},{when:"Noun + 이다",add:"N(이)냐고 물어봤어요",ex:"학생 → 학생이냐고 / 친구 → 친구냐고 물어봤어요"},{when:"With a question word (누구/언제/어디 …)",add:"keep the question word + -냐고",ex:"어디 가다 → 어디 가냐고 물어봤어요"}]},more:{func:'Use -냐고 물어봤어요 (or 물었어요) to report a question someone asked — "someone asked whether/what …". The reported part ends in -냐고 no matter how polite the original question was.',keyPoint:{label:"-다고 vs. -냐고",body:"Statements use -다고 했어요; questions use -냐고 물어봤어요. The following verb is your clue: 했어요/말했어요 (said) for statements, 물어봤어요/물었어요 (asked) for questions."},pronunciation:"In 먹었냐고 the ㅆ받침 before ㄴ becomes an ㄴ sound, so it links as [머건냐고]."}}],canDo:"Relay an order with -(으)라고 하다 (제출하라고 했어요)",id:"chapter-37-b4",chapterId:"chapter-37",index:3},{kind:"words",title:"단어 Words 3 · 확인하다~",cards:[{kind:"guess",word:{ko:"확인하다",romanization:"hwaginhada",en:"to check",pos:"verb",nuance:"확인하다 (確認하다, 確 'certain/firm' + 認 'recognize') means to check, verify, or confirm that something is correct or true — facts, times, reservations, messages — making sure reality matches what you expect. The crucial contrast is with 찾다, which English 'check' can blur: 찾다 is 'to look FOR / search' something not yet located (열쇠를 찾다, 'look for the keys'), whereas 확인하다 is 'to verify' something you can already see (열쇠가 있는지 확인하다, 'check whether the keys are there'). It also differs from 알아보다 ('look into/inquire to find out', 가격을 알아보다). It's a regular noun+하다 verb: 확인하 + 여요 → 확인해요, past 확인했어요, with 안/못 splitting before 하다 (확인 안 해요, 확인 못 해요). English-speaker pitfall: 'check the box' or 'check off' is NOT 확인하다 — ticking a box is 체크하다/표시하다; and 'check out a book/check out (a hotel)' uses 빌리다 or 체크아웃하다, not 확인하다, which strictly means 'verify/confirm'."},sentence:{ko:"몇 시에 만나는지 확인해 주세요.",en:"Please check what time we are meeting."},target:"확인해",options:["to check","to convey; to pass on","said that..."],note:"Often follows an embedded question."},{kind:"guess",word:{ko:"내용",romanization:"naeyong",en:"content; details",pos:"noun",nuance:"내용 (內容, 內 'inside' + 容 'contain') is the substance or gist inside something — a book, message, lecture, contract — as opposed to its outer form. The sharp contrast is 내용 (what it says) vs 형식 (the form/format): a report can have weak 내용 but proper 형식. Don't confuse it with a physical container either; the box itself is 상자/봉투, while 내용물 specifically means the physical 'contents' (items) inside a package. Typical partners: 내용을 이해하다/정리하다/확인하다, 내용이 어렵다/풍부하다, 회의 내용, 문자 내용. The English-speaker pitfall is particle choice driven by the adjective: 'the content is hard' becomes 내용이 어렵다 ✓, not 내용을 어렵다 ✗ — 를/을 attaches only to action verbs like 이해하다, never to descriptive 어렵다."},sentence:{ko:"메시지 내용을 확인했어요.",en:"I checked the message content."},target:"내용",options:["content; details","homework","exam"],note:"What was said or written."},{kind:"guess",word:{ko:"전하다",romanization:"jeonhada",en:"to convey; to pass on",pos:"verb",nuance:"전하다 (Sino-Korean 傳, 'transmit/hand down') means relaying something from a sender to a receiver: a message, regards, an item, news, or even a feeling, so the receiver takes 에게/한테 or honorific 께 while the thing passed takes 을/를. The nearest rival is 말하다, but 말하다 is you simply saying something yourself, whereas 전하다 stresses that you are the go-between carrying someone else's words or goods to a third party — '사장님이 잘했다고 전하래요' (the boss told me to tell you 'well done'). Everyday set phrases include 안부를 전하다 (send one's regards), 말씀 전해 주세요 (please pass on the message), and 소식을 전하다 (deliver news). The big English-speaker trap is hearing 전 and thinking 전화하다 ('to make a phone call'): they share the 전 syllable but are unrelated, so '전해 주세요' is 'please relay it', not 'please call them'."},sentence:{ko:"제가 친구한테 내용을 전할게요.",en:"I will pass the details on to my friend."},target:"전할",options:["to convey; to pass on","to submit","to check"],note:"The communication job of reported speech."}],canDo:"Report a question someone asked with -냐고 물어봤어요",id:"chapter-37-b5",chapterId:"chapter-37",index:4},{kind:"pattern",title:"문법 Grammar · V-는지 / A-(으)ㄴ지 / N인지",cards:[{kind:"hunt",name:"V-는지 / A-(으)ㄴ지 / N인지",sub:'"whether / what / where …" inside a sentence',lines:[{tokens:[{pre:"친구가",mid:"",post:"",hit:!1},{pre:"어디",mid:"",post:"",hit:!1},{pre:"사",mid:"는지",post:"",hit:!0},{pre:"몰라요.",mid:"",post:"",hit:!1}],ko:"친구가 어디 사는지 몰라요.",en:"I don't know where my friend lives.",romanization:"chinguga eodi saneunji mollayo."},{tokens:[{pre:"저",mid:"",post:"",hit:!1},{pre:"사람이",mid:"",post:"",hit:!1},{pre:"누구",mid:"인지",post:"",hit:!0},{pre:"아세요?",mid:"",post:"",hit:!1}],ko:"저 사람이 누구인지 아세요?",en:"Do you know who that person is?",romanization:"jeo sarami nuguinji aseyo?"}],rule:{name:"V-는지 / A-(으)ㄴ지 / N인지",rows:[{when:"Action verb, present",add:"-는지",ex:"가다 → 가는지 / 먹다 → 먹는지 모르겠어요"},{when:"Adjective, present",add:"-(으)ㄴ지",ex:"좋다 → 좋은지 / 바쁘다 → 바쁜지 모르겠어요"},{when:"Any verb/adjective, past",add:"-았/었는지",ex:"먹었다 → 먹었는지 / 갔다 → 갔는지 모르겠어요"},{when:"Noun + 이다",add:"N인지",ex:"학생 → 학생인지 / 누구 → 누구인지 모르겠어요"}]},more:{func:`Use -는지/-(으)ㄴ지/-인지 to tuck a question inside a bigger sentence — "I don't know whether/what/where …", "Do you know if …?". It turns the question into a clause that then connects to verbs like 알다, 모르다, 궁금하다.`,keyPoint:{label:"Adjective -(으)ㄴ지 vs. verb -는지",body:"In the present, adjectives take -(으)ㄴ지 (좋은지, 바쁜지) and action verbs take -는지 (가는지, 먹는지). In the past, both use -았/었는지 (좋았는지, 갔는지), so the split only matters in the present."},pronunciation:"먹는지 comes out [멍는지] (ㄱ → ㅇ before ㄴ); in 좋은지 the ㅎ drops, so it sounds like [조은지]."}},{kind:"drill",prompt:"I wonder whether this movie is good.",sentence:"이 영화가 재미있___ 궁금해요.",options:[{text:"는지",ok:!0},{text:"인지",ok:!1}],explanation:"재미있다 takes -는지 (not -(으)ㄴ지) because of the 있다 part."}],canDo:"Report a question someone asked with -냐고 물어봤어요",id:"chapter-37-b6",chapterId:"chapter-37",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A classmate passes along what the teacher said after class.",lines:[{speaker:"민서",ko:"선생님이 뭐라고 하셨어요?",en:"What did the teacher say?",romanization:"seonsaengnimi mworago hasyeosseoyo?"},{speaker:"지훈",ko:"내일까지 숙제를 제출하라고 하셨어요.",en:"The teacher told us to submit the homework by tomorrow.",romanization:"naeilkkaji sukjereul jechulharago hasyeosseoyo."},{speaker:"민서",ko:"시험이 언제인지도 말씀하셨어요?",en:"Did the teacher also say when the exam is?",romanization:"siheomi eonjeinjido malsseumhasyeosseoyo?"},{speaker:"지훈",ko:"네, 금요일에 본다고 하셨어요.",en:"Yes, the teacher said we will take it on Friday.",romanization:"ne, geumyoire bondago hasyeosseoyo."},{speaker:"민서",ko:"친구는 뭐라고 물어봤어요?",en:"What did your friend ask?",romanization:"chinguneun mworago mureobwasseoyo?"},{speaker:"지훈",ko:"몇 시에 만나냐고 물어봤어요.",en:"They asked what time we are meeting.",romanization:"myeot sie mannanyago mureobwasseoyo."}]},{kind:"order",prompt:"Build: 'My friend asked what time we meet.'",tokens:["친구가","몇 시에 만나냐고","물어봤어요"],correct:"친구가 몇 시에 만나냐고 물어봤어요",explanation:"Reported questions use -냐고 물어봤어요. The embedded question keeps 몇 시에 inside the reported content."}],canDo:"Pass along what someone said with -다고 했어요 (어렵다고 했어요)",id:"chapter-37-b7",chapterId:"chapter-37",index:6},{kind:"reading",title:"읽기 Reading · 선생님이 뭐라고 하셨어요?",cards:[{kind:"read",title:"선생님이 뭐라고 하셨어요?",chunks:["수업이 끝난 뒤 친구에게 내용을 전할 때는 원래 문장이 어떤 종류였는지 먼저 봐야 해요. 선생님이 '금요일에 시험을 봐요'라고 말한 내용은 '금요일에 본다고 하셨어요'로 전할 수 있어요. 질문을 전할 때는 '-냐고'를 써요.","그래서 '몇 시에 만나요?'는 '몇 시에 만나냐고 물어봤어요'가 돼요. 하지만 누가 질문한 것이 아니라 내가 답을 알고 싶은 상황이면 '-는지'가 자연스러워요. '시험이 언제인지 알아요?'처럼 큰 문장 안에 질문을 넣는 거예요."],translation:"When passing along class information, first identify the original sentence type. Statements use -다고 했어요, questions use -냐고 물어봤어요, and embedded questions use -는지 inside verbs like know, not know, or check.",qas:[{q:"원래 문장이 statement이면 어떤 표현을 써요?",a:"-다고 했어요를 써요."},{q:"질문을 전할 때는 어떤 표현을 써요?",a:"-냐고 물어봤어요를 써요."},{q:"큰 문장 안에 질문을 넣을 때는 어떤 표현을 써요?",a:"-는지를 써요."}]}],canDo:"Relay an order with -(으)라고 하다 (제출하라고 했어요)",id:"chapter-37-b8",chapterId:"chapter-37",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"The teacher said, '금요일에 시험을 봐요.' Which report is correct?",sentence:null,options:[{text:"금요일에 본다고 하셨어요.",ok:!0},{text:"금요일에 보냐고 하셨어요.",ok:!1},{text:"금요일에 보라고 하셨어요.",ok:!1}],explanation:"The original is a statement, so use -다고 하셨어요."},{kind:"drill",prompt:"Your friend asked, '몇 시에 만나요?' Which report is correct?",sentence:null,options:[{text:"몇 시에 만나냐고 물어봤어요.",ok:!0},{text:"몇 시에 만난다고 물어봤어요.",ok:!1},{text:"몇 시에 만나라고 물어봤어요.",ok:!1}],explanation:"The original is a question, so use -냐고 물어봤어요."},{kind:"drill",prompt:"Choose the embedded question form.",sentence:null,options:[{text:"시험이 언제인지 알아요?",ok:!0},{text:"시험이 언제냐고 알아요?",ok:!1},{text:"시험이 언제라고 알아요?",ok:!1}],explanation:"알다 takes the embedded question form -는지/-인지."},{kind:"drill",prompt:"선생님___ 숙제를 제출하라고 하셨어요. (The teacher told us to submit homework.)",sentence:null,options:[{text:"께서",ok:!0},{text:"께",ok:!1},{text:"를",ok:!1}],explanation:"선생님 is the respected subject who gave the instruction, so use 께서. 께 would mark a recipient instead."},{kind:"order",prompt:"Build: 'My friend asked what time we meet.'",tokens:["친구가","몇 시에 만나냐고","물어봤어요"],correct:"친구가 몇 시에 만나냐고 물어봤어요",explanation:"Reported questions use -냐고 물어봤어요. The embedded question keeps 몇 시에 inside the reported content."},{kind:"drill",prompt:"Which is the spoken short form of 선생님이 내일 시험이 있다고 했어요?",sentence:null,options:[{text:"내일 시험이 있대요.",ok:!0},{text:"내일 시험이 있냐고요.",ok:!1},{text:"내일 시험이 있으라고요.",ok:!1}],explanation:"-대요 is the common spoken contraction for “they say that.” 있냐고요 would report or repeat a question."}],canDo:"Report a question someone asked with -냐고 물어봤어요",id:"chapter-37-b9",chapterId:"chapter-37",index:8}]},{id:"chapter-38",number:38,title:"Stacked Noun Modifiers: Packing a Clause Before a Noun · Passive Verbs (이/히/리/기): Focusing on What Happens, Not the Doer",goal:"Unpack long noun phrases such as 어제 올라온 공지 and 변경된 일정.",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · 올라온 공지~",cards:[{kind:"guess",word:{ko:"올라온 공지",romanization:"ollaon gongji",en:"a notice that was posted",pos:"noun phrase",nuance:"올라온 is not a separate full sentence here. It sits before 공지 and tells you which notice."},sentence:{ko:"어제 올라온 공지를 확인했어요.",en:"I checked the notice that was posted yesterday."},target:"올라온 공지",options:["a notice that was posted","to be read / to make someone read","to be seen / to be visible"],note:"A compact noun phrase: 올라온 tells you which 공지."},{kind:"guess",word:{ko:"변경된 일정",romanization:"byeongyeongdoen iljeong",en:"a changed schedule",pos:"noun phrase",nuance:"변경된 focuses on the resulting state. It sounds natural in notices, emails, and announcements."},sentence:{ko:"변경된 일정이 공지에 나왔어요.",en:"The changed schedule appeared in the notice."},target:"변경된 일정",options:["a changed schedule","to be read / to make someone read","to be seen / to be visible"],note:"변경된 focuses on the resulting state."},{kind:"guess",word:{ko:"제출할 보고서",romanization:"jechulhal bogoseo",en:"a report to submit",pos:"noun phrase",nuance:"제출할 points forward. It differs from 제출한 보고서, a report that was already submitted."},sentence:{ko:"내일 제출할 보고서를 다시 검토했어요.",en:"I reviewed the report I will submit tomorrow."},target:"제출할 보고서",options:["to be read / to make someone read","a report to submit","to be seen / to be visible"],note:"제출할 marks a future action attached to 보고서."},{kind:"guess",word:{ko:"읽히다",romanization:"ilkida",en:"to be read / to make someone read",pos:"verb",nuance:"With texts, 읽히다 often describes how easily something is read or understood."},sentence:{ko:"이 책은 초급 수업에서 자주 읽혀요.",en:"This book is often read in beginner classes."},target:"읽혀",options:["to be read / to make someone read","to be seen / to be visible","to be sold"],note:"Passive reading: the book is the subject."},{kind:"guess",word:{ko:"보이다",romanization:"boida",en:"to be seen / to be visible",pos:"verb",nuance:"보이다 is the passive/spontaneous counterpart of 보다 (to look): something enters your field of vision on its own, so the thing seen takes 이/가 (산이 보여요 = 'the mountain is visible'), NOT 을/를. The 요-form contracts 보이-+-어요 → 보여요 (past 보였어요). The sharp contrast learners need is 보이다 vs 보다: 보다 is an active choice ('I look at / watch'), 보이다 is involuntary ('it is seen / comes into view'). A second, very frequent meaning is 'to look/seem' — adjective stem + 보이다 (행복해 보여요 'you look happy'; 비싸 보여요 'it looks expensive'); here English 'looks' maps cleanly. With 주다 it flips to active 'show' (보여 주다). The English-speaker pitfall: saying 산을 보여요 to mean 'I see the mountain' — that is wrong; use 산이 보여요 (it is visible) or 산을 봐요 (I look at it)."},sentence:{ko:"멀리서 바다가 보여요.",en:"The sea is visible from far away."},target:"보여",options:["to be read / to make someone read","to be sold","to be seen / to be visible"],note:"The thing visible becomes the subject."},{kind:"payoff",line:{speaker:"민서",ko:"어제 올라온 공지 봤어요?",en:"Did you see the notice posted yesterday?"},hl:"올라온 공지"}],canDo:"Pack a whole clause before a noun to describe it (어제 올라온 공지, 변경된 일정)",id:"chapter-38-b1",chapterId:"chapter-38",index:0},{kind:"pattern",title:"문법 Grammar · Stacked Noun Modifiers: Packing a Clause Before a Noun",cards:[{kind:"teach",name:"Stacked Noun Modifiers: Packing a Clause Before a Noun",sub:"",rows:[{when:"Past action (verb)",add:"-(으)ㄴ",ex:"읽다 → 읽은 (책) / 주다 → 친구가 준 (선물)"},{when:"Present / ongoing (verb)",add:"-는",ex:"먹다 → 먹는 (사람) / 보다 → 내가 보는 (영화)"},{when:"Future / not-yet (verb)",add:"-(으)ㄹ",ex:"가다 → 갈 (곳) / 만나다 → 내일 만날 (친구)"},{when:"Adjective describing a noun",add:"-(으)ㄴ",ex:"예쁘다 → 예쁜 (꽃) / 비싸다 → 비싼 (가방)"}],examples:[{ko:"어제 친구가 준 책을 다 읽었어요.",en:"I finished reading the book my friend gave me yesterday.",romanization:"eoje chinguga jun chaegeul da ilgeosseoyo.",note:'준 (past modifier of 주다) packs "my friend gave" in front of 책.'},{ko:"제가 자주 가는 카페가 문을 닫았어요.",en:"The cafe I often go to closed down.",romanization:"jega jaju ganeun kapega muneul dadasseoyo.",note:"가는 (present modifier of 가다) shows an ongoing, habitual action before 카페. 문을 닫다 = to close down."}],more:{func:'In Korean a whole clause can describe a noun, but it always comes BEFORE the noun, and the verb changes into a modifier form ending in -ㄴ/-은/-는/-(으)ㄹ. So "the book my friend gave me yesterday" becomes 어제 친구가 준 책 — everything piles up in front of 책.',keyPoint:{label:"Past vs. present vs. future modifier",body:"The modifier ending carries the TIME, so the final verb of the sentence can stay simple: 친구가 준 책 (already gave), 친구가 주는 책 (is giving), 친구가 줄 책 (will give). Pick the wrong one and the meaning of the whole noun phrase changes."},pronunciation:"읽은 sounds like [일근] — the ㄺ cluster splits and ㄱ links to 은. 많아요 sounds like [마나요], with the ㅎ in ㄶ dropping out."}}],canDo:"Pack a whole clause before a noun to describe it (어제 올라온 공지, 변경된 일정)",id:"chapter-38-b2",chapterId:"chapter-38",index:1},{kind:"words",title:"단어 Words 2 · 팔리다~",cards:[{kind:"guess",word:{ko:"팔리다",romanization:"pallida",en:"to be sold",pos:"verb",nuance:"Use 팔리다 when the seller is not important or not known."},sentence:{ko:"인기 상품이 하루 만에 다 팔렸어요.",en:"The popular item sold out in one day."},target:"팔렸",options:["to be read / to make someone read","to be sold","to be seen / to be visible"],note:"The product is the subject; the seller is not important."},{kind:"guess",word:{ko:"잡히다",romanization:"japida",en:"to be caught / to be set",pos:"verb",nuance:"잡히다 is natural for appointments, schedules, reservations, and plans."},sentence:{ko:"회의 일정이 다음 주로 잡혔어요.",en:"The meeting schedule was set for next week."},target:"잡혔",options:["to be caught / to be set","to be read / to make someone read","to be seen / to be visible"],note:"For schedules, 잡히다 means it has been fixed/set."},{kind:"guess",word:{ko:"닫히다",romanization:"datida",en:"to be closed",pos:"verb",nuance:"Use 닫히다 when you care about the closed state/result more than the person closing it."},sentence:{ko:"문이 자동으로 닫혔어요.",en:"The door closed automatically."},target:"닫혔",options:["to be closed","to be read / to make someone read","to be seen / to be visible"],note:"The door is the subject; the closing result is highlighted."},{kind:"guess",word:{ko:"먹이다",romanization:"meogida",en:"to feed / make someone eat",pos:"verb",nuance:"The subject is the causer, not the person eating."},sentence:{ko:"엄마가 아이에게 약을 먹였어요.",en:"The mother made the child take medicine."},target:"먹였",options:["to be seen / to be visible","to be sold","to feed / make someone eat"],note:"Causative: someone causes another person to eat/take something."},{kind:"guess",word:{ko:"앉히다",romanization:"anjhida",en:"to seat someone",pos:"verb",nuance:"앉다 is what the person does; 앉히다 is what someone else does to seat them."},sentence:{ko:"직원이 손님을 창가 자리에 앉혔어요.",en:"The employee seated the guest by the window."},target:"앉혔",options:["to seat someone","to be seen / to be visible","to be sold"],note:"Causative: someone makes/lets another person sit."}],canDo:"Describe what happens to something with passive verbs (바뀌다, 닫히다, 팔리다)",id:"chapter-38-b3",chapterId:"chapter-38",index:2},{kind:"pattern",title:"문법 Grammar · Passive Verbs (이/히/리/기): Focusing on What Happens, Not the Doer",cards:[{kind:"teach",name:"Passive Verbs (이/히/리/기): Focusing on What Happens, Not the Doer",sub:"",rows:[{when:"add -이-",add:"보다→보이다, 놓다→놓이다, 쌓다→쌓이다",ex:"산이 보여요. (You can see the mountain.)"},{when:"add -히-",add:"닫다→닫히다, 막다→막히다, 잡다→잡히다",ex:"문이 닫혔어요. (The door got closed.)"},{when:"add -리-",add:"열다→열리다, 듣다→들리다, 팔다→팔리다",ex:"음악이 들려요. (You can hear music.)"},{when:"add -기-",add:"끊다→끊기다, 쫓다→쫓기다, 안다→안기다",ex:"전화가 끊겼어요. (The call got cut off.)"}],examples:[{ko:"문이 갑자기 닫혔어요.",en:"The door suddenly closed.",romanization:"muni gapjagi dachyeosseoyo.",note:"닫히다 (passive of 닫다) — nobody is named as the one closing it; we just see the result."},{ko:"여기에서 바다가 잘 보여요.",en:"You can see the sea well from here.",romanization:"yeogieseo badaga jal boyeoyo.",note:'보이다 (passive of 보다) means "is visible," focusing on what shows up, not who looks.'}],more:{func:"Passive verbs describe what HAPPENS to something without saying who did it — the focus moves to the result or the affected thing. You build them by adding -이-, -히-, -리-, or -기- inside certain action verbs: 열다 (to open) → 열리다 (to be opened / to open on its own).",keyPoint:{label:"Active vs. passive subject marking",body:"In an active sentence the doer takes 이/가 and the thing takes 을/를: 제가 문을 열었어요. In the passive, the affected thing becomes the 이/가 subject and the doer usually drops out: 문이 열렸어요. If you do keep the doer, it takes 에 or 한테/에게: 문이 바람에 열렸어요 (The door opened from the wind)."},pronunciation:"닫히다 sounds like [다치다] — ㄷ and ㅎ blend into ㅊ. 막히다 sounds like [마키다], where ㄱ and ㅎ blend into ㅋ."}}],canDo:"Describe what happens to something with passive verbs (바뀌다, 닫히다, 팔리다)",id:"chapter-38-b4",chapterId:"chapter-38",index:3},{kind:"words",title:"단어 Words 3 · 입히다~",cards:[{kind:"guess",word:{ko:"입히다",romanization:"ipida",en:"to dress someone / put clothes on someone",pos:"verb",nuance:"입다 is wear; 입히다 is dress someone else."},sentence:{ko:"아버지가 아기에게 코트를 입혔어요.",en:"The father put a coat on the baby."},target:"입혔",options:["to be seen / to be visible","to be sold","to dress someone / put clothes on someone"],note:"Causative pair with 입다."},{kind:"guess",word:{ko:"알리다",romanization:"allida",en:"to inform / let know",pos:"verb",nuance:"알리다 is the causative of 알다 ('to know'), so literally 'to make (someone) know' — you give a piece of information to a person, who takes 에게/한테, while the fact taught takes 을/를. The form you will reach for ten times a day is 알려 주세요 ('please let me know'), used to ask for an address, a time, a price, or any update. The near-synonym 가르치다 also means 'let know', but 가르치다 leans toward teaching a skill or directions ('역으로 가는 길 좀 가르쳐 주세요'), while 알리다 is just transmitting a fact ('결과를 알려 주세요'). The classic learner error is using plain 알다: 알아요 means 'I know' (a state), and you cannot make a request with it — you must use the causative 알려 주세요 to mean 'inform me'. Beyond person-to-person, 알리다 also covers public announcing — '진실을 세상에 알리다' (reveal the truth to the world)."},sentence:{ko:"안내 문자가 변경 사항을 알려 줬어요.",en:"The 안내 text message informed me of the changes."},target:"알려",options:["to be read / to make someone read","to be seen / to be visible","to inform / let know"],note:"Causative-like lexical verb: make information known."},{kind:"guess",word:{ko:"문장",romanization:"munjang",en:"sentence",pos:"noun",nuance:"문장(文章)은 '글월 문 + 글 장'으로, 주어와 서술어를 갖춰 생각을 완결되게 표현하는 한 덩어리의 말이에요. 비슷해 보이는 '글'은 문장이 여러 개 모인 더 큰 글덩이(에세이·기사 전체)를 뜻하고, '문구'는 짧은 어구나 문장 한 토막을 가리켜서 범위가 달라요. 또 '단어/낱말'은 더 작은 단위라, 낱말 하나만으로는 '문장'이 되지 않아요. 영어 화자는 sentence를 무조건 '문장'으로 옮기지만, 표지판의 'No smoking' 같은 짧은 문구는 한국어로 '문구'가 더 자연스러울 때가 있어요. 또 sentence에 '형(刑)을 선고하다'라는 뜻도 있는데 그건 한국어 '문장'과 전혀 무관하니 직역하면 안 돼요. '문장을 만들다/짓다/외우다/읽다'와 잘 어울립니다."},sentence:{ko:"긴 문장은 먼저 명사구를 찾아서 읽어요.",en:"For long sentences, first find the noun phrases."},target:"문장",options:["news article / report","sentence","a notice that was posted"],note:"This chapter is about unpacking compressed sentence structure."},{kind:"guess",word:{ko:"기사",romanization:"gisa",en:"news article / report",pos:"noun",nuance:"기사 (記事, 記 'record/write down' + 事 'matter, event') means a news article or report — a single written piece of journalism in a newspaper, magazine, or online; the hanja literally means 'a written record of an event'. Distinguish it carefully from neighbors: 언론 is the press as an institution, 보도 (報道) is the ACT of reporting, and 기사 is the concrete written unit of content that results. A crucial English-speaker pitfall is the homonym trap: 기사 is also a completely separate word meaning 'driver' (司機/운전기사) — and historically 'knight' (騎士) — so 택시 기사 is 'taxi driver', not 'taxi article'; only context tells which 기사 is meant. Natural collocations: 기사를 쓰다, 기사가 나다, 신문 기사, 기사를 검색하다. Don't reach for 기사 when you mean the abstract media institution — that is 언론."},sentence:{ko:"기사에는 변경된 일정과 새 규칙이 함께 나왔어요.",en:"The article included the changed schedule and the new rule together."},target:"기사",options:["sentence","a notice that was posted","news article / report"],note:"News prose often uses noun modification and passive/result forms."},{kind:"payoff",line:{speaker:"지훈",ko:"저는 그 문장이 처음에 잘 안 읽혔어요.",en:"At first, that sentence did not read clearly to me."},hl:"문장"}],canDo:"Say someone makes/lets another do something with causatives (알리다, 먹이다)",id:"chapter-38-b5",chapterId:"chapter-38",index:4},{kind:"pattern",title:"문법 Grammar · Causative Verbs (이/히/리/기/우): Making or Helping Someone Do Something",cards:[{kind:"teach",name:"Causative Verbs (이/히/리/기/우): Making or Helping Someone Do Something",sub:"",rows:[{when:"add -이-",add:"먹다→먹이다, 보다→보이다, 죽다→죽이다",ex:"아기에게 밥을 먹여요. (I feed the baby rice.)"},{when:"add -히-",add:"입다→입히다, 앉다→앉히다, 읽다→읽히다",ex:"아이에게 옷을 입혀요. (I dress the child.)"},{when:"add -리-",add:"울다→울리다, 살다→살리다, 알다→알리다",ex:"동생을 울렸어요. (I made my sibling cry.)"},{when:"add -기-/-우-",add:"웃다→웃기다, 자다→재우다, 타다→태우다",ex:"아기를 재웠어요. (I put the baby to sleep.)"}],examples:[{ko:"엄마가 아기에게 밥을 먹여요.",en:"The mom feeds the baby rice.",romanization:"eommaga agiege babeul meogyeoyo.",note:"먹이다 (causative of 먹다) = make the baby eat; the eater takes 에게/한테."},{ko:"아이에게 따뜻한 옷을 입혔어요.",en:"I dressed the child in warm clothes.",romanization:"aiege ttatteutan oseul iphyeosseoyo.",note:"입히다 (causative of 입다) — the parent makes the child wear the clothes."}],more:{func:"Causative verbs say that the subject CAUSES another person or thing to do or undergo the action. You build them by adding -이-, -히-, -리-, -기-, or -우- inside the verb: 먹다 (to eat) → 먹이다 (to feed = make someone eat).",keyPoint:{label:"Causative vs. plain verb — who acts",body:"Plain 자다 means the subject sleeps (아기가 자요 = the baby sleeps). Causative 재우다 means the subject makes someone else sleep (엄마가 아기를 재워요 = Mom puts the baby to sleep). The original doer (the baby) moves from the 이/가 subject to a 을/를 (or 에게) slot — the new subject is the cause."},pronunciation:"입히다 sounds like [이피다] — ㅂ and ㅎ blend into ㅍ. 읽히다 sounds like [일키다], where the ㄱ in the ㄺ cluster joins ㅎ to make ㅋ."}}],canDo:"Say someone makes/lets another do something with causatives (알리다, 먹이다)",id:"chapter-38-b6",chapterId:"chapter-38",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Minseo reads a school portal notice and explains the changed presentation schedule to Jihoon.",lines:[{speaker:"민서",ko:"어제 올라온 공지 봤어요?",en:"Did you see the notice posted yesterday?",romanization:"eoje ollaon gongji bwasseoyo?"},{speaker:"지훈",ko:"네, 발표 시간이 다음 주로 잡혔더라고요.",en:"Yes, the presentation time was set for next week.",romanization:"ne, balpyo sigani daeum juro japhyeotdeoragoyo."},{speaker:"민서",ko:"변경된 일정이 표 아래에 작게 쓰여 있었어요.",en:"The changed schedule was written in small print below the table.",romanization:"byeongyeongdoen iljeongi pyo araee jakge sseuyeo isseosseoyo."},{speaker:"지훈",ko:"저는 그 문장이 처음에 잘 안 읽혔어요.",en:"At first, that sentence did not read clearly to me.",romanization:"jeoneun geu munjangi cheoeume jal an ilkhyeosseoyo."},{speaker:"민서",ko:"담당자가 학생들을 앞자리에 앉힌다는 내용도 있었어요.",en:"It also said the staff would seat students in the front rows.",romanization:"damdangjaga haksaengdeureul apjarie anjhindaneun naeyongdo isseosseoyo."},{speaker:"지훈",ko:"이런 공지는 누가 했는지보다 뭐가 바뀌었는지가 중요하네요.",en:"For notices like this, what changed matters more than who did it.",romanization:"ireon gongjineun nuga haenneunjiboda mwoga bakkwieonneunjiga jungyohaneyo."}]},{kind:"order",prompt:"Build: 'the schedule changed today' as a noun phrase",tokens:["오늘","변경된","일정"],correct:"오늘 변경된 일정",explanation:"Korean packs the description before the noun. 변경된 comes before 일정 to make one noun phrase."}],canDo:"Pack a whole clause before a noun to describe it (어제 올라온 공지, 변경된 일정)",id:"chapter-38-b7",chapterId:"chapter-38",index:6},{kind:"reading",title:"읽기 Reading · 어제 올라온 공지에서 변경된 일정 보기",cards:[{kind:"read",title:"어제 올라온 공지에서 변경된 일정 보기",chunks:["학교나 회사 공지는 짧아 보여도 정보가 압축되어 있는 경우가 많아요. '어제 올라온 공지'는 '공지가 어제 올라왔어요'라는 문장을 명사 앞에 붙인 표현이고, '변경된 일정'은 이미 바뀐 결과를 일정 앞에 붙인 표현이에요. 이런 문장을 읽을 때는 끝에 있는 명사를 먼저 찾으세요.","공지인지, 일정인지, 문장인지, 내용인지 확인한 다음 앞에 붙은 말을 풀어 보면 훨씬 잘 읽혀요. 또 '발표 시간이 다음 주로 잡혔어요'처럼 피동형이 쓰이면 누가 정했는지보다 결과가 중요하다는 뜻으로 읽으면 됩니다."],translation:"Notices often compress information into noun phrases. First find the final noun, then unpack the words before it. Passive/result forms like 잡히다 focus on the result, not on who caused it.",qas:[{q:"긴 명사구를 읽을 때 무엇을 먼저 찾아야 해요?",a:"끝에 있는 명사를 먼저 찾아야 해요."},{q:"변경된 일정은 어떤 뜻이에요?",a:"이미 바뀐 일정이라는 뜻이에요."},{q:"잡혔어요 같은 피동형은 무엇을 더 강조해요?",a:"누가 했는지보다 결과를 더 강조해요."}]}],canDo:"Describe what happens to something with passive verbs (바뀌다, 닫히다, 팔리다)",id:"chapter-38-b8",chapterId:"chapter-38",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which phrase means “the notice posted yesterday”?",sentence:null,options:[{text:"어제 올라온 공지",ok:!0},{text:"어제 올리는 공지",ok:!1},{text:"어제 올라갈 공지",ok:!1}],explanation:"올라온 is a completed-action modifier attached to 공지."},{kind:"drill",prompt:"Which sentence focuses on the schedule being set, not who set it?",sentence:null,options:[{text:"발표 시간이 다음 주로 잡혔어요.",ok:!0},{text:"발표 시간이 다음 주를 잡았어요.",ok:!1},{text:"발표 시간을 다음 주가 잡았어요.",ok:!1}],explanation:"잡히다 makes the schedule the subject and highlights the result."},{kind:"drill",prompt:"Which sentence uses a causative verb naturally?",sentence:null,options:[{text:"직원이 손님을 창가 자리에 앉혔어요.",ok:!0},{text:"직원이 손님이 창가 자리에 앉았어요.",ok:!1},{text:"직원이 손님을 창가 자리에 앉았어요.",ok:!1}],explanation:"앉히다 means someone causes another person to sit."},{kind:"drill",prompt:"공지___ 올라왔어요. (The notice was posted.)",sentence:null,options:[{text:"가",ok:!0},{text:"를",ok:!1},{text:"에",ok:!1}],explanation:"올라오다 describes the notice appearing or being posted, so 공지 is the subject. 를 would make it an object of someone else’s action."},{kind:"order",prompt:"Build: 'the schedule changed today' as a noun phrase",tokens:["오늘","변경된","일정"],correct:"오늘 변경된 일정",explanation:"Korean packs the description before the noun. 변경된 comes before 일정 to make one noun phrase."},{kind:"drill",prompt:"Which sentence uses a causative verb naturally?",sentence:null,options:[{text:"직원이 손님을 자리에 앉혔어요.",ok:!0},{text:"손님이 자리에 앉혔어요.",ok:!1},{text:"자리가 손님을 앉았어요.",ok:!1}],explanation:"앉히다 means to seat someone or make/help someone sit. 손님 is the person being seated."}],canDo:"Say someone makes/lets another do something with causatives (알리다, 먹이다)",id:"chapter-38-b9",chapterId:"chapter-38",index:8}]},{id:"chapter-39",number:39,title:"V-(으)ㄹ 수밖에 없다 · V-(으)ㄹ 리가 없다",goal:"Use -(으)ㄹ 수밖에 없다 for a no-choice situation.",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · 수밖에 없다~",cards:[{kind:"guess",word:{ko:"수밖에 없다",romanization:"subakke eopda",en:"to have no choice but to",pos:"bound expression",nuance:"수밖에 없다 is resignation to the only remaining option, not inability."},sentence:{ko:"마감이 오늘이라서 야근할 수밖에 없어요.",en:"The deadline is today, so we have no choice but to work late."},target:"수밖에 없어",options:["to have no choice but to","there is no way that","it cannot be helped"],note:"No-choice situation caused by a real constraint."},{kind:"guess",word:{ko:"리가 없다",romanization:"riga eopda",en:"there is no way that",pos:"bound expression",nuance:"리가 없다 carries confidence or emotional conviction. It is not a neutral maybe-not."},sentence:{ko:"지금 포기할 리가 없어요.",en:"There is no way we would give up now."},target:"리가 없어",options:["to have no choice but to","there is no way that","to be only; nothing but"],note:"Strong disbelief, not a soft guess."},{kind:"guess",word:{ko:"뿐이다",romanization:"ppunida",en:"to be only; nothing but",pos:"bound expression",nuance:"뿐이다 closes the scope. It differs from 뿐만 아니라, which opens the sentence to an additional point."},sentence:{ko:"남은 건 이 방법뿐이에요.",en:"The only thing left is this method."},target:"뿐이",options:["there is no way that","it cannot be helped","to be only; nothing but"],note:"Limits the situation to one option."},{kind:"guess",word:{ko:"어쩔 수 없죠",romanization:"eojjeol su eopsjyo",en:"it cannot be helped",pos:"expression",nuance:"Casual-polite phrase for gracefully accepting something outside your control — a verbal shrug built from 어찌하다 ('to do how/what') contracted to 어쩌다 → 어쩔 수 없다 ('there's no way to do anything about it'). The -죠 softens the inevitability with 'right? / don't you agree?' — making the resignation feel communal rather than bitter. The closest near-synonym is 할 수 없죠, nearly interchangeable in most situations. The sharper contrast is with 포기하다 ('to give up'): 어쩔 수 없죠 is passive ACCEPTANCE of a situation that was never in your hands, while 포기하다 is an ACTIVE choice to stop something you could have continued. Tone is everything: said calmly it reads as mature and easygoing; said with a sharp sigh or flat affect, it tips into passive-aggressive 'fine, whatever.' The adverb variant 어쩔 수 없이 is a separate form that modifies verbs ('I unavoidably went') and cannot substitute for the standalone phrase."},sentence:{ko:"마감이 오늘이면 어쩔 수 없죠.",en:"If the deadline is today, it cannot be helped."},target:"어쩔 수 없죠",options:["to have no choice but to","there is no way that","it cannot be helped"],note:"Accepts the constraint."},{kind:"guess",word:{ko:"마감",romanization:"magam",en:"deadline; closing date",pos:"noun",nuance:"마감 is a native Korean noun (from the verb 막다 'to block/close off') meaning the point at which something is sealed shut: a report's due date, an application cutoff, a shop's last order, even a magazine going to press. The near-synonym confusion is with 기한 and 데드라인: 기한 (期限) is the dry, official 'time limit/term' you see on documents (제출 기한), while 마감 feels more like the live moment things close, and 데드라인 is a borrowed buzzword. Its signature collocation is the idiom 마감에 쫓기다 (chased by the deadline), the universal way to describe last-minute panic. The English-speaker pitfall is mapping 'meet a deadline' onto 만나다 ('meet a person'): you do NOT 마감을 만나다 — you 마감을 지키다 (keep/protect it). Note 지키다 is the same verb used for keeping a promise (약속을 지키다), which is the right mental image."},sentence:{ko:"마감이 오늘이라서 선택지가 별로 없어요.",en:"The deadline is today, so there are not many choices."},target:"마감",options:["deadline; closing date","method; way","situation; circumstances"],note:"The pressure that creates the no-choice frame."},{kind:"payoff",line:{speaker:"민서",ko:"마감이 오늘이라서 야근할 수밖에 없어요.",en:"The deadline is today, so we have no choice but to work late."},hl:"마감"}],canDo:"Say I have no other option with -(으)ㄹ 수밖에 없다 (야근할 수밖에 없어요)",id:"chapter-39-b1",chapterId:"chapter-39",index:0},{kind:"pattern",title:"문법 Grammar · V-(으)ㄹ 수밖에 없다",cards:[{kind:"teach",name:"V-(으)ㄹ 수밖에 없다",sub:"to have no choice but to",rows:[{when:"Verb stem ends in a consonant (받침 O)",add:"-을 수밖에 없다",ex:"먹다 → 먹을 수밖에 없다 (have no choice but to eat)"},{when:"Verb stem ends in a vowel (받침 X)",add:"-ㄹ 수밖에 없다",ex:"가다 → 갈 수밖에 없다 (have no choice but to go)"},{when:"Verb stem ends in ㄹ (ㄹ stays, just add 수밖에 없다)",add:"-ㄹ 수밖에 없다",ex:"살다 → 살 수밖에 없다 (have no choice but to live)"},{when:"Adjectives work too (= it can only be / it's bound to be)",add:"-(으)ㄹ 수밖에 없다",ex:"비싸다 → 비쌀 수밖에 없다 (it's bound to be expensive)"}],examples:[{ko:"버스가 없어서 걸어갈 수밖에 없었어요.",en:"There was no bus, so I had no choice but to walk.",romanization:"beoseu-ga eopseoseo georeogal su-bakke eopseosseoyo.",note:"A reason clause (없어서) plus this pattern is the most common shape: cause, then forced result."},{ko:"시간이 없어서 택시를 탈 수밖에 없어요.",en:"I don't have time, so I have no choice but to take a taxi.",romanization:"sigani eopseoseo taeksi-reul tal su-bakke eopseoyo.",note:"탈 from 타다 (vowel stem) just adds -ㄹ. Shows the everyday 'I'm forced into it' feeling."}],more:{func:`Use this to say there's no other option, so you end up doing the action whether you want to or not. It often sounds a little reluctant: "There's nothing else I can do, so I just do this."`,keyPoint:{label:"수밖에 없다 vs. -아/어야 하다",body:"-아/어야 하다 means you 'have to / should' do something (a duty, but other choices might still exist). V-(으)ㄹ 수밖에 없다 means every other option is gone, so you do it even if you'd rather not. '공부해야 해요' = I should study; '공부할 수밖에 없어요' = I've got no other choice but to study. (You'll meet -아/어야 하다 in its own lesson.)"},pronunciation:"수밖에 sounds like [수바께]: the ㄲ of 밖 links into 에 and stays tense. So 수밖에 없다 comes out as [수바께 업따]."}}],canDo:"Say I have no other option with -(으)ㄹ 수밖에 없다 (야근할 수밖에 없어요)",id:"chapter-39-b2",chapterId:"chapter-39",index:1},{kind:"words",title:"단어 Words 2 · 야근하다~",cards:[{kind:"guess",word:{ko:"야근하다",romanization:"yageunhada",en:"to work overtime; work late",pos:"verb",nuance:"야근하다 is the verb every Korean office worker knows: to stay and work into the evening, past regular hours. The hanja 夜勤 is 夜 'night' + 勤 'work/service' (the same 勤 as in 근무), literally 'night-work'. Its form is neutral, but in real use it almost always carries a tired, faintly complaining tone, because overtime is a charged feature of Korean work culture; the noun 야근 anchors a whole vocabulary of grievance — 야근 수당 (OT pay), 야근 잦아요 (lots of overtime), 칼퇴 (leaving right on time, the dream). The sharp boundary is against 야간근무: 야근 is staying late on an otherwise daytime job, whereas 야간근무 is a scheduled night shift (nurses, security, factory lines). Don't equate it with English 'overtime' as a contractual category either — that abstract concept is 초과근무 / 시간 외 근무. And for an all-nighter it escalates to 밤샘. Habitual collocations: 야근하다, 야근 수당, 야근이 잦다, 야근 안 하다."},sentence:{ko:"오늘은 야근할 수밖에 없어요.",en:"Today I have no choice but to work late."},target:"야근할",options:["to have no choice but to","to work overtime; work late","there is no way that"],note:"A common work-life no-choice sentence."},{kind:"guess",word:{ko:"포기하다",romanization:"pogihada",en:"to give up",pos:"verb",nuance:"포기하다 = to give up, abandon, or relinquish a goal, plan, claim, or even a person. The hanja 抛棄 is vivid: 抛 'to throw/hurl away' + 棄 'to discard, abandon', so the image is hurling something aside and walking off — a decisive letting-go, not a gentle fade. Contrast 포기하다 (stop pursuing a goal entirely) with 그만두다 (stop/quit an ongoing activity — a job, a habit) and with 단념하다 (a more bookish 'resign oneself to abandoning hope'); in speech 포기하다 is the everyday choice. Grammar: it pairs with 을/를 (목표를 포기하다) or with 는 거 / 는 걸 (사는 걸 포기하다 = 'give up on buying'). Culturally the word is loaded: N포세대, the 'give-up generation', names young Koreans said to have surrendered dating, marriage, and kids to economic pressure. English-speaker pitfall: the negative is 포기 안 해 / 포기 못 해 (noun + 안/못 + 해), NOT 안 포기해."},sentence:{ko:"지금 포기할 리가 없어요.",en:"There is no way we would give up now."},target:"포기할",options:["to have no choice but to","there is no way that","to give up"],note:"Natural with -ㄹ 리가 없다."},{kind:"guess",word:{ko:"방법",romanization:"bangbeop",en:"method; way",pos:"noun",nuance:"방법 is Sino-Korean (方法, 方 'direction/manner' + 法 'rule/method'), the 'way', 'method', or 'means' of doing something — the procedure or approach to reach a goal. Compare it with 방식 (方式, 'style/mode/manner'): 방법 is the concrete how-to ('a method to fix it'), while 방식 is the overall style or fashion in which something is done (생활 방식 = lifestyle, 사고방식 = way of thinking) — you wouldn't say 사고방법. Also distinguish 수단 (手段, 'means/instrument', often the tool or even an unscrupulous means: 교통수단 = means of transport, 수단과 방법을 가리지 않다 = by any means necessary). Register-neutral, very common. Core collocations: 방법이 있다/없다, 방법을 찾다/알다/모르다/바꾸다, [동사]~는 방법 (a way to do ~), 해결 방법 (solution), 사용 방법 (how to use). The English-speaker pitfall is the 'a way to do X' frame: it's [verb in ~는 form] + 방법, e.g. 'a way to study' is 공부하는 방법, NOT 공부 방법 in spoken contexts (though 공부 방법 as a fixed noun-noun compound is fine for 'study method'). Don't say 방법으로 어떻게 when you just mean 어떻게 ('how') — 방법 is the noun 'method', not the question word 'how'."},sentence:{ko:"남은 건 이 방법뿐이에요.",en:"The only thing left is this method."},target:"방법",options:["deadline; closing date","method; way","situation; circumstances"],note:"Pairs naturally with 뿐이다."},{kind:"guess",word:{ko:"가능하다",romanization:"ganeunghada",en:"to be possible",pos:"adjective",nuance:"가능하다 (可能, 可 'can/permissible' + 能 'ability') means 'possible / doable / available', and it is wonderfully practical for daily service questions — 예약 가능해요? ('Is a reservation possible?'), 카드 가능해요? ('Can I pay by card?'). In these, a noun sits directly before it and it neatly replaces a longer '-ㄹ 수 있다' clause, sounding crisp and businesslike. The softener 가능하면 ('if possible') makes requests polite, and the fixed frame 가능한 한 + adjective/adverb means 'as ~ as possible' (가능한 한 빨리 'as soon as possible') — note this is different from 가능한 N ('a possible N'). Its antonym is 불가능하다. One pitfall: while 가능하다 and '-ㄹ 수 있다' both render English 'can', '-ㄹ 수 있다' attaches to a verb stem describing an action you're able to do (갈 수 있어요 'I can go'), whereas 가능하다 attaches to a noun or stands alone judging feasibility — don't merge them into 갈 가능해요."},sentence:{ko:"오늘 안에 가능해요?",en:"Is it possible within today?"},target:"가능해",options:["to be possible","to have no choice but to","there is no way that"],note:"Plain possibility, not no-choice."},{kind:"guess",word:{ko:"불가능하다",romanization:"bulganeunghada",en:"to be impossible",pos:"adjective",nuance:"불가능하다 (不可能, the prefix 不 'not/un-' on 가능 'possible') is the direct antonym of 가능하다: 불 flips it to 'cannot be done, impossible'. The 不-prefix pattern recurs across Sino-Korean adjectives (불편하다 'uncomfortable', 불확실하다 'uncertain'), so recognising 불- as a negator unlocks many words. In service settings 불가능하다 is a firm but polite way to refuse, and Koreans habitually cushion it with 좀 ('a bit') or pair it with a 'but...' offer (환불은 불가능하지만 교환은 가능해요) to soften the blow. For an everyday personal 'I can't', the '-ㄹ 수 없다' pattern (갈 수 없어요 'I can't go') is more natural than forcing 불가능하다, which leans toward declaring something infeasible in principle. As a 하다-adjective the pre-noun is 불가능한, never 불가능하는."},sentence:{ko:"지금 방식으로는 거의 불가능해요.",en:"With the current method, it is almost impossible."},target:"불가능해",options:["to be impossible","to have no choice but to","there is no way that"],note:"Useful contrast with -ㄹ 리가 없다."},{kind:"payoff",line:{speaker:"지훈",ko:"결국 남은 건 이 방법뿐이에요.",en:"In the end, this method is the only thing left."},hl:"방법"}],canDo:"Reject something as impossible with -(으)ㄹ 리가 없다 (끝날 리가 없어요)",id:"chapter-39-b3",chapterId:"chapter-39",index:2},{kind:"pattern",title:"문법 Grammar · V-(으)ㄹ 리가 없다",cards:[{kind:"teach",name:"V-(으)ㄹ 리가 없다",sub:"there's no way that's true",rows:[{when:"Verb/Adjective stem ends in a consonant (받침 O)",add:"-을 리가 없다",ex:"먹다 → 먹을 리가 없다 (there's no way he'd eat it)"},{when:"Verb/Adjective stem ends in a vowel (받침 X)",add:"-ㄹ 리가 없다",ex:"오다 → 올 리가 없다 (there's no way it'll come / he'll come)"},{when:"Past meaning (it already happened)",add:"-았/었을 리가 없다",ex:"가다 → 갔을 리가 없다 (there's no way he went)"},{when:"Noun + 이다",add:"일 리가 없다",ex:"학생 → 학생일 리가 없다 (there's no way he's a student)"}],examples:[{ko:"그 친구가 거짓말을 했을 리가 없어요.",en:"There's no way that friend lied.",romanization:"geu chinguga geojinmareul haesseul liga eopseoyo.",note:"Past form 했을 리가 없다 rejects that a past action happened. Very common with 거짓말."},{ko:"지금 밤 12시인데 학생들이 학교에 있을 리가 없어요.",en:"It's midnight now, so there's no way the students are at school.",romanization:"jigeum bam yeoldu-si-inde haksaengdeuri hakgyo-e isseul liga eopseoyo.",note:"A known fact (it's the middle of the night) makes the idea impossible. The typical 'fact + 리가 없다' shape."}],more:{func:`Use this to say you really don't believe something: you're sure it can't be the case because it makes no sense. It's the Korean way of saying "There's no way…" or "It can't possibly be that…"`,keyPoint:{label:"-(으)ㄹ 리가 없다 vs. -(으)ㄹ 수 없다",body:"-(으)ㄹ 수 없다 is about real ability: 'can't do it' (갈 수 없어요 = I'm not able to go). -(으)ㄹ 리가 없다 is about your certainty that a claim is false: 'there's no way that's true' (갔을 리가 없어요 = no way he went). The first is about being able; the second is about believing."},pronunciation:"없어요 sounds like [업써요]: the ㅅ of the 없- cluster slides onto the next syllable and goes tense, while ㅂ stays as a stop. So 리가 없어요 comes out as [리가 업써요]."}}],canDo:"Reject something as impossible with -(으)ㄹ 리가 없다 (끝날 리가 없어요)",id:"chapter-39-b4",chapterId:"chapter-39",index:3},{kind:"words",title:"단어 Words 3 · 상황~",cards:[{kind:"guess",word:{ko:"상황",romanization:"sanghwang",en:"situation; circumstances",pos:"noun",nuance:"상황 (狀況, '狀 condition/form + 況 circumstances' — the configuration of circumstances) describes the overall set of conditions surrounding a moment or event, broader than a single 경우 (a specific case or instance — 이런 경우 = 'in this one case', vs 이런 상황 = 'in this whole situation'). The reflexive phrase 상황에 따라(서) 다르다 ('it depends on the situation') is one of the most useful hedges in Korean, and 이런/그런 상황에서 sets up advice or reactions. Register is neutral. Two pitfalls: keep 상황 (the circumstances around an event) distinct from 상태 (狀態, the state/condition of a single thing or body — 건강 상태 'health condition', 배터리 상태 'battery state'); you describe a person's mood with a 상태, but the events around them with a 상황. And use 에 따라 (not 으로) for 'depending on': 상황에 따라, never 상황으로."},sentence:{ko:"이런 상황에서는 다시 확인할 수밖에 없어요.",en:"In this situation, we have no choice but to check again."},target:"상황",options:["deadline; closing date","method; way","situation; circumstances"],note:"The noun that explains why there is no other option."},{kind:"guess",word:{ko:"자료",romanization:"jaryo",en:"materials; data; documents",pos:"noun",nuance:"자료 can mean data, but in daily work and study talk it often means the file, handout, or slide deck someone needs."},sentence:{ko:"자료가 틀렸을 리가 없어요.",en:"There is no way the data is wrong."},target:"자료",options:["deadline; closing date","materials; data; documents","situation; circumstances"],note:"Work/study content that can be checked or revised."},{kind:"guess",word:{ko:"설명",romanization:"seolmyeong",en:"explanation",pos:"noun",nuance:"설명(說明) is Sino-Korean — 說 'to tell/speak' + 明 'clear, bright' — literally 'to make clear by telling,' i.e. an explanation of how or why something works. Distinguish it from 설득(說得) 'persuasion' (talking someone INTO agreeing, sharing the 說 root) and from 묘사(描寫) 'description' (depicting what something looks/feels like); 설명 is about clarifying and informing, not convincing or portraying. As a noun it becomes the verb with 하다: 설명하다, very often softened to 설명해 주세요/주시겠어요 'please explain for me.' Collocations: 설명을 하다/듣다, 자세한 설명, 설명이 부족하다/이해가 안 되다, 설명서 'instruction manual.' The English-speaker pitfall: English 'explain to me' tempts learners to mark the listener with 를 (저를 설명하다 ✗, which would mean 'explain ME'); the listener takes 한테/에게 (저한테 설명해 주세요), and what you explain takes 을/를. Bare 설명 can't be the verb — use 설명하다. Don't confuse 설명 with the look-alike 설탕 'sugar.'"},sentence:{ko:"설명은 다시 쓸 수밖에 없어요.",en:"We have no choice but to rewrite the explanation."},target:"설명",options:["deadline; closing date","explanation","method; way"],note:"A realistic repair action under a deadline."},{kind:"payoff",line:{speaker:"민서",ko:"자료는 맞지만 설명은 다시 쓸 수밖에 없어요.",en:"The data is right, but we have no choice but to rewrite the explanation."},hl:"자료"}],canDo:"Limit things to just one with -(으)ㄹ 뿐이다 / N뿐이다 (이것뿐이에요)",id:"chapter-39-b5",chapterId:"chapter-39",index:4},{kind:"pattern",title:"문법 Grammar · V-(으)ㄹ 뿐이다 / N뿐이다",cards:[{kind:"teach",name:"V-(으)ㄹ 뿐이다 / N뿐이다",sub:"only, nothing more",rows:[{when:"Verb/Adjective stem + 받침 O",add:"-을 뿐이다",ex:"믿다 → 믿을 뿐이다 (I just believe it, that's all)"},{when:"Verb/Adjective stem + 받침 X",add:"-ㄹ 뿐이다",ex:"기다리다 → 기다릴 뿐이다 (I'm only waiting)"},{when:"Past meaning",add:"-았/었을 뿐이다",ex:"하다 → 했을 뿐이다 (I just did it, nothing more)"},{when:"Noun (no -(으)ㄹ; 뿐 attaches straight to the noun)",add:"N + 뿐이다",ex:"물 → 물뿐이다 (there's only water)"}],examples:[{ko:"저는 사실대로 말했을 뿐이에요.",en:"I only told the truth, that's all.",romanization:"jeoneun sasildaero malhaesseul ppunieyo.",note:"Past 말했을 뿐이다 is the classic 'I just did X, so don't blame me' use."},{ko:"그냥 농담했을 뿐이에요. 화내지 마세요.",en:"I was just joking, nothing more. Don't be mad.",romanization:"geunyang nongdamhaesseul ppunieyo. hwanaeji maseyo.",note:"그냥 ('just') goes naturally with 뿐이다 to play an action down."}],more:{func:"Use this to limit things to just one: 'that's all there is, nothing else.' With verbs/adjectives it means 'only does / is only'; attached straight to a noun, 뿐이다 means 'only that, and nothing else.'",keyPoint:{label:"-(으)ㄹ 뿐이다 vs. N뿐이다 (and 만)",body:"After a verb or adjective, use the -(으)ㄹ form: 기다릴 뿐이에요. After a noun, drop -(으)ㄹ and stick 뿐 right on: 물뿐이에요. Compare 만 ('only'): 만 picks one out of several options (물만 마셔요 = I drink only water), while N뿐이다 says that noun is all there is (물뿐이에요 = water is all there is)."},pronunciation:"뿐이에요 links smoothly as [뿌니에요]: the ㄴ of 뿐 slides onto 이. With a noun like 물, 물뿐이에요 sounds like [물뿌니에요]."}}],canDo:"Limit things to just one with -(으)ㄹ 뿐이다 / N뿐이다 (이것뿐이에요)",id:"chapter-39-b6",chapterId:"chapter-39",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A team handles a deadline where there is no realistic choice left.",lines:[{speaker:"민서",ko:"마감이 오늘이라서 야근할 수밖에 없어요.",en:"The deadline is today, so we have no choice but to work late.",romanization:"magami oneuriraseo yageunhal subakke eopseoyo."},{speaker:"지훈",ko:"그래도 지금 포기할 리가 없죠.",en:"Still, there is no way we would give up now.",romanization:"geuraedo jigeum pogihal riga eopsjyo."},{speaker:"민서",ko:"자료는 맞지만 설명은 다시 쓸 수밖에 없어요.",en:"The data is right, but we have no choice but to rewrite the explanation.",romanization:"jaryoneun matjiman seolmyeongeun dasi sseul subakke eopseoyo."},{speaker:"지훈",ko:"결국 남은 건 이 방법뿐이에요.",en:"In the end, this method is the only thing left.",romanization:"gyeolguk nameun geon i bangbeopppunieyo."}]},{kind:"order",prompt:"Build: 'There is no way that person will give up.'",tokens:["그 사람이","포기할 리가 없어요"],correct:"그 사람이 포기할 리가 없어요",explanation:"-(으)ㄹ 리가 없어요 strongly rejects a possibility. 포기할 리가 없어요 means giving up is not plausible."}],canDo:"Say I have no other option with -(으)ㄹ 수밖에 없다 (야근할 수밖에 없어요)",id:"chapter-39-b7",chapterId:"chapter-39",index:6},{kind:"reading",title:"읽기 Reading · 마감이라서 할 수밖에 없어요",cards:[{kind:"read",title:"마감이라서 할 수밖에 없어요",chunks:["마감이 가까우면 선택지가 줄어들어요. 이때 '할 수 없어요'라고 말하면 능력이 없거나 불가능하다는 뜻이 되지만, '할 수밖에 없어요'라고 말하면 하기 싫어도 그 방법밖에 없다는 뜻이 돼요. 반대로 '포기할 리가 없어요'는 포기할 가능성을 강하게 부정하는 말이에요.","그리고 '남은 건 이 방법뿐이에요'는 다른 선택이 없고 이 방법만 남았다는 뜻이에요. 세 표현은 모두 한계와 관련이 있지만, 각각 no choice, no way, only one이라는 다른 느낌을 가지고 있어요."],translation:"When a deadline is close, choices shrink. 할 수밖에 없어요 means there is no choice but to do it, not that you cannot do it. 리가 없어요 strongly rejects a possibility, and 뿐이에요 limits the situation to only one remaining option.",qas:[{q:"할 수 없어요와 할 수밖에 없어요는 어떻게 달라요?",a:"할 수 없어요는 불가능, 할 수밖에 없어요는 다른 선택이 없다는 뜻이에요."},{q:"포기할 리가 없어요는 어떤 느낌이에요?",a:"포기할 가능성을 강하게 부정하는 느낌이에요."},{q:"이 방법뿐이에요는 무엇을 뜻해요?",a:"이 방법만 남았다는 뜻이에요."}]}],canDo:"Reject something as impossible with -(으)ㄹ 리가 없다 (끝날 리가 없어요)",id:"chapter-39-b8",chapterId:"chapter-39",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence means “I have no choice but to work late”?",sentence:null,options:[{text:"야근할 수밖에 없어요.",ok:!0},{text:"야근할 수 없어요.",ok:!1},{text:"야근할지도 몰라요.",ok:!1}],explanation:"수밖에 없다 means the situation leaves no other option."},{kind:"drill",prompt:"Which sentence strongly rejects a possibility?",sentence:null,options:[{text:"포기할 리가 없어요.",ok:!0},{text:"포기할 수도 있어요.",ok:!1},{text:"포기할 뿐만 아니라.",ok:!1}],explanation:"-ㄹ 리가 없다 means there is no way that possibility is true."},{kind:"drill",prompt:"Which sentence means only one method remains?",sentence:null,options:[{text:"남은 건 이 방법뿐이에요.",ok:!0},{text:"남은 건 이 방법뿐만 아니라예요.",ok:!1},{text:"남은 건 이 방법일 리가 없어요.",ok:!1}],explanation:"N뿐이다 limits the situation to only that noun."},{kind:"drill",prompt:"마감___ 있어서 야근할 수밖에 없어요. (Because there is a deadline...)",sentence:null,options:[{text:"이",ok:!0},{text:"을",ok:!1},{text:"에",ok:!1}],explanation:"있다 takes 이/가 for the thing that exists. 마감이 있어서 gives the reason before the no-choice result."},{kind:"order",prompt:"Build: 'There is no way that person will give up.'",tokens:["그 사람이","포기할 리가 없어요"],correct:"그 사람이 포기할 리가 없어요",explanation:"-(으)ㄹ 리가 없어요 strongly rejects a possibility. 포기할 리가 없어요 means giving up is not plausible."},{kind:"drill",prompt:"Only one realistic option remains. Which sentence fits?",sentence:null,options:[{text:"이 방법뿐이에요.",ok:!0},{text:"이 방법보다 더예요.",ok:!1},{text:"이 방법일걸요.",ok:!1}],explanation:"뿐이에요 means only this and nothing more. The other options compare or guess rather than limit the options."}],canDo:"Limit things to just one with -(으)ㄹ 뿐이다 / N뿐이다 (이것뿐이에요)",id:"chapter-39-b9",chapterId:"chapter-39",index:8}]},{id:"chapter-40",number:40,title:"-(으)ㄹ걸요 · -(으)면 좋겠어요",goal:"Use -ㄹ걸요 for a soft but fairly confident guess.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 걸요~",cards:[{kind:"guess",word:{ko:"걸요",romanization:"geolyo",en:"probably; I think...",pos:"sentence ending",nuance:"걸요 is softer than a plain statement, but it is not as open-ended as 글쎄요. The speaker still has a hunch."},sentence:{ko:"그분은 아직 회의 중일걸요.",en:"They are probably still in a meeting."},target:"걸요",options:["I hope; it would be good if...","probably; I think...","if; supposing that"],note:"Linked to word-ext-ch40-geolyo."},{kind:"guess",word:{ko:"좋겠어요",romanization:"jokesseoyo",en:"I hope; it would be good if...",pos:"wish expression",nuance:"좋겠어요 is useful when you want to express a hope or suggestion without sounding like an order."},sentence:{ko:"메시지를 남겨 두면 좋겠어요.",en:"It would be good to leave a message."},target:"좋겠어요",options:["probably; I think...","I hope; it would be good if...","if; supposing that"],note:"Linked to word-ext-ch40-jokesseoyo."},{kind:"guess",word:{ko:"다면",romanization:"damyeon",en:"if; supposing that",pos:"conditional ending",nuance:"다면 often feels more hypothetical or careful than plain -(으)면."},sentence:{ko:"혹시 이미 나갔다면 메시지를 남겨 두면 좋겠어요.",en:"If they already left, it would be good to leave a message."},target:"다면",options:["probably; I think...","I hope; it would be good if...","if; supposing that"],note:"Linked to word-ext-ch40-damyeon."},{kind:"guess",word:{ko:"것 같아요",romanization:"geot gatayo",en:"I think; it seems like",pos:"hedging expression",nuance:"것 같아요 is not the same as 같다 meaning 'same.' Here it softens the whole statement."},sentence:{ko:"제 생각에는 먼저 물어보는 게 좋을 것 같아요.",en:"In my opinion, I think it would be good to ask first."},target:"것 같아요",options:["I think; it seems like","I hope; it would be good if...","if; supposing that"],note:"Linked to word-ext-ch40-geot-gatayo."},{kind:"guess",word:{ko:"겠",romanization:"get",en:"inference or intention marker",pos:"modal marker",nuance:"겠 is not one English word. It can be intention, inference, or a set response depending on context."},sentence:{ko:"제가 조심스럽게 물어보겠습니다.",en:"I will ask carefully."},target:"겠",options:["inference or intention marker","probably; I think...","I hope; it would be good if..."],note:"Linked to word-ext-ch40-get."},{kind:"guess",word:{ko:"조심스럽게",romanization:"josimseureopge",en:"carefully; cautiously",pos:"adverb",nuance:"조심스럽게 is about tone and risk. It is not just physical carefulness."},sentence:{ko:"확실하지 않으니까 조심스럽게 물어볼게요.",en:"Since I am not sure, I will ask carefully."},target:"조심스럽게",options:["probably","by any chance","carefully; cautiously"],note:"Linked to word-ext-ch40-josimseureopge."},{kind:"guess",word:{ko:"아마",romanization:"ama",en:"probably",pos:"adverb",nuance:"아마 means 'probably / perhaps,' expressing the speaker's reasonable guess, and its grammar is almost inseparable: it is normally completed by a conjecture ending — most often -ㄹ/을 거예요 ('will probably'), or -ㄹ 것 같다, -겠-, -ㄹ걸요. The bare statement 아마 비가 와요 sounds unfinished; you want 아마 비가 올 거예요. A near-synonym is 아마도, which is just a softer, slightly more deliberative version of 아마 (interchangeable; 아마도 can feel a touch more written or musing). Distinguish the certainty scale: 아마 is a fairly confident guess (~maybe 70-80%), 어쩌면/혹시 lean toward 'possibly, by any chance' (lower, more tentative), and 분명히/틀림없이 mean 'surely/definitely' (high certainty). The English-speaker pitfall is using 아마 with a flat present/past as if it were the English adverb that can float anywhere ('he's probably home'): in Korean the verb itself must carry the guessing form, so 'he's probably home' = 아마 집에 있을 거예요, not 아마 집에 있어요. Also avoid 아마 with established facts — 아마 물은 H2O일 거예요 sounds odd because you're hedging a certainty. Place 아마 near the front of the clause, and let the sentence-final ending do the conjecture work."},sentence:{ko:"아마 담당자가 알걸요.",en:"The person in charge probably knows."},target:"아마",options:["carefully; cautiously","probably","by any chance"],note:"Linked to dictionary card word-ext-1242."},{kind:"payoff",line:{speaker:"민서",ko:"그분은 아직 회의 중일걸요.",en:"They are probably still in a meeting."},hl:"걸요"}],canDo:"Offer a soft but confident guess with -(으)ㄹ걸요 (괜찮을걸요)",id:"chapter-40-b1",chapterId:"chapter-40",index:0},{kind:"pattern",title:"문법 Grammar · -(으)ㄹ걸요",cards:[{kind:"teach",name:"-(으)ㄹ걸요",sub:"A Soft but Confident Guess",rows:[{when:"Verb/adjective stem ends in a vowel",add:"-ㄹ걸요",ex:"가다 → 갈걸요; 비싸다 → 비쌀걸요"},{when:"Verb/adjective stem ends in a consonant",add:"-을걸요",ex:"먹다 → 먹을걸요; 작다 → 작을걸요"},{when:"Stem ends in ㄹ",add:"drop ㄹ, then add -ㄹ걸요",ex:"살다 → 살걸요; 멀다 → 멀걸요"},{when:"Past (any stem)",add:"-았/었을걸요",ex:"가다 → 갔을걸요; 먹다 → 먹었을걸요"},{when:"Noun (guess about a fact)",add:"N일걸요",ex:"학생 → 학생일걸요"}],examples:[{ko:"친구는 지금 집에 있을걸요.",en:"My friend is probably home right now.",romanization:"chinguneun jigeum jibe isseulgeolyo.",note:"A guess you're fairly sure of, softened so it doesn't sound like a flat claim."},{ko:"그 영화 재미있을걸요.",en:"That movie's probably good.",romanization:"geu yeonghwa jaemiisseulgeolyo.",note:"있다 ends in a consonant, so it takes -을걸요."}],more:{func:`Use -(으)ㄹ걸요 when you make a guess you're fairly sure about, but want to sound gentle instead of flat-out telling someone. It feels like "I'd say..." or "probably..." based on what you know.`,keyPoint:{label:"-(으)ㄹ걸요 vs. -(으)ㄹ 거예요",body:`Both say something is likely. -(으)ㄹ 거예요 sounds like a plain prediction; -(으)ㄹ걸요 adds a softer "I'd guess" feeling, often when the other person might be thinking otherwise. Save the finer back-vowel rules for later — just match vowel vs. consonant stems for now.`},pronunciation:"걸요 sounds like [거료], so 갈걸요 comes out [갈꺼료] — the ㄱ tenses and the ㄹ links smoothly into 요."}}],canDo:"Offer a soft but confident guess with -(으)ㄹ걸요 (괜찮을걸요)",id:"chapter-40-b2",chapterId:"chapter-40",index:1},{kind:"words",title:"단어 Words 2 · 글쎄요~",cards:[{kind:"guess",word:{ko:"글쎄요",romanization:"geulsseyo",en:"Hmm, I'm not sure",pos:"expression",nuance:"글쎄요 is the classic Korean verbal hedge — a non-committal 'hmm, well, I'm not sure' that lets you avoid both 'yes' and 'no.' It buys time, signals reluctance or uncertainty, and very often functions as a soft pre-refusal or a polite way to withhold agreement without contradicting the other person. The 요 makes it polite; 글쎄 alone is 반말 and can also mean 'we'll see' or even an insistent 'I told you…' depending on tone. Register: 글쎄요 polite, 글쎄 casual. The dividing line from 모르겠어요 ('I don't know') is intent: 모르겠어요 states genuine lack of knowledge, while 글쎄요 is a strategic hedge — you may well have an opinion but are choosing not to commit, so it's softer and more diplomatic for declining or dodging. The English-speaker trap is hearing 글쎄요 as a real 'I don't know' and re-explaining or pressing for an answer; in many cases it politely means 'eh, probably not' or 'I'd rather not say', and pushing is impolite. Another error is overusing it as a filler the way English uses 'well' — too many 글쎄요s can read as evasive or wishy-washy. Pair it with 잘 모르겠는데요 ('I'm not really sure') or 생각해 봐야겠어요 ('I'd have to think') to extend the hedge gracefully. Crucially, recognize it from the other side: when a Korean answers your request with 글쎄요, treat it as a likely soft 'no', not an invitation to argue your case."},sentence:{ko:"글쎄요, 이미 퇴근했을 수도 있어요.",en:"Hmm, they may have already left work."},target:"글쎄요",options:["in my opinion; I think","I hope; it would be good if...","Hmm, I'm not sure"],note:"Linked to dictionary card expr-327."},{kind:"guess",word:{ko:"제 생각에는",romanization:"je saenggageneun",en:"in my opinion; I think",pos:"expression",nuance:"제 생각에는 is the standard polite opener that signals 'this is just my view, not a command or fact'. 제 is the humble form of 나 ('my'), and 에는 sets up a frame — literally 'as for within my thinking'. It works with anyone: strangers, seniors, classmates, colleagues, customers. To go casual with a close friend, swap to 내 생각에는; for a more considered, slightly formal feel use 제 생각으로는 (the -으로는 particle stresses the viewpoint angle). The nearest alternative is 제가 보기에는 — the dividing line is thinking vs observing: 제 생각에는 comes from your internal reasoning, while 제가 보기에는 is based on what you see or sense from evidence. The classic English-speaker mistake is calquing 'in my opinion' literally as 제 의견에는, which is bookish and rare in spoken Korean. A second trap: dropping the particle entirely (제 생각 좋아요) — without 에는 or 엔 the opener is ungrammatical."},sentence:{ko:"제 생각에는 먼저 물어보는 게 좋을 것 같아요.",en:"In my opinion, I think it would be good to ask first."},target:"제 생각에는",options:["Hmm, I'm not sure","in my opinion; I think","I hope; it would be good if..."],note:"Linked to dictionary card expr-567."},{kind:"guess",word:{ko:"의견",romanization:"uigyeon",en:"opinion",pos:"noun",nuance:"의견 is Sino-Korean (意見, 意 'mind/intention' + 見 'view/seeing'), literally 'how your mind sees something' — a considered position or judgment you can defend, usually about a topic, plan, or issue. The crucial contrast is with 생각: 생각 is the broad word for any 'thought' that crosses your mind, while 의견 is specifically a stance offered for discussion or evaluation, so a meeting asks for 의견 (positions), not just 생각 (musings). It is register-neutral and very common in school and workplace settings; the polite request 의견을 여쭤봐도 될까요? raises it a notch. Natural collocations: 의견을 말하다/내다/제시하다 (state/put forward), 의견이 다르다/같다 (disagree/agree), 의견을 모으다 (gather opinions), 반대 의견 (an opposing view). The English-speaker pitfall is reaching for 의견 every time you'd say 'I think' — 'I think it's good' is 좋은 것 같아요 or 좋다고 생각해요, NOT 좋은 의견이에요; 의견 is the opinion itself as a thing, not the act of thinking. Also don't say 의견하다 — there is no such verb; you 의견을 말하다."},sentence:{ko:"의견을 조심스럽게 말하는 게 좋겠어요.",en:"It would be good to state the opinion carefully."},target:"의견",options:["opinion","burden; pressure","meeting"],note:"Linked to dictionary card word-ext-2048."},{kind:"guess",word:{ko:"확실하다",romanization:"hwaksilhada",en:"to be certain; sure",pos:"adjective",nuance:"확실하다 (確實, 確 'firm/sure' + 實 'real/true') expresses certainty and confidence — you're sure something is true, settled, or reliable. The adverb 확실히 ('certainly, definitely, for sure') is very common when answering or confirming (확실히 그래요 'that's definitely so'). The sharp contrast is with 분명하다: 확실하다 centres on the speaker's subjective confidence ('I'm sure of it'), while 분명하다 centres on a thing being objectively obvious/unambiguous — so 나는 확실해 ('I'm certain') but 증거가 분명해 ('the evidence is clear-cut'). It also brushes against 틀림없다 ('there's no mistake / definitely'), which is even more emphatic. Crucially, 확실하다 is for certainty, not possibility: to say 'maybe' you need 아마 ('probably') or '-ㄹ지도 몰라요' ('might'), not 확실하다. The natural adverb is 확실히 in everyday speech (확실하게 is a touch stiffer)."},sentence:{ko:"확실하지 않으니까 조심스럽게 물어볼게요.",en:"Since I am not sure, I will ask carefully."},target:"확실하",options:["probably; I think...","I hope; it would be good if...","to be certain; sure"],note:"Linked to dictionary card word-ext-1254."},{kind:"guess",word:{ko:"부담",romanization:"budam",en:"burden; pressure",pos:"noun",nuance:"부담 is essential for navigating Korean social give-and-take, where accepting too much puts you in someone's debt. It is Sino-Korean 負擔 (負 'to carry on the back' + 擔 'to shoulder'), literally 'a load you shoulder', and it covers both a *financial* weight (rent, a pricey gift) and an *emotional* one (expectations, obligation). When a host says 부담 갖지 마세요, they are pre-emptively lifting that load off you; when you call a gesture 부담스러워요, you are politely signaling 'this is too generous, I'd feel indebted.' The contrast to learn is 부담 (mental/social pressure or weight) vs 짐 (a literal piece of luggage, or a metaphorical 'I'm a burden to you' = 짐이 되다). The English-speaker trap is translating it only as 'burden' and missing the warm 'please don't trouble yourself' social move, and confusing the formal verb 부담하다 (to bear a *cost*, as in 비용을 부담하다) with feeling pressure, for which you want 부담스럽다 or 부담이 되다."},sentence:{ko:"이렇게 말하면 좀 부담스러운 것 같아요.",en:"If we say it this way, I think it feels a bit pressuring."},target:"부담",options:["burden; pressure","opinion","meeting"],note:"Linked to dictionary card word-ext-733."},{kind:"guess",word:{ko:"혹시",romanization:"hoksi",en:"by any chance",pos:"adverb",nuance:"혹시 is the Sino-Korean 或是 (或 'perhaps' + 是 'be so') and lives at the FRONT of a question to soften it, exactly like English 'by any chance' or 'do you happen to': it signals you are unsure and refuse to assume, so requests and guesses land politely rather than pushily. Do not confuse it with 만약 (萬若, 'if / supposing'): 만약 sets up a conditional clause and pairs with -면 (만약 비가 오면 = if it rains), whereas 혹시 colors a whole question with tentativeness and does NOT need -면. The big English-speaker trap is dropping 혹시 into a flat statement; it belongs with a question or with the set phrase 혹시 몰라서 / 혹시 모르니까 ('just in case'). It also collocates with 혹시나 (an even softer, more anxious variant) and with 혹시 ~ 거 아니에요? for a worried hunch."},sentence:{ko:"혹시 이미 나갔다면 메시지를 남겨 두면 좋겠어요.",en:"If they already left, it would be good to leave a message."},target:"혹시",options:["by any chance","carefully; cautiously","already"],note:"Linked to dictionary card word-ext-646."},{kind:"guess",word:{ko:"이미",romanization:"imi",en:"already",pos:"adverb",nuance:"이미 means 'already,' emphasizing that an action or state is completed and now fixed — often colored by 'and there's no changing it now.' The sharp contrast every learner needs is 이미 vs 벌써. Both translate as 'already,' but 이미 is neutral and factual ('it is already done, that's just the situation'), while 벌써 adds emotional surprise that it happened so fast or so soon ('already?! that quick?'). 이미 끝났어요 = a calm statement of fact; 벌써 끝났어요?! = 'it's over already?!' with raised eyebrows. So choose 이미 when calmly noting that the moment/deadline has passed, and 벌써 when reacting to unexpected speed. 이미 is native Korean and is also future-blind: it only describes things already done, never things about to happen. It pairs naturally with completed clauses and with -더라고요, -았/었- past forms."},sentence:{ko:"이미 퇴근했을 수도 있어요.",en:"They may have already left work."},target:"이미",options:["already","carefully; cautiously","probably"],note:"Linked to dictionary card word-ext-983."},{kind:"payoff",line:{speaker:"지훈",ko:"글쎄요, 이미 퇴근했을 수도 있어요.",en:"Hmm, they may have already left work."},hl:"글쎄요"}],canDo:"Express a hope or wish with -(으)면 좋겠어요 (괜찮으면 좋겠어요)",id:"chapter-40-b3",chapterId:"chapter-40",index:2},{kind:"pattern",title:"문법 Grammar · -(으)면 좋겠어요",cards:[{kind:"hunt",name:"-(으)면 좋겠어요",sub:"A Hope or Gentle Wish",lines:[{tokens:[{pre:"내일",mid:"",post:"",hit:!1},{pre:"날씨가",mid:"",post:"",hit:!1},{pre:"좋",mid:"으면",post:"",hit:!0},{pre:"",mid:"좋겠어요",post:".",hit:!0}],ko:"내일 날씨가 좋으면 좋겠어요.",en:"I hope the weather's nice tomorrow.",romanization:"naeil nalssiga joeumyeon jokesseoyo."},{tokens:[{pre:"시간이",mid:"",post:"",hit:!1},{pre:"좀",mid:"",post:"",hit:!1},{pre:"더",mid:"",post:"",hit:!1},{pre:"있",mid:"으면",post:"",hit:!0},{pre:"",mid:"좋겠어요",post:".",hit:!0}],ko:"시간이 좀 더 있으면 좋겠어요.",en:"I wish I had a little more time.",romanization:"sigani jom deo isseumyeon jokesseoyo."}],rule:{name:"-(으)면 좋겠어요",rows:[{when:"Stem ends in a vowel",add:"-면 좋겠어요",ex:"오다 → 오면 좋겠어요; 싸다 → 싸면 좋겠어요"},{when:"Stem ends in a consonant",add:"-으면 좋겠어요",ex:"먹다 → 먹으면 좋겠어요; 많다 → 많으면 좋겠어요"},{when:"Stem ends in ㄹ",add:"-면 좋겠어요 (keep ㄹ)",ex:"살다 → 살면 좋겠어요"},{when:"Wish about now / something not true",add:"-았/었으면 좋겠어요",ex:"오다 → 왔으면 좋겠어요; 있다 → 있었으면 좋겠어요"},{when:"Noun",add:"N(이)면 좋겠어요",ex:"주말 → 주말이면 좋겠어요"}]},more:{func:`Use -(으)면 좋겠어요 to say "I hope..." or "I wish...". It literally means "it'd be nice if...," and it's the everyday way to say what you'd like to happen.`,keyPoint:{label:"-(으)면 좋겠어요 vs. -고 싶어요",body:`-고 싶어요 means "I want to (do it myself)." -(으)면 좋겠어요 means "I hope (it happens)," so it can be about other people, the weather, or things you don't control. The contrary-to-fact nuance of the -았/었으면 form gets fuller treatment in a later chapter.`},pronunciation:"좋겠어요 sounds like [조케써요]: ㅎ + ㄱ blend into an aspirated [ㅋ], and 겠 tenses the next ㅅ into [써]."}}],canDo:"Express a hope or wish with -(으)면 좋겠어요 (괜찮으면 좋겠어요)",id:"chapter-40-b4",chapterId:"chapter-40",index:3},{kind:"words",title:"단어 Words 3 · 아직~",cards:[{kind:"guess",word:{ko:"아직",romanization:"ajik",en:"still; yet",pos:"adverb",nuance:"아직 covers both 'still' and 'not yet', and which one surfaces depends on polarity: with a POSITIVE verb it means 'still' (아직 자요 'still sleeping'), and with a NEGATIVE verb it means 'not yet' (아직 안 잤어요 'haven't slept yet'). It is the natural counterpart to 벌써/이미 — 아직 안 끝났어요 ('not finished yet') is the mirror of 벌써 끝났어요 ('already finished'). It often rides with the ongoing form -고 있다 to stress an action in progress (아직 자고 있어요 'still sleeping right now') and shows up in fixed phrases like 아직 멀었어요 ('still a long way off'). Register-neutral. The English-speaker pitfall is the 아직/벌써 confusion and the negation logic: because English 'yet' lives in questions/negatives, learners forget that Korean 아직 itself flips meaning with the verb's polarity — pair 아직 with 안/못 to say 'not yet', and use it with a plain positive verb to say 'still'."},sentence:{ko:"그분은 아직 회의 중일걸요.",en:"They are probably still in a meeting."},target:"아직",options:["still; yet","carefully; cautiously","probably"],note:"Linked to dictionary card word-ext-285."},{kind:"guess",word:{ko:"회의",romanization:"hoeui",en:"meeting",pos:"noun",nuance:"회의 (漢字 會議, 會 'gather' + 議 'discuss') is a formal, work-style meeting where people gather to discuss and decide something — a board meeting, a team sync, a planning session. The near-synonym learners reach for is 모임, but 모임 is a social get-together (a dinner, a club, friends meeting up) with no agenda, so calling drinks with friends a 회의 sounds robotic; conversely calling a budget review a 모임 sounds too loose. It pairs naturally with 회의를 하다 (hold), 회의에 들어가다 (go into), 회의가 길어지다 (run long). The English-speaker pitfall is the particle: you are *in* a meeting as a location, so the action takes 회의에서, but you *enter* a meeting with 회의에 들어가다 — and never confuse 회의 with the look-alike 회사 (company) or 회비 (membership fee)."},sentence:{ko:"아직 회의 중일걸요.",en:"They are probably still in a meeting."},target:"회의",options:["meeting","opinion","burden; pressure"],note:"Linked to dictionary card word-ext-121."},{kind:"guess",word:{ko:"메시지",romanization:"mesiji",en:"message",pos:"noun",nuance:"메시지 is the loanword from English 'message' and covers chat/app messages broadly (a KakaoTalk message, a DM); the everyday near-synonym 문자 (literally 文字 'letters/characters') specifically means an SMS text, so '문자 보내' = 'text me' while '메시지' is the wider term. There's also 카톡, the verb-able brand shorthand for a KakaoTalk message, used constantly in real life (카톡 보낼게 'I'll Kakao you'). The English-speaker pitfall is twofold: first, the recipient is marked with 한테/에게 ('to a person'), not the English bare object — 친구한테 메시지를 보내다, where 친구한테 = 'to my friend' and 메시지를 is the thing sent; second, the message arriving uses intransitive 오다 with 이/가 (메시지가 오다), but you sending it uses 보내다 with 을/를 (메시지를 보내다). Don't carry the English 'send him a message' double-object pattern straight over."},sentence:{ko:"메시지를 남겨 두면 좋겠어요.",en:"It would be good to leave a message."},target:"메시지",options:["burden; pressure","message","meeting"],note:"Linked to dictionary card word-ext-167."},{kind:"guess",word:{ko:"퇴근하다",romanization:"toegeunhada",en:"to leave work",pos:"verb",nuance:"퇴근하다 is Sino-Korean 退勤 — 退 'withdraw/retreat' + 勤 'duty' — literally 'withdraw from your duty', i.e. finish the workday and head home. It is the precise mirror of 출근하다 (出勤). Don't confuse it with 끝나다 'to end' or 쉬다 'to rest': 퇴근하다 specifically means YOU leave the workplace, whereas 일이 끝나다 means the work is finished and 쉬다 means to take a break. As a noun+하다 verb it conjugates entirely on 하다: 퇴근해요, 퇴근했어요, formal 퇴근합니다. The English-speaker pitfall is the same family of splits — the negative is 퇴근 안 해요 and the impossible form 퇴근 못 해요, never 안 퇴근해요. A second trap: English 'get off work' tempts learners to invent a particle, but 퇴근하다 takes no object at all; the time is enough — 여섯 시에 퇴근해요. Beware the very common slang 칼퇴근(하다), 'knife clock-out', meaning you leave at the exact end time without a second of overtime."},sentence:{ko:"이미 퇴근했을 수도 있어요.",en:"They may have already left work."},target:"퇴근했",options:["to guess; to infer","probably; I think...","to leave work"],note:"Linked to dictionary card word-verb-485."},{kind:"guess",word:{ko:"물어보다",romanization:"mureoboda",en:"to ask; to ask and find out",pos:"verb phrase",nuance:"묻다 is the dictionary/base verb. 물어보다 is often the natural spoken choice for asking someone."},sentence:{ko:"확실하지 않으니까 조심스럽게 물어볼게요.",en:"Since I am not sure, I will ask carefully."},target:"물어볼",options:["probably; I think...","to ask; to ask and find out","I hope; it would be good if..."],note:"Linked to dictionary card word-ext-ch37-mureoboda."},{kind:"guess",word:{ko:"가능성",romanization:"ganeungseong",en:"possibility; chance",pos:"noun",nuance:"가능성 is a noun, so it pairs with 있다, 없다, 높다, and 낮다. It is a little more formal than just saying -ㄹ지도 몰라요."},sentence:{ko:"그럴 가능성도 있는 것 같아요.",en:"I think there is also a possibility of that."},target:"가능성",options:["opinion","possibility; chance","burden; pressure"],note:"Linked to dictionary card word-ext-ch26-ganeungseong."},{kind:"guess",word:{ko:"추측하다",romanization:"chucheukhada",en:"to guess; to infer",pos:"verb",nuance:"추측하다 is more explicit than -나 봐요. In conversation, the pattern often does the work, and 추측하다 names the thinking process."},sentence:{ko:"확실하지 않을 때는 너무 단정하지 말고 조심스럽게 추측해요.",en:"When you are not sure, do not state it too firmly; guess carefully."},target:"추측해",options:["to leave work","to guess; to infer","probably; I think..."],note:"Linked to dictionary card word-ext-ch26-chucheukhada."},{kind:"payoff",line:{speaker:"민서",ko:"그분은 아직 회의 중일걸요.",en:"They are probably still in a meeting."},hl:"아직"}],canDo:"Read -겠- as intention, a guess, or a set phrase (알 수 있겠죠)",id:"chapter-40-b5",chapterId:"chapter-40",index:4},{kind:"pattern",title:"문법 Grammar · -겠-",cards:[{kind:"teach",name:"-겠-",sub:"Intention, a Good Guess, or a Set Polite Phrase",rows:[{when:'Intention (your own plan, "I")',add:"stem + -겠-",ex:"하다 → 하겠어요; 먹다 → 먹겠습니다"},{when:"Guess (about something you can see/know)",add:"stem + -겠-",ex:"맛있다 → 맛있겠어요; 춥다 → 춥겠어요"},{when:"Guess about the past",add:"-았/었겠-",ex:"힘들다 → 힘들었겠어요"},{when:"Set polite phrases",add:"fixed forms",ex:"알겠어요 (got it); 모르겠어요 (I don't know); 잘 먹겠습니다"},{when:"Noun + guess",add:"N(이)겠-",ex:"학생 → 학생이겠어요"}],examples:[{ko:"제가 내일 다시 오겠습니다.",en:"I'll come back tomorrow.",romanization:"jega naeil dasi ogesseumnida.",note:"Your own plan; -겠습니다 sounds firm and polite, common when serving someone or in formal speech."},{ko:"이 음식 정말 맛있겠어요!",en:"This food looks so good!",romanization:"i eumsik jeongmal masitgesseoyo!",note:"A guess from what you see — you haven't tasted it yet, but you can tell it must be good."}],more:{func:`-겠- does three everyday jobs: stating your own plan ("I'll..."), making a guess about a situation ("that must be..."), and forming a few set polite phrases. You read which one it is from the context and the subject.`,keyPoint:{label:"Intention -겠- vs. Guess -겠-",body:`With "I" as the subject and an action verb, -겠- usually means a plan ("I'll"). With someone else, or with an adjective describing a situation, it means a guess ("must be / looks like"). The subject and the kind of verb tell you which. The polite "future" feel of -겠- in set phrases comes later.`},pronunciation:"-겠- tenses the next consonant: 먹겠어요 → [먹께써요], 맛있겠어요 → [마싣께써요]."}}],canDo:"Read -겠- as intention, a guess, or a set phrase (알 수 있겠죠)",id:"chapter-40-b6",chapterId:"chapter-40",index:5},{kind:"pattern",title:"문법 Grammar · -다면 / N(이)라면",cards:[{kind:"hunt",name:"-다면 / N(이)라면",sub:"If That Were the Case",lines:[{tokens:[{pre:"돈이",mid:"",post:"",hit:!1},{pre:"많",mid:"다면",post:"",hit:!0},{pre:"큰",mid:"",post:"",hit:!1},{pre:"집을",mid:"",post:"",hit:!1},{pre:"사고",mid:"",post:"",hit:!1},{pre:"싶어요.",mid:"",post:"",hit:!1}],ko:"돈이 많다면 큰 집을 사고 싶어요.",en:"If I had a lot of money, I'd want to buy a big house.",romanization:"doni mantamyeon keun jibeul sago sipeoyo."},{tokens:[{pre:"내가",mid:"",post:"",hit:!1},{pre:"너",mid:"라면",post:"",hit:!0},{pre:"그",mid:"",post:"",hit:!1},{pre:"사람한테",mid:"",post:"",hit:!1},{pre:"전화할",mid:"",post:"",hit:!1},{pre:"거예요.",mid:"",post:"",hit:!1}],ko:"내가 너라면 그 사람한테 전화할 거예요.",en:"If I were you, I'd call him.",romanization:"naega neoramyeon geu saramhante jeonhwahal geoyeyo."}],rule:{name:"-다면 / N(이)라면",rows:[{when:"Verb stem",add:"-ㄴ/는다면",ex:"가다 → 간다면; 먹다 → 먹는다면"},{when:"Adjective stem",add:"-다면",ex:"바쁘다 → 바쁘다면; 많다 → 많다면"},{when:"Past (any stem)",add:"-았/었다면",ex:"왔다면; 먹었다면"},{when:"Noun ending in a consonant",add:"N이라면",ex:"학생 → 학생이라면"},{when:"Noun ending in a vowel",add:"N라면",ex:"부자 → 부자라면; 의사 → 의사라면"}]},more:{func:`Use -다면 / N(이)라면 to set up a "what if" — an imagined or supposed situation, often one you don't really expect or that isn't true right now: "if (let's say)...".`,keyPoint:{label:"-다면 vs. -(으)면",body:'-(으)면 is the all-purpose "if/when," fine for real, likely things (밥 먹으면 = when/if I eat). -다면 puts more weight on "just supposing," so it suits imagined or unlikely cases. For everyday real conditions, -(으)면 is still your default. The full -았/었다면 "would have" pattern is explored more later.'},pronunciation:"많다면 sounds like [만타면]: the ㅎ in 많 blends with the following ㄷ into an aspirated [ㅌ]."}},{kind:"drill",prompt:"If you happen to have time, let's catch a movie.",sentence:"시간이 있___ 같이 영화 봐요.",options:[{text:"다면",ok:!0},{text:"라면",ok:!1}],explanation:"있다 takes -다면; here it frames a supposed condition before a suggestion."}],canDo:"Hedge and leave room with trailing -(으)ㄴ/는데요 and 아마 / 글쎄요",id:"chapter-40-b7",chapterId:"chapter-40",index:6},{kind:"pattern",title:"문법 Grammar · -(으)ㄴ/는데요",cards:[{kind:"hunt",name:"-(으)ㄴ/는데요",sub:"Softening and Leaving Room",lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"매운",mid:"",post:"",hit:!1},{pre:"거",mid:"",post:"",hit:!1},{pre:"잘",mid:"",post:"",hit:!1},{pre:"못",mid:"",post:"",hit:!1},{pre:"먹",mid:"는데요",post:".",hit:!0}],ko:"저는 매운 거 잘 못 먹는데요.",en:"I'm not so good with spicy food, actually...",romanization:"jeoneun maeun geo jal mot meongneundeyo."},{tokens:[{pre:"어제는",mid:"",post:"",hit:!1},{pre:"비가",mid:"",post:"",hit:!1},{pre:"왔",mid:"는데요",post:".",hit:!0}],ko:"어제는 비가 왔는데요.",en:"It rained yesterday, though...",romanization:"eojeneun biga watneundeyo."}],rule:{name:"-(으)ㄴ/는데요",rows:[{when:"Action verb (present)",add:"-는데요",ex:"가다 → 가는데요; 먹다 → 먹는데요"},{when:"Adjective, vowel stem (present)",add:"-ㄴ데요",ex:"바쁘다 → 바쁜데요; 크다 → 큰데요"},{when:"Adjective, consonant stem (present)",add:"-은데요",ex:"좋다 → 좋은데요; 작다 → 작은데요"},{when:"Past (any stem)",add:"-았/었는데요",ex:"가다 → 갔는데요; 먹다 → 먹었는데요"},{when:"Noun (present)",add:"N인데요",ex:"학생 → 학생인데요"}]},more:{func:`Ending a sentence with -(으)ㄴ/는데요 softens it. Instead of a hard statement, it sets something up and leaves the door open — for the other person to react, for a "but...," or for a gentle pushback. It's one of the most common ways Koreans avoid sounding too direct.`,keyPoint:{label:"-(으)ㄴ/는데요 vs. a plain -아/어요 ending",body:`좀 바빠요 just states "I'm busy." 좀 바쁜데요 says the same thing but trails off, inviting the other person to fill in the rest — softer and less final. Use it to hedge, hint, or set up a contrast. Its longer use for connecting two clauses ("~는데, …") comes in a separate point.`},pronunciation:"In 먹는데요, the ㄱ before ㄴ turns nasal: it sounds like [멍는데요]. 좋은데요 sounds like [조은데요], with the ㅎ dropping out."}}],canDo:"Offer a soft but confident guess with -(으)ㄹ걸요 (괜찮을걸요)",id:"chapter-40-b8",chapterId:"chapter-40",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two coworkers need to contact someone, but they are not sure whether that person is still available.",lines:[{speaker:"민서",ko:"그분은 아직 회의 중일걸요.",en:"They are probably still in a meeting.",romanization:"geubuneun ajik hoeui jungilgeolyo."},{speaker:"지훈",ko:"글쎄요, 이미 퇴근했을 수도 있어요.",en:"Hmm, they may have already left work.",romanization:"geulsseyo, imi toegeunhaesseul sudo isseoyo."},{speaker:"민서",ko:"혹시 이미 나갔다면 메시지를 남겨 두면 좋겠어요.",en:"If they already left, it would be good to leave a message.",romanization:"hoksi imi nagatdamyeon mesijireul namgyeo dumyeon jokesseoyo."},{speaker:"지훈",ko:"네, 확실하지 않으니까 조심스럽게 물어볼게요.",en:"Yes, since I am not sure, I will ask carefully.",romanization:"ne, hwaksilhaji aneunikka josimseureopge mureobolgeyo."},{speaker:"민서",ko:"제 생각에는 먼저 물어보는 게 좋을 것 같아요.",en:"In my opinion, I think it would be good to ask first.",romanization:"je saenggageneun meonjeo mureoboneun ge joeul geot gatayo."}]},{kind:"order",prompt:"Build: 'If that is the case, let's ask first.'",tokens:["그렇다면","먼저 물어봐요"],correct:"그렇다면 먼저 물어봐요",explanation:"그렇다면 opens a hypothetical path from the previous idea. 먼저 물어봐요 gives the suggested next step."}],canDo:"Offer a soft but confident guess with -(으)ㄹ걸요 (괜찮을걸요)",id:"chapter-40-b9",chapterId:"chapter-40",index:8},{kind:"reading",title:"읽기 Reading · 확실하지 않을 때 말하는 법",cards:[{kind:"read",title:"확실하지 않을 때 말하는 법",chunks:["회사 단톡방에서 누가 아직 회의 중인지, 이미 퇴근했는지 모를 때가 있어요. 이때 한국어는 한 가지 'I think'만 쓰지 않아요. 기억이나 상황을 보고 짐작하면 '아직 회의 중일걸요'라고 말할 수 있고, 가능성을 열어 두고 싶으면 '이미 나갔다면 메시지를 남겨 두면 좋겠어요'처럼 말해요.","내 의견을 조심스럽게 말할 때는 '제 생각에는 먼저 물어보는 게 좋을 것 같아요'가 자연스러워요. 중요한 건 약하게 말하는 것이 아니라, 내가 아는 정도에 맞게 문장을 고르는 거예요."],translation:"In a work chat, you may not know whether someone is still in a meeting or already left work. Korean does not use one single 'I think' for every case. Use -ㄹ걸요 for a hunch, -다면 for a hypothetical, 좋겠어요 for a hoped-for or gentle next step, and 것 같아요 to soften your own opinion. The point is not to be weak; it is to match the sentence to how much you actually know.",qas:[{q:"회의 중인지 확실하지 않을 때 어떤 표현을 쓸 수 있어요?",a:"아직 회의 중일걸요."},{q:"이미 나갔을 가능성을 열어 둘 때 어떤 연결을 썼어요?",a:"이미 나갔다면"},{q:"내 의견을 조심스럽게 말할 때 왜 것 같아요를 써요?",a:"의견을 너무 단정적으로 들리지 않게 부드럽게 만들기 위해서예요."}]}],canDo:"Express a hope or wish with -(으)면 좋겠어요 (괜찮으면 좋겠어요)",id:"chapter-40-b10",chapterId:"chapter-40",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence gives a soft but fairly confident guess?",sentence:null,options:[{text:"아직 회의 중일걸요.",ok:!0},{text:"아직 회의 중이라면요.",ok:!1},{text:"아직 회의 중이면 좋겠어요.",ok:!1}],explanation:"-ㄹ걸요 marks a careful guess based on what the speaker thinks."},{kind:"drill",prompt:"Which sentence opens a hypothetical before suggesting the next step?",sentence:null,options:[{text:"이미 나갔다면 메시지를 남겨 두면 좋겠어요.",ok:!0},{text:"이미 나갔을걸요 메시지를 남겨요.",ok:!1},{text:"이미 나간 것 같아요 회의 중이에요.",ok:!1}],explanation:"-다면 sets up the condition, and -으면 좋겠어요 gives a gentle suggestion."},{kind:"drill",prompt:"Which reply is the standard, fixed way to say you understood a request?",sentence:null,options:[{text:"네, 알겠어요.",ok:!0},{text:"네, 알 것 같아요.",ok:!1},{text:"네, 알걸요.",ok:!1}],explanation:"알겠어요 is a set response meaning 'I understand / okay.'"},{kind:"drill",prompt:"제 생각___ 먼저 물어보는 게 좋아요. (In my opinion...)",sentence:null,options:[{text:"에는",ok:!0},{text:"을",ok:!1},{text:"에서",ok:!1}],explanation:"제 생각에는 frames the statement as your opinion. 을 and 에서 do not make the opinion-frame expression."},{kind:"order",prompt:"Build: 'If that is the case, let's ask first.'",tokens:["그렇다면","먼저 물어봐요"],correct:"그렇다면 먼저 물어봐요",explanation:"그렇다면 opens a hypothetical path from the previous idea. 먼저 물어봐요 gives the suggested next step."},{kind:"drill",prompt:"Which response is the cautious “Hmm, I am not sure”?",sentence:null,options:[{text:"글쎄요.",ok:!0},{text:"좋겠어요.",ok:!1},{text:"그렇다면요.",ok:!1}],explanation:"글쎄요 is the natural cautious hesitation. 좋겠어요 is a wish, and 그렇다면요 depends on a hypothetical."}],canDo:"Read -겠- as intention, a guess, or a set phrase (알 수 있겠죠)",id:"chapter-40-b11",chapterId:"chapter-40",index:10}]},{id:"chapter-41",number:41,title:"ㅂ Irregular: 춥다 → 추워요 · ㄷ Irregular: 듣다 → 들어요",goal:"Match high-frequency dictionary forms with their real polite forms.",biteCount:12,bites:[{kind:"words",title:"단어 Words 1 · 춥다~",cards:[{kind:"guess",word:{ko:"춥다",romanization:"chupda",en:"cold (weather)",pos:"adjective",nuance:"춥다 is the ㅂ-irregular adjective for ambient air being unpleasantly cold — winter, a chilly room, a draft. The crucial contrast for English speakers is 춥다 vs 차갑다: 춥다 is how the WEATHER/AIR feels to your whole body, while 차갑다 is how a cold OBJECT feels to your hand (차가운 물 'cold water', 차가운 손 'cold hands'). Never say 추운 물 — water is 차갑다. As a ㅂ-irregular it conjugates 춥다 → 추워요 → 추운 → 추우니까 → 추워서, so writing 춥어요 or 춥은 (the regular pattern) is the classic beginner slip. It is register-neutral and universal. The matching noun is 추위, and 추위를 타다 means 'to be cold-sensitive,' the exact mirror of 더위를 타다."},sentence:{ko:"오늘 너무 추워요.",en:"It is so cold today."},target:"추워",options:["to be spicy","cold (weather)","to be difficult"],note:"Linked to dictionary card word-ext-266."},{kind:"guess",word:{ko:"덥다",romanization:"deopda",en:"hot (weather)",pos:"adjective",nuance:"덥다 is the ㅂ-irregular adjective for FELT air temperature being unpleasantly high — hot weather, a stuffy room, a sweaty body. The key English-speaker trap is that English 'hot' covers four different Korean words: use 덥다 ONLY for ambient air/weather. A hot object you touch is 뜨겁다 (뜨거운 커피, never 더운 커피), spicy food is 맵다, and pleasant warmth is 따뜻하다. Because it is ㅂ-irregular, the ㅂ becomes 우 before a vowel: 덥다 → 더워요(polite) → 더운(modifier) → 더우니까(reason) → 더워서. Beginners constantly write 덥어요 or 덥은 by treating it as regular — that is the number-one error. It is neutral in register and used by everyone; the related noun is 더위 ('the heat'), and people say 더위를 먹다 to mean 'suffer heatstroke.'"},sentence:{ko:"어제는 정말 더웠어요.",en:"Yesterday was really hot."},target:"더웠",options:["hot (weather)","to be spicy","to be difficult"],note:"Linked to dictionary card word-ext-265."},{kind:"guess",word:{ko:"맵다",romanization:"maepda",en:"to be spicy",pos:"adjective",nuance:"맵다 is ㅂ irregular: 매워요, 매운 음식. It is especially useful for food restrictions, because 매운 음식은 못 먹어요 is a survival sentence."},sentence:{ko:"이 떡볶이는 많이 매워요.",en:"This tteokbokki is very spicy."},target:"매워",options:["cold (weather)","to be spicy","hot (weather)"],note:"Linked to dictionary card word-adjective-035."},{kind:"guess",word:{ko:"어렵다",romanization:"eoryeopda",en:"to be difficult",pos:"adjective",nuance:"어렵다 is ㅂ irregular: 어려워요, 어려운. It is useful in classroom repair conversations because learners often need to say a sentence or lesson is difficult."},sentence:{ko:"이 문제는 너무 어려워요.",en:"This problem is too difficult."},target:"어려워",options:["to be difficult","cold (weather)","hot (weather)"],note:"Linked to dictionary card word-adjective-037."},{kind:"guess",word:{ko:"쉽다",romanization:"swipda",en:"to be easy",pos:"adjective",nuance:"쉽다 is ㅂ irregular: 쉬워요, 쉬운. It helps learners talk about difficulty level, but the opposite 어렵다 is often needed in the same lesson."},sentence:{ko:"생각보다 쉬워요.",en:"It is easier than I thought."},target:"쉬워",options:["to be easy","cold (weather)","hot (weather)"],note:"Linked to dictionary card word-adjective-036."},{kind:"guess",word:{ko:"듣다",romanization:"deutda",en:"to listen",pos:"verb",nuance:"듣다 is ㄷ irregular: 듣다 becomes 들어요 in polite speech."},sentence:{ko:"저는 아침마다 음악을 들어요.",en:"I listen to music every morning."},target:"들어",options:["to walk","to ask","to listen"],note:"Linked to dictionary card word-verb-013."}],canDo:"Conjugate ㅂ-irregular adjectives correctly (춥다→추워요 · 어렵다→어려워요)",id:"chapter-41-b1",chapterId:"chapter-41",index:0},{kind:"pattern",title:"문법 Grammar · ㅂ Irregular: 춥다 → 추워요",cards:[{kind:"teach",name:"ㅂ Irregular: 춥다 → 추워요",sub:"",rows:[{when:"Stem ends in ㅂ, before a vowel ending (-아/어요, -았/었-, -으니까)",add:"ㅂ → 우, then add 어요 (우+어 = 워)",ex:"춥다 → 추+우+어요 → 추워요"},{when:"Stem ends in ㅂ, before a consonant ending (-고, -지만, -습니다)",add:"no change, ㅂ stays",ex:"춥다 → 춥고, 춥지만"},{when:"돕다 / 곱다 only",add:"ㅂ → 오 (오+아 = 와)",ex:"돕다 → 도+오+아요 → 도와요"}],examples:[{ko:"오늘 날씨가 너무 추워요.",en:"The weather is so cold today.",romanization:"oneul nalssiga neomu chuwoyo.",note:"춥다 + 아/어요: ㅂ turns to 우, then 우+어 joins into 워."},{ko:"이 가방은 정말 가벼워요.",en:"This bag is really light.",romanization:"i gabangeun jeongmal gabyeowoyo.",note:"가볍다 follows the same ㅂ → 우 → 워 pattern."}],more:{func:"A lot of describing words (and a few action words) whose stem ends in ㅂ change that ㅂ to 우 when a vowel ending comes next. That's why 춥다 (to be cold) becomes 추워요, not 춥어요.",keyPoint:{label:"Vowel ending vs consonant ending",body:"The ㅂ only changes before a vowel: 춥다 → 추워요 (vowel) but 춥다 → 춥고 (consonant). Almost all ㅂ-irregular words use 우; only 돕다 and 곱다 use 오. For now, just learn 추워요 as a set phrase and you'll see the pattern."},pronunciation:"추워요 is said smoothly as [추워요]. The 우+어 → 워 is a real spelling change, not just a sound, so you actually write 워."}}],canDo:"Conjugate ㅂ-irregular adjectives correctly (춥다→추워요 · 어렵다→어려워요)",id:"chapter-41-b2",chapterId:"chapter-41",index:1},{kind:"words",title:"단어 Words 2 · 걷다~",cards:[{kind:"guess",word:{ko:"걷다",romanization:"geotda",en:"to walk",pos:"verb",nuance:"걷다 means to walk on foot and is a ㄷ irregular verb: before a vowel ending the final ㄷ softens to ㄹ, so the 요-form is 걸어요 (not 걷어요) and the past is 걸었어요. Before a consonant ending the ㄷ stays put, so the formal form remains 걷습니다 and you say 걷지 마세요, 걷고 싶어요. The nearest relative is 산책하다 ('take a stroll'): 걷다 is the raw act of walking anywhere, while 산책하다 implies a leisurely walk for pleasure, so 'I walk to work' is 걸어서 출근해요, never 산책해서 출근해요. The trap for English speakers is that 걷다 doesn't take an object the way 'walk the dog' does — Korean uses 산책시키다 for that, and the path you walk takes 을/를 (공원을 걸어요), so don't reach for 에. Also remember 걸어서 ('on foot') is one fixed chunk for describing how you travel."},sentence:{ko:"퇴근하고 공원을 걸어요.",en:"I walk in the park after work."},target:"걸어",options:["to walk","to listen","to ask"],note:"Linked to dictionary card word-verb-400."},{kind:"guess",word:{ko:"묻다",romanization:"mutda",en:"to ask",pos:"verb",nuance:"묻다 means 'to ask (a question / inquire)' and takes the object marker 을/를 for the thing asked about: 길을 물어요. It is a ㄷ-irregular verb: before a vowel ending the stem ㄷ changes to ㄹ, giving 물어요 and 물었어요 and 물을 거예요, but before consonant endings the ㄷ stays — 묻습니다, 묻고, 묻지 마세요. The person you ask takes 에게/한테, or honorific 께 for someone of higher status: 선생님께 물어요. In real speech Koreans far more often say 물어보다 ('ask and see', literally 묻다 + 보다), which sounds softer and more tentative than the bare, slightly abrupt 묻다 — so 물어보세요 ('please ask') is the natural request, not 물으세요. Two contrasts: do not confuse this 묻다 with the homograph 묻다 meaning 'to bury' (regular: 땅에 묻다), and distinguish 묻다 ('ask a question') from 부탁하다 ('to request a favor'). The English-speaker pitfall is keeping the ㄷ before a vowel to say 묻어요 (which actually reads as the 'bury' verb) instead of the irregular 물어요."},sentence:{ko:"모르면 선생님께 물어봐요.",en:"If you do not know, ask the teacher."},target:"물어",options:["to listen","to walk","to ask"],note:"Linked to dictionary card word-verb-353."},{kind:"guess",word:{ko:"낫다",romanization:"natda",en:"to heal; to get better",pos:"verb",nuance:"낫다 means an illness or wound heals, and it is a ㅅ-irregular verb: the ㅅ disappears before a vowel (나아요, 나았어요, 나을, 나으세요) but stays before a consonant (낫습니다, 낫고, 낫지). It is intransitive — the cold or the cut is the subject (감기가 나았어요, 상처가 나았어요) — so you never 'heal something' with it; for that you'd use 치료하다 (to treat) or 고치다 (to cure/fix). The big trap for everyone, native and learner alike, is the homophone cluster: 낫다 'heal', 낳다 'give birth', and 났다 (from 나다, 'broke out/occurred') all sound like [낟따] but mean totally different things, so 나았어요 (got better) must never be spelled 낳았어요 (gave birth). Note 낫다 also has a second meaning, 'to be better/preferable' (이게 더 나아요 = this one's better), which shares the exact same conjugation. It collocates with 빨리/금방/곧 낫다 (heal fast/soon) and 다 낫다 (fully heal)."},sentence:{ko:"감기가 다 나았어요.",en:"My cold got completely better."},target:"나았",options:["to heal; to get better","to listen","to walk"],note:"Linked to dictionary card word-verb-053."},{kind:"guess",word:{ko:"모르다",romanization:"moreuda",en:"to not know",pos:"verb",nuance:"모르다 is the standalone verb 'to not know / be unaware of', the lexical opposite of 알다, and it likewise takes the object marker 을/를: 길을 몰라요. It is a 르-irregular: when an 아/어 ending attaches, the 르 stem doubles the ㄹ and the vowel drops, so 모르 + 아요 → 몰라요 (never 모르아요) and the past is 몰랐어요. The crucial register tool is 겠: 잘 모르겠어요 ('I'm not quite sure') is markedly softer and more natural than a blunt 몰라요, which can sound curt or even dismissive depending on tone, so Koreans lean on the 겠 form constantly when admitting ignorance politely. Compare 모르다 with 헷갈리다 ('to be confused / mix things up'): 모르다 is having no information at all, while 헷갈리다 is having information but getting it tangled. The English-speaker pitfall is the conjugation — applying a regular pattern to get 모르아요 instead of the irregular 몰라요 — and forgetting that the smooth, courteous version is 잘 모르겠어요."},sentence:{ko:"저는 그 사람 이름을 몰라요.",en:"I do not know that person's name."},target:"몰라",options:["to listen","to walk","to not know"],note:"Linked to dictionary card word-verb-345."},{kind:"guess",word:{ko:"다르다",romanization:"dareuda",en:"to be different",pos:"adjective",nuance:"다르다 is the antonym of 같다 and conjugates as a 르-irregular: the stem 다르 + 아요 doubles the ㄹ and drops 으 to give 달라요 (never 다라요); past is 달랐어요. The pre-noun form 다른 is one of the most-used words in Korean and covers both 'different' and 'another' (다른 색 = 'a different/another colour'). The dangerous trap for English speakers is 틀리다, which means 'to be wrong / incorrect' — even native speakers loosely say 틀리다 for 'different' in speech, but in correct Korean 답이 틀리다 = 'the answer is wrong' while 답이 다르다 = 'the answer is different'. Mixing them can imply someone is mistaken when you only meant they differ, which can sound rude. Pair 다르다 with 하고/와 for the thing compared: 작년하고 달라요 ('it's different from last year')."},sentence:{ko:"두 색깔이 조금 달라요.",en:"The two colors are a little different."},target:"달라",options:["to be different","cold (weather)","hot (weather)"],note:"Linked to dictionary card word-ext-1244."},{kind:"guess",word:{ko:"부르다",romanization:"bureuda",en:"to call",pos:"verb",nuance:"부르다 chiefly means to call/summon someone to come (택시를 부르다, 친구를 부르다), to call out a name (이름을 부르다), and — a key idiom — to sing (노래를 부르다, the standard phrase, not 노래를 하다). Don't confuse it with 전화하다, which is 'to phone': 친구를 불러요 means call your friend over to where you are, while 친구한테 전화해요 means ring them up. It's a textbook 르-irregular: before an 아/어 ending the final ㅡ drops and an extra ㄹ appears, so 부르 + 어요 → 불러요 and past → 불렀어요, but before consonant endings it stays whole (부르고, 부를 거예요, 부릅니다). Two traps: first, learners say 부르어요 — wrong, it must be 불러요. Second, beware the homonym 부르다 'to be full' (배가 부르다), a completely different adjective; 배가 불러요 means 'I'm full', not 'the stomach calls'. Also note honorific contexts: to summon a superior you'd soften with 모시다 ('escort/bring respectfully') rather than bluntly 부르다."},sentence:{ko:"제 이름을 불러 주세요.",en:"Please call my name."},target:"불러",options:["to listen","to call","to walk"],note:"Linked to dictionary card word-verb-477."},{kind:"payoff",line:{speaker:"지훈",ko:"맞아요. 모르다는 몰라요, 빨갛다는 빨개요처럼 익히면 돼요.",en:"Right. Learn them as pairs, like 모르다 to 몰라요 and 빨갛다 to 빨개요."},hl:"모르"}],canDo:"Conjugate ㄷ-irregular verbs correctly (듣다→들어요 · 걷다→걸어요)",id:"chapter-41-b3",chapterId:"chapter-41",index:2},{kind:"pattern",title:"문법 Grammar · ㄷ Irregular: 듣다 → 들어요",cards:[{kind:"teach",name:"ㄷ Irregular: 듣다 → 들어요",sub:"",rows:[{when:"ㄷ-irregular stem + vowel ending (-아/어요, -았/었-, -으면)",add:"ㄷ → ㄹ, then add 어요",ex:"듣다 → 들+어요 → 들어요"},{when:"ㄷ-irregular stem + consonant ending (-고, -지만, -습니다)",add:"no change, ㄷ stays",ex:"듣다 → 듣고, 듣습니다"},{when:"Regular ㄷ verbs (받다, 닫다, 믿다)",add:"ㄷ never changes",ex:"받다 → 받아요 (not 발아요)"}],examples:[{ko:"저는 음악을 자주 들어요.",en:"I listen to music a lot.",romanization:"jeoneun eumageul jaju deureoyo.",note:"듣다 + 아/어요: ㄷ becomes ㄹ before the vowel, so 들어요."},{ko:"매일 학교까지 걸어요.",en:"I walk to school every day.",romanization:"maeil hakgyokkaji georeoyo.",note:"걷다 (to walk) is ㄷ-irregular: 걷 → 걸 → 걸어요."}],more:{func:"A small group of action words whose stem ends in ㄷ change that ㄷ to ㄹ when a vowel ending follows. So 듣다 (to hear/listen) becomes 들어요, not 듣어요.",keyPoint:{label:"Not every ㄷ verb is irregular",body:"Only a few verbs change (듣다, 걷다, 묻다 'ask', 싣다 'load'). Everyday verbs like 받다 (get), 닫다 (close), 믿다 (believe) keep their ㄷ: 받아요, 닫아요, 믿어요. You just have to remember which ones are irregular."},pronunciation:"들어요 links as [드러요] — the ㄹ slides into the next syllable. Don't worry about the rule mid-conversation; learn 들어요 as a chunk."}}],canDo:"Conjugate ㄷ-irregular verbs correctly (듣다→들어요 · 걷다→걸어요)",id:"chapter-41-b4",chapterId:"chapter-41",index:3},{kind:"words",title:"단어 Words 3 · 빨갛다~",cards:[{kind:"guess",word:{ko:"빨갛다",romanization:"ppalgata",en:"to be red",pos:"adjective",nuance:"빨갛다 is the vivid, pure 'red' of an apple, a stop light, or a blushing face. Among red words, contrast it with 붉다, which is the more literary, darker 'reddish/crimson' used for blood, sunsets, and emotion (붉은 노을), while 빨갛다 is the bright everyday red a child would point at. As an adjective it describes a STATE, so the thing that is red takes 이/가 (얼굴이 빨개요), never 을/를. The biggest trap for English speakers is the ㅎ-irregular: the stem-final ㅎ vanishes AND the vowel fuses, so it is never 빨갛아요 but 빨개요, and the noun-modifying form is 빨간 (빨간 사과), not 빨갛은. To say something 'turns red,' use 빨개지다, because 빨갛다 alone is a static quality, not a change. Note 빨간색 is the noun 'the color red.'"},sentence:{ko:"얼굴이 빨개요.",en:"Your face is red."},target:"빨개",options:["to be red","cold (weather)","hot (weather)"],note:"Linked to dictionary card word-ext-1207."},{kind:"guess",word:{ko:"파랗다",romanization:"parata",en:"to be blue",pos:"adjective",nuance:"파랗다 is the bright blue of a clear sky and the sea, and in Korean it famously also covers what English calls 'green' for traffic lights and fresh leaves (파란불 'the green light,' 파란 잔디 'green grass') — a real surprise for learners. The neighboring word 푸르다 is more poetic and leans 'verdant/azure,' used for 푸른 산 'green mountains' and 푸른 하늘 in songs, while 파랗다 is the plain everyday blue. Being an adjective, the blue thing takes 이/가 (하늘이 파래요), not 을/를. The ㅎ-irregular is the key pitfall: never 파랗아요 but 파래요, and the modifier is 파란 (파란 바다), not 파랗은. Use 파래지다 for 'turn blue,' and 파란색 for the noun 'the color blue.'"},sentence:{ko:"오늘 하늘이 파래요.",en:"The sky is blue today."},target:"파래",options:["cold (weather)","to be blue","hot (weather)"],note:"Linked to dictionary card word-ext-1208."},{kind:"guess",word:{ko:"노랗다",romanization:"norata",en:"to be yellow",pos:"adjective",nuance:"노랗다 is the cheerful pure yellow of a banana, a chick, or a school bus. Korean color adjectives like this come in a 'bright vs dark' vowel-harmony pair: 노랗다 (bright, with ㅗ/ㅏ) feels light and vivid, while its darker partner 누렇다 (with ㅜ/ㅓ) means a dull, dingy, faded yellow like old paper or unhealthy skin — choosing the wrong one changes the whole feeling. As an adjective it takes 이/가 on the yellow thing (잎이 노래요), not 을/를. Watch the ㅎ-irregular: it is 노래요, never 노랗아요, and the modifier is 노란 (노란 우산), not 노랗은. There is also a vivid set phrase 눈앞이 노래지다 'to feel faint/hopeless,' literally 'the front of the eyes turns yellow.' The noun is 노란색."},sentence:{ko:"바나나가 노래요.",en:"The banana is yellow."},target:"노래",options:["to be yellow","cold (weather)","hot (weather)"],note:"Linked to dictionary card word-ext-1209."},{kind:"guess",word:{ko:"어떻다",romanization:"eotteota",en:"to be how",pos:"adjective",nuance:"어떻다 is the question-adjective 'to be how / to be what-like,' the root behind a whole family Koreans use constantly. Learn its three faces: 어때(요)? = 'How is it? / How about it?' (asking a state or making a soft suggestion — 이거 어때요?), 어떤 = the modifier 'what kind of' before a noun (어떤 음악 'what kind of music'), and 어떻게 = the adverb 'how / in what way' for asking method (어떻게 해요? 'how do you do it?'). Do not confuse 어떻다 with 어떡하다, the contraction of 어떻게 하다 'to do how,' which gives the very common cry 어떡해! 'what do I do?!' As an irregular ㅎ adjective, the polite/question form is 어때요, never 어떻아요, and the past is 어땠어요. The single most frequent learner error is choosing the wrong family member — using 어떤 where 어떻게 is needed, or vice versa."},sentence:{ko:"이 방법은 어때요?",en:"How is this method?"},target:"어때",options:["to be how","cold (weather)","hot (weather)"],note:"Linked to dictionary card word-ext-1218."},{kind:"guess",word:{ko:"알다",romanization:"alda",en:"to know",pos:"verb",nuance:"알다 means 'to know / be aware of / be acquainted with' and takes the object marker 을/를: 저 사람을 알아요. It is a ㄹ-irregular verb: the stem ㄹ drops before ㅂ, ㄴ, and the honorific ㅅ, giving 압니다 (not 알습니다) and 아세요 (not 알으세요), but the ㄹ stays before vowel endings, so the everyday polite form is 알아요. Two contrasts are essential. First, its opposite is not the negative 안 알아요 — that is wrong — but the separate verb 모르다, so 'I don't know' is 몰라요. Second, 알다 vs 알겠다: 알아요 claims knowledge you already hold ('I know that'), while 알겠어요 signals you have just understood or accepted something ('I see / got it / will do'), which is why a polite 'understood' is 알겠습니다, never 압니다. The English-speaker pitfall is twofold: forming 'don't know' as 안 알아요 instead of 몰라요, and keeping the ㄹ to say 알습니다 instead of 압니다."},sentence:{ko:"이 단어를 아세요?",en:"Do you know this word?"},target:"아세",options:["to know","to listen","to walk"],note:"Linked to dictionary card word-verb-344."},{kind:"guess",word:{ko:"살다",romanization:"salda",en:"to live",pos:"verb",nuance:"살다 means 'to live' in two senses — to reside somewhere and to be alive — and is a ㄹ-irregular verb. The stem ㄹ disappears before ㅂ, ㄴ, and the honorific 시, producing 삽니다 (not 살읍니다), 사세요 (not 살으세요), and 사니까; before vowel endings the ㄹ stays, so the polite present is 살아요. For where you live, the default particle is the static-location 에: 서울에 살아요. Interestingly, because living is an activity carried out over time, the dynamic-location 에서 is also acceptable and common, especially with hopes and experiences (한국에서 살고 싶어요) — this is one of the few cases where both 에 and 에서 work with the same verb. Contrast 살다 with 거주하다 (居住하다, Sino-Korean 'to reside'), a stiff, formal/written word used on official forms (거주지 'place of residence'); in speech you always say 살다. The English-speaker pitfall is keeping the ㄹ to say 살읍니다 instead of 삽니다, and reflexively choosing 에서 for every location when plain residence prefers 에."},sentence:{ko:"어디 사세요?",en:"Where do you live?"},target:"사세",options:["to live","to listen","to walk"],note:"Linked to dictionary card word-verb-346."},{kind:"payoff",line:{speaker:"지훈",ko:"맞아요. 모르다는 몰라요, 빨갛다는 빨개요처럼 익히면 돼요.",en:"Right. Learn them as pairs, like 모르다 to 몰라요 and 빨갛다 to 빨개요."},hl:"빨갛"}],canDo:"Conjugate 르-irregular and ㅡ-irregular words (모르다→몰라요 · 바쁘다→바빠요)",id:"chapter-41-b5",chapterId:"chapter-41",index:4},{kind:"pattern",title:"문법 Grammar · ㅅ Irregular: 낫다 → 나아요",cards:[{kind:"teach",name:"ㅅ Irregular: 낫다 → 나아요",sub:"",rows:[{when:"ㅅ-irregular stem + vowel ending (-아/어요, -았/었-, -으면)",add:"ㅅ drops; vowels stay separate (no joining)",ex:"낫다 → 나+아요 → 나아요"},{when:"ㅅ-irregular stem + consonant ending (-고, -지만, -습니다)",add:"no change, ㅅ stays",ex:"낫다 → 낫고, 낫습니다"},{when:"Regular ㅅ verbs (웃다, 씻다, 벗다)",add:"ㅅ never drops",ex:"웃다 → 웃어요 (not 우어요)"}],examples:[{ko:"감기가 다 나았어요.",en:"My cold is all better now.",romanization:"gamgiga da naasseoyo.",note:"낫다 → 나았어요; ㅅ drops but 나+았 stays as two parts, no joining."},{ko:"이 식당이 저 식당보다 나아요.",en:"This restaurant is better than that one.",romanization:"i sikdangi jeo sikdangboda naayo.",note:"낫다 'be better' → 나아요; the two ㅏ's stay separate, written 나아."}],more:{func:"Some action/describing words whose stem ends in ㅅ drop the ㅅ before a vowel ending — but unlike ㄷ and ㅂ, the two vowels do NOT join up. So 낫다 (to get better) becomes 나아요, keeping both vowels.",keyPoint:{label:"ㅅ drops but the vowels stay apart",body:"Unlike 추워요 or 들어요, the ㅅ-irregular leaves the two vowels apart: 낫다 → 나아요 (not 나요). Compare regular 웃다 → 웃어요, where the ㅅ stays. The irregular ones to know: 낫다, 붓다, 젓다, 짓다."},pronunciation:"나아요 keeps two clear ㅏ sounds [나아요]; don't shorten it to [나요]. That held, two-beat vowel is the giveaway of the ㅅ-irregular."}}],canDo:"Conjugate 르-irregular and ㅡ-irregular words (모르다→몰라요 · 바쁘다→바빠요)",id:"chapter-41-b6",chapterId:"chapter-41",index:5},{kind:"pattern",title:"문법 Grammar · 르 Irregular: 모르다 → 몰라요",cards:[{kind:"teach",name:"르 Irregular: 모르다 → 몰라요",sub:"",rows:[{when:"르 stem + vowel ending, when the syllable before 르 has ㅏ or ㅗ",add:"drop ㅡ, add ㄹ to the syllable before, then 라",ex:"모르다 → 몰ㄹ + 아 → 몰라요"},{when:"르 stem + vowel ending, when the syllable before 르 has any other vowel",add:"drop ㅡ, add ㄹ to the syllable before, then 러",ex:"부르다 → 불ㄹ + 어 → 불러요"},{when:"르 stem + consonant ending (-고, -지만)",add:"no change",ex:"모르다 → 모르고, 모르지만"}],examples:[{ko:"그 사람 이름을 잘 몰라요.",en:"I don't really know that person's name.",romanization:"geu saram ireumeul jal mollayo.",note:"모르다 → 몰라요; 모 before 르 has ㅗ, so the ending is 라."},{ko:"친구가 노래를 불렀어요.",en:"My friend sang a song.",romanization:"chinguga noraereul bulleosseoyo.",note:"부르다 → 불렀어요; 부 has ㅜ (not ㅏ/ㅗ), so the ending is 러/렀."}],more:{func:"Words ending in 르 add an extra ㄹ to the syllable before 르 and drop the ㅡ before -아/어. So 모르다 (to not know) becomes 몰라요, with a doubled ㄹ.",keyPoint:{label:"라 vs 러 depends on the vowel before 르",body:"If the syllable before 르 has ㅏ or ㅗ, use 라 (모르다 → 몰라요, 빠르다 → 빨라요). Otherwise use 러 (부르다 → 불러요, 누르다 → 눌러요). It's the same ㅏ/ㅗ vs everything-else choice as -아요/-어요."},pronunciation:"몰라요 has a strong doubled ㄹ [몰라요] — the first ㄹ closes 몰 and the second opens 라."}}],canDo:"Conjugate ㅂ-irregular adjectives correctly (춥다→추워요 · 어렵다→어려워요)",id:"chapter-41-b7",chapterId:"chapter-41",index:6},{kind:"pattern",title:"문법 Grammar · ㅡ Irregular: 바쁘다 → 바빠요",cards:[{kind:"teach",name:"ㅡ Irregular: 바쁘다 → 바빠요",sub:"",rows:[{when:"ㅡ stem + vowel ending, when the syllable before ㅡ has ㅏ or ㅗ",add:"drop ㅡ, add 아 → 빠",ex:"바쁘다 → 바ㅃ + 아 → 바빠요"},{when:"ㅡ stem + vowel ending, other vowel (or no syllable before, like 쓰다)",add:"drop ㅡ, add 어 → 써/뻐",ex:"쓰다 → ㅆ + 어 → 써요"},{when:"ㅡ stem + consonant ending (-고, -지만)",add:"no change, ㅡ stays",ex:"바쁘다 → 바쁘고, 바쁘지만"}],examples:[{ko:"요즘 일이 너무 바빠요.",en:"I'm so busy these days.",romanization:"yojeum iri neomu bappayo.",note:"바쁘다 → 바빠요; 바 has ㅏ, so the dropped ㅡ takes 아 → 빠."},{ko:"지금 편지를 써요.",en:"I'm writing a letter right now.",romanization:"jigeum pyeonjireul sseoyo.",note:"쓰다 → 써요; nothing before ㅡ, so it defaults to 어 → 써."}],more:{func:"When a stem ends in ㅡ (like 쓰다, 바쁘다), the ㅡ drops out before -아/어. Then the syllable before it decides whether you add 아 or 어. So 바쁘다 (to be busy) becomes 바빠요.",keyPoint:{label:"Drop the ㅡ, then pick 아 or 어",body:"The ㅡ always disappears before -아/어. To choose, look at the syllable before it: ㅏ/ㅗ → 아 (바빠요, 아파요), anything else (or nothing) → 어 (써요, 예뻐요). This is the same vowel-harmony idea as regular -아요/-어요."},pronunciation:"바빠요 has a tense ㅃ [바빠요], and 써요 starts with a tense ㅆ [써요]. The dropped ㅡ leaves a strong, double consonant sound."}}],canDo:"Conjugate ㄷ-irregular verbs correctly (듣다→들어요 · 걷다→걸어요)",id:"chapter-41-b8",chapterId:"chapter-41",index:7},{kind:"pattern",title:"문법 Grammar · ㅎ Irregular: 빨갛다 → 빨개요",cards:[{kind:"teach",name:"ㅎ Irregular: 빨갛다 → 빨개요",sub:"",rows:[{when:"ㅎ-irregular stem + -아/어요",add:"drop ㅎ, vowel becomes ㅐ, add 요",ex:"빨갛다 → 빨가 → 빨개요"},{when:"ㅎ-irregular stem + 어떻다 / 이렇다 etc.",add:"same: drop ㅎ, vowel → ㅐ",ex:"어떻다 → 어때요 / 이렇다 → 이래요"},{when:"ㅎ-irregular stem + consonant ending (-고, -지만)",add:"no change, ㅎ stays",ex:"빨갛다 → 빨갛고, 빨갛지만"}],examples:[{ko:"사과가 정말 빨개요.",en:"The apple is really red.",romanization:"sagwaga jeongmal ppalgaeyo.",note:"빨갛다 → 빨개요; ㅎ drops and the vowel turns into ㅐ."},{ko:"하늘이 너무 파래요.",en:"The sky is so blue.",romanization:"haneuri neomu paraeyo.",note:"파랗다 → 파래요; same ㅎ-drop with the vowel becoming ㅐ."}],more:{func:"Most color words and a few pointing words (그렇다, 어떻다) end in ㅎ. Before -아/어, the ㅎ drops AND the vowel changes to ㅐ. So 빨갛다 (to be red) becomes 빨개요. Note: 좋다 is regular — 좋아요.",keyPoint:{label:"ㅎ drops and the vowel turns into ㅐ",body:"With ㅎ-irregulars, two things happen at once before -아/어: the ㅎ disappears and the vowel becomes ㅐ (빨갛다 → 빨개요, 그렇다 → 그래요). Watch out: 좋다 (be good) is NOT irregular — it's just 좋아요. Learn 그래요 and 어때요 as ready-made phrases first."},pronunciation:"빨개요 is said [빨개요] with the ㅐ vowel; 그래요 is [그래요]. Don't try to keep the ㅎ sound — it's gone before the ending."}}],canDo:"Conjugate 르-irregular and ㅡ-irregular words (모르다→몰라요 · 바쁘다→바빠요)",id:"chapter-41-b9",chapterId:"chapter-41",index:8},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A learner asks why common words change shape in polite speech.",lines:[{speaker:"민서",ko:"오늘 너무 추워요. 그런데 왜 '춥어요'가 아니에요?",en:"It is so cold today. But why isn't it '춥어요'?",romanization:"oneul neomu chuwoyo. geureonde wae 'chupeoyo'ga anieyo?"},{speaker:"지훈",ko:"춥다처럼 ㅂ으로 끝나는 말은 추워요, 더워요처럼 바뀌어요.",en:"Words ending in ㅂ, like 춥다, change to forms like 추워요 and 더워요.",romanization:"chupdacheoreom bieubeuro kkeutnaneun mareun chuwoyo, deowoyo-cheoreom bakkwieoyo."},{speaker:"민서",ko:"그럼 듣다는 들어요, 걷다는 걸어요가 맞죠?",en:"Then 듣다 becomes 들어요, and 걷다 becomes 걸어요, right?",romanization:"geureom deutdaneun deureoyo, geotdaneun georeoyoga matjyo?"},{speaker:"지훈",ko:"맞아요. 모르다는 몰라요, 빨갛다는 빨개요처럼 익히면 돼요.",en:"Right. Learn them as pairs, like 모르다 to 몰라요 and 빨갛다 to 빨개요.",romanization:"majayo. moreudaneun mollayo, ppalgataneun ppalgaeyo-cheoreom ikhimyeon dwaeyo."},{speaker:"민서",ko:"알겠어요. 자주 쓰는 단어부터 외울게요.",en:"Got it. I will memorize the high-frequency words first.",romanization:"algesseoyo. jaju sseuneun daneobuteo oeulgeyo."}]},{kind:"order",prompt:"Build: 'I don't know well.'",tokens:["잘","몰라요"],correct:"잘 몰라요",explanation:"모르다 is a 르 irregular and becomes 몰라요. 잘 softens it to “I do not know well.”"}],canDo:"Conjugate ㅂ-irregular adjectives correctly (춥다→추워요 · 어렵다→어려워요)",id:"chapter-41-b10",chapterId:"chapter-41",index:9},{kind:"reading",title:"읽기 Reading · 사전형과 말할 때의 모양",cards:[{kind:"read",title:"사전형과 말할 때의 모양",chunks:["한국어 사전에는 춥다, 듣다, 모르다처럼 기본형이 나오지만, 실제 대화에서는 추워요, 들어요, 몰라요처럼 바뀐 모양을 더 자주 들어요. 그래서 불규칙 활용은 시험용 표가 아니라 일상 발음과 문장을 바로잡는 도구예요. '오늘 추워요', '음악을 들어요', '저는 잘 몰라요', '이 방법은 어때요?'","같은 문장을 먼저 익히면 규칙 이름도 자연스럽게 따라와요. 단, 비슷하게 생겼다고 모두 바뀌지는 않아요. 듣다는 들어요지만 닫다는 닫아요이고, 낫다는 나아요지만 웃다는 웃어요예요."],translation:"Korean dictionaries show base forms such as 춥다, 듣다, and 모르다, but real conversation uses changed forms such as 추워요, 들어요, and 몰라요. Irregular conjugation is not just a test table; it repairs everyday pronunciation and sentences. Learn useful sentences first, then attach the rule names. Also remember that lookalikes are not always irregular: 듣다 changes to 들어요, but 닫다 stays 닫아요; 낫다 changes to 나아요, but 웃다 stays 웃어요.",qas:[{q:"사전에는 어떤 모양이 나오지만 실제 대화에서는 어떤 모양을 더 자주 들어요?",a:"사전에는 춥다, 듣다, 모르다 같은 기본형이 나오지만 실제 대화에서는 추워요, 들어요, 몰라요 같은 활용형을 더 자주 들어요."},{q:"듣다와 닫다는 어떻게 달라요?",a:"듣다는 들어요로 바뀌지만 닫다는 닫아요로 그대로 활용해요."},{q:"불규칙 활용은 왜 일상 대화에 중요해요?",a:"추워요, 들어요, 몰라요 같은 매우 자주 쓰는 문장에 바로 들어가기 때문이에요."}]}],canDo:"Conjugate ㄷ-irregular verbs correctly (듣다→들어요 · 걷다→걸어요)",id:"chapter-41-b11",chapterId:"chapter-41",index:10},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which form correctly conjugates 춥다 in polite present speech?",sentence:null,options:[{text:"추워요",ok:!0},{text:"춥어요",ok:!1},{text:"춥아요",ok:!1}],explanation:"춥다 follows the ㅂ irregular: ㅂ changes to 우 before 어요."},{kind:"drill",prompt:"Which pair shows the ㄷ irregular?",sentence:null,options:[{text:"듣다 → 들어요",ok:!0},{text:"닫다 → 달아요",ok:!1},{text:"받다 → 발아요",ok:!1}],explanation:"듣다 changes ㄷ to ㄹ. 닫다 and 받다 are regular."},{kind:"drill",prompt:"Which sentence uses 르 irregular correctly?",sentence:null,options:[{text:"저는 그 이름을 몰라요.",ok:!0},{text:"저는 그 이름을 모르어요.",ok:!1},{text:"저는 그 이름을 모라요.",ok:!1}],explanation:"모르다 becomes 몰라요: ㄹ doubles onto the previous syllable."},{kind:"drill",prompt:"Which form is natural for 어떻다?",sentence:null,options:[{text:"어때요?",ok:!0},{text:"어떻어요?",ok:!1},{text:"어떻게요?",ok:!1}],explanation:"어떻다 is a ㅎ irregular adjective: 어떻다 + 어요 → 어때요."},{kind:"drill",prompt:"Which sentence shows ㄹ deletion before -세요?",sentence:null,options:[{text:"이 단어를 아세요?",ok:!0},{text:"이 단어를 알세요?",ok:!1},{text:"이 단어를 알아세요?",ok:!1}],explanation:"알다 keeps ㄹ in 알아요 but drops ㄹ before -세요: 아세요."},{kind:"drill",prompt:"날씨___ 추워요. (The weather is cold.)",sentence:null,options:[{text:"가",ok:!0},{text:"를",ok:!1},{text:"에",ok:!1}],explanation:"춥다 describes the weather, so 날씨 takes 가. 를 would make weather an object, which does not fit an adjective sentence."},{kind:"order",prompt:"Build: 'I don't know well.'",tokens:["잘","몰라요"],correct:"잘 몰라요",explanation:"모르다 is a 르 irregular and becomes 몰라요. 잘 softens it to “I do not know well.”"}],canDo:"Conjugate 르-irregular and ㅡ-irregular words (모르다→몰라요 · 바쁘다→바빠요)",id:"chapter-41-b12",chapterId:"chapter-41",index:11}]},{id:"chapter-42",number:42,title:"에게 / 한테 / 께 · 와/과 · 하고 · (이)랑",goal:"Choose the right particle for receiver, companion, possession, also, only, scarcity, surprising amount, and minimum option.",biteCount:14,bites:[{kind:"words",title:"단어 Words 1 · 친구~",cards:[{kind:"guess",word:{ko:"친구",romanization:"chingu",en:"friend",pos:"noun",nuance:"친구 can mean friend or same-age peer depending on context."},sentence:{ko:"주말에 친구랑 영화도 보러 가요?",en:"Are you also going to see a movie with a friend this weekend?"},target:"친구",options:["teacher","gift; present","friend"],note:"Linked to dictionary card word-noun-003."},{kind:"guess",word:{ko:"선생님",romanization:"seonsaengnim",en:"teacher",pos:"noun",nuance:"님 makes the word respectful. 선생님 is also used as a polite title."},sentence:{ko:"선생님께 이메일도 드렸어요.",en:"I also sent the teacher an email."},target:"선생님",options:["friend","teacher","gift; present"],note:"Linked to dictionary card word-noun-002."},{kind:"guess",word:{ko:"선물",romanization:"seonmul",en:"gift; present",pos:"noun",nuance:"선물 can be the thing given, received, bought, or prepared. In this chapter, focus on the particle around the person and the particle attached to 선물 itself."},sentence:{ko:"친구에게 선물을 줬어요.",en:"I gave a gift to a friend."},target:"선물",options:["gift; present","friend","teacher"],note:"Linked to dictionary card word-ext-ch42-seonmul."},{kind:"guess",word:{ko:"이메일",romanization:"imeil",en:"email",pos:"noun",nuance:"이메일 is the everyday loanword (from English 'e-mail') for electronic mail, used freely at work and in daily life; the Sino alternative 전자우편 (電子郵便 'electronic post') exists but sounds stiff and bureaucratic, mostly seen on official forms. Crucially, 이메일 ≠ paper mail: a physical letter is 편지, and the postal-mail system is 우편, so 'I got your letter' about a posted envelope is 편지를 받았어요, not 이메일. It collocates with 보내다 (send), 받다 (receive), 확인하다 (check), 첨부하다 (attach a file), 답장하다 (reply). The English-speaker pitfall is the recipient particle — a person who receives mail takes 에게/한테 (동료에게 이메일을 보내요), and don't drag the English verb 'do' over: you 이메일을 보내다 or 쓰다, never 이메일하다."},sentence:{ko:"선생님께 이메일도 드려야 해요.",en:"I also need to send the teacher an email."},target:"이메일",options:["friend","teacher","email"],note:"Linked to dictionary card word-ext-123."},{kind:"guess",word:{ko:"책",romanization:"chaek",en:"book",pos:"noun",nuance:"책 is useful with 읽다, 사다, 있다, and 없다. It also helps beginners practice object marker 을 because 책 ends in a consonant."},sentence:{ko:"친구의 책도 돌려줘야 해요.",en:"I also need to return my friend's book."},target:"책",options:["friend","teacher","book"],note:"Linked to dictionary card word-noun-025."},{kind:"guess",word:{ko:"영화",romanization:"yeonghwa",en:"movie",pos:"noun",nuance:"영화 is Sino-Korean, 映畵 ('project-picture'), literally a projected image, and it is the standard word for a movie/film. It pairs with 보다 ('see/watch'), never 듣다 ('listen'), because film is something you view. A single film is counted with the bound noun 편 (영화 두 편 = two movies), not 개. Don't confuse 영화 with 드라마: 드라마 is a serialized TV series, while 영화 is a self-contained cinema film, so a Korean TV soap is a 드라마, not a 영화. The cinema building is 영화관 (or the loanword 극장). The classic English-speaker pitfall is letting 'a movie' steer you to the generic counter 개 (영화 한 개 sounds wrong) — use 편; and don't calque 'go to a movie' as 영화에 가다, since you say 영화(를) 보러 가다, 'go in order to watch a movie'."},sentence:{ko:"영화도 보러 가요?",en:"Are you also going to see a movie?"},target:"영화",options:["friend","movie","teacher"],note:"Linked to dictionary card word-ext-302."},{kind:"payoff",line:{speaker:"민서",ko:"주말에 친구랑 영화도 보러 가요?",en:"Are you also going to see a movie with a friend this weekend?"},hl:"친구"}],canDo:"Mark the person who receives an action (친구한테 · 선생님께)",id:"chapter-42-b1",chapterId:"chapter-42",index:0},{kind:"pattern",title:"문법 Grammar · 에게 / 한테 / 께",cards:[{kind:"hunt",name:"에게 / 한테 / 께",sub:"to a person (께 = honorific)",lines:[{tokens:[{pre:"친구",mid:"에게",post:"",hit:!0},{pre:"선물을",mid:"",post:"",hit:!1},{pre:"줬어요.",mid:"",post:"",hit:!1}],ko:"친구에게 선물을 줬어요.",en:"I gave a gift to a friend.",romanization:"chinguege seonmureul jwosseoyo."},{tokens:[{pre:"동생",mid:"한테",post:"",hit:!0},{pre:"책을",mid:"",post:"",hit:!1},{pre:"빌려줬어요.",mid:"",post:"",hit:!1}],ko:"동생한테 책을 빌려줬어요.",en:"I lent a book to my younger sibling.",romanization:"dongsaenghante chaegeul billyeojwosseoyo."}],rule:{name:"에게 / 한테 / 께",rows:[{when:"Neutral or written, after any person noun",add:"noun + 에게",ex:"친구 → 친구에게 (to a friend)"},{when:"Casual spoken, after any person noun",add:"noun + 한테",ex:"동생 → 동생한테 (to my younger sibling)"},{when:"Honorific, a person you respect",add:"noun + 께",ex:"선생님 → 선생님께 (to the teacher)"},{when:"'from a person' (source)",add:"noun + 에게서 / 한테서",ex:"친구한테서 들었어요 (I heard it from a friend)"}]},more:{func:"Marks the person who receives or is the target of an action: giving, sending, asking, telling, lending. English uses 'to (a person)'.",keyPoint:{label:"에게/한테 vs 께",body:"에게 and 한테 mean the same thing (한테 just sounds more casual). 께 is the honorific version for a respected person and usually rides with humble verbs like 드리다 and 여쭤보다."},pronunciation:"께 is a tense [kk] sound, like the kk in 'bookkeeper' — 선생님께 is [seon-saeng-nim-kke], never a plain [g]."}}],canDo:"Mark the person who receives an action (친구한테 · 선생님께)",id:"chapter-42-b2",chapterId:"chapter-42",index:1},{kind:"words",title:"단어 Words 2 · 시험~",cards:[{kind:"guess",word:{ko:"시험",romanization:"siheom",en:"exam",pos:"noun",nuance:"시험 is Sino-Korean 試驗 — 試 'try/test' + 驗 'examine', literally 'a trial examination'. The collocation English speakers must memorize is 시험을 보다 — Koreans 'see' an exam, they do not 'do' it, so 시험을 하다 is wrong. Passing and failing are vivid metaphors with the particle 에: 시험에 붙다 (literally 'stick to the exam') = pass, 시험에 떨어지다 ('fall off the exam') = fail — note these take 에, not 을. Contrast 시험 with 퀴즈(quiz, a small in-class test) and with 검사(檢査, an inspection/medical test like 건강 검사): a graded school test is always 시험, never 퀴즈 unless it is a tiny informal one. The classic 직역 trap is 'take an exam' → 시험을 가지다/취하다 ✗ (English 'take' never transfers); and learners often write 시험을 통과하다, which is understandable but bookish — the everyday word is 붙다."},sentence:{ko:"시험 문제가 세 개나 남았어요.",en:"As many as three exam questions are left."},target:"시험",options:["exam","friend","teacher"],note:"Linked to dictionary card word-ext-111."},{kind:"guess",word:{ko:"문제",romanization:"munje",en:"problem; question",pos:"noun",nuance:"문제(問題, 'ask + topic') has two everyday senses English keeps apart: a trouble or difficulty ('we have a problem') AND a question on a test or exercise ('problem 3'). Crucially, both are solved with the same verb 풀다 (literally 'to untie/loosen') — 문제를 풀다 works for a math item and for a real-life difficulty alike, where English would switch to 'answer' vs 'solve.' Other key partners: 문제가 생기다 (a problem arises), 문제가 되다 (to become an issue), and the handy one-word 문제없어요 ('no problem'). Contrast 문제 with 질문 (a question you ASK someone to get information) — a test 문제 is a problem to solve, but raising your hand to ask is 질문하다, not 문제하다. The English-speaker pitfall is the subject/object split: existence and arising take 이 (문제가 있다/생기다), but solving takes 를 (문제를 풀다) — learners often say 문제가 풀어요."},sentence:{ko:"문제가 세 개나 남았어요.",en:"As many as three questions are left."},target:"문제",options:["friend","problem; question","teacher"],note:"Linked to dictionary card word-ext-426."},{kind:"guess",word:{ko:"공부",romanization:"gongbu",en:"study; studying",pos:"noun",nuance:"공부(工夫)는 한자 그대로 '공을 들여 애씀'이라는 뜻으로, 지식이나 기술을 배우고 익히는 모든 활동을 가리키는 가장 기본적인 단어예요. 비슷한 말 '학습'은 교과서나 보고서에 어울리는 딱딱한 한자어라 일상 대화에서는 거의 안 쓰고, '연습'은 이미 배운 것을 몸에 익히려 반복하는 것이라 '머리로 새로 익히는' 공부와는 결이 달라요. 영어 study처럼 목적어를 바로 붙여 '공부 Korean'이라고 하면 안 되고, 반드시 '한국어를 공부하다'처럼 -을/를을 쓰거나 '한국어 공부를 하다'로 명사화해야 해요. 동사로 쓸 때 '공부를 하다'와 한 단어 '공부하다'가 둘 다 자연스럽고, '열심히/같이/매일'과 잘 어울려요."},sentence:{ko:"공부밖에 못 해요.",en:"I can do nothing but study."},target:"공부",options:["friend","teacher","study; studying"],note:"Linked to dictionary card word-ext-1560."},{kind:"guess",word:{ko:"커피",romanization:"keopi",en:"coffee",pos:"noun",nuance:"In speech, 커피 마셔요 without 를 is also natural, but learn the full frame first."},sentence:{ko:"커피라도 마실래요?",en:"Do you want to at least drink coffee?"},target:"커피",options:["friend","teacher","coffee"],note:"Linked to dictionary card word-noun-013."},{kind:"guess",word:{ko:"시간",romanization:"sigan",en:"time",pos:"noun",nuance:"시간 works with 있어요/없어요 and is essential for scheduling."},sentence:{ko:"한 시간만요.",en:"Just one hour."},target:"시간",options:["time","friend","teacher"],note:"Linked to dictionary card word-noun-009."},{kind:"guess",word:{ko:"물",romanization:"mul",en:"water",pos:"noun",nuance:"물 is essential in restaurants. 물 주세요 is more useful than just knowing “water.”"},sentence:{ko:"물이라도 드릴까요?",en:"Should I at least bring you water?"},target:"물",options:["water","friend","teacher"],note:"Linked to dictionary card word-noun-012."},{kind:"payoff",line:{speaker:"지훈",ko:"아니요, 시험 문제가 세 개나 남아서 공부밖에 못 해요.",en:"No, as many as three exam questions are left, so I can only study."},hl:"시험"}],canDo:"Link nouns or a companion with 'and/with' (친구하고 · 친구랑)",id:"chapter-42-b3",chapterId:"chapter-42",index:2},{kind:"pattern",title:"문법 Grammar · 와/과 · 하고 · (이)랑",cards:[{kind:"teach",name:"와/과 · 하고 · (이)랑",sub:"and / with",rows:[{when:"After a vowel-final noun (written/tidy)",add:"noun + 와",ex:"커피 → 커피와 물 (coffee and water)"},{when:"After a consonant-final noun (written/tidy)",add:"noun + 과",ex:"책 → 책과 가방 (a book and a bag)"},{when:"Any noun (neutral spoken)",add:"noun + 하고",ex:"민수하고 (with Minsu)"},{when:"Vowel-final / consonant-final (casual spoken)",add:"noun + 랑 / 이랑",ex:"친구 → 친구랑 / 동생 → 동생이랑"}],examples:[{ko:"친구랑 영화를 봐요.",en:"I watch a movie with a friend.",romanization:"chingurang yeonghwareul bwayo.",note:"친구 ends in a vowel, so 랑; casual speech prefers (이)랑."},{ko:"민수하고 같이 갔어요.",en:"I went together with Minsu.",romanization:"minsuhago gachi gasseoyo.",note:"하고 plus 같이 makes the 'with / together' reading unmistakable."}],more:{func:"Links two nouns ('A and B') or marks the companion you do something with ('with A'). All three mean the same; they differ only in register.",keyPoint:{label:"와/과 vs 하고 vs (이)랑",body:"Meaning is identical; register differs. 와/과 = neutral-to-written, 하고 = neutral spoken, (이)랑 = casual spoken. Add 같이 when you want 'with' to be clear over 'and'."},pronunciation:"과 after a consonant tenses: 책과 sounds like [chaek-kkwa]; 와 after a vowel stays light, 커피와 [keo-pi-wa]."}}],canDo:"Link nouns or a companion with 'and/with' (친구하고 · 친구랑)",id:"chapter-42-b4",chapterId:"chapter-42",index:3},{kind:"words",title:"단어 Words 3 · 돈~",cards:[{kind:"guess",word:{ko:"돈",romanization:"don",en:"money",pos:"noun",nuance:"돈 is money. In stores, 카드 and 현금 are often more specific and useful."},sentence:{ko:"돈이 만 원밖에 없어요.",en:"I only have 10,000 won."},target:"돈",options:["money","friend","teacher"],note:"Linked to dictionary card word-noun-015."},{kind:"guess",word:{ko:"방법",romanization:"bangbeop",en:"method; way",pos:"noun",nuance:"방법 is Sino-Korean (方法, 方 'direction/manner' + 法 'rule/method'), the 'way', 'method', or 'means' of doing something — the procedure or approach to reach a goal. Compare it with 방식 (方式, 'style/mode/manner'): 방법 is the concrete how-to ('a method to fix it'), while 방식 is the overall style or fashion in which something is done (생활 방식 = lifestyle, 사고방식 = way of thinking) — you wouldn't say 사고방법. Also distinguish 수단 (手段, 'means/instrument', often the tool or even an unscrupulous means: 교통수단 = means of transport, 수단과 방법을 가리지 않다 = by any means necessary). Register-neutral, very common. Core collocations: 방법이 있다/없다, 방법을 찾다/알다/모르다/바꾸다, [동사]~는 방법 (a way to do ~), 해결 방법 (solution), 사용 방법 (how to use). The English-speaker pitfall is the 'a way to do X' frame: it's [verb in ~는 form] + 방법, e.g. 'a way to study' is 공부하는 방법, NOT 공부 방법 in spoken contexts (though 공부 방법 as a fixed noun-noun compound is fine for 'study method'). Don't say 방법으로 어떻게 when you just mean 어떻게 ('how') — 방법 is the noun 'method', not the question word 'how'."},sentence:{ko:"이 방법밖에 없어요.",en:"There is no way except this."},target:"방법",options:["friend","method; way","teacher"],note:"Linked to dictionary card word-ext-428."},{kind:"guess",word:{ko:"계획",romanization:"gyehoek",en:"plan",pos:"noun",nuance:"계획(計劃, 'count/reckon + plan') is a worked-out plan or scheme for the future. Its single most important quirk is the verb: Koreans BUILD a plan with 세우다 (literally 'to erect/stand up') — 계획을 세우다 — not 만들다 ('make') as the English calque suggests. Other partners: 계획이 있다 (have a plan) and the smooth adverb 계획대로 ('as planned'). Distinguish 계획 from 예정 豫定, which is a SCHEDULED arrangement that is already set ('내일 출발할 예정이에요' = I'm scheduled/due to leave tomorrow), and from 약속, a personal commitment/appointment with someone — 계획 is your own roadmap, 예정 is a fixed scheduling, 약속 involves another party. The English-speaker pitfall is exactly 계획을 만들다 (use 세우다), and translating 'plan to do' with 계획 as a verb — Korean uses -(으)려고 하다 or -(으)ㄹ 계획이다: 여행할 계획이에요 ('I plan to travel'), not 여행을 계획해요 in casual speech."},sentence:{ko:"오늘의 계획은 공부예요.",en:"Today's plan is studying."},target:"계획",options:["plan","friend","teacher"],note:"Linked to dictionary card word-ext-429."},{kind:"guess",word:{ko:"주다",romanization:"juda",en:"to give",pos:"verb",nuance:"주세요 comes from 주다 and is one of the most important polite request endings."},sentence:{ko:"친구에게 선물을 줬어요.",en:"I gave a gift to a friend."},target:"줬",options:["to give","friend","teacher"],note:"Linked to dictionary card word-verb-022."},{kind:"guess",word:{ko:"드리다",romanization:"deurida",en:"to give/send humbly to someone respected",pos:"verb",nuance:"드리다 respects the recipient, not the subject. It is different from -(으)시-, which honors the subject."},sentence:{ko:"선생님께 이메일을 드렸어요.",en:"I sent the teacher an email."},target:"드렸",options:["friend","to give/send humbly to someone respected","teacher"],note:"Linked to dictionary card word-ext-ch13-deurida."},{kind:"payoff",line:{speaker:"지훈",ko:"좋아요. 선생님께 이메일도 보내드리고, 친구의 책도 돌려줘야 해요.",en:"Sounds good. I also need to send the teacher an email and return my friend's book."},hl:"드리"}],canDo:"Use 밖에 + negative for 'only', and 마다 for 'every' (한 시간밖에 없어요 · 주말마다)",id:"chapter-42-b5",chapterId:"chapter-42",index:4},{kind:"pattern",title:"문법 Grammar · 밖에 + negative",cards:[{kind:"hunt",name:"밖에 + negative",sub:"nothing but / only (and it's not enough)",lines:[{tokens:[{pre:"공부",mid:"밖에",post:"",hit:!0},{pre:"못",mid:"",post:"",hit:!1},{pre:"해요.",mid:"",post:"",hit:!1}],ko:"공부밖에 못 해요.",en:"I can do nothing but study.",romanization:"gongbubakke mot haeyo."},{tokens:[{pre:"한",mid:"",post:"",hit:!1},{pre:"시간",mid:"밖에",post:"",hit:!0},{pre:"없어요.",mid:"",post:"",hit:!1}],ko:"한 시간밖에 없어요.",en:"I only have one hour.",romanization:"han siganbakke eopseoyo."}],rule:{name:"밖에 + negative",rows:[{when:"noun + 밖에 with 없다",add:"noun + 밖에 + 없어요",ex:"한 시간밖에 없어요 (I only have one hour)"},{when:"noun + 밖에 with 못",add:"noun + 밖에 + 못 V",ex:"물밖에 못 마셔요 (I can drink nothing but water)"},{when:"noun + 밖에 with 안 / -지 않다",add:"noun + 밖에 + 안 V",ex:"공부밖에 안 해요 (I do nothing but study)"},{when:"Replaces 이/가/을/를",add:"no subject/object particle before 밖에",ex:"이것밖에 없어요 (✓), 이것을밖에 (✗)"}]},more:{func:"Marks a limit that always needs a negative predicate. It frames the amount as scarce or insufficient: 'nothing but X', 'only X (and that's all there is)'.",keyPoint:{label:"밖에 vs 만",body:"Both translate as 'only', but 밖에 demands a negative predicate and feels scarce/insufficient (공부밖에 못 해요), while 만 is neutral and takes a positive verb (공부만 해요). If you see a positive verb, you need 만, not 밖에."},pronunciation:"밖에 links across the ㄲ: [ba-kke], so 공부밖에 is [gong-bu-ba-kke] and 한 시간밖에 is [han si-gan-ba-kke]."}}],canDo:"Use 밖에 + negative for 'only', and 마다 for 'every' (한 시간밖에 없어요 · 주말마다)",id:"chapter-42-b6",chapterId:"chapter-42",index:5},{kind:"pattern",title:"문법 Grammar · (이)나",cards:[{kind:"hunt",name:"(이)나",sub:"as many as / or",lines:[{tokens:[{pre:"문제가",mid:"",post:"",hit:!1},{pre:"세",mid:"",post:"",hit:!1},{pre:"개",mid:"나",post:"",hit:!0},{pre:"남았어요.",mid:"",post:"",hit:!1}],ko:"문제가 세 개나 남았어요.",en:"As many as three questions are left.",romanization:"munjega se gaena namasseoyo."},{tokens:[{pre:"커피를",mid:"",post:"",hit:!1},{pre:"다섯",mid:"",post:"",hit:!1},{pre:"잔",mid:"이나",post:"",hit:!0},{pre:"마셨어요.",mid:"",post:"",hit:!1}],ko:"커피를 다섯 잔이나 마셨어요.",en:"I drank as many as five cups of coffee.",romanization:"keopireul daseot jan-ina masyeosseoyo."}],rule:{name:"(이)나",rows:[{when:"After a consonant-final number/noun",add:"+ 이나",ex:"다섯 잔 → 다섯 잔이나 (as many as 5 cups)"},{when:"After a vowel-final number/noun",add:"+ 나",ex:"세 개 → 세 개나 (as many as 3)"},{when:"'A or B' (rough choice)",add:"noun(이)나 noun",ex:"커피나 물 (coffee or water)"},{when:"Loose suggestion ('or something')",add:"noun + (이)나",ex:"물이나 마실까요? (shall we just drink water or something?)"}]},more:{func:"After a number or amount it adds 'surprisingly much' (as many as); between two nouns it offers a loose choice ('A or B'). This chapter centers on the 'as many as' use.",keyPoint:{label:"(이)나 vs 밖에",body:"Both attach to amounts but pull opposite ways. 다섯 잔이나 = the amount feels big (more than expected); 다섯 잔밖에 못 마셨어요 = the amount feels small (less than wanted). 나 says 'wow, that much'; 밖에 says 'only that little'."},pronunciation:"이나/나 trigger no special tensing; just match the final sound: 개나 [gae-na], 잔이나 [jan-i-na]."}},{kind:"drill",prompt:"I waited a whole hour.",sentence:"한 시간___ 기다렸어요.",options:[{text:"나",ok:!1},{text:"이나",ok:!0}],explanation:"시간 ends in a consonant → 이나; the wait felt long."}],canDo:"Show means or direction with (으)로 (버스로 가요)",id:"chapter-42-b7",chapterId:"chapter-42",index:6},{kind:"pattern",title:"문법 Grammar · (이)라도",cards:[{kind:"hunt",name:"(이)라도",sub:"at least; even if only",lines:[{tokens:[{pre:"시간",mid:"",post:"",hit:!1},{pre:"없으면",mid:"",post:"",hit:!1},{pre:"물",mid:"이라도",post:"",hit:!0},{pre:"마셔요.",mid:"",post:"",hit:!1}],ko:"시간 없으면 물이라도 마셔요.",en:"If you don't have time, at least drink some water.",romanization:"sigan eopseumyeon murirado masyeoyo."},{tokens:[{pre:"커피",mid:"라도",post:"",hit:!0},{pre:"한잔할까요?",mid:"",post:"",hit:!1}],ko:"커피라도 한잔할까요?",en:"Shall we at least grab a coffee?",romanization:"keopirado hanjanhalkkayo?"}],rule:{name:"(이)라도",rows:[{when:"After a vowel-final noun",add:"noun + 라도",ex:"커피 → 커피라도 (coffee, if nothing else)"},{when:"After a consonant-final noun",add:"noun + 이라도",ex:"물 → 물이라도 (at least water)"},{when:"With a suggestion (-(으)ㄹ까요? / -읍시다)",add:"noun(이)라도 + suggestion",ex:"물이라도 마실까요? (shall we at least drink some water?)"},{when:"'even a little' with time/amount",add:"amount + (이)라도",ex:"잠깐이라도 쉬세요 (rest, even for a moment)"}]},more:{func:"Offers a minimum or fallback option when the ideal one isn't available: 'at least X', 'even if only X', 'X if nothing else'.",keyPoint:{label:"(이)라도 vs 만",body:"만 picks X as the exclusive choice ('only X'); (이)라도 picks X as a settling-for second choice ('X if nothing better'). 물만 마셔요 = I drink only water (by choice); 물이라도 마셔요 = at least drink water (since there's nothing else)."},pronunciation:"(이)라도 is light with no tensing; just link smoothly: 물이라도 [mu-ri-ra-do], 커피라도 [keo-pi-ra-do]."}},{kind:"drill",prompt:"Rest, even for just a moment.",sentence:"잠깐___ 쉬세요.",options:[{text:"이라도",ok:!0},{text:"라도",ok:!1}],explanation:"잠깐 is consonant-final → 이라도; 'even a little' time is better than none."}],canDo:"Mark the person who receives an action (친구한테 · 선생님께)",id:"chapter-42-b8",chapterId:"chapter-42",index:7},{kind:"pattern",title:"문법 Grammar · 의",cards:[{kind:"teach",name:"의",sub:"'s / of (noun-to-noun link)",rows:[{when:"noun + 의 + noun (possession)",add:"의",ex:"친구의 책 (a friend's book) · 한국의 음식 (Korea's food)"},{when:"저/나 + 의 contract",add:"제 / 내",ex:"저의 → 제 · 나의 → 내"},{when:"Usually dropped in speech",add:"(no 의)",ex:"친구 가방 = 친구의 가방"}],examples:[{ko:"이건 친구의 책이에요.",en:"This is my friend's book.",romanization:"igeon chinguui chaegieyo.",note:"친구 + 의 + 책 — the first noun owns the second."},{ko:"제 가방이 어디 있어요?",en:"Where is my bag?",romanization:"je gabangi eodi isseoyo?",note:'저의 contracts to 제 — the everyday way to say "my."'}],more:{func:`의 links two nouns to show possession or relationship, like English "'s" or "of": 친구의 가방 (a friend's bag). In speech it is usually dropped (친구 가방), and 저의/나의 contract to 제/내.`,keyPoint:{label:"Drop 의 in speech; contract 저의 → 제",body:"Written Korean keeps 의 (친구의 책), but spoken Korean usually drops it (친구 책). The one place it survives is the contractions 제 (저의), 내 (나의), 네 (너의) — always say 제 책, not 저의 책 in conversation."},pronunciation:"의 as a particle is pronounced [에]: 친구의 → [친구에]. (의 keeps its [의] sound only at the start of a word, like 의자.)"}}],canDo:"Link nouns or a companion with 'and/with' (친구하고 · 친구랑)",id:"chapter-42-b9",chapterId:"chapter-42",index:8},{kind:"pattern",title:"문법 Grammar · (으)로",cards:[{kind:"hunt",name:"(으)로",sub:"by means of / toward (direction)",lines:[{tokens:[{pre:"버스",mid:"로",post:"",hit:!0},{pre:"학교에",mid:"",post:"",hit:!1},{pre:"가요.",mid:"",post:"",hit:!1}],ko:"버스로 학교에 가요.",en:"I go to school by bus.",romanization:"beoseuro hakgyoe gayo."},{tokens:[{pre:"손",mid:"으로",post:"",hit:!0},{pre:"먹었어요.",mid:"",post:"",hit:!1}],ko:"손으로 먹었어요.",en:"I ate with my hands.",romanization:"soneuro meogeosseoyo."}],rule:{name:"(으)로",rows:[{when:"After a vowel-final noun",add:"noun + 로",ex:"버스 → 버스로 (by bus)"},{when:"After a consonant-final noun",add:"noun + 으로",ex:"손 → 손으로 (with one's hand)"},{when:"After a ㄹ-final noun (no 으)",add:"noun + 로",ex:"지하철 → 지하철로 (by subway)"},{when:"Direction (toward)",add:"place + (으)로",ex:"오른쪽으로 가세요 (go to the right)"}]},more:{func:"Marks how you do something (tool, means, transport) or which direction you head: 'by/with X', 'toward X'.",keyPoint:{label:"(으)로 vs 에 (destination)",body:"에 marks the exact destination you arrive at (학교에 가요 = go to school); (으)로 marks the direction you face or the means you use (학교로 가요 = head toward school; 버스로 가요 = go by bus). For transport and tools, always (으)로, never 에."},pronunciation:"After ㄹ the 로 doubles the ㄹ: 지하철로 is [ji-ha-cheol-lo], not [ji-ha-cheol-ro]."}},{kind:"drill",prompt:"I transferred to the subway.",sentence:"지하철___ 갈아탔어요.",options:[{text:"로",ok:!0},{text:"으로",ok:!1}],explanation:"지하철 ends in ㄹ, so just 로 (no 으); pronounced [ji-ha-cheol-lo]."}],canDo:"Use 밖에 + negative for 'only', and 마다 for 'every' (한 시간밖에 없어요 · 주말마다)",id:"chapter-42-b10",chapterId:"chapter-42",index:9},{kind:"pattern",title:"문법 Grammar · 마다",cards:[{kind:"teach",name:"마다",sub:"every / each",rows:[{when:"After a time noun",add:"noun + 마다",ex:"아침 → 아침마다 (every morning)"},{when:"After a counted unit",add:"unit + 마다",ex:"세 시간 → 세 시간마다 (every three hours)"},{when:"After a person/thing noun",add:"noun + 마다",ex:"사람 → 사람마다 (each person)"},{when:"With a place noun",add:"place + 마다",ex:"나라 → 나라마다 (every country)"}],examples:[{ko:"아침마다 커피를 마셔요.",en:"I drink coffee every morning.",romanization:"achimmada keopireul masyeoyo.",note:"아침 + 마다 = 'every morning'; no extra time particle is needed."},{ko:"주말마다 친구를 만나요.",en:"I meet my friends every weekend.",romanization:"jumalmada chingureul mannayo.",note:"마다 attaches straight to 주말; it already means 'every', so don't add 에."}],more:{func:"Attaches to a noun to mean 'every X' or 'each X', often for repeated times or all members of a group: 'every morning', 'each person'.",keyPoint:{label:"마다 vs 매-",body:"마다 is a particle stuck onto a noun (아침마다, 날마다). 매 is a prefix glued in front (매일 = every day, 매주 = every week). Both mean 'every', but 매 forms set words while 마다 attaches freely to almost any noun."},pronunciation:"마다 is plain and light: 아침마다 [a-chim-ma-da], 주말마다 [ju-mal-ma-da]. No tensing or linking surprises."}}],canDo:"Show means or direction with (으)로 (버스로 가요)",id:"chapter-42-b11",chapterId:"chapter-42",index:10},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two friends negotiate a weekend plan while one person has study obligations.",lines:[{speaker:"민서",ko:"주말에 친구랑 영화도 보러 가요?",en:"Are you also going to see a movie with a friend this weekend?",romanization:"jumare chingurang yeonghwado boreo gayo?"},{speaker:"지훈",ko:"아니요, 시험 문제가 세 개나 남아서 공부밖에 못 해요.",en:"No, as many as three exam questions are left, so I can only study.",romanization:"aniyo, siheom munjega se gaena namaseo gongbubakke mot haeyo."},{speaker:"민서",ko:"그럼 커피라도 마실래요? 한 시간만요.",en:"Then do you want to at least drink coffee? Just one hour.",romanization:"geureom keopirado masillaeyo? han siganmannyo."},{speaker:"지훈",ko:"좋아요. 선생님께 이메일도 보내드리고, 친구의 책도 돌려줘야 해요.",en:"Sounds good. I also need to send the teacher an email and return my friend's book.",romanization:"joayo. seonsaengnimkke imeildo bonaedeurigo, chinguui chaekdo dollyeojwoya haeyo."}]},{kind:"order",prompt:"Build: 'I have only one hour, and it is not enough.'",tokens:["한 시간밖에","없어요"],correct:"한 시간밖에 없어요",explanation:"밖에 must pair with a negative like 없어요. It sounds like the amount is limited or insufficient."}],canDo:"Mark the person who receives an action (친구한테 · 선생님께)",id:"chapter-42-b12",chapterId:"chapter-42",index:11},{kind:"reading",title:"읽기 Reading · 주말 계획을 조사로 정리하기",cards:[{kind:"read",title:"주말 계획을 조사로 정리하기",chunks:["주말 계획을 말할 때는 명사보다 조사가 더 많은 정보를 줄 때가 있어요. 친구랑 영화를 보면 함께 가는 사람을 말하는 것이고, 영화도 본다고 하면 다른 일에 영화를 추가하는 거예요. 시험 문제가 세 개나 남았다고 하면 양이 많게 느껴지고, 공부밖에 못 한다고 하면 선택지가 거의 없다는 뜻이에요.","그래도 커피라도 마시자고 하면 완전한 약속은 아니지만 최소한 가능한 제안을 하는 거예요. 마지막으로 선생님께 이메일을 보내드리고 친구의 책을 돌려줘야 한다면, 께는 받는 사람의 높임, 의는 소유 관계를 보여 줘요."],translation:"When talking about weekend plans, particles often carry more information than the noun itself. 친구랑 tells who you go with, 영화도 adds a movie to other plans, 세 개나 shows the amount feels large, 공부밖에 못 해요 means the options are limited, 커피라도 offers a minimum plan, 께 marks a respected receiver, and 의 marks possession.",qas:[{q:"친구랑 영화 보면 어떤 의미예요?",a:"친구와 함께 영화를 본다는 뜻이에요."},{q:"공부밖에 못 해요에서 왜 못 해요가 필요해요?",a:"밖에가 부정 표현과 함께 쓰여서 선택지가 제한된다는 뜻을 만들기 때문이에요."},{q:"커피라도 마실래요?는 어떤 느낌이에요?",a:"완전한 계획은 아니지만 최소한 커피라도 마시자는 제안이에요."}]}],canDo:"Link nouns or a companion with 'and/with' (친구하고 · 친구랑)",id:"chapter-42-b13",chapterId:"chapter-42",index:12},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence correctly marks the teacher as a respected receiver?",sentence:null,options:[{text:"선생님께 이메일을 드렸어요.",ok:!0},{text:"선생님에서 이메일을 드렸어요.",ok:!1},{text:"선생님만 이메일을 드렸어요.",ok:!1}],explanation:"께 marks a respected person receiving the action, and 드리다 matches the respectful tone."},{kind:"drill",prompt:"Which sentence uses 밖에 correctly?",sentence:null,options:[{text:"공부밖에 못 해요.",ok:!0},{text:"공부밖에 해요.",ok:!1},{text:"공부밖에 좋아요.",ok:!1}],explanation:"밖에 needs a negative idea such as 못, 안, or 없어요."},{kind:"drill",prompt:"Which sentence means 'as many as three exam questions are left'?",sentence:null,options:[{text:"시험 문제가 세 개나 남았어요.",ok:!0},{text:"시험 문제가 세 개만 남았어요.",ok:!1},{text:"시험 문제가 세 개밖에 남았어요.",ok:!1}],explanation:"이나/나 after a number shows the amount feels large or surprising."},{kind:"drill",prompt:"Which pair shows the difference between 만 and 밖에?",sentence:null,options:[{text:"커피만 마셨어요 / 커피밖에 못 마셨어요",ok:!0},{text:"커피만 못 마셨어요 / 커피밖에 마셨어요",ok:!1},{text:"커피만 마셨어요 / 커피밖에 마셨어요",ok:!1}],explanation:"만 works with a positive predicate; 밖에 needs a negative predicate."},{kind:"drill",prompt:"Which sentence naturally marks possession?",sentence:null,options:[{text:"친구의 책도 돌려줘야 해요.",ok:!0},{text:"친구에게 책도 돌려줘야 해요.",ok:!1},{text:"친구밖에 책도 돌려줘야 해요.",ok:!1}],explanation:"의 links 친구 to 책: the friend's book."},{kind:"drill",prompt:"선생님___ 이메일을 보냈어요. (I sent an email to the teacher.)",sentence:null,options:[{text:"께",ok:!0},{text:"께서",ok:!1},{text:"를",ok:!1}],explanation:"께 respectfully marks the receiver of the email. 께서 would mark the teacher as a respected subject, and 를 would make the teacher a direct object."},{kind:"order",prompt:"Build: 'I have only one hour, and it is not enough.'",tokens:["한 시간밖에","없어요"],correct:"한 시간밖에 없어요",explanation:"밖에 must pair with a negative like 없어요. It sounds like the amount is limited or insufficient."},{kind:"drill",prompt:"Which sentence means “I only drink coffee” without the scarcity feeling?",sentence:null,options:[{text:"커피만 마셔요.",ok:!0},{text:"커피밖에 안 마셔요.",ok:!1},{text:"커피라도 마셔요.",ok:!1}],explanation:"만 simply limits the choice to coffee. 밖에 plus negative adds a stronger “nothing except” feeling."}],canDo:"Use 밖에 + negative for 'only', and 마다 for 'every' (한 시간밖에 없어요 · 주말마다)",id:"chapter-42-b14",chapterId:"chapter-42",index:13}]},{id:"chapter-43",number:43,title:"Counting Word Order: Noun + Number + Counter · Native-Number Contractions Before a Counter",goal:"Use noun + number + counter order confidently.",biteCount:12,bites:[{kind:"words",title:"단어 Words 1 · 개~",cards:[{kind:"guess",word:{ko:"개",romanization:"gae",en:"general counter for things",pos:"counter",nuance:"개 is the general counter for things. Everyday counts normally use native-number forms such as 한 개, 두 개, and 세 개; formal labels and technical contexts can follow other numbering conventions."},sentence:{ko:"의자 네 개가 필요해요.",en:"We need four chairs."},target:"개",options:["general counter for things","student","puppy; dog"],note:"Linked to dictionary card word-ext-010."},{kind:"guess",word:{ko:"명",romanization:"myeong",en:"counter for people",pos:"counter",nuance:"명 is the neutral counter for people; use the honorific counter 분 when respect is relevant. Everyday counts normally use 한 명, 두 명, 세 명, and 네 명."},sentence:{ko:"학생 세 명이 와요.",en:"Three students are coming."},target:"명",options:["student","counter for people","puppy; dog"],note:"Linked to dictionary card word-ext-011."},{kind:"guess",word:{ko:"마리",romanization:"mari",en:"counter for animals",pos:"counter",nuance:"마리 is the universal counter for animals — dogs, cats, fish, birds, insects, livestock, and even a whole cooked chicken or fish on the table. Crucially it is size-independent: the same word counts an ant (개미 한 마리) and an elephant (코끼리 한 마리). 마리 is native Korean (no hanja) and takes native numbers. Its single most important contrast is with 명, the counter for PEOPLE: animals are 마리, humans are 명, and crossing that line matters socially. 마리 is also distinct from 분, the honorific people-counter. The big English-speaker pitfall is using 마리 for people because English says 'two' for both — but calling a person 한 마리 is insulting or mocking (treating them like an animal); always use 명 (or honorific 분) for humans. A second slip is the generic 개 for animals, which sounds wrong — creatures take 마리."},sentence:{ko:"강아지 한 마리도 데려온대요.",en:"They say they are bringing one dog too."},target:"마리",options:["counter for animals","student","puppy; dog"],note:"Linked to dictionary card word-ext-691."},{kind:"guess",word:{ko:"잔",romanization:"jan",en:"counter for cups/glasses",pos:"counter",nuance:"잔 is the counter for a serving of liquid held in a cup or glass — it counts the POURED drink, not the container itself. Its near-rivals are 병 (a whole bottle) and 컵 (the physical cup as an object), and the dividing line is what you're measuring: 맥주 한 병 is a full bottle, 맥주 한 잔 is one glass poured from it. The hanja is 盞 ('small cup'), though it feels fully native in use and always takes native-Korean numbers (한, 두, 세 잔), never Sino-Korean 일/이. Watch two traps: 한잔하다 written together is a VERB ('go for a drink') and is idiomatic, so don't read it as a literal count; and English 'a cup of coffee' tempts learners to reach for 컵, but the natural measure word for the drink itself is 잔."},sentence:{ko:"커피 네 잔 준비할게요.",en:"I will prepare four cups of coffee."},target:"잔",options:["student","counter for cups/glasses","puppy; dog"],note:"Linked to dictionary card word-ext-682."},{kind:"guess",word:{ko:"권",romanization:"gwon",en:"counter for books and volumes",pos:"counter",nuance:"권 is the counter for anything BOUND into a spine — novels, textbooks, notebooks, magazines, and each separate volume of a multi-volume series. Its critical contrast is with 장, which counts a single loose SHEET: 종이 한 장 is one sheet of paper, but the whole bound book made of many sheets is 책 한 권. The hanja is 卷, originally 'a scroll/roll', which is why it now measures a complete bound work. It always takes native-Korean numbers and is among the most frequent counters when you talk about reading or studying. The classic English-speaker pitfall is defaulting to the all-purpose 개 ('책 두 개') because English just says 'two books' — but printed/bound works specifically take 권; a related slip is using 권 for a single page, when one page is 한 장."},sentence:{ko:"안내 책도 두 권만 주세요.",en:"Please give me just two guide books too."},target:"권",options:["counter for books and volumes","student","puppy; dog"],note:"Linked to dictionary card word-ext-685."},{kind:"guess",word:{ko:"장",romanization:"jang",en:"counter for flat sheets",pos:"counter",nuance:"장 counts flat, thin items — sheets of paper, tickets, photographs, banknotes, stickers, postcards, and even thin foods like a sheet of dried seaweed (김) or a slice of cheese. Its sharpest contrast is with 권: 장 is the single loose SHEET, whereas many sheets bound together become 책 한 권 (a book). The hanja is 張, meaning 'to stretch/spread out flat', which captures exactly the flatness it measures. It always takes native numbers and is one of the most-used counters in daily errands — at ticket counters, copy machines, and photo booths. The English-speaker pitfall is reaching for 개 (a generic count) for tickets and photos because English says 'two tickets'; the natural, expected counter is 장. A second trap is using 장 for a whole magazine or book, which is 권, since those are bound, not loose."},sentence:{ko:"종이 열 장이면 돼요.",en:"Ten sheets of paper are enough."},target:"장",options:["counter for flat sheets","student","puppy; dog"],note:"Linked to dictionary card word-ext-686."},{kind:"payoff",line:{speaker:"지훈",ko:"학생 세 명이 오고, 강아지 한 마리도 데려온대요.",en:"Three students are coming, and they say they are bringing one dog too."},hl:"마리"}],canDo:"Order a count as NOUN + NUMBER + COUNTER (학생이 세 명)",id:"chapter-43-b1",chapterId:"chapter-43",index:0},{kind:"pattern",title:"문법 Grammar · Counting Word Order: Noun + Number + Counter",cards:[{kind:"teach",name:"Counting Word Order: Noun + Number + Counter",sub:"",rows:[{when:"Basic count of a thing",add:"noun + (space) number + (space) counter",ex:"사과 세 개 = three apples (apple / three / units)"},{when:"Add a verb after the count",add:"keep noun + number + counter, then verb",ex:"커피 두 잔 주세요 = please give me two coffees"},{when:"Mark the counted noun as object",add:"the object particle 을/를 goes on the NOUN, not on the counter",ex:"빵을 네 개 샀어요 = I bought four pieces of bread"}],examples:[{ko:"사과 세 개 주세요.",en:"Please give me three apples.",romanization:"sagwa se gae juseyo.",note:"Order is noun (사과) → number (세) → counter (개); no particle joins 세 and 개."},{ko:"고양이 두 마리가 있어요.",en:"There are two cats.",romanization:"goyangi du mari-ga isseoyo.",note:"The subject particle 가 attaches to the counter 마리 at the end of the count phrase, not to 고양이."}],more:{func:"To count things in Korean, you name the thing first, then say how many. The pattern is NOUN + NUMBER + COUNTER, with no particle between the number and the counter. English says 'three apples'; Korean says 'apple three (units)' — 사과 세 개.",keyPoint:{label:"Korean reverses the English order",body:"English usually uses number + noun ('three apples'). Standard Korean counting uses noun + number + counter (사과 세 개). In short lists or elliptical speech you may also hear a counter omitted, but noun + number + counter is the reliable full pattern for learners."},pronunciation:""}}],canDo:"Order a count as NOUN + NUMBER + COUNTER (학생이 세 명)",id:"chapter-43-b2",chapterId:"chapter-43",index:1},{kind:"words",title:"단어 Words 2 · 벌~",cards:[{kind:"guess",word:{ko:"벌",romanization:"beol",en:"counter for sets of clothing",pos:"counter",nuance:"벌 counts clothing as a COMPLETE garment or a coordinated outfit, so a suit, dress, hanbok, or pajama set is 한 벌 even though it physically has several pieces — the counter measures the whole worn unit, not the parts. Its near-synonyms split by what they measure: 벌 is the full set, while 장 counts a single flat piece (티셔츠 한 장 — one tee) and 개 is the casual generic count. 벌 is native Korean (no hanja) and takes native numbers. The biggest English-speaker trap is logic-counting the pieces: a two-piece suit feels like 'two items', but the matching set is 한 벌, not 두 벌. A second trap is genre confusion — clothes are 벌, but the shoes that complete the look are 켤레, so don't say 신발 한 벌."},sentence:{ko:"옷 한 벌만 챙겼어요.",en:"I packed only one set of clothes."},target:"벌",options:["student","puppy; dog","counter for sets of clothing"],note:"Linked to dictionary card word-ext-684."},{kind:"guess",word:{ko:"대",romanization:"dae",en:"counter for vehicles and machines",pos:"counter",nuance:"대 is the all-purpose counter for machines and vehicles — cars, motorcycles, bicycles, computers, phones, cameras, TVs, washing machines, and air conditioners — basically anything mechanical or electronic, so a resident reaches for it constantly when talking about appliances. The hanja is 臺 ('platform/stand'), historically the base a machine sat on, which is why it measures equipment. It contrasts with 채 (whole buildings) and 명 (people): the vehicle is 대, the people riding inside it are 명. It always takes native-Korean numbers. The main English-speaker pitfall is reaching for the generic 개 ('차 두 개') because English just says 'two cars'; machines and vehicles specifically take 대. A subtler trap is counting passengers with 대 — only the machine is 대, while the humans in it are counted with 명."},sentence:{ko:"노트북 한 대가 필요해요.",en:"We need one laptop."},target:"대",options:["student","counter for vehicles and machines","puppy; dog"],note:"Linked to dictionary card word-ext-687."},{kind:"guess",word:{ko:"번",romanization:"beon",en:"counter for times or number labels",pos:"counter",nuance:"번 (한자 番) is the counter for an assigned, ordered number — bus and route numbers, subway exits, exam questions, list items, jersey and seat numbers — and in this ID sense it always takes Sino-Korean numbers: 삼 번 출구, 오 번 버스, never 세 번 출구. Its tricky twin is the homograph 번 meaning 'times/occasions', which takes NATIVE numbers: 세 번 (three times), 다섯 번 (five times). The dividing line is meaning, not spelling: does 번 label a thing (use Sino) or count repetitions (use native)? A near-synonym for the labelling sense is 호(號), but 호 attaches to rooms and issue/model numbers (302호, 창간호) while 번 covers routes, exits, and questions. The English-speaker pitfall is the Sino/native split inside a single counter: learners who have just mastered '세 번 = three times' over-apply native numbers to bus and exit numbers, producing 세 번 버스 — which a Korean parses as 'the bus, three times', not 'bus number 3'. Anchor it with the contrast pair 삼 번 (No. 3) vs. 세 번 (3 times)."},sentence:{ko:"벌써 세 번 해 봤어요.",en:"I have already tried it three times."},target:"번",options:["student","puppy; dog","counter for times or number labels"],note:"Linked to dictionary card word-ext-1424."},{kind:"guess",word:{ko:"학생",romanization:"haksaeng",en:"student",pos:"noun",nuance:"학생 is a common identity word. Use 이에요 after 학생 because it ends in a consonant."},sentence:{ko:"학생 세 명이 와요.",en:"Three students are coming."},target:"학생",options:["student","puppy; dog","coffee"],note:"Linked to dictionary card word-noun-001."},{kind:"guess",word:{ko:"강아지",romanization:"gangaji",en:"puppy; dog",pos:"noun",nuance:"강아지 literally means a puppy (the young of 개 'dog'), but in real Korean life it is the warm, default word people use for any beloved pet dog regardless of age — saying 우리 강아지 about a ten-year-old dog is completely normal and conveys affection, much like English 'puppy' or 'doggy' used fondly. The neutral, technical word for a grown dog is 개, which is what you use in formal writing, signs (개 조심 'beware of dog'), and breed talk; bare 개 can also sound blunt or even appear in insults (이 개 같은...), so 강아지 is the gentler everyday choice. As an endearment, calling a child 우리 강아지 means 'my little darling'. The English-speaker pitfall is register: in a report or formal context use 개, but in warm daily speech 강아지 is right. It ends in a vowel, so it takes 가/를."},sentence:{ko:"강아지 한 마리도 데려온대요.",en:"They say they are bringing one dog too."},target:"강아지",options:["student","puppy; dog","coffee"],note:"Linked to dictionary card word-ext-216."},{kind:"guess",word:{ko:"커피",romanization:"keopi",en:"coffee",pos:"noun",nuance:"In speech, 커피 마셔요 without 를 is also natural, but learn the full frame first."},sentence:{ko:"커피 네 잔 준비할게요.",en:"I will prepare four cups of coffee."},target:"커피",options:["student","puppy; dog","coffee"],note:"Linked to dictionary card word-noun-013."},{kind:"payoff",line:{speaker:"민서",ko:"오늘 체험 수업에 학생 몇 명 와요?",en:"How many students are coming to today's trial class?"},hl:"학생"}],canDo:"Contract native numbers before a counter (하나→한 · 둘→두 · 셋→세 · 넷→네)",id:"chapter-43-b3",chapterId:"chapter-43",index:2},{kind:"pattern",title:"문법 Grammar · Native-Number Contractions Before a Counter",cards:[{kind:"teach",name:"Native-Number Contractions Before a Counter",sub:"",rows:[{when:"하나 + counter",add:"하나 → 한",ex:"한 개 = one item (NOT 하나 개)"},{when:"둘 + counter",add:"둘 → 두",ex:"두 잔 = two cups"},{when:"셋 + counter",add:"셋 → 세",ex:"세 명 = three people"},{when:"넷 + counter",add:"넷 → 네",ex:"네 마리 = four animals"},{when:"스물 + counter",add:"스물 → 스무",ex:"스무 살 = twenty years old"}],examples:[{ko:"커피 한 잔 마셨어요.",en:"I drank one cup of coffee.",romanization:"keopi han jan masyeosseoyo.",note:"하나 contracts to 한 before the counter 잔; saying 하나 잔 is wrong."},{ko:"연필 두 자루 빌려주세요.",en:"Please lend me two pencils.",romanization:"yeonpil du jaru billyeo-juseyo.",note:"둘 becomes 두 before 자루, the counter for pencils and pen-shaped things."}],more:{func:"Korean native numbers 하나, 둘, 셋, 넷 and 스물 change shape when a counter follows them. They drop their final part: 하나→한, 둘→두, 셋→세, 넷→네, 스물→스무. Use the contracted form only when a counter comes right after.",keyPoint:{label:"Contract only before a counter",body:"하나/둘/셋/넷/스물 keep their full form when counting alone ('하나, 둘, 셋…') but contract to 한/두/세/네/스무 the moment a counter follows. Compare: 사과가 하나 있어요 (one apple, no counter) vs. 사과 한 개 있어요 (one apple, with counter 개)."},pronunciation:""}}],canDo:"Contract native numbers before a counter (하나→한 · 둘→두 · 셋→세 · 넷→네)",id:"chapter-43-b4",chapterId:"chapter-43",index:3},{kind:"words",title:"단어 Words 3 · 책~",cards:[{kind:"guess",word:{ko:"책",romanization:"chaek",en:"book",pos:"noun",nuance:"책 is useful with 읽다, 사다, 있다, and 없다. It also helps beginners practice object marker 을 because 책 ends in a consonant."},sentence:{ko:"책 두 권만 주세요.",en:"Please give me just two books."},target:"책",options:["student","puppy; dog","book"],note:"Linked to dictionary card word-noun-025."},{kind:"guess",word:{ko:"종이",romanization:"jongi",en:"paper",pos:"noun",nuance:"종이 is a pure native Korean word for paper, both as the material (made from 나무/pulp) and as a sheet of it. The crucial point is its counter: flat, thin things are counted with 장 (종이 한 장, 두 장) — the same 장 used for tickets (표 한 장), photos (사진 한 장), and pizza slices, so learning 종이 anchors the whole 'flat-sheet' counter family. Distinguish the raw material 종이 from finished paper products that have their own names: a 신문 (newspaper), a 책 (book), a 공책/노트 (notebook), and a filled-out 서류 (document) are all made of 종이 but are never just called 종이. Useful collocations: 종이에 쓰다/적다 (write on paper), 종이를 접다 (fold paper), 종이를 자르다/찢다 (cut/tear paper). The English-speaker pitfall is twofold: defaulting to 개 instead of 장 to count sheets, and using 종이 for a form you must complete — that is 서류 (paperwork) or the document's specific name."},sentence:{ko:"종이는 몇 장 필요해요?",en:"How many sheets of paper do we need?"},target:"종이",options:["student","paper","puppy; dog"],note:"Linked to dictionary card word-ext-1374."},{kind:"guess",word:{ko:"의자",romanization:"uija",en:"chair",pos:"noun",nuance:"의자 is Sino-Korean 椅子 ('chair') and covers any seat with legs — dining chairs, office chairs (사무용 의자 or 사무 의자), folding chairs (접이식 의자). The single most common English-speaker error is the particle with 앉다: sitting DOWN is reaching a resting position, so it must be 의자에 앉아요 (에 = destination), not 의자에서 앉아요 — even though English 'sit ON the chair' tempts you toward a location particle. Compare with standing up, which is motion away and DOES take 에서: 의자에서 일어나요. Distinguish 의자 (chair, you sit on it) from 소파 (sofa/couch, plush multi-seat) and 책상 (desk) — beginners sometimes pair them loosely. The set phrase for offering someone a seat is 의자를 빼 드리다 (pull the chair out for them). Register is neutral."},sentence:{ko:"의자 네 개가 필요해요.",en:"We need four chairs."},target:"의자",options:["student","chair","puppy; dog"],note:"Linked to dictionary card word-ext-065."},{kind:"guess",word:{ko:"옷",romanization:"ot",en:"clothes",pos:"noun",nuance:"옷 is a pure native Korean word (no hanja) meaning clothes/clothing for the body, and the verb you MUST pair it with is 입다 (to wear on the torso/body) — never 신다, which is reserved for footwear on the feet (신발을 신다), nor 쓰다 (hats/glasses) nor 끼다 (gloves/rings). English 'wear/put on' covers every garment with one verb, so this split is the central pitfall: 옷을 신어요 is a classic beginner error. To take clothes off is 벗다, to change them 갈아입다. For 'these clothes look good on you,' Korean says 옷이 잘 어울려요 (the clothes suit you), not a direct translation of 'you look good.' Note 옷 is treated as singular/uncountable grammatically (no plural needed): one outfit or a wardrobe full is still just 옷. The dressier counterpart 의상 (costume/attire, 衣裳) is for performances or formal contexts. Register is neutral and everyday."},sentence:{ko:"옷 한 벌만 챙겼어요.",en:"I packed only one set of clothes."},target:"옷",options:["student","puppy; dog","clothes"],note:"Linked to dictionary card word-ext-067."},{kind:"guess",word:{ko:"사진",romanization:"sajin",en:"photo",pos:"noun",nuance:"사진 is usually paired with 찍다 for taking photos."},sentence:{ko:"사진 세 장만 보내 주세요.",en:"Please send just three photos."},target:"사진",options:["student","photo","puppy; dog"],note:"Linked to dictionary card word-noun-023."},{kind:"payoff",line:{speaker:"민서",ko:"그럼 의자 네 개랑 커피 네 잔 준비할게요.",en:"Then I will prepare four chairs and four cups of coffee."},hl:"의자"}],canDo:"Pick the right counter for people, animals, and objects (명 · 마리 · 잔 · 권 · 개)",id:"chapter-43-b5",chapterId:"chapter-43",index:4},{kind:"pattern",title:"문법 Grammar · Counting People and Animals: 명 / 분 / 마리",cards:[{kind:"teach",name:"Counting People and Animals: 명 / 분 / 마리",sub:"",rows:[{when:"Counting people (neutral/plain)",add:"native number (contracted) + 명",ex:"학생 세 명 = three students"},{when:"Counting people politely (honorific)",add:"native number (contracted) + 분",ex:"손님 두 분 = two guests"},{when:"Counting any animal",add:"native number (contracted) + 마리",ex:"개 한 마리 = one dog"}],examples:[{ko:"교실에 학생 다섯 명이 있어요.",en:"There are five students in the classroom.",romanization:"gyosil-e haksaeng daseot myeong-i isseoyo.",note:"명 is the neutral counter for people: classmates, friends, ordinary people."},{ko:"할머니 두 분이 오셨어요.",en:"Two grandmothers came.",romanization:"halmeoni du bun-i osyeosseoyo.",note:"분 is the honorific counter, right for elders; the verb is also honorific 오셨어요."}],more:{func:"People are counted with 명 (plain) or 분 (honorific, for people you respect). Animals — pets, fish, birds, insects — are all counted with 마리.",keyPoint:{label:"명 vs. 분 = respect level",body:"명 and 분 both count people; the difference is politeness. Use 분 for guests, elders, teachers, and customers; use 명 for friends, kids, or a general headcount. Never use 분 for yourself. Animals always take 마리, never 명."},pronunciation:""}}],canDo:"Pick the right counter for people, animals, and objects (명 · 마리 · 잔 · 권 · 개)",id:"chapter-43-b6",chapterId:"chapter-43",index:5},{kind:"pattern",title:"문법 Grammar · Counting Objects, Drinks, Books, and Sheets: 개 / 잔 / 권 / 장",cards:[{kind:"teach",name:"Counting Objects, Drinks, Books, and Sheets: 개 / 잔 / 권 / 장",sub:"",rows:[{when:"General object (default counter)",add:"number + 개",ex:"사탕 두 개 = two candies"},{when:"A drink served in a cup or glass",add:"number + 잔",ex:"물 한 잔 = one glass of water"},{when:"A book or notebook",add:"number + 권",ex:"책 세 권 = three books"},{when:"A thin flat sheet",add:"number + 장",ex:"종이 네 장 = four sheets of paper"}],examples:[{ko:"지우개 두 개만 주세요.",en:"Please give me just two erasers.",romanization:"jiugae du gae-man juseyo.",note:"개 is the all-purpose counter for everyday objects like erasers."},{ko:"녹차 한 잔 더 주세요.",en:"One more cup of green tea, please.",romanization:"nokcha han jan deo juseyo.",note:"잔 counts drinks served in a cup or glass — tea, coffee, water, juice."}],more:{func:"Different kinds of things take different counters. 개 = general objects, 잔 = cups/glasses of a drink, 권 = books and notebooks, 장 = flat sheets (paper, tickets, photos).",keyPoint:{label:"개 is the safe default",body:"When you don't know the right counter, 개 usually works for objects. But the specific counters are expected for their categories: drinks → 잔, books → 권, flat sheets → 장. Saying 책 세 개 is understandable but sounds like a learner; 책 세 권 is correct."},pronunciation:"권 ends in a clear final ㄴ; before 을 it links as 권을 [궈늘 / gwo-neul]. 장을 links as [장을 / jang-eul] with the ㅇ carrying over."}}],canDo:"Order a count as NOUN + NUMBER + COUNTER (학생이 세 명)",id:"chapter-43-b7",chapterId:"chapter-43",index:6},{kind:"pattern",title:"문법 Grammar · Counting Clothes and Machines: 벌 / 대",cards:[{kind:"teach",name:"Counting Clothes and Machines: 벌 / 대",sub:"",rows:[{when:"A set or suit of clothes",add:"number + 벌",ex:"옷 한 벌 = one set of clothes"},{when:"Another outfit or suit",add:"number + 벌",ex:"양복 두 벌 = two suits"},{when:"A car or vehicle",add:"number + 대",ex:"차 한 대 = one car"},{when:"A machine or appliance",add:"number + 대",ex:"컴퓨터 두 대 = two computers"}],examples:[{ko:"새 옷 한 벌 샀어요.",en:"I bought one new set of clothes.",romanization:"sae ot han beol sasseoyo.",note:"벌 counts a full outfit, not single garments; 한 from 하나 before the counter."},{ko:"양복 두 벌이 필요해요.",en:"I need two suits.",romanization:"yangbok du beol-i piryohaeyo.",note:"벌 also counts suits and other matched sets of clothing."}],more:{func:"벌 counts sets of clothing — an outfit, a suit, pajamas. 대 counts machines and vehicles — cars, phones, computers, TVs, anything mechanical.",keyPoint:{label:"벌 = clothing sets, 대 = machines",body:"Use 벌 for clothes you wear as a set (옷 한 벌, 양복 두 벌) and 대 for anything mechanical (차 한 대, 핸드폰 두 대, 세탁기 한 대). Don't reach for 개 here — 차 한 개 or 옷 한 개 sounds clearly wrong to native ears."},pronunciation:""}}],canDo:"Contract native numbers before a counter (하나→한 · 둘→두 · 셋→세 · 넷→네)",id:"chapter-43-b8",chapterId:"chapter-43",index:7},{kind:"pattern",title:"문법 Grammar · Counting Time and Frequency: 번 / 시간 / 살",cards:[{kind:"teach",name:"Counting Time and Frequency: 번 / 시간 / 살",sub:"",rows:[{when:"Number of times (occurrences)",add:"number + 번",ex:"한 번 = one time / once"},{when:"Repeating an action",add:"number + 번",ex:"세 번 봤어요 = I saw it three times"},{when:"Duration in hours",add:"number + 시간",ex:"두 시간 = two hours"},{when:"A person's age",add:"number + 살",ex:"스무 살 = twenty years old"}],examples:[{ko:"그 영화를 두 번 봤어요.",en:"I watched that movie twice.",romanization:"geu yeonghwa-reul du beon bwasseoyo.",note:"번 counts how many times; 둘 contracts to 두 before it."},{ko:"하루에 세 번 약을 먹어요.",en:"I take medicine three times a day.",romanization:"haru-e se beon yag-eul meogeoyo.",note:"번 with a native number gives the frequency of an action."}],more:{func:"번 counts the number of times something happens (once, twice). 시간 counts hours of duration. 살 counts years of age. All three take native numbers, contracted before the counter.",keyPoint:{label:"시간 (duration) vs. 시 (o'clock)",body:"세 시간 means 'three hours' (how long), but 세 시 means 'three o'clock' (what time). Both use native numbers but answer different questions. 번 counts occurrences (한 번 = once), and 살 counts age (열 살 = ten years old)."},pronunciation:""}}],canDo:"Pick the right counter for people, animals, and objects (명 · 마리 · 잔 · 권 · 개)",id:"chapter-43-b9",chapterId:"chapter-43",index:8},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two staff members prepare supplies for a small trial class.",lines:[{speaker:"민서",ko:"오늘 체험 수업에 학생 몇 명 와요?",en:"How many students are coming to today's trial class?",romanization:"oneul cheheom sueobe haksaeng myeot myeong wayo?"},{speaker:"지훈",ko:"학생 세 명이 오고, 강아지 한 마리도 데려온대요.",en:"Three students are coming, and they say they are bringing one dog too.",romanization:"haksaeng se myeongi ogo, gangaji han marido deryeondaeyo."},{speaker:"민서",ko:"그럼 의자 네 개랑 커피 네 잔 준비할게요.",en:"Then I will prepare four chairs and four cups of coffee.",romanization:"geureom uija ne gaerang keopi ne jan junbihalgeyo."},{speaker:"지훈",ko:"종이는 몇 장 필요해요?",en:"How many sheets of paper do we need?",romanization:"jongineun myeot jang piryohaeyo?"},{speaker:"민서",ko:"열 장이면 돼요. 안내 책도 두 권만 주세요.",en:"Ten sheets are enough. Please give me just two guide books too.",romanization:"yeol jangimyeon dwaeyo. annae chaekdo du gwonman juseyo."},{speaker:"지훈",ko:"이 준비는 벌써 세 번 해 봐서 괜찮아요.",en:"We have already done this prep three times, so it is fine.",romanization:"i junbineun beolsseo se beon hae bwaseo gwaenchanayo."}]},{kind:"order",prompt:"Build: 'two cups of coffee'",tokens:["커피","두 잔"],correct:"커피 두 잔",explanation:"Korean counter order is noun + number + counter. 잔 is the counter for cups or glasses."}],canDo:"Order a count as NOUN + NUMBER + COUNTER (학생이 세 명)",id:"chapter-43-b10",chapterId:"chapter-43",index:9},{kind:"reading",title:"읽기 Reading · 몇 개가 아니라 무엇을 세는지 먼저 보기",cards:[{kind:"read",title:"몇 개가 아니라 무엇을 세는지 먼저 보기",chunks:["한국어에서 수량을 말할 때는 숫자만 맞으면 끝이 아니에요. 무엇을 세는지 먼저 봐야 해요. 학생은 세 명, 강아지는 한 마리, 커피는 네 잔, 책은 두 권, 종이는 열 장처럼 명사에 맞는 단위가 달라져요.","처음에는 개를 모든 물건에 붙이고 싶지만, 책 두 개보다 책 두 권이 자연스럽고, 사진 세 개보다 사진 세 장이 자연스러워요. 또 하나, 둘, 셋, 넷은 단위명사 앞에서 한, 두, 세, 네로 줄어들어요. 그래서 하나 명이 아니라 한 명, 둘 잔이 아니라 두 잔이라고 말해요."],translation:"In Korean, counting is not only about choosing the right number. You first look at what kind of thing you are counting. Students are counted with 명, animals with 마리, cups of coffee with 잔, books with 권, and sheets of paper or photos with 장. The first few native Korean numbers also contract before counters: 하나 becomes 한, 둘 becomes 두, 셋 becomes 세, and 넷 becomes 네.",qas:[{q:"학생을 셀 때 어떤 단위명사를 써요?",a:"명"},{q:"책 두 개보다 어떤 표현이 더 자연스러워요?",a:"책 두 권"},{q:"하나, 둘, 셋, 넷은 단위명사 앞에서 어떻게 바뀌어요?",a:"한, 두, 세, 네로 바뀌어요."}]}],canDo:"Contract native numbers before a counter (하나→한 · 둘→두 · 셋→세 · 넷→네)",id:"chapter-43-b11",chapterId:"chapter-43",index:10},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which counter fits students?",sentence:null,options:[{text:"학생 세 명",ok:!0},{text:"학생 세 마리",ok:!1},{text:"학생 세 잔",ok:!1}],explanation:"명 counts people."},{kind:"drill",prompt:"Which counter fits a dog?",sentence:null,options:[{text:"강아지 한 마리",ok:!0},{text:"강아지 한 명",ok:!1},{text:"강아지 한 권",ok:!1}],explanation:"마리 counts animals."},{kind:"drill",prompt:"Which counter fits coffee?",sentence:null,options:[{text:"커피 두 잔",ok:!0},{text:"커피 두 장",ok:!1},{text:"커피 두 권",ok:!1}],explanation:"잔 counts cups or glasses."},{kind:"drill",prompt:"Which counter fits books?",sentence:null,options:[{text:"책 두 권",ok:!0},{text:"책 두 잔",ok:!1},{text:"책 두 마리",ok:!1}],explanation:"권 counts books and volumes."},{kind:"drill",prompt:"Which sentence counts occurrences?",sentence:null,options:[{text:"세 번 해 봤어요.",ok:!0},{text:"세 권 해 봤어요.",ok:!1},{text:"세 잔 해 봤어요.",ok:!1}],explanation:"번 counts occurrences or number labels depending on context."},{kind:"drill",prompt:"학생 세 명___ 왔어요. (Three students came.)",sentence:null,options:[{text:"이",ok:!0},{text:"을",ok:!1},{text:"에",ok:!1}],explanation:"The counted group is the subject that came, so 명 takes 이 here. 을 would make the students an object."},{kind:"order",prompt:"Build: 'two cups of coffee'",tokens:["커피","두 잔"],correct:"커피 두 잔",explanation:"Korean counter order is noun + number + counter. 잔 is the counter for cups or glasses."},{kind:"drill",prompt:"Which phrase counts two dogs naturally?",sentence:null,options:[{text:"강아지 두 마리",ok:!0},{text:"강아지 둘 개",ok:!1},{text:"강아지 이 명",ok:!1}],explanation:"Animals take 마리, and two before a counter is 두. 명 counts people, not animals."}],canDo:"Pick the right counter for people, animals, and objects (명 · 마리 · 잔 · 권 · 개)",id:"chapter-43-b12",chapterId:"chapter-43",index:11}]},{id:"chapter-44",number:44,title:"연음 (Linking): A Final Consonant Slides onto the Next Vowel · 경음화 (Tensing): A Plain Consonant Tenses After a Stop",goal:"Map written Korean to spoken Korean using four high-frequency rules.",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · 먹다~",cards:[{kind:"guess",word:{ko:"먹다",romanization:"meokda",en:"to eat",pos:"verb",nuance:"먹다 is used for meals and food. For medicine, Korean often uses 약을 먹어요, literally “eat medicine,” which means “take medicine.”"},sentence:{ko:"먹어요는 [머거요]처럼 이어져요.",en:"먹어요 links and sounds like [머거요]."},target:"먹어",options:["to sit","to read","to eat"],note:"Linked to dictionary card word-verb-001."},{kind:"guess",word:{ko:"한국어",romanization:"hangugeo",en:"Korean language",pos:"noun",nuance:"한국어 points to the language. 한국 사람 points to a Korean person."},sentence:{ko:"한국어는 [한구거]처럼 이어져요.",en:"한국어 links and sounds like [한구거]."},target:"한국어",options:["Korean language","school","gukbap; soup with rice"],note:"Linked to dictionary card word-ext-ch03-hangugeo."},{kind:"guess",word:{ko:"앉다",romanization:"antda",en:"to sit",pos:"verb",nuance:"앉아 주세요 is a polite request; 앉으세요 is also common and a little more direct."},sentence:{ko:"앉아요는 [안자요]처럼 들려요.",en:"앉아요 sounds like [안자요]."},target:"앉아",options:["to eat","to read","to sit"],note:"Linked to dictionary card word-verb-010."},{kind:"guess",word:{ko:"읽다",romanization:"ikda",en:"to read",pos:"verb",nuance:"읽다 has pronunciation changes, but beginners can first memorize 읽어요 as the practical polite form."},sentence:{ko:"읽어요는 [일거요]처럼 들려요.",en:"읽어요 sounds like [일거요]."},target:"읽어",options:["to read","to eat","to sit"],note:"Linked to dictionary card word-verb-011."},{kind:"guess",word:{ko:"학교",romanization:"hakgyo",en:"school",pos:"noun",nuance:"학교 is one of the clearest words for practicing 에 vs 에서."},sentence:{ko:"학교는 [학꾜]처럼 들려요.",en:"학교 sounds like [학꾜]."},target:"학교",options:["Korean language","gukbap; soup with rice","school"],note:"Linked to dictionary card word-noun-006."},{kind:"guess",word:{ko:"국밥",romanization:"gukbap",en:"gukbap; soup with rice",pos:"noun",nuance:"국밥 is literally 국 'soup' + 밥 'rice' — a hot bowl in which rice is either pre-mixed into the broth (토렴) or served alongside to add yourself, eaten fast and cheap as a complete one-bowl meal. It differs from a plain 국 in that 국밥 is a whole meal (rice included), whereas 국 is just the soup component of a larger spread. The defining verb to learn is 말다 'to put/swirl rice into soup' — 밥을 국에 말다 — which has no clean English equivalent and trips learners up. 국밥 is the classic 해장 'hangover-cure' food, and Busan's 돼지국밥 (pork) is nationally famous. Pitfall: even though it looks like soup, you say 국밥을 먹다 'eat gukbap', not 마시다 'drink', because the rice makes it food, not a beverage — and don't forget the counter 그릇 when ordering a single bowl."},sentence:{ko:"국밥은 [국빱]처럼 들려요.",en:"국밥 sounds like [국빱]."},target:"국밥",options:["gukbap; soup with rice","Korean language","school"],note:"Linked to dictionary card word-ext-707."},{kind:"payoff",line:{speaker:"민서",ko:"먹어요는 [먹-어-요]가 아니라 [머거요]처럼 이어져요.",en:"먹어요 is not [meok-eo-yo]; it links and sounds like [머거요]."},hl:"먹어"}],canDo:"Read a 받침 linking onto the next vowel (한국어 → [한구거], 연음)",id:"chapter-44-b1",chapterId:"chapter-44",index:0},{kind:"pattern",title:"문법 Grammar · 연음 (Linking): A Final Consonant Slides onto the Next Vowel",cards:[{kind:"teach",name:"연음 (Linking): A Final Consonant Slides onto the Next Vowel",sub:"",rows:[{when:"받침 + a vowel starting with ㅇ",add:"the 받침 moves into the empty ㅇ slot",ex:"한국어 → [한구거]"},{when:"a single 받침 (ㄱ/ㄴ/ㄹ/ㅁ/ㅂ/ㅅ etc.) before a vowel",add:"that consonant becomes the next syllable's onset",ex:"음악 → [으막], 옷이 → [오시]"},{when:"a double 받침 (겹받침) before a vowel",add:"the first consonant stays, the second links over",ex:"읽어요 → [일거요], 앉아요 → [안자요]"},{when:"받침 ㅇ before a vowel",add:"no linking; ㅇ [ŋ] stays where it is",ex:"고양이 → [고양이] (the ㅇ does not move)"}],examples:[{ko:"한국어 발음이 어려워요.",en:"Korean pronunciation is hard.",romanization:"han-gu-geo ba-reu-mi eo-ryeo-wo-yo",note:"한국어 → [한구거] (국's ㄱ links to 어); 발음이 → [바르미] (음's ㅁ links to 이)."},{ko:"이 단어를 읽어 보세요.",en:"Try reading this word.",romanization:"i da-neo-reul il-geo bo-se-yo",note:"단어 → [다너] (단's ㄴ links to 어); 읽어 → [일거] (겹받침 ㄺ splits: ㄹ stays, ㄱ links)."}],more:{func:"When a syllable ends in a 받침 (final consonant) and the next syllable starts with ㅇ (a silent placeholder before a vowel), the 받침 jumps over and is pronounced as the first sound of that next syllable. The spelling never changes — only the sound. This is why 한국어 is said [한구거]: the ㄱ of 국 links onto the 어.",keyPoint:{label:"Spelling vs. sound",body:"Linking changes only the sound, never the spelling. You always write 한국어, but you say [한구거]. Reading each syllable as written (han-guk-eo) sounds robotic; native speakers link automatically."},pronunciation:"한국어 is [한구거], not [한국어]. Listen for the 받침 sliding right: 옷이 [오시], 꽃이 [꼬치], 밥을 [바블]."}}],canDo:"Read a 받침 linking onto the next vowel (한국어 → [한구거], 연음)",id:"chapter-44-b2",chapterId:"chapter-44",index:1},{kind:"words",title:"단어 Words 2 · 국민~",cards:[{kind:"guess",word:{ko:"국민",romanization:"gungmin",en:"citizens; the people of a nation",pos:"noun",nuance:"국민 (國民, 國 'nation' + 民 'people' — 'the people of the nation') means the people as citizens of a particular country: a civic, collective term bound up with rights (권리), duties (의무), and the state. Distinguish it from two neighbors. Against 사람들 ('people' in general): 국민 is people specifically as a national citizenry, so '거리에 사람들이 많아요' (lots of people on the street) could never be 국민. Against 시민 (市民, 'citizens'): 시민 leans toward city residents or civil society (시민 단체 = civic groups, 서울 시민 = Seoul residents), while 국민 frames people in relation to the nation and government. Use 국민 whenever the context is national identity, elections, law, or the state's relationship to its population."},sentence:{ko:"국민은 [궁민]처럼 들려요.",en:"국민 sounds like [궁민]."},target:"국민",options:["Korean language","citizens; the people of a nation","school"],note:"Linked to dictionary card word-ext-1818."},{kind:"guess",word:{ko:"닫다",romanization:"datda",en:"to close",pos:"verb",nuance:"닫다 is the opposite of 열다. Use it for doors, windows, stores, apps, and lids."},sentence:{ko:"닫다는 [닫따]처럼 들려요.",en:"닫다 sounds like [닫따]."},target:"닫다",options:["to eat","to close","to sit"],note:"Linked to dictionary card word-verb-025."},{kind:"guess",word:{ko:"좋다",romanization:"jota",en:"to be good; to like",pos:"adjective",nuance:"좋아요 can mean “it is good” or “I like it.” The subject often takes 이/가."},sentence:{ko:"좋다는 [조타]처럼 들려요.",en:"좋다 sounds like [조타]."},target:"좋다",options:["to be good; to like","to eat","Korean language"],note:"Linked to dictionary card word-adjective-027."},{kind:"guess",word:{ko:"입학하다",romanization:"iphakada",en:"to enroll in school",pos:"verb",nuance:"입학하다 is Sino-Korean 入學 — 入 'enter' + 學 'learning/school' — literally 'enter into learning', i.e. be admitted to and begin a school. Its exact opposite is 졸업하다 (卒業). Here is a beautiful particle trap that mirrors its opposite: 입학하다 uses 에 ('enter INTO' a school — 대학에 입학하다), whereas 졸업하다 uses 를 (대학을 졸업하다). English 'enroll IN' luckily matches the 에 here, but learners who memorized 졸업하다's 를 wrongly carry it over. Don't confuse 입학하다 with 등록하다 'to register': 입학하다 is the once-in-a-school-career act of being admitted, while 등록하다 is the recurring paperwork of signing up (for a term, a course). As a noun+하다 verb it conjugates on 하다 (입학해요, 입학했어요, formal 입학합니다); negative and impossible split the noun (입학 안 해요, 입학 못 해요). Note the pronunciation: 입학 sounds like [이팍], the ㅂ and ㅎ fusing to ㅍ."},sentence:{ko:"입학은 [이팍]처럼 들려요.",en:"입학 sounds like [이팍]."},target:"입학",options:["to eat","to sit","to enroll in school"],note:"Linked to dictionary card word-verb-487."},{kind:"guess",word:{ko:"축하해요",romanization:"chukahaeyo",en:"Congratulations.",pos:"expression",nuance:"축하해요 congratulates someone on genuinely HAPPY news. 축하(祝賀) is Sino-Korean — 祝 'to wish, to celebrate' + 賀 'to congratulate' — and it conjugates as a 하다-verb: 축하하다 → 축하해요 (polite) → 축하합니다 (formal) → 축하해 (casual). The structural pattern is [occasion noun] + 축하해요: 결혼 축하해요, 합격 축하해요, 생일 축하해요, 출산 축하해요. Register is critical: toward a senior, use the humble 축하드려요 / 축하드립니다 (드리다 'to give humbly'), NOT plain 축하해요, because you are offering the congratulation upward as a gift rather than stating it. The English-speaker pitfall is using 축하해요 like the broad English 'congratulations' — in Korean, 축하 is strictly for joyful milestones. For someone going through hardship (failed exam, difficult project, loss) you never 축하; you say 힘내세요 ('stay strong'), 고생했어요 ('you worked hard'), or offer 수고 language. Also, don't conflate with 화이팅 — 화이팅 cheers someone ON before they face a challenge; 축하해요 celebrates AFTER the good outcome has arrived."},sentence:{ko:"축하해요는 [추카해요]처럼 들려요.",en:"축하해요 sounds like [추카해요]."},target:"축하해요",options:["I'm not good at Korean.","to eat","Congratulations."],note:"Linked to dictionary card expr-123."},{kind:"guess",word:{ko:"한국어를 잘 못해요",romanization:"hangugeoreul jal motaeyo",en:"I'm not good at Korean.",pos:"expression",nuance:"한국어를 잘 못해요 = 한국어 (Korean language) + 를 (object marker) + 잘 (well) + 못하다 (to be unable to do well). The key interpretive point: 잘 못하다 means 'can't do it well' (ability is limited), while 안 하다 means 'I don't do it' (by choice). Using 안 하다 — 한국어를 안 해요 — implies you are refusing or unwilling, which is not what you mean. The 잘 softens the claim from 'I can't speak Korean at all' (한국어 못해요) to 'I'm not good at it', which is more accurate and humble. 한국어 is the neutral/formal word for the language, while 한국말 is more colloquial and warm; both are correct. The classic follow-up toolkit: 천천히 말씀해 주세요 ('please speak slowly'), 다시 한 번 말씀해 주시겠어요? ('could you say that again?'), and 영어 하시는 분 계세요? ('is there anyone who speaks English?'). English speakers most often get the particle wrong (한국어가 잘 못해요 — the language is the object, not the subject) or write 잘못해요 as one word, which means 'to do something wrong/make a mistake' — a completely different word."},sentence:{ko:"못해요는 [모태요]처럼 들려요.",en:"못해요 sounds like [모태요]."},target:"못해요",options:["I'm not good at Korean.","Congratulations.","to eat"],note:"Linked to dictionary card expr-394."},{kind:"payoff",line:{speaker:"지훈",ko:"그럼 국민은 [궁민], 먹는은 [멍는]처럼 들리죠?",en:"Then 국민 sounds like [궁민], and 먹는 sounds like [멍는], right?"},hl:"국민"}],canDo:"Hear a plain consonant tense after a stop (학교 → [학꾜], 경음화)",id:"chapter-44-b3",chapterId:"chapter-44",index:2},{kind:"pattern",title:"문법 Grammar · 경음화 (Tensing): A Plain Consonant Tenses After a Stop",cards:[{kind:"teach",name:"경음화 (Tensing): A Plain Consonant Tenses After a Stop",sub:"",rows:[{when:"[ㄱ] 받침 + ㄱ/ㄷ/ㅂ/ㅅ/ㅈ",add:"the following consonant tenses",ex:"학교 → [학꾜], 책상 → [책쌍]"},{when:"[ㄷ] 받침 (ㄷ,ㅅ,ㅈ,ㅊ,ㅌ all sound [ㄷ]) + a plain consonant",add:"the following consonant tenses",ex:"숟가락 → [숟까락], 듣고 → [듣꼬]"},{when:"[ㅂ] 받침 (ㅂ,ㅍ sound [ㅂ]) + a plain consonant",add:"the following consonant tenses",ex:"입국 → [입꾹], 잡지 → [잡찌]"},{when:"a plain consonant after ㄴ/ㄹ/ㅁ/ㅇ",add:"usually NO tensing (those are not stops)",ex:"안경 → [안경] (stays plain)"}],examples:[{ko:"학교에서 한국어를 배워요.",en:"I learn Korean at school.",romanization:"hak-kkyo-e-seo han-gu-geo-reul bae-wo-yo",note:"학교 → [학꾜]: the [ㄱ] of 학 tenses the following ㄱ into ㄲ."},{ko:"책상 위에 책이 있어요.",en:"There is a book on the desk.",romanization:"chaek-ssang wi-e chae-gi i-sseo-yo",note:"책상 → [책쌍]: the [ㄱ] 받침 tenses ㅅ to ㅆ. (책이 → [채기] is linking, a separate rule.)"}],more:{func:"When a 받침 pronounced as a stop [ㄱ/ㄷ/ㅂ] is immediately followed by a plain consonant ㄱ, ㄷ, ㅂ, ㅅ, or ㅈ, that following consonant becomes its tense (된소리) version: ㄱ→ㄲ, ㄷ→ㄸ, ㅂ→ㅃ, ㅅ→ㅆ, ㅈ→ㅉ. This is why 학교 is said [학꾜].",keyPoint:{label:"Tense only after a stop",body:"Tensing happens after the three stop sounds [ㄱ][ㄷ][ㅂ], not after the sonorants ㄴ/ㄹ/ㅁ/ㅇ. Compare 학교 [학꾜] (tensing) with 안경 [안경] (no tensing) — the 받침 in 안경 is ㄴ, which is not a stop."},pronunciation:"학교 is [학꾜], not [학교]. The ㄲ is the same tense sound as in 꼬리/꽃 — tighten the throat, no puff of air."}}],canDo:"Hear a plain consonant tense after a stop (학교 → [학꾜], 경음화)",id:"chapter-44-b4",chapterId:"chapter-44",index:3},{kind:"pattern",title:"문법 Grammar · 비음화 (Nasalization): A Stop Becomes Nasal Before ㄴ/ㅁ",cards:[{kind:"teach",name:"비음화 (Nasalization): A Stop Becomes Nasal Before ㄴ/ㅁ",sub:"",rows:[{when:"[ㄱ] 받침 + ㄴ/ㅁ",add:"ㄱ → ㅇ [ŋ]",ex:"한국말 → [한궁말], 작년 → [장년]"},{when:"[ㄷ] 받침 + ㄴ/ㅁ",add:"ㄷ → ㄴ",ex:"듣는 → [든는], 끝나다 → [끈나다]"},{when:"[ㅂ] 받침 + ㄴ/ㅁ",add:"ㅂ → ㅁ",ex:"입니다 → [임니다], 감사합니다 → [감사함니다]"},{when:"a stop + a non-nasal consonant",add:"no nasalization (a different rule applies)",ex:"학교 → [학꾜] (tensing, not nasal)"}],examples:[{ko:"한국말 발음이 자연스러워요.",en:"Your Korean pronunciation is natural.",romanization:"han-gung-mal ba-reu-mi ja-yeon-seu-reo-wo-yo",note:"한국말 → [한궁말]: the [ㄱ] of 국 becomes ㅇ before ㅁ."},{ko:"감사합니다.",en:"Thank you.",romanization:"gam-sa-ham-ni-da",note:"합니다 → [함니다]: the [ㅂ] of 합 becomes ㅁ before ㄴ — the single most common nasalization learners hear."}],more:{func:"When a 받침 pronounced as a stop [ㄱ/ㄷ/ㅂ] is followed by the nasal consonant ㄴ or ㅁ, the stop changes into the matching nasal: ㄱ→ㅇ[ŋ], ㄷ→ㄴ, ㅂ→ㅁ. The mouth assimilates to the nasal that follows. This is why 한국말 is said [한궁말].",keyPoint:{label:"-입니다 / -습니다",body:"The polite formal endings -ㅂ니다 / -습니다 are ALWAYS nasalized in speech: 입니다 [임니다], 습니다 [슴니다]. Saying [입니다] with a real ㅂ sounds unnatural — the ㅂ always becomes ㅁ before the ㄴ."},pronunciation:"한국말 is [한궁말]: the ㄱ disappears into a nasal ㅇ. Hum it — the air should go through your nose on the 궁."}}],canDo:"Recognize nasalization and aspiration in speech (국민 → [궁민]; 좋다 → [조타])",id:"chapter-44-b5",chapterId:"chapter-44",index:4},{kind:"pattern",title:"문법 Grammar · 격음화 (Aspiration): ㅎ Merges with a Plain Stop into an Aspirate",cards:[{kind:"teach",name:"격음화 (Aspiration): ㅎ Merges with a Plain Stop into an Aspirate",sub:"",rows:[{when:"ㅎ 받침 + ㄱ/ㄷ/ㅈ",add:"merge into ㅋ/ㅌ/ㅊ",ex:"좋다 → [조타], 좋고 → [조코], 좋지 → [조치]"},{when:"[ㄱ] 받침 + ㅎ",add:"ㄱ + ㅎ → ㅋ",ex:"축하 → [추카], 백화점 → [배콰점]"},{when:"[ㄷ] 받침 + ㅎ",add:"ㄷ + ㅎ → ㅌ",ex:"맏형 → [마텽]"},{when:"[ㅂ] 받침 + ㅎ",add:"ㅂ + ㅎ → ㅍ",ex:"입학 → [이팍], 잡화 → [자퐈]"}],examples:[{ko:"발음이 좋다고 들었어요.",en:"I heard your pronunciation is good.",romanization:"ba-reu-mi jo-ta-go deu-reo-sseo-yo",note:"좋다 → [조타]: ㅎ 받침 + ㄷ merge into the aspirate ㅌ."},{ko:"입학을 축하해요!",en:"Congratulations on starting school!",romanization:"i-pa-geul chu-ka-hae-yo",note:"입학 → [이팍]: [ㅂ] + ㅎ → ㅍ; 축하 → [추카]: [ㄱ] + ㅎ → ㅋ. Two aspirations in one sentence."}],more:{func:"When ㅎ meets a plain consonant ㄱ, ㄷ, ㅂ, or ㅈ (in either order — ㅎ before the consonant, or a [ㄱ/ㄷ/ㅂ] 받침 before ㅎ), the two merge into a single aspirated consonant: ㄱ→ㅋ, ㄷ→ㅌ, ㅂ→ㅍ, ㅈ→ㅊ. This is why 좋다 is said [조타].",keyPoint:{label:"Aspiration vs. tensing",body:"Both reshape a plain stop, but the trigger differs. ㅎ + ㄱ/ㄷ/ㅂ/ㅈ gives an ASPIRATED consonant (ㅋ/ㅌ/ㅍ/ㅊ, with a puff of air): 좋다 [조타]. A stop + plain consonant gives a TENSE consonant (ㄲ/ㄸ/ㅃ, no air): 학교 [학꾜]. Hold your hand to your mouth — aspiration puffs, tensing doesn't."},pronunciation:"좋다 is [조타], not [졷다] or [조따]. The ㅌ is aspirated like the ㅌ in 타요 — release a clear puff of air, not a tense ㄸ."}}],canDo:"Read a 받침 linking onto the next vowel (한국어 → [한구거], 연음)",id:"chapter-44-b6",chapterId:"chapter-44",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A learner compares written Hangul with actual pronunciation.",lines:[{speaker:"민서",ko:"먹어요는 [먹-어-요]가 아니라 [머거요]처럼 이어져요.",en:"먹어요 is not [meok-eo-yo]; it links and sounds like [머거요].",romanization:"meogeoyoneun [meok-eo-yo]ga anira [meogeoyo]cheoreom ieojyeoyo."},{speaker:"지훈",ko:"학교랑 국밥은 왜 [학꾜], [국빱]처럼 들려요?",en:"Why do 학교 and 국밥 sound like [학꾜] and [국빱]?",romanization:"hakgyorang gukbabeun wae [hakkkyo], [gukppap]cheoreom deullyeoyo?"},{speaker:"민서",ko:"받침 뒤에서 된소리가 나서 그래요.",en:"It is because a tense sound appears after the final consonant.",romanization:"batchim dwieseo doensoriga naseo geuraeyo."},{speaker:"지훈",ko:"그럼 국민은 [궁민], 먹는은 [멍는]처럼 들리죠?",en:"Then 국민 sounds like [궁민], and 먹는 sounds like [멍는], right?",romanization:"geureom gungmineun [gungmin], meongneuneun [meongneun]cheoreom deullijyo?"},{speaker:"민서",ko:"맞아요. 좋다와 입학은 [조타], [이팍]처럼 ㅎ 때문에 세게 나요.",en:"Right. 좋다 and 입학 become stronger sounds like [조타] and [이팍] because of ㅎ.",romanization:"majayo. jotdawa iphak-eun [jota], [ipak]cheoreom hieut ttaemune sege nayo."}]},{kind:"order",prompt:"Build: 'Read Korean slowly.'",tokens:["한국어를","천천히 읽어요"],correct:"한국어를 천천히 읽어요",explanation:"This sentence keeps pronunciation practice inside a real action phrase. 한국어를 is the object and 천천히 tells how to read."}],canDo:"Read a 받침 linking onto the next vowel (한국어 → [한구거], 연음)",id:"chapter-44-b7",chapterId:"chapter-44",index:6},{kind:"reading",title:"읽기 Reading · 글자대로 읽는 것과 실제로 들리는 소리",cards:[{kind:"read",title:"글자대로 읽는 것과 실제로 들리는 소리",chunks:["한글은 규칙적인 문자지만, 실제 말소리는 글자 블록을 하나씩 끊어 읽지 않아요. 먹어요는 [먹-어-요]가 아니라 [머거요]처럼 이어지고, 한국어도 [한구거]처럼 들려요. 반대로 학교와 국밥은 뒤 음절이 세져서 [학꾜], [국빱]처럼 들려요.","또 국민과 먹는처럼 ㄴ이나 ㅁ 앞에서는 받침 소리가 코소리로 바뀌고, 좋다와 입학처럼 ㅎ을 만나면 [조타], [이팍]처럼 거센소리가 나요. 철자는 그대로 외우되, 말할 때는 실제 소리 지도를 함께 익혀야 자연스럽게 들립니다."],translation:"Hangul spelling is regular, but speech does not read each block separately. 먹어요 links to [머거요], 한국어 sounds like [한구거], 학교 and 국밥 gain tense sounds, 국민 and 먹는 nasalize before ㄴ or ㅁ, and 좋다 and 입학 aspirate because of ㅎ. Keep the spelling, but learn the spoken map too.",qas:[{q:"먹어요는 실제로 어떻게 이어져 들려요?",a:"[머거요]처럼 들려요."},{q:"학교와 국밥에서 어떤 변화가 일어나요?",a:"뒤 음절이 된소리로 세져서 [학꾜], [국빱]처럼 들려요."},{q:"좋다와 입학은 왜 [조타], [이팍]처럼 들려요?",a:"ㅎ을 만나서 거센소리가 나기 때문이에요."}]}],canDo:"Hear a plain consonant tense after a stop (학교 → [학꾜], 경음화)",id:"chapter-44-b8",chapterId:"chapter-44",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"먹어요 is naturally pronounced closer to:",sentence:null,options:[{text:"[머거요]",ok:!0},{text:"[먹어 요]",ok:!1},{text:"[먹꼬요]",ok:!1}],explanation:"연음 links ㄱ into the following vowel."},{kind:"drill",prompt:"학교 often sounds like [학꾜] because of:",sentence:null,options:[{text:"경음화",ok:!0},{text:"비음화",ok:!1},{text:"격음화",ok:!1}],explanation:"The following ㄱ becomes tense after the final consonant."},{kind:"drill",prompt:"Which word shows nasalization?",sentence:null,options:[{text:"국민 → [궁민]",ok:!0},{text:"국밥 → [국빱]",ok:!1},{text:"좋다 → [조타]",ok:!1}],explanation:"ㄱ becomes ㅇ before ㅁ."},{kind:"drill",prompt:"Which pair shows aspiration caused by ㅎ?",sentence:null,options:[{text:"입학 → [이팍]",ok:!0},{text:"한국어 → [한구거]",ok:!1},{text:"먹는 → [멍는]",ok:!1}],explanation:"ㅂ and ㅎ combine into ㅍ in speech."},{kind:"drill",prompt:"국민 is naturally heard closer to:",sentence:null,options:[{text:"궁민",ok:!0},{text:"국민 그대로",ok:!1},{text:"군민",ok:!1}],explanation:"Before ㄴ or ㅁ, a stop sound can nasalize. ㄱ before ㅁ is heard closer to ㅇ, giving 궁민."},{kind:"order",prompt:"Build: 'Read Korean slowly.'",tokens:["한국어를","천천히 읽어요"],correct:"한국어를 천천히 읽어요",explanation:"This sentence keeps pronunciation practice inside a real action phrase. 한국어를 is the object and 천천히 tells how to read."},{kind:"drill",prompt:"학교___ 가요. (I go to school.)",sentence:null,options:[{text:"에",ok:!0},{text:"에서",ok:!1},{text:"가",ok:!1}],explanation:"가요 takes 에 for the destination. 에서 marks an action place, and 가 would make 학교 the subject of going. The pronunciation of 학교 may tense in speech, but the written particle is still 에."}],canDo:"Recognize nasalization and aspiration in speech (국민 → [궁민]; 좋다 → [조타])",id:"chapter-44-b9",chapterId:"chapter-44",index:8}]},{id:"chapter-45",number:45,title:"안 + verb/adjective · 못 + verb",goal:"Choose 안 for simple choice or ordinary negation.",biteCount:10,bites:[{kind:"words",title:"단어 Words 1 · 가다~",cards:[{kind:"guess",word:{ko:"가다",romanization:"gada",en:"to go",pos:"verb",nuance:"Use 에 for destination: 학교에 가요, 집에 가요. Do not use 에서 for destination."},sentence:{ko:"안 가는 거예요, 아니면 못 가는 거예요?",en:"Are you choosing not to go, or are you unable to go?"},target:"가는",options:["to eat","to go","to do"],note:"Linked to dictionary card word-verb-003."},{kind:"guess",word:{ko:"먹다",romanization:"meokda",en:"to eat",pos:"verb",nuance:"먹다 is used for meals and food. For medicine, Korean often uses 약을 먹어요, literally “eat medicine,” which means “take medicine.”"},sentence:{ko:"알레르기가 있어서 고기를 못 먹어요.",en:"I cannot eat meat because I have an allergy."},target:"먹어",options:["to go","to do","to eat"],note:"Linked to dictionary card word-verb-001."},{kind:"guess",word:{ko:"하다",romanization:"hada",en:"to do",pos:"verb",nuance:"하다 combines with many nouns: 공부하다, 일하다, 운동하다. It is one of the most important Korean verbs."},sentence:{ko:"요즘 운동 안 해요.",en:"I do not exercise these days."},target:"해",options:["to go","to do","to eat"],note:"Linked to dictionary card word-verb-007."},{kind:"guess",word:{ko:"시간",romanization:"sigan",en:"time",pos:"noun",nuance:"시간 works with 있어요/없어요 and is essential for scheduling."},sentence:{ko:"시간이 없어서 못 가요.",en:"I cannot go because I do not have time."},target:"시간",options:["time","working overtime","meat"],note:"Linked to dictionary card word-noun-009."},{kind:"guess",word:{ko:"야근",romanization:"yageun",en:"working overtime",pos:"noun",nuance:"야근 specifically means staying at the office working late into the night — the iconic symbol of old-school Korean work culture. It is Sino-Korean 夜勤, literally 'night-duty', sharing the 勤 ('duty/labor') of 외근 and 출근. The contrast to nail: 야근 is overtime that runs LATE/at night, whereas 특근 (特勤, 'special duty') and 추가 근무 cover extra work generally, including daytime, weekends, or holidays — so weekend morning work is 특근, not 야근. Its cultural foil is the slang 칼퇴 ('knife-exit' = leaving on the dot at quitting time), the thing everyone dreams of instead. And the carrot is 야근 수당 (overtime pay), which is 나오다 (paid out), not 받다-only. The English-speaker pitfall is using 야근 as a blanket word for all 'overtime' — keep the time-of-day nuance — and saying 야근을 가다 ('go to overtime'); you don't go to it, you 야근을 하다."},sentence:{ko:"야근 때문에 못 가요.",en:"I cannot go because of overtime."},target:"야근",options:["working overtime","time","meat"],note:"Linked to dictionary card word-ext-548."},{kind:"guess",word:{ko:"고기",romanization:"gogi",en:"meat",pos:"noun",nuance:"In everyday speech 고기 by default means red land meat — usually 돼지고기(pork) or 소고기(beef) — so 고기 먹으러 가자 implies a BBQ, not seafood. To be specific you compound the animal onto 고기: 닭고기(chicken), 소고기(beef), 돼지고기(pork). The words to contrast are 생선(fish as food) and 해산물(seafood), which Koreans do NOT file under 고기; chicken sits on the edge, so people usually say 닭고기 rather than bare 고기 for it. The set cooking verb is 굽다, a ㅂ-irregular that becomes 구워요/구웠어요 (not 'gubeoyo'). The English-speaker pitfall is the English umbrella sense of 'meat' that includes fish and poultry — in Korean, unmarked 고기 leans strongly toward pork/beef, and you should name the animal when you mean otherwise."},sentence:{ko:"고기는 안 먹어요?",en:"Do you not eat meat?"},target:"고기",options:["meat","time","working overtime"],note:"Linked to dictionary card word-ext-040."},{kind:"payoff",line:{speaker:"민서",ko:"오늘 모임에는 못 가요. 시간이 없어요.",en:"I cannot go to the gathering today. I do not have time."},hl:"가요"}],canDo:"Negate by choice or fact with 안 (안 먹어요)",id:"chapter-45-b1",chapterId:"chapter-45",index:0},{kind:"pattern",title:"문법 Grammar · 안 + verb/adjective",cards:[{kind:"hunt",name:"안 + verb/adjective",sub:"simple negation",lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"술을",mid:"",post:"",hit:!1},{pre:"",mid:"안",post:"",hit:!0},{pre:"마셔요.",mid:"",post:"",hit:!1}],ko:"저는 술을 안 마셔요.",en:"I don't drink alcohol.",romanization:"jeoneun sureul an masyeoyo."},{tokens:[{pre:"오늘은",mid:"",post:"",hit:!1},{pre:"학교에",mid:"",post:"",hit:!1},{pre:"",mid:"안",post:"",hit:!0},{pre:"가요.",mid:"",post:"",hit:!1}],ko:"오늘은 학교에 안 가요.",en:"I'm not going to school today.",romanization:"oneureun hakgyoe an gayo."}],rule:{name:"안 + verb/adjective",rows:[{when:"Most verbs and adjectives",add:"안 in front of the word",ex:"가요 → 안 가요 (don't go)"},{when:"Adjective",add:"안 in front",ex:"바빠요 → 안 바빠요 (not busy)"},{when:"하다 action verbs (공부하다 등)",add:"안 splits IN: noun + 안 + 해요",ex:"공부해요 → 공부 안 해요 (don't study)"}]},more:{func:`Put 안 directly in front of a verb or adjective to make it negative. This is the everyday spoken negation: "I don't / it isn't." It states a choice or a plain fact, with no sense of being blocked or unable.`,keyPoint:{label:"안 vs 못",body:"안 = don't or won't, by choice or as a plain fact (안 가요, I'm not going). 못 = can't, blocked by an outside obstacle (못 가요, I can't go). If you simply chose not to, use 안; if something stops you, use 못."},pronunciation:"안 is pronounced [an] and, unlike 못, it does NOT tense the next sound. 안 가요 stays [an ga.yo], 안 봐요 stays [an bwa.yo]. Before a verb starting with ㅁ/ㄴ the nasal flows smoothly: 안 마셔요 → [an ma.syeo.yo]. No double-consonant tensing anywhere."}}],canDo:"Negate by choice or fact with 안 (안 먹어요)",id:"chapter-45-b2",chapterId:"chapter-45",index:1},{kind:"words",title:"단어 Words 2 · 알레르기~",cards:[{kind:"guess",word:{ko:"알레르기",romanization:"allereugi",en:"allergy",pos:"noun",nuance:"알레르기 gives a concrete outside reason. In Korean this often makes 못 sound appropriate because the limit is physical or medical, not a preference."},sentence:{ko:"알레르기가 있어서 못 먹어요.",en:"I cannot eat it because I have an allergy."},target:"알레르기",options:["time","working overtime","allergy"],note:"Linked to dictionary card word-ext-ch45-allergy."},{kind:"guess",word:{ko:"싫다",romanization:"silta",en:"to dislike; to be undesirable",pos:"adjective",nuance:"싫어요 can sound strong. For polite refusal, 고 싶지 않아요 can be softer."},sentence:{ko:"가기 싫은 건 아니에요.",en:"It is not that I do not want to go."},target:"싫은",options:["to be difficult","to dislike; to be undesirable","to go"],note:"Linked to dictionary card word-adjective-028."},{kind:"guess",word:{ko:"어렵다",romanization:"eoryeopda",en:"to be difficult",pos:"adjective",nuance:"어렵다 is ㅂ irregular: 어려워요, 어려운. It is useful in classroom repair conversations because learners often need to say a sentence or lesson is difficult."},sentence:{ko:"어렵지 않게 다른 메뉴로 예약할게요.",en:"I will reserve a different menu so it is not difficult."},target:"어렵",options:["to be difficult","to dislike; to be undesirable","to go"],note:"Linked to dictionary card word-adjective-037."},{kind:"guess",word:{ko:"공부",romanization:"gongbu",en:"study; studying",pos:"noun",nuance:"공부(工夫)는 한자 그대로 '공을 들여 애씀'이라는 뜻으로, 지식이나 기술을 배우고 익히는 모든 활동을 가리키는 가장 기본적인 단어예요. 비슷한 말 '학습'은 교과서나 보고서에 어울리는 딱딱한 한자어라 일상 대화에서는 거의 안 쓰고, '연습'은 이미 배운 것을 몸에 익히려 반복하는 것이라 '머리로 새로 익히는' 공부와는 결이 달라요. 영어 study처럼 목적어를 바로 붙여 '공부 Korean'이라고 하면 안 되고, 반드시 '한국어를 공부하다'처럼 -을/를을 쓰거나 '한국어 공부를 하다'로 명사화해야 해요. 동사로 쓸 때 '공부를 하다'와 한 단어 '공부하다'가 둘 다 자연스럽고, '열심히/같이/매일'과 잘 어울려요."},sentence:{ko:"오늘은 공부 못 해요.",en:"I cannot study today."},target:"공부",options:["time","working overtime","study; studying"],note:"Linked to dictionary card word-ext-1560."},{kind:"guess",word:{ko:"운동",romanization:"undong",en:"exercise",pos:"noun",nuance:"운동 is Sino-Korean, 運動 ('move-motion'), and is the umbrella word for physical exercise; it normally appears as 운동하다 (운동을 해요). Crucially it is NOT counted or pluralized like English 'a workout' — you don't say 운동들 for several sessions; you say 운동을 자주 해요. The nearest relative is 스포츠 (a borrowed word for organized sports as a category, e.g. watching 스포츠 on TV), whereas 운동 is the act of exercising your own body, so '운동선수' = athlete but '스포츠 경기' = a sports match. The very same 運動 also means a social 'movement/campaign' (민주화 운동 the democracy movement), so context decides. The English-speaker pitfall is reaching for 만들다 ('make') by analogy with 'make exercise' — Korean uses the light verb 하다; and remember the desire ending goes on the verb (운동하고 싶어요), never on the bare noun."},sentence:{ko:"요즘 운동 안 해요.",en:"I do not exercise these days."},target:"운동",options:["time","exercise","working overtime"],note:"Linked to dictionary card word-ext-301."},{kind:"guess",word:{ko:"전화",romanization:"jeonhwa",en:"phone call",pos:"noun",nuance:"전화 is a noun, but 전화하다 is the verb “to call.”"},sentence:{ko:"지금은 전화 못 해요.",en:"I cannot call right now."},target:"전화",options:["phone call","time","working overtime"],note:"Linked to dictionary card word-noun-024."},{kind:"payoff",line:{speaker:"민서",ko:"싫어서 안 먹는 게 아니라 알레르기가 있어서 못 먹어요.",en:"It is not that I avoid it because I dislike it; I cannot eat it because I have an allergy."},hl:"알레르기"}],canDo:"Say you can't because something blocks you with 못 (시간이 없어서 못 가요)",id:"chapter-45-b3",chapterId:"chapter-45",index:2},{kind:"pattern",title:"문법 Grammar · 못 + verb",cards:[{kind:"hunt",name:"못 + verb",sub:"cannot, because something blocks you",lines:[{tokens:[{pre:"오늘",mid:"",post:"",hit:!1},{pre:"너무",mid:"",post:"",hit:!1},{pre:"바빠서",mid:"",post:"",hit:!1},{pre:"",mid:"못",post:"",hit:!0},{pre:"가요.",mid:"",post:"",hit:!1}],ko:"오늘 너무 바빠서 못 가요.",en:"I can't go today because I'm too busy.",romanization:"oneul neomu bappaseo mot gayo."},{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"매운",mid:"",post:"",hit:!1},{pre:"음식을",mid:"",post:"",hit:!1},{pre:"",mid:"못",post:"",hit:!0},{pre:"먹어요.",mid:"",post:"",hit:!1}],ko:"저는 매운 음식을 못 먹어요.",en:"I can't eat spicy food.",romanization:"jeoneun maeun eumsigeul mot meogeoyo."}],rule:{name:"못 + verb",rows:[{when:"Most action verbs",add:"못 in front of the verb",ex:"가요 → 못 가요 (can't go)"},{when:"하다 action verbs",add:"못 splits IN: noun + 못 + 해요",ex:"수영해요 → 수영 못 해요 (can't swim)"},{when:"NOT with plain adjectives",add:"use 안 instead",ex:"안 바빠요 (○) / 못 바빠요 (✗)"}]},more:{func:"Put 못 in front of a verb to say you CANNOT do it — not because you don't want to, but because something blocks or prevents you (no time, no skill, no permission, an obstacle). 못 is used with action verbs, not with descriptive adjectives.",keyPoint:{label:"못 + verb only (never adjectives)",body:"못 means 'unable to DO an action,' so it attaches to action verbs (못 가요, 못 먹어요). You can't be 'unable to be tall' or 'unable to be busy' — for adjectives use 안 (안 커요, 안 바빠요). 못 바빠요 is wrong."},pronunciation:"못 is written with final ㅅ but pronounced [몯]. Before a vowel it links: 못 와요 → [모 돠요]. Before ㄱ/ㄷ/ㅂ/ㅈ it TENSES the next sound: 못 가요 → [몯 까요], 못 봐요 → [몯 빠요]. That tensing is the audible signal of 못 — and the clearest way to tell it apart from 안."}}],canDo:"Say you can't because something blocks you with 못 (시간이 없어서 못 가요)",id:"chapter-45-b4",chapterId:"chapter-45",index:3},{kind:"pattern",title:"문법 Grammar · -지 않아요",cards:[{kind:"hunt",name:"-지 않아요",sub:"the longer / written negation",lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"고기를",mid:"",post:"",hit:!1},{pre:"먹",mid:"지",post:"",hit:!0},{pre:"",mid:"않아요",post:".",hit:!0}],ko:"저는 고기를 먹지 않아요.",en:"I don't eat meat.",romanization:"jeoneun gogireul meokji anayo."},{tokens:[{pre:"그",mid:"",post:"",hit:!1},{pre:"가게는",mid:"",post:"",hit:!1},{pre:"비싸",mid:"지",post:"",hit:!0},{pre:"",mid:"않아요",post:".",hit:!0}],ko:"그 가게는 비싸지 않아요.",en:"That shop isn't expensive.",romanization:"geu gageneun bissaji anayo."}],rule:{name:"-지 않아요",rows:[{when:"Verb or adjective stem",add:"stem + -지 않아요",ex:"가다 → 가지 않아요 (don't go)"},{when:"Adjective",add:"stem + -지 않아요",ex:"바쁘다 → 바쁘지 않아요 (not busy)"},{when:"하다 verbs (no splitting!)",add:"공부하 + -지 않아요",ex:"공부하다 → 공부하지 않아요 (don't study)"}]},more:{func:"Attach -지 않아요 to a verb or adjective stem for the 'long form' of negation. It means the same as 안, but is a little more formal and is common in writing, careful speech, and longer sentences. It works smoothly with every verb and adjective, including 하다 verbs (no splitting).",keyPoint:{label:"안 vs -지 않아요",body:"They mean the same thing. 안 먹어요 = 먹지 않아요 (I don't eat). 안 is short and spoken; -지 않아요 is longer and slightly more formal or written. Bonus: 하다 verbs DON'T split with -지 않아요 (운동하지 않아요), unlike 운동 안 해요."},pronunciation:"않아요 is pronounced [아나요] — the ㅎ in 않 is silent and the ㄴ links into the following vowel: 가지 않아요 → [가지 아나요]. The ㅎ never makes its own sound here."}}],canDo:"Use the longer written negation -지 않아요 (좋아하지 않아요)",id:"chapter-45-b5",chapterId:"chapter-45",index:4},{kind:"pattern",title:"문법 Grammar · N이/가 없어요",cards:[{kind:"hunt",name:"N이/가 없어요",sub:`absence / "don't have"`,lines:[{tokens:[{pre:"지금",mid:"",post:"",hit:!1},{pre:"시간",mid:"이",post:"",hit:!0},{pre:"",mid:"없어요",post:".",hit:!0}],ko:"지금 시간이 없어요.",en:"I don't have time right now.",romanization:"jigeum sigani eopseoyo."},{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"차",mid:"가",post:"",hit:!0},{pre:"",mid:"없어요",post:".",hit:!0}],ko:"저는 차가 없어요.",en:"I don't have a car.",romanization:"jeoneun chaga eopseoyo."}],rule:{name:"N이/가 없어요",rows:[{when:"Noun ends in a consonant",add:"noun + 이 없어요",ex:"시간 → 시간이 없어요 (no time)"},{when:"Noun ends in a vowel",add:"noun + 가 없어요",ex:"차 → 차가 없어요 (no car)"},{when:"Opposite (positive)",add:"있어요",ex:"시간이 있어요 (have time)"}]},more:{func:"없어요 is the verb for 'there isn't / I don't have.' It is the opposite of 있어요 (there is / have). The noun takes the subject marker 이/가, and 없어요 covers both 'don't possess' and 'isn't present / doesn't exist.'",keyPoint:{label:"없어요 vs 안 + verb",body:"For NOT HAVING or NOT EXISTING, use 없어요, never 안 있어요. 안 있어요 is wrong. So 'no time' = 시간이 없어요 (○), not 시간이 안 있어요 (✗). 안 negates actions and qualities; 없어요 negates existence and possession."},pronunciation:"없어요 is pronounced [업써요]: the ㅂㅅ cluster keeps the ㅂ [p] sound, and the ㅅ links to the next vowel as a tense [ss]. So 시간이 없어요 → [시가니 업써요]."}},{kind:"drill",prompt:"There's no milk in the fridge.",sentence:"냉장고에 우유___.",options:[{text:"이 없어요",ok:!1},{text:"가 없어요",ok:!0}],explanation:"Same 없어요 also means 'isn't there / doesn't exist' — the absence of a thing in a place. 우유 ends in a vowel → 우유가."}],canDo:"Express absence or 'don't have' with N이/가 없어요 (시간이 없어요)",id:"chapter-45-b6",chapterId:"chapter-45",index:5},{kind:"pattern",title:"문법 Grammar · Boundary check",cards:[{kind:"teach",name:"Boundary check",sub:"안 vs 못 vs 아니에요 vs 싫어요",rows:[{when:"Choice / plain fact about an action or quality",add:"안 + verb/adjective",ex:"안 가요 (I'm not going)"},{when:"Inability / outside obstacle",add:"못 + verb",ex:"못 가요 (I can't go)"},{when:"'It is NOT [a noun]' (identity)",add:"noun + 이/가 아니에요",ex:"학생이 아니에요 (not a student)"},{when:"Dislike / 'I don't want to'",add:"싫어요 (or 안 좋아요)",ex:"숙제가 싫어요 (I hate homework)"}],examples:[{ko:"오늘은 안 가요.",en:"I'm not going today.",romanization:"oneureun an gayo.",note:"A choice or plan — plain negation of the action, so 안."},{ko:"바빠서 오늘은 못 가요.",en:"I can't go today because I'm busy.",romanization:"bappaseo oneureun mot gayo.",note:"Something blocks the action (being busy), so 못, not 안."}],more:{func:"Korean splits the English word 'not' across several forms, and choosing the wrong one sounds off. This note sorts them: 안 = don't/won't (choice or fact), 못 = can't (blocked), 아니에요 = 'it's not [a noun]' (identity), 싫어요 = 'I don't like it / I don't want to' (dislike or refusal). Match the form to the meaning, not to the English word.",keyPoint:{label:"One English 'not,' four Korean choices",body:"Ask what kind of 'not' it is. Action by choice → 안. Action blocked → 못. 'It's not [a noun]' → 아니에요. 'I don't like / don't want' → 싫어요. Picking by feeling, not by the English word, is the whole skill of this chapter."},pronunciation:"아니에요 → [아니에요], four clear syllables, no linking trick. 싫어요 → [시러요]: the ㅎ in 싫 is silent and the ㄹ links into the vowel, so it sounds like [시러요], not [실허요]."}}],canDo:"Negate by choice or fact with 안 (안 먹어요)",id:"chapter-45-b7",chapterId:"chapter-45",index:6},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A friend clarifies whether a refusal is about choice, schedule, or a real restriction.",lines:[{speaker:"민서",ko:"오늘 모임에는 못 가요. 시간이 없어요.",en:"I cannot go to the gathering today. I do not have time.",romanization:"oneul moimeneun mot gayo. sigani eopseoyo."},{speaker:"지훈",ko:"안 가는 거예요, 아니면 정말 못 가는 거예요?",en:"Are you choosing not to go, or are you really unable to go?",romanization:"an ganeun geoyeyo, animyeon jeongmal mot ganeun geoyeyo?"},{speaker:"민서",ko:"가기 싫은 건 아니에요. 야근 때문에 못 가요.",en:"It is not that I do not want to go. I cannot go because of overtime.",romanization:"gagi silheun geon anieyo. yageun ttaemune mot gayo."},{speaker:"지훈",ko:"그럼 회식에서 고기는 안 먹어요?",en:"Then at the company dinner, do you not eat meat?",romanization:"geureom hoesigeseo gogineun an meogeoyo?"},{speaker:"민서",ko:"싫어서 안 먹는 게 아니라 알레르기가 있어서 못 먹어요.",en:"It is not that I avoid it because I dislike it; I cannot eat it because I have an allergy.",romanization:"silheoseo an meongneun ge anira allereugiga isseoseo mot meogeoyo."},{speaker:"지훈",ko:"그럼 어렵지 않게 다른 메뉴로 예약할게요.",en:"Then I will reserve a different menu so it is not difficult.",romanization:"geureom eoryeopji anke dareun menyuro yeyakhalgeyo."}]},{kind:"order",prompt:"Build: 'I cannot eat meat because of an allergy.'",tokens:["알레르기 때문에","고기를 못 먹어요"],correct:"알레르기 때문에 고기를 못 먹어요",explanation:"때문에 gives the medical reason, and 못 marks inability. 고기 is what cannot be eaten, so 고기를 is the object."}],canDo:"Negate by choice or fact with 안 (안 먹어요)",id:"chapter-45-b8",chapterId:"chapter-45",index:7},{kind:"reading",title:"읽기 Reading · 안 가요와 못 가요는 같은 말이 아니에요",cards:[{kind:"read",title:"안 가요와 못 가요는 같은 말이 아니에요",chunks:["친구의 초대를 거절할 때 '안 가요'와 '못 가요'는 느낌이 달라요. '안 가요'는 내가 가지 않기로 한 선택처럼 들릴 수 있고, '못 가요'는 시간, 일, 건강 같은 이유 때문에 갈 수 없다는 뜻이에요. 그래서 '시간이 없어서 못 가요'라고 말하면 오해가 줄어요.","음식도 마찬가지예요. '고기는 안 먹어요'는 취향이나 습관처럼 들릴 수 있지만, '알레르기가 있어서 못 먹어요'는 몸의 제한을 설명해요. 더 조심스럽게 말하고 싶을 때는 '싫지 않아요', '어렵지 않아요', '먹지 않아요'처럼 -지 않아요를 쓸 수 있어요."],translation:"When declining an invitation, 안 가요 and 못 가요 do not feel the same. 안 가요 can sound like a choice, while 못 가요 says you cannot go because of time, work, health, or another limit. Food works similarly: 고기는 안 먹어요 may sound like preference or habit, but 알레르기가 있어서 못 먹어요 explains a physical restriction. For careful clarification, use -지 않아요.",qas:[{q:"안 가요는 어떤 느낌으로 들릴 수 있어요?",a:"내가 가지 않기로 한 선택처럼 들릴 수 있어요."},{q:"알레르기가 있을 때 왜 못 먹어요가 자연스러워요?",a:"취향이 아니라 몸의 제한 때문에 먹을 수 없다는 뜻이기 때문이에요."},{q:"조심스럽게 부정하거나 설명할 때 어떤 형태를 쓸 수 있어요?",a:"-지 않아요를 쓸 수 있어요."}]}],canDo:"Say you can't because something blocks you with 못 (시간이 없어서 못 가요)",id:"chapter-45-b9",chapterId:"chapter-45",index:8},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence says circumstances make it impossible to go?",sentence:null,options:[{text:"오늘은 못 가요.",ok:!0},{text:"오늘은 안 가요.",ok:!1},{text:"오늘은 가기 싫어요.",ok:!1}],explanation:"못 marks inability or a blocked situation."},{kind:"drill",prompt:"Which sentence best explains a medical food restriction?",sentence:null,options:[{text:"알레르기가 있어서 못 먹어요.",ok:!0},{text:"싫어서 안 먹어요.",ok:!1},{text:"먹기 싫지 않아요.",ok:!1}],explanation:"알레르기 is an outside restriction, so 못 먹어요 is natural."},{kind:"drill",prompt:"Which sentence uses absence as the reason?",sentence:null,options:[{text:"시간이 없어서 못 가요.",ok:!0},{text:"시간을 안 가요.",ok:!1},{text:"시간이 못 있어요.",ok:!1}],explanation:"없어요 negates the existence/possession of time."},{kind:"drill",prompt:"Which pair correctly contrasts choice and inability?",sentence:null,options:[{text:"안 가요 / 못 가요",ok:!0},{text:"못 가요 / 시간이 없어요",ok:!1},{text:"없어요 / 아니에요",ok:!1}],explanation:"안 often marks not doing or choosing not to; 못 marks inability or blocked action."},{kind:"drill",prompt:"시간___ 없어요. (I do not have time.)",sentence:null,options:[{text:"이",ok:!0},{text:"을",ok:!1},{text:"에",ok:!1}],explanation:"없어요 uses 이/가 for the thing that is absent. 시간 is not an object of an action here."},{kind:"order",prompt:"Build: 'I cannot eat meat because of an allergy.'",tokens:["알레르기 때문에","고기를 못 먹어요"],correct:"알레르기 때문에 고기를 못 먹어요",explanation:"때문에 gives the medical reason, and 못 marks inability. 고기 is what cannot be eaten, so 고기를 is the object."}],canDo:"Use the longer written negation -지 않아요 (좋아하지 않아요)",id:"chapter-45-b10",chapterId:"chapter-45",index:9}]},{id:"chapter-46",number:46,title:"N이었어요 / N였어요 · N인데 / N인데도",goal:"Turn role nouns into past identity: 학생이었어요, 회사원이었어요.",biteCount:10,bites:[{kind:"words",title:"단어 Words 1 · 학생~",cards:[{kind:"guess",word:{ko:"학생",romanization:"haksaeng",en:"student",pos:"noun",nuance:"학생 is a common identity word. Use 이에요 after 학생 because it ends in a consonant."},sentence:{ko:"작년에는 학생이었어요.",en:"I was a student last year."},target:"학생",options:["student","office worker","employee; staff member"],note:"Core role noun for N이었어요/였어요, N이라서, and N이니까."},{kind:"guess",word:{ko:"회사원",romanization:"hoesawon",en:"office worker",pos:"noun",nuance:"회사원 is 會社員 ('company-member'), literally a member of a company, and it is the neutral catch-all a salaried employee of a private firm gives when asked 무슨 일 하세요? Contrast it with 직장인, which means 'a working person' in general (anyone with a paid job, including teachers or nurses): every 회사원 is a 직장인, but not every 직장인 is a 회사원. Also separate it from 사업가, the owner who runs the business — a 회사원 is employed by someone else. The pitfall for English speakers is twofold: 회사원 ends in a consonant so the copula is 회사원이에요, never 'office worker'-style 회사원예요; and don't translate 'I work at a company' as a job title — to name the job you simply say 회사원이에요 rather than literally rendering the English sentence."},sentence:{ko:"지금은 회사원인데도 계속 공부해요.",en:"Even though I am an office worker now, I keep studying."},target:"회사원",options:["student","office worker","employee; staff member"],note:"Better fit than a random job word because it explains a busy adult schedule."},{kind:"guess",word:{ko:"직원",romanization:"jigwon",en:"employee; staff member",pos:"noun",nuance:"직원 (職員, 'duty-personnel') is the plain, everyday word for anyone who works at a company, shop, bank, or office — the person on the other side of the counter helping you. The synonym contrast to nail: 직원 is generic 'staff' regardless of rank, while 사원 (社員) specifically names the entry-level rung on the corporate ladder, and 종업원 sounds older/more clerical (waitstaff, hired help). In daily life 직원 is overwhelmingly the natural choice — 직원한테 물어보세요 (ask a staff member) is a sentence you'll use weekly. Register is neutral and safe for everyone. The English-speaker pitfall is twofold: first, don't call the customer a 직원 — the 직원 is the one who WORKS there, not the visitor (that's 손님); second, English says 'I asked the staff' with no particle, but Korean must mark the person with 한테/에게: 직원에게 물어봤어요."},sentence:{ko:"저는 직원인데요, 담당자는 아니에요.",en:"I am an employee, but I am not the person in charge."},target:"직원",options:["employee; staff member","student","office worker"],note:"Useful for soft background with 인데요."},{kind:"guess",word:{ko:"작년",romanization:"jangnyeon",en:"last year",pos:"noun",nuance:"작년 means last year. Both 작년에 만났어요 and the particle-less 작년 만났어요 can occur; 에 is useful when clearly marking the time point, but it is not obligatory in every sentence."},sentence:{ko:"작년에는 학생이었어요.",en:"I was a student last year."},target:"작년",options:["student","office worker","last year"],note:"Time anchor for past identity."},{kind:"guess",word:{ko:"올해",romanization:"olhae",en:"this year",pos:"noun",nuance:"올해 is the native Korean word for the present calendar year and slots straight in front of a verb, normally WITHOUT 에: 올해 졸업해요 (I graduate this year), not 올해에. It anchors the three-year set 작년 (last year) – 올해 (this year) – 내년 (next year). There is a Sino-Korean synonym 금년 (今年, 'present year'), but it is stiff and limited to formal writing or speeches; in conversation 올해 is the only natural choice. Two English-speaker pitfalls stand out. First, the 에 habit: because English says 'in this year' learners over-add 에, but native usage drops it after 올해. Second, the look-alike trap with 오늘 ('today') — both start with 오, yet 올해 is a whole year and 오늘 is a single day, so 'I'm twenty this year' is 올해 스무 살이에요, never 오늘."},sentence:{ko:"올해는 회사원이에요.",en:"This year I am an office worker."},target:"올해",options:["student","office worker","this year"],note:"Pairs naturally with 작년 when comparing past and present identity."},{kind:"guess",word:{ko:"주말",romanization:"jumal",en:"weekend",pos:"noun",nuance:"주말 is Sino-Korean, 週末 — 週 'week' + 末 'end', literally 'week-end', and its opposites are 평일 平日 'weekday' and 주중 週中 'midweek'. It refers to Saturday and Sunday as a block. The contrast worth noting is 주말 vs 휴일: 주말 is specifically the weekend, while 휴일 休日 is any day off including public holidays — so a Wednesday holiday is a 휴일 but not a 주말. Habitual partners: 주말에 쉬다/놀다, 이번/지난/다음 주말, 주말마다, 즐거운 주말, and the farewell 주말 잘 보내세요. The English-speaker pitfall is the particle: learners borrow 'at/on' loosely and write 주말에서, but 에서 marks a LOCATION or a source ('from'); the time-when always takes 에 → 주말에. A second subtlety: for 'this weekend' use 이번 주말 (이번 = the current instance), not 오늘 주말; and 다음 주말 'next weekend' vs 다음 주 주말 can differ, so keep 다음 주말 for the upcoming Sat–Sun."},sentence:{ko:"주말이니까 한 시간이라도 공부해요.",en:"Since it is the weekend, let's study even if just for one hour."},target:"주말",options:["weekend","student","office worker"],note:"Time noun that naturally supports 니까 and 라도 practice."},{kind:"payoff",line:{speaker:"민서",ko:"작년에는 학생이었어요?",en:"Were you a student last year?"},hl:"학생"}],canDo:"Say what something was in the past (학생이었어요 · 주말이었어요)",id:"chapter-46-b1",chapterId:"chapter-46",index:0},{kind:"pattern",title:"문법 Grammar · N이었어요 / N였어요",cards:[{kind:"hunt",name:"N이었어요 / N였어요",sub:'"It was an N" (past of 이다)',lines:[{tokens:[{pre:"어제는",mid:"",post:"",hit:!1},{pre:"제",mid:"",post:"",hit:!1},{pre:"생일",mid:"이었어요",post:".",hit:!0}],ko:"어제는 제 생일이었어요.",en:"Yesterday was my birthday.",romanization:"eojeneun je saengirieosseoyo."},{tokens:[{pre:"그",mid:"",post:"",hit:!1},{pre:"사람은",mid:"",post:"",hit:!1},{pre:"제",mid:"",post:"",hit:!1},{pre:"친구",mid:"였어요",post:".",hit:!0}],ko:"그 사람은 제 친구였어요.",en:"That person was my friend.",romanization:"geu sarameun je chinguyeosseoyo."}],rule:{name:"N이었어요 / N였어요",rows:[{when:"Noun ends in a consonant (받침)",add:"N + 이었어요",ex:"학생 → 학생이었어요 (was a student)"},{when:"Noun ends in a vowel",add:"N + 였어요 (shortened from 이었어요)",ex:"친구 → 친구였어요 (was a friend)"},{when:"Casual 반말 past",add:"N이었어 / N였어",ex:"주말이었어 / 친구였어 (was the weekend / was a friend)"},{when:"Negative past (was not N)",add:"N이/가 아니었어요",ex:"학생이 아니었어요 (wasn't a student)"}]},more:{func:'Says what something was in the past — an identity, role, or category that was true before now: "It was my birthday," "She was a student," "Yesterday was the weekend." It is just 이다 put into the past polite form.',keyPoint:{label:"이었어요 vs 였어요 — just a sound rule",body:"Both are the same past form of 이다. After a consonant, keep the full 이었어요 (학생이었어요). After a vowel, 이었어요 shrinks to 였어요 (친구였어요). The meaning is identical — only the spelling and sound change, based on the noun's final letter."},pronunciation:"학생이었어요 links across the boundary and sounds like [학쌩이어써요]; 친구였어요 sounds like [친구여써요]."}},{kind:"drill",prompt:"Last year I was a student too.",sentence:"작년에는 저도 학생___.",options:[{text:"이었어요",ok:!0},{text:"였어요",ok:!1}],explanation:"학생 ends in a consonant → 이었어요; 작년 (last year) sets the past time."}],canDo:"Say what something was in the past (학생이었어요 · 주말이었어요)",id:"chapter-46-b2",chapterId:"chapter-46",index:1},{kind:"words",title:"단어 Words 2 · 평일~",cards:[{kind:"guess",word:{ko:"평일",romanization:"pyeongil",en:"weekday",pos:"noun",nuance:"평일 is Sino-Korean 平日 (平 'flat/ordinary' + 日 'day'), literally an 'ordinary day' — Monday through Friday, the regular working days, set against 주말 (weekend) and 휴일 (holiday/day off). The dividing line vs 주중 (週中, 'inside the week'): 평일 simply names the ordinary days as a category, while 주중 frames those same days as the span 'during the week' and pairs naturally with 주말 as a matched contrast (주중에는 바쁘고 주말에는 쉬어요). 평일 is neutral and used by everyone in any register, from a weather report to a friend's text. It habitually appears as 평일 + time-of-day (평일 아침/낮/저녁) and with 에/에는. The English-speaker pitfall: 'weekday' in English can mean 'any single working day' OR the whole work portion of the week, but in Korean 평일 leans toward the category of ordinary days, so for a duration like 'during the week I'm busy' Koreans more often say 주중에는 바빠요; also don't write the near-homophone 휴일 (rest day) by mistake."},sentence:{ko:"평일이라서 오래 못 해요.",en:"Because it is a weekday, I cannot do it for long."},target:"평일",options:["weekday","student","office worker"],note:"Useful contrast with 주말 for schedule-based reasons."},{kind:"guess",word:{ko:"아침",romanization:"achim",en:"morning; breakfast",pos:"noun",nuance:"아침 is a native Korean word that does double duty: the early part of the day (roughly sunrise to mid-morning) and the breakfast meal — the same way English 'morning' differs from the meal but Korean merges the breakfast sense into the time word. The grammar disambiguates: with 에 (아침에) it's the time, with 을 (아침을 먹다) it's the food. Contrast 아침 vs 오전: 아침 is the felt, lived early morning, while 오전 午前 is the neutral clock-AM you put on timetables — so 아침에 일어나요 (waking life) but 오전 9시 회의 (a scheduled item). Habitual partners: 아침에 일어나다/운동하다, 아침을 먹다/거르다 ('skip breakfast'), 아침 일찍, 매일 아침. The big English-speaker pitfall is using 오전 for the breakfast meal — 오전 is only the clock period and can never name food, so 'eat breakfast' must be 아침을 먹다, never 오전을 먹다. Also don't force 에 onto the meal sense: you eat 아침을, you don't 'eat at morning'."},sentence:{ko:"아침이라도 괜찮아요?",en:"Would even morning be okay?"},target:"아침",options:["student","office worker","morning; breakfast"],note:"Works as a fallback time when the better time is unavailable."},{kind:"guess",word:{ko:"시간",romanization:"sigan",en:"time; hour",pos:"noun",nuance:"시간 works with 있어요/없어요 and is essential for scheduling."},sentence:{ko:"한 시간이라도 공부해요.",en:"Let's study even if it is just one hour."},target:"시간",options:["time; hour","student","office worker"],note:"A high-value noun for 라도 because learners often negotiate minimum time."},{kind:"guess",word:{ko:"질문",romanization:"jilmun",en:"question",pos:"noun",nuance:"질문 is Sino-Korean 質問 — 質 'substance/inquire into' + 問 'ask', literally 'to inquire and ask', i.e. a question put to someone. The set verb is 질문을 하다 (or the single verb 질문하다); the person you ask takes 에게/한테 (or honorific 께 for a teacher): 선생님께 질문을 하다. Its natural partner is 대답/답(答) — a 질문 is answered by a 대답. The big redundancy trap for English speakers is 질문을 물어보다 ✗: 물어보다 already means 'to ask', so this literally says 'ask a question-asking' — say either 질문을 하다 or just 물어보다, never both. Distinguish 질문 (a question seeking information/an answer) from 문제(問題, a 'problem' or exam item) — '3 questions on the test' are 문제 세 개, but 'I have a question for you' is 질문이 있어요. Note answering takes 에: 질문에 답하다, not 질문을 답하다."},sentence:{ko:"질문이라도 하나 해 보세요.",en:"Try asking at least one question."},target:"질문",options:["student","question","office worker"],note:"A small action that fits the minimum-option meaning of 라도."},{kind:"guess",word:{ko:"할인",romanization:"harin",en:"discount",pos:"noun",nuance:"할인(割引) is Sino-Korean — 割 'cut' + 引 'pull (down)' — literally 'cut and pull down', i.e. knock money off a price. The key contrast for learners is 할인 vs 세일: 할인 is the abstract act/amount of reducing a price on an item ('10% off', a discount), while 세일 (from English 'sale') names a store-wide selling event (백화점 세일 a department-store sale). So a 세일 contains many 할인s. Watch the voice carefully: from the price's point of view you say 할인이 되다/할인되다 ('it gets discounted'); from your point of view as buyer you say 할인을 받다 ('I receive a discount'); and to actively ask for one you say 할인해 주세요 ('please discount it for me'). The English-speaker pitfall is firing 할인해요 at a clerk hoping it means 'give me a discount' — bare 할인해요 just states 'someone discounts', so it lands as a flat description, not a request. Add 주세요/돼요 to make it work. Common partners: 할인되다, 할인받다, 할인 행사 (discount event), 할인 쿠폰."},sentence:{ko:"학생이라서 할인을 받을 수 있어요.",en:"Because I am a student, I can get a discount."},target:"할인",options:["student","discount","office worker"],note:"Shows why 학생 is not just an identity word but a real reason in daily life."},{kind:"payoff",line:{speaker:"지훈",ko:"네. 평일에는 바쁘니까 아침에만 조금 해요.",en:"Yes. Since weekdays are busy, I only do a little in the morning."},hl:"평일"}],canDo:"Set the scene or mark mild contrast on a noun (회사원인데 · 주말인데도)",id:"chapter-46-b3",chapterId:"chapter-46",index:2},{kind:"pattern",title:"문법 Grammar · N인데 / N인데도",cards:[{kind:"hunt",name:"N인데 / N인데도",sub:`"it's N, and… / even though it's N"`,lines:[{tokens:[{pre:"오늘은",mid:"",post:"",hit:!1},{pre:"주말",mid:"인데",post:"",hit:!0},{pre:"어디",mid:"",post:"",hit:!1},{pre:"갈까요?",mid:"",post:"",hit:!1}],ko:"오늘은 주말인데 어디 갈까요?",en:"It's the weekend today, so where shall we go?",romanization:"oneureun jumarinde eodi galkkayo?"},{tokens:[{pre:"주말",mid:"인데도",post:"",hit:!0},{pre:"회사에",mid:"",post:"",hit:!1},{pre:"가요.",mid:"",post:"",hit:!1}],ko:"주말인데도 회사에 가요.",en:"Even though it's the weekend, I go to work.",romanization:"jumarindedo hoesae gayo."}],rule:{name:"N인데 / N인데도",rows:[{when:"Noun (any ending) + background / lead-in",add:"N + 인데",ex:"학생인데… (I'm a student, so/and…)"},{when:`Noun + "even though it's N"`,add:"N + 인데도",ex:"주말인데도 (even though it's the weekend)"},{when:"Past noun background",add:"N + 이었는데 / 였는데",ex:"친구였는데 (we were friends, but…)"},{when:`Polite sentence-ender (soft "it's N, but…")`,add:"N + 인데요",ex:"여기 제 자리인데요. (Um, this is my seat…)"}]},more:{func:`Attaches to a noun to set the scene before the main clause: "It's the weekend, so…/and…" (인데), or to mark a mild contrast "even though it's N" (인데도). 인데 softens a statement and leads into the rest; 인데도 adds "despite that."`,keyPoint:{label:"인데 vs 인데도",body:`인데 is neutral: it just hands you a noun-fact as a lead-in, and context decides whether it means "so" or "but." 인데도 is clearly concessive — it always means "even though it's N," and the next clause is something surprising. Add 도 only when you want the firm "despite" feeling.`},pronunciation:"인데 sounds like [인데] with no change; 인데도 sounds like [인데도], the 도 stays plain."}}],canDo:"Set the scene or mark mild contrast on a noun (회사원인데 · 주말인데도)",id:"chapter-46-b4",chapterId:"chapter-46",index:3},{kind:"pattern",title:"문법 Grammar · N이라서 / 라서",cards:[{kind:"hunt",name:"N이라서 / 라서",sub:'"because it is N"',lines:[{tokens:[{pre:"오늘은",mid:"",post:"",hit:!1},{pre:"주말",mid:"이라서",post:"",hit:!0},{pre:"가게가",mid:"",post:"",hit:!1},{pre:"쉬어요.",mid:"",post:"",hit:!1}],ko:"오늘은 주말이라서 가게가 쉬어요.",en:"Because it's the weekend today, the shop is closed.",romanization:"oneureun jumariraseo gagega swieoyo."},{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"초보",mid:"라서",post:"",hit:!0},{pre:"천천히",mid:"",post:"",hit:!1},{pre:"할게요.",mid:"",post:"",hit:!1}],ko:"저는 초보라서 천천히 할게요.",en:"Because I'm a beginner, I'll go slowly.",romanization:"jeoneun chobolaseo cheoncheonhi halgeyo."}],rule:{name:"N이라서 / 라서",rows:[{when:"Noun ends in a consonant",add:"N + 이라서",ex:"학생이라서 (because I'm a student)"},{when:"Noun ends in a vowel",add:"N + 라서",ex:"친구라서 (because we're friends)"},{when:"More formal / written-sounding reason",add:"N + 이어서 / 여서",ex:"주말이어서 (because it's the weekend)"},{when:"Reason for a noun negative",add:"N이/가 아니라서",ex:"가족이 아니라서 (because I'm not family)"}]},more:{func:`Gives a reason that is a noun fact: "Because it's the weekend, the shop is closed," "Because I'm a beginner, it's hard." It is the 이다 version of the reason ending -아서/어서.`,keyPoint:{label:"이라서 vs verb -아서/어서",body:`For verbs and adjectives you say -아서/어서 (먹어서, 좋아서). For nouns you must run the reason through 이다 → 이라서/라서. So "because it's a student" is 학생이라서, never 학생어서. Reach for the noun form whenever the reason is a noun.`},pronunciation:"학생이라서 sounds like [학쌩이라서]. The [쌩] is just how 학생 is always said — the ㄱ받침 of 학 tenses the 생; 이라서 itself adds no new tensing."}},{kind:"drill",prompt:"Because it's a weekday, there's nobody around.",sentence:"평일___ 사람이 없어요.",options:[{text:"이라서",ok:!0},{text:"라서",ok:!1}],explanation:"평일 (consonant-final) + 이라서 gives the reason."}],canDo:"Give a noun-based reason (주말이라서 · 주말이니까)",id:"chapter-46-b5",chapterId:"chapter-46",index:4},{kind:"pattern",title:"문법 Grammar · N이니까 / 니까",cards:[{kind:"hunt",name:"N이니까 / 니까",sub:'"since it is N, so…"',lines:[{tokens:[{pre:"오늘은",mid:"",post:"",hit:!1},{pre:"주말",mid:"이니까",post:"",hit:!0},{pre:"같이",mid:"",post:"",hit:!1},{pre:"공부해요.",mid:"",post:"",hit:!1}],ko:"오늘은 주말이니까 같이 공부해요.",en:"Since it's the weekend today, let's study together.",romanization:"oneureun jumarinikka gachi gongbuhaeyo."},{tokens:[{pre:"우리는",mid:"",post:"",hit:!1},{pre:"친구",mid:"니까",post:"",hit:!0},{pre:"괜찮아요.",mid:"",post:"",hit:!1}],ko:"우리는 친구니까 괜찮아요.",en:"Since we're friends, it's okay.",romanization:"urineun chingunikka gwaenchanayo."}],rule:{name:"N이니까 / 니까",rows:[{when:"Noun ends in a consonant",add:"N + 이니까",ex:"주말이니까 (since it's the weekend)"},{when:"Noun ends in a vowel",add:"N + 니까",ex:"친구니까 (since we're friends)"},{when:"Leading a suggestion / command",add:"N이니까 + ~해요/하세요",ex:"주말이니까 같이 공부해요 (it's the weekend, so let's study together)"},{when:"Noun negative reason",add:"N이/가 아니니까",ex:"애기가 아니니까 (since you're not a baby)"}]},more:{func:`Gives a reason with a "since you know this, therefore let's…" feel — strong for backing up a command, suggestion, or decision: "Since it's the weekend, let's study," "Since it's my birthday, I'll treat you." It is the 이다 version of -(으)니까.`,keyPoint:{label:"이니까 vs 이라서",body:`Both mean "because it's N," but 이니까 is the one you use before commands and suggestions (조용히 하세요, 같이 공부해요) and when the reason is shared or obvious. 이라서 is more about plain cause and sounds off before a command. Rule of thumb: order or invite → 이니까; just explain → 이라서.`},pronunciation:"주말이니까 sounds like [주마리니까]; 까 is written with ㄲ, so it is always tense."}},{kind:"drill",prompt:"Since it's my birthday today, I'll treat you.",sentence:"오늘은 제 생일___ 제가 살게요.",options:[{text:"이니까",ok:!0},{text:"니까",ok:!1}],explanation:"이니까 supports the speaker's decision (제가 살게요)."}],canDo:"Offer a fallback option with N이라도/라도 (커피라도 마셔요)",id:"chapter-46-b6",chapterId:"chapter-46",index:5},{kind:"pattern",title:"문법 Grammar · N이라도 / 라도",cards:[{kind:"hunt",name:"N이라도 / 라도",sub:'"even just an N / at least N"',lines:[{tokens:[{pre:"주말이니까",mid:"",post:"",hit:!1},{pre:"한",mid:"",post:"",hit:!1},{pre:"시간",mid:"이라도",post:"",hit:!0},{pre:"같이",mid:"",post:"",hit:!1},{pre:"공부해요.",mid:"",post:"",hit:!1}],ko:"주말이니까 한 시간이라도 같이 공부해요.",en:"Since it's the weekend, let's study together even if just for one hour.",romanization:"jumarinikka han siganirado gachi gongbuhaeyo."},{tokens:[{pre:"바쁘면",mid:"",post:"",hit:!1},{pre:"커피",mid:"라도",post:"",hit:!0},{pre:"한잔해요.",mid:"",post:"",hit:!1}],ko:"바쁘면 커피라도 한잔해요.",en:"If you're busy, let's at least grab a coffee.",romanization:"bappeumyeon keopirado hanjanhaeyo."}],rule:{name:"N이라도 / 라도",rows:[{when:"Noun ends in a consonant",add:"N + 이라도",ex:"한 시간이라도 (even just one hour)"},{when:"Noun ends in a vowel",add:"N + 라도",ex:"커피라도 (coffee, at least)"},{when:"Offering a fallback choice",add:"N이라도 + 할까요? / 드세요",ex:"물이라도 드세요 (at least have some water)"},{when:'"even on/at N" (time noun)',add:"시간 noun + 이라도/라도",ex:"주말이라도 (even on the weekend, at least)"}]},more:{func:`Marks a noun as a not-ideal-but-acceptable fallback: "Let's study even just one hour," "Have at least some water." It says "this isn't the best option, but it'll do." It is the 이다 form behind the 라도 fallback marker.`,keyPoint:{label:'라도 = "not the best, but okay"',body:"이라도/라도 picks a noun that isn't your first choice but is good enough: 한 시간이라도 (even just one hour), 커피라도 (at least a coffee). Use 이라도 after a consonant and 라도 after a vowel — the same sound split you see in 이라서/라서 and 이니까/니까."},pronunciation:"한 시간이라도 sounds like [한 시가니라도]; 커피라도 sounds like [커피라도], no special change."}},{kind:"drill",prompt:"If you're hungry, at least have some bread.",sentence:"배고프면 빵___ 드세요.",options:[{text:"이라도",ok:!0},{text:"라도",ok:!1}],explanation:"빵 (consonant-final) + 이라도 offers a fallback food."}],canDo:"Say what something was in the past (학생이었어요 · 주말이었어요)",id:"chapter-46-b7",chapterId:"chapter-46",index:6},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two learners are scheduling study time while explaining role and time with 이다 forms.",lines:[{speaker:"민서",ko:"작년에는 학생이었어요?",en:"Were you a student last year?",romanization:"jangnyeoneneun haksaengieosseoyo?"},{speaker:"지훈",ko:"네, 지금은 회사원인데도 계속 공부해요.",en:"Yes, even though I am an office worker now, I keep studying.",romanization:"ne, jigeumeun hoesawonindedo gyesok gongbuhaeyo."},{speaker:"민서",ko:"회사원이라서 한국어가 더 필요해요?",en:"Because you are an office worker, do you need Korean more?",romanization:"hoesawoniraseo hangugeoga deo piryohaeyo?"},{speaker:"지훈",ko:"네. 평일에는 바쁘니까 아침에만 조금 해요.",en:"Yes. Since weekdays are busy, I only do a little in the morning.",romanization:"ne. pyeongireneun bappeunikka achimenman jogeum haeyo."},{speaker:"민서",ko:"그럼 주말이니까 한 시간이라도 같이 공부해요.",en:"Then since it is the weekend, let's study together even if just for one hour.",romanization:"geureom jumarinikka han siganirado gachi gongbuhaeyo."}]},{kind:"order",prompt:"Build: 'Since it is the weekend, let's meet in the morning.'",tokens:["주말이니까","아침에 만나요"],correct:"주말이니까 아침에 만나요",explanation:"-니까 gives a reason that supports the next decision. 주말이니까 sounds like “since it is the weekend.”"}],canDo:"Say what something was in the past (학생이었어요 · 주말이었어요)",id:"chapter-46-b8",chapterId:"chapter-46",index:7},{kind:"reading",title:"읽기 Reading · 회사원인데도 계속 공부해요",cards:[{kind:"read",title:"회사원인데도 계속 공부해요",chunks:["지훈은 작년에는 학생이었어요. 올해는 회사원인데도 한국어를 계속 공부해요. 회사원이라서 회의와 이메일에서 한국어가 더 필요해요.","평일은 바쁘니까 아침에만 조금 공부하고, 주말이니까 한 시간이라도 친구와 같이 공부해요. 시간이 많지 않아도 역할 명사와 시간 명사를 잘 고르면 이다 표현을 자연스럽게 쓸 수 있어요."],translation:"Jihun was a student last year. This year, even though he is an office worker, he keeps studying Korean. Because he is an office worker, he needs Korean more in meetings and email. Weekdays are busy, so he studies only a little in the morning, and since it is the weekend, he studies with a friend even if just for one hour. Even without much time, choosing role nouns and time nouns well makes the 이다 forms feel natural.",qas:[{q:"지훈은 작년에 무엇이었어요?",a:"학생이었어요."},{q:"지훈은 왜 한국어가 더 필요해요?",a:"회사원이라서 회의와 이메일에서 한국어가 더 필요해요."},{q:"주말에는 얼마나 공부해요?",a:"한 시간이라도 친구와 같이 공부해요."}]}],canDo:"Set the scene or mark mild contrast on a noun (회사원인데 · 주말인데도)",id:"chapter-46-b9",chapterId:"chapter-46",index:8},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence correctly says 'I was a student last year'?",sentence:null,options:[{text:"작년에는 학생이었어요.",ok:!0},{text:"작년에는 학생했어요.",ok:!1},{text:"작년에는 학생였어요.",ok:!1}],explanation:"학생 ends in a consonant, so the past copula is 학생이었어요."},{kind:"drill",prompt:"Choose the soft explanation: 'Because I am an office worker, I need Korean.'",sentence:null,options:[{text:"회사원이라서 한국어가 필요해요.",ok:!0},{text:"회사원이라도 한국어가 필요해요.",ok:!1},{text:"회사원인데도 한국어가 필요해요.",ok:!1}],explanation:"이라서 gives a cause based on what someone is. 라도 means fallback, and 인데도 means contrast."},{kind:"drill",prompt:"Which sentence gives a reason that leads straight into a study plan?",sentence:null,options:[{text:"주말이니까 한 시간이라도 공부해요.",ok:!0},{text:"주말이라도 한 시간이에요.",ok:!1},{text:"주말이었어요 한 시간 공부해요.",ok:!1}],explanation:"주말이니까 gives the reason, and 한 시간이라도 gives the minimum study amount."},{kind:"drill",prompt:"Which sentence marks a minimum acceptable option?",sentence:null,options:[{text:"한 시간이라도 공부해요.",ok:!0},{text:"한 시간만 공부해요.",ok:!1},{text:"한 시간이라서 공부해요.",ok:!1}],explanation:"이라도 means 'even if only / at least'. 만 means only, and 이라서 gives a cause."},{kind:"drill",prompt:"작년___ 학생이었어요. (Last year, I was a student.)",sentence:null,options:[{text:"에",ok:!0},{text:"에서",ok:!1},{text:"를",ok:!1}],explanation:"작년에 marks the time when the identity was true. 에서 would mark an action place, not a year."},{kind:"order",prompt:"Build: 'Since it is the weekend, let's meet in the morning.'",tokens:["주말이니까","아침에 만나요"],correct:"주말이니까 아침에 만나요",explanation:"-니까 gives a reason that supports the next decision. 주말이니까 sounds like “since it is the weekend.”"},{kind:"drill",prompt:"Which sentence gives a soft noun background?",sentence:null,options:[{text:"저는 회사원인데 한국어가 필요해요.",ok:!0},{text:"저는 회사원이라도 한국어가 필요해요.",ok:!1},{text:"저는 회사원뿐 한국어가 필요해요.",ok:!1}],explanation:"N인데 gives background before the main point. 이라도 and 뿐 do not fit this explanation."}],canDo:"Give a noun-based reason (주말이라서 · 주말이니까)",id:"chapter-46-b10",chapterId:"chapter-46",index:9}]},{id:"chapter-47",number:47,title:"저희 가족은 ~ 명이에요 · 형 / 오빠 / 누나 / 언니",goal:"Describe family size with 저희 가족은 ~ 명이에요.",biteCount:10,bites:[{kind:"words",title:"단어 Words 1 · 저희~",cards:[{kind:"guess",word:{ko:"저희",romanization:"jeohui",en:"our / my (humble, polite)",pos:"pronoun",nuance:"저희 is not colder than 우리; it is socially careful. Use it when the listener is outside your group and the situation is polite. Use 우리 with close friends, family, and many natural everyday phrases like 우리 엄마."},sentence:{ko:"저희 가족은 네 명이에요.",en:"There are four people in my family."},target:"저희",options:["our / my (humble, polite)","family","counter for people"],note:"Core word for polite family introductions."},{kind:"guess",word:{ko:"가족",romanization:"gajok",en:"family",pos:"noun",nuance:"가족 is the Sino-Korean word 家族 ('house' 家 + 'clan/group' 族), so it names the whole family unit as a collective, never a single relative — for one member you must say 가족 한 명 or name the relationship (형, 누나). The near-synonym 식구 also means family but literally means 食口 'mouths to feed', stressing the people who live and eat under one roof, so 식구 feels warmer and more domestic ('우리 식구 다섯이에요') while 가족 is the neutral standard term that also covers relatives living apart. Register is neutral and safe in any setting. The big English-speaker trap is two-fold: 'big/small family' is 가족이 많다/적다 (many/few), never 가족이 크다 (that sounds like physically large bodies); and Koreans say 우리 가족 ('our family') where English forces 'my family', so the 우리 is idiomatic, not a mistake."},sentence:{ko:"가족이 몇 명이에요?",en:"How many people are in your family?"},target:"가족",options:["parents","father","family"],note:"Pairs with 명 for family size."},{kind:"guess",word:{ko:"명",romanization:"myeong",en:"counter for people",pos:"counter",nuance:"명 is the neutral people counter. In everyday family counts use native-number forms such as 한 명, 두 명, 세 명, and 네 명; use 분 when respectfully counting other people in an appropriate context."},sentence:{ko:"저희 가족은 다섯 명이에요.",en:"There are five people in my family."},target:"명",options:["our / my (humble, polite)","counter for people","family"],note:"People take 명, not 개."},{kind:"guess",word:{ko:"부모님",romanization:"bumonim",en:"parents",pos:"noun",nuance:"부모님 is Sino-Korean 父母 ('father' 父 + 'mother' 母) plus the honorific suffix 님, so the respect is baked into the word itself and it is the everyday polite default — there is no need to add anything to make it courteous. The bare root 부모 exists but is abstract and institutional ('부모의 역할' the role of parents, '부모 교육' parenting education); aimed at a real person it sounds cold, so for your own or anyone's parents you say 부모님. Because 님 marks the referent as worthy of respect, every verb around it must climb to its honorific tier: 있다→계시다, 주다→드리다, 집→댁, 에게→께, and the topic/subject can even take 께서. The classic English-speaker pitfall is pairing 부모님 with plain verbs ('부모님이 있어요', '부모님한테 줬어요'); grammatically the words exist, but to a Korean ear it clashes like saying 'Her Majesty ate fast' — you must use 계세요 and 드렸어요/께."},sentence:{ko:"부모님께서도 결혼식에 오세요.",en:"My parents are coming to the wedding too."},target:"부모님",options:["family","parents","father"],note:"Respected family noun plus 께서."},{kind:"guess",word:{ko:"아버지",romanization:"abeoji",en:"father",pos:"noun",nuance:"아버지 is the respectful, neutral word for 'father,' used in polite conversation, in writing, and whenever you speak about your dad to others. Its near-synonym 아빠 is the warm home word ('dad/daddy'): children and many adults call him 아빠 to his face, while 아버지 sounds more grown-up, dignified, or formal — the gap is exactly the English 'dad' vs 'father.' One step higher is 아버님, reserved for someone else's father or your father-in-law. Because a father is an elder, 아버지 naturally pulls honorific machinery: the subject marker 께서, the dative 께, and -(으)시- verb endings (읽으세요, 주무세요). Two English-speaker pitfalls: the copula is 아버지예요 (vowel-final 지 → 예요, not '아버지이에요'); and possession uses 우리 아버지 ('our father'), since 내 아버지 sounds oddly cold to Korean ears."},sentence:{ko:"아버지께서도 오세요.",en:"My father is coming too."},target:"아버지",options:["father","family","parents"],note:"Use 아버지 in polite introductions."},{kind:"guess",word:{ko:"어머니",romanization:"eomeoni",en:"mother",pos:"noun",nuance:"어머니 is the respectful, neutral word for 'mother,' used in polite speech, in writing, and when talking about your mom to others. Its near-synonym 엄마 is the affectionate home word ('mom/mommy') that people usually call her directly at home, while 어머니 carries more formality and respect — the same distance as English 'mom' vs 'mother.' The higher honorific 어머님 is for someone else's mother or your mother-in-law. As an elder, 어머니 routinely takes honorific particles and endings: 께서 for the subject, 께 for 'to,' and -(으)시- verbs (하세요, 주무세요). Watch two English-speaker traps: the copula contracts to 어머니예요 after the vowel 니 (not '어머니이에요'); and you give things to her with the honorific 어머니께 ... 드리다, not the plain 어머니한테 ... 줘요. Possession is likewise 우리 어머니, since 내 어머니 sounds unnaturally distant."},sentence:{ko:"어머니께서 오셨어요.",en:"My mother came."},target:"어머니",options:["mother","family","parents"],note:"Use 어머니 in polite introductions."},{kind:"payoff",line:{speaker:"민서",ko:"가족이 몇 명이에요?",en:"How many people are in your family?"},hl:"가족"}],canDo:"Say how big my family is politely (저희 가족은 ~ 명이에요)",id:"chapter-47-b1",chapterId:"chapter-47",index:0},{kind:"pattern",title:"문법 Grammar · 저희 가족은 ~ 명이에요",cards:[{kind:"teach",name:"저희 가족은 ~ 명이에요",sub:"Saying How Many People Are in Your Family",rows:[{when:"Counting people, use a native-Korean number + 명",add:"한/두/세/네/다섯… + 명",ex:"네 명 (four people), 다섯 명 (five people)"},{when:"Numbers 1–4 change shape right before a counter",add:"하나→한, 둘→두, 셋→세, 넷→네",ex:"두 명, 세 명, 네 명 (NOT 둘 명 / 셋 명)"},{when:"Closing the sentence after 명",add:"명 + 이에요 (명 ends in a consonant, so 이에요)",ex:"저희 가족은 네 명이에요."}],examples:[{ko:"저희 가족은 네 명이에요.",en:"There are four people in my family.",romanization:"jeohui gajogeun ne myeong-ieyo.",note:'저희 (humble "our") + 명 is the standard polite way to give family size; the native number 네 is used before 명.'},{ko:"저희 가족은 다섯 명이에요. 부모님, 형, 누나, 그리고 저요.",en:"There are five people in my family: my parents, older brother, older sister, and me.",romanization:"jeohui gajogeun daseot myeong-ieyo. bumonim, hyeong, nuna, geurigo jeoyo.",note:'Shows how to break the number down into members; 저요 ("and me") naturally closes the list.'}],more:{func:'To tell someone how big your family is, politely. 저희 is the humble form of 우리 ("our"), used to be modest in front of a listener, and 명 is the counter for people. You name the group (저희 가족은 = "my family"), then give the count with a native-Korean number + 명 + 이에요.',keyPoint:{label:"명 vs. 분 for counting people",body:"명 is the neutral people-counter and is correct for your own family: 저희 가족은 네 명이에요. When you respectfully count other people (elders, guests), use 분 instead: 손님 세 분 (three guests). You always count your OWN family with 명, never 분, because you don't elevate your own in-group when speaking to others."},pronunciation:"가족은 links across the 받침: 가족 + 은 → [가조근]. The same happens in 가족이 → [가조기]. The final ㄱ of 가족 slides onto the following vowel."}}],canDo:"Say how big my family is politely (저희 가족은 ~ 명이에요)",id:"chapter-47-b2",chapterId:"chapter-47",index:1},{kind:"words",title:"단어 Words 2 · 형~",cards:[{kind:"guess",word:{ko:"형",romanization:"hyeong",en:"older brother (male speaker)",pos:"noun",nuance:"형 (Sino-Korean 兄 'elder brother') is the word a MALE uses for an older brother, and crucially it is also a warm address term a younger man uses for any slightly-older male he is close to — an older friend, schoolmate, or colleague — so '민수 형' can mean 'Minsu, my big-brother-figure', not a blood relative. The matched set is gendered by speaker: a female says 오빠 for the same older-brother relationship, while 누나/언니 cover older sisters — so the single word leaks the speaker's gender, something English's flat 'older brother' never does. Register is casual-but-respectful: 형 is itself an honorific address (you call him 형, never his bare name), and you speak up to him. The dominant English-speaker pitfall is gender: a woman must never call her older brother 형 — that is 오빠 — and second, don't assume 형 always means kin; in daily life it is most often the affectionate title for an older male friend."},sentence:{ko:"저는 형이 한 명 있어요.",en:"I have one older brother."},target:"형",options:["family","parents","older brother (male speaker)"],note:"Used by a male speaker."},{kind:"guess",word:{ko:"오빠",romanization:"oppa",en:"older brother (female speaker)",pos:"noun",nuance:"오빠 is the word a FEMALE uses for an older brother, and it is the most socially loaded kinship term in Korean: a woman also calls a close older male friend, a senior, or especially a boyfriend 오빠, so '오빠' on its own can mean 'my big brother', 'my guy friend', or 'babe' depending on context — hence 친오빠 exists to specify the actual sibling. Its gendered counterpart is 형, used by a MALE for the same older-brother relationship, so 오빠 vs 형 splits by speaker, and the word instantly reveals the speaker is a woman. Register is casual and affectionate, used with -요 forms, and 오빠 is itself the address term (never his bare name). The major English-speaker pitfall is gender — a man must say 형, never 오빠 — and the cultural trap: because 오빠 also means 'boyfriend' in romantic use, calling a male friend 오빠 can imply flirtation, so learners should know the connotation before using it freely."},sentence:{ko:"저는 오빠가 한 명 있어요.",en:"I have one older brother."},target:"오빠",options:["family","parents","older brother (female speaker)"],note:"Used by a female speaker."},{kind:"guess",word:{ko:"누나",romanization:"nuna",en:"older sister (male speaker)",pos:"noun",nuance:"누나 is the word a MALE uses for an older sister, and like 형 it doubles as a warm address title a younger man uses for any older woman he is close to — an older female friend, senior student, or, famously, a beloved older woman ('누나' in K-pop). Its gendered partner is 언니, which a FEMALE uses for the very same older-sister relationship, so 누나 vs 언니 is split purely by who is speaking, and the word betrays the speaker's gender in a way English 'older sister' cannot. Register is casual but deferential: 누나 is itself a respectful address (you call her 누나, not her name) and you speak up to her with -요 forms. A very natural collocation is 도와주다 'help (as a favor)'. The headline English-speaker pitfall is gender: a man must say 누나 and a woman 언니 for an older sister — swapping them is an immediate giveaway — and remember 누나 is also how a younger man fondly addresses an older woman, not only a sibling."},sentence:{ko:"저는 누나가 한 명 있어요.",en:"I have one older sister."},target:"누나",options:["family","parents","older sister (male speaker)"],note:"Used by a male speaker."},{kind:"guess",word:{ko:"언니",romanization:"eonni",en:"older sister (female speaker)",pos:"noun",nuance:"언니 is the word a FEMALE uses for an older sister, and it extends warmly to any close older woman — an older female friend, a senior at school or work — and is also the friendly way younger women address a female shopkeeper or restaurant server ('언니, 여기요!'), so it ranges from blood sister to polite stranger. Its gendered counterpart is 누나, used by a MALE for the same older-sister bond, so 언니 vs 누나 splits purely by the speaker's gender, and the word reveals that the speaker is a woman — a distinction English 'older sister' simply lacks. Register is casual and affectionate, used with -요 endings, and 언니 itself serves as the address (you say 언니, not her name). The chief English-speaker pitfall is gender: a man must say 누나, never 언니, for an older sister; and don't be surprised to hear women call a saleswoman 언니 — it is friendly social lubricant, not a claim of kinship."},sentence:{ko:"저는 언니가 한 명 있어요.",en:"I have one older sister."},target:"언니",options:["family","older sister (female speaker)","parents"],note:"Used by a female speaker."},{kind:"guess",word:{ko:"동생",romanization:"dongsaeng",en:"younger sibling",pos:"noun",nuance:"동생 (Sino-Korean 同生 'born of the same' parents) means a younger sibling and, unlike the older-sibling words, is NOT split by speaker gender and does NOT itself reveal whether the sibling is male or female — to specify you prepend 남 (男) for 남동생 'younger brother' or 여 (女) for 여동생 'younger sister'. It also extends to any younger person you are close to (a junior at work or school), mirroring how 형/오빠/누나/언니 work upward; the system is asymmetric — elders get gendered, speaker-dependent titles, while juniors share the one neutral 동생. Register: unlike the older-sibling titles, 동생 is NOT used as a direct address — you call a younger sibling by name, and 동생 is only how you refer to them. The key English-speaker pitfall is assuming 동생 means 'younger brother'; it is sex-neutral, so without 남/여 it could be either, and you should never address someone as '동생' the way you'd say '형' — call them by name instead."},sentence:{ko:"저는 동생이 한 명 있어요.",en:"I have one younger sibling."},target:"동생",options:["family","parents","younger sibling"],note:"Works regardless of the speaker's gender."},{kind:"guess",word:{ko:"할아버지",romanization:"harabeoji",en:"grandfather",pos:"noun",nuance:"할아버지 is your grandfather on either side, and casual speech uses it for both the father's and the mother's father; 외할아버지 (maternal) or 친할아버지 (paternal) pin down the side when it matters. It is 할- (a prefix for the generation above) + 아버지 'father', and like 할머니 it can respectfully address any elderly man you know. The spelling trips beginners because of the liaison: it is one solid word, 할아버지, written together — never 할 아버지 — and the ㄹ slides onto the next syllable so it sounds like 하라버지. The deeper pitfall for English speakers is honorifics: a grandfather outranks you, so the verb climbs to the honorific level (읽으세요, 주무세요, 진지 드세요), and 밥 politely becomes 진지. Say 우리 할아버지, mirroring 우리 할머니, rather than the textbook-literal 제 할아버지."},sentence:{ko:"할아버지께서 오세요.",en:"My grandfather is coming."},target:"할아버지",options:["grandfather","family","parents"],note:"Good noun for practicing 께서."},{kind:"payoff",line:{speaker:"지훈",ko:"저희 가족은 다섯 명이에요. 부모님하고 형, 동생이 있어요.",en:"There are five people in my family. I have my parents, an older brother, and a younger sibling."},hl:"동생"}],canDo:"Pick the right older-sibling word for my own gender (형 · 오빠 · 누나 · 언니)",id:"chapter-47-b3",chapterId:"chapter-47",index:2},{kind:"pattern",title:"문법 Grammar · 형 / 오빠 / 누나 / 언니",cards:[{kind:"teach",name:"형 / 오빠 / 누나 / 언니",sub:"Older-Sibling Words That Depend on YOUR Gender",rows:[{when:"A male speaker's older brother",add:"형",ex:"(남자가) 우리 형 (my older brother)"},{when:"A female speaker's older brother",add:"오빠",ex:"(여자가) 우리 오빠 (my older brother)"},{when:"A male speaker's older sister",add:"누나",ex:"(남자가) 우리 누나 (my older sister)"},{when:"A female speaker's older sister",add:"언니",ex:"(여자가) 우리 언니 (my older sister)"}],examples:[{ko:"(남자) 우리 형은 회사에 다녀요.",en:"(male speaker) My older brother works at a company.",romanization:"(namja) uri hyeong-eun hoesa-e danyeoyo.",note:"A boy calls his older brother 형; 오빠 would be wrong here for a male speaker."},{ko:"(여자) 우리 오빠는 키가 커요.",en:"(female speaker) My older brother is tall.",romanization:"(yeoja) uri oppa-neun kiga keoyo.",note:"A girl calls her older brother 오빠 — same person, different word from a boy's 형."}],more:{func:'To name an older brother or older sister. Korean has no single word for "older brother" or "older sister" — the word you pick depends on whether YOU (the speaker) are male or female. A man and a woman use completely different words for the very same person.',keyPoint:{label:"The word encodes the SPEAKER's gender, not the sibling's",body:"Picture a 2×2 grid. Older brother: 형 (said by a male) vs. 오빠 (said by a female). Older sister: 누나 (said by a male) vs. 언니 (said by a female). The same older brother is 형 to his younger brother and 오빠 to his younger sister at the same time. Younger siblings have no gendered split — they are just 동생 (남동생 = younger brother, 여동생 = younger sister)."},pronunciation:"오빠's ㅃ is a tense, slightly held stop. 언니 → [언니] keeps both ㄴ sounds clear. 형은 → [형은], with the ㅇ (ng) carrying over softly; no tensing here."}}],canDo:"Pick the right older-sibling word for my own gender (형 · 오빠 · 누나 · 언니)",id:"chapter-47-b4",chapterId:"chapter-47",index:3},{kind:"words",title:"단어 Words 3 · 할머니~",cards:[{kind:"guess",word:{ko:"할머니",romanization:"halmeoni",en:"grandmother",pos:"noun",nuance:"할머니 is your grandmother on either side, and in plain conversation Koreans use it for both the father's and the mother's mother; add 외- (외할머니) or 친- (친할머니) only when you must mark the side. It is built from 할- (an old prefix meaning a generation above) + 어머니 'mother', and it doubles as a warm, respectful way to address ANY elderly woman you feel close to, much like English 'grandma' for a kindly neighbor. The big trap for English speakers is grammar of respect, not vocabulary: a grandmother is a high-status elder, so the verb itself must be honorific — say 할머니는 사세요 / 주무세요 / 드세요, never the flat 살아요 / 자요 / 먹어요. Pair it with 우리 할머니 ('our grandmother'), not 제 할머니, because Korean treats family as shared. Compared with the polite stranger-address 아주머니/아주머님 (a middle-aged woman), 할머니 implies real old age, so misjudging the age can sting."},sentence:{ko:"할머니께 안부를 전해 주세요.",en:"Please send my regards to your grandmother."},target:"할머니",options:["family","parents","grandmother"],note:"께 marks a respected receiver; 께서 marks a respected subject."},{kind:"guess",word:{ko:"결혼식",romanization:"gyeolhonsik",en:"wedding ceremony",pos:"noun",nuance:"결혼식 is the wedding CEREMONY (식 = 式 'ceremony/rite'), as opposed to 결혼 (結婚, 'tie + marry'), which is the marriage or the act of getting married — so 결혼했어요 means 'I got married,' while 결혼식에 갔어요 means 'I attended a wedding.' That 결혼/결혼식 split is the #1 trap for English speakers, since English 'wedding' blurs both. Compared with the everyday synonym 예식 (禮式, 'ceremony of courtesy'), 결혼식 is the plain default and 예식 sounds slightly more formal/venue-flavored (hence 예식장). The ceremony itself is famously short (30–60 minutes); the socially weighty part is the buffet meal afterward, which your cash gift 축의금 helps cover. Habitual collocations: 결혼식에 가다/참석하다, 결혼식을 올리다, 결혼식장. Take 에 for attendance — 결혼식을 가다 is a common particle error."},sentence:{ko:"부모님께서도 결혼식에 오세요.",en:"My parents are coming to the wedding too."},target:"결혼식",options:["family","wedding ceremony","parents"],note:"A natural event where family members are introduced politely."},{kind:"guess",word:{ko:"오다",romanization:"oda",en:"to come",pos:"verb",nuance:"오다 is from the speaker’s point of view. If someone moves toward you or your place, 오다 is usually right."},sentence:{ko:"어머니께서 오셨어요.",en:"My mother came."},target:"오셨",options:["to come","to call by phone","our / my (humble, polite)"],note:"오다 becomes 오세요/오셨어요 when honoring the subject."},{kind:"guess",word:{ko:"전화하다",romanization:"jeonhwahada",en:"to call by phone",pos:"verb",nuance:"전화하다 is noun + 하다, so 전화 안 해요 is a natural short negative."},sentence:{ko:"부모님께 자주 전화해요.",en:"I often call my parents."},target:"전화해",options:["to come","our / my (humble, polite)","to call by phone"],note:"Useful family-contact verb; 전화드려요 is the more respectful version."},{kind:"payoff",line:{speaker:"민서",ko:"부모님께서도 결혼식에 오세요?",en:"Are your parents coming to the wedding too?"},hl:"결혼식"}],canDo:"Refer to my parents respectfully (부모님 · 아버지 · 어머니)",id:"chapter-47-b5",chapterId:"chapter-47",index:4},{kind:"pattern",title:"문법 Grammar · 부모님 / 아버지 / 어머니",cards:[{kind:"teach",name:"부모님 / 아버지 / 어머니",sub:"Respectful Words for Parents",rows:[{when:"Both parents together, respectfully",add:"부모 + 님 (honorific suffix)",ex:"부모님 (one's parents)"},{when:"Father — respectful vs. casual",add:"아버지 (respectful) / 아빠 (casual)",ex:"저희 아버지 vs. 우리 아빠"},{when:"Mother — respectful vs. casual",add:"어머니 (respectful) / 엄마 (casual)",ex:"저희 어머니 vs. 우리 엄마"},{when:"Someone else's parents (extra polite)",add:"아버님 / 어머님 (add ~님)",ex:"친구 어머님 (a friend's mother)"}],examples:[{ko:"저희 부모님은 부산에 사세요.",en:"My parents live in Busan.",romanization:"jeohui bumonim-eun busan-e saseyo.",note:"부모님 + the honorific verb 사세요 (from 살다) elevate the parents — the natural pairing for elders."},{ko:"저희 아버지는 선생님이세요.",en:"My father is a teacher.",romanization:"jeohui abeoji-neun seonsaengnim-iseyo.",note:"아버지 (not 아빠) is the respectful choice when speaking to people outside the family; ~세요 honors him."}],more:{func:'To talk about your parents respectfully. These are the polite nouns for family elders. 부모님 = "parents" (with the honorific suffix ~님), 아버지 = "father," 어머니 = "mother." They contrast with the casual 아빠 (dad) and 엄마 (mom) that children use at home.',keyPoint:{label:"아버지/어머니 (respectful) vs. 아빠/엄마 (casual)",body:'Use 아버지/어머니 when you describe your parents TO other people, in writing, or in any polite setting — they show respect. Use 아빠/엄마 to ADDRESS your own parents at home or among close family, like English "Dad/Mom" vs. "father/mother." 부모님 always carries ~님 and has no casual short form.'},pronunciation:"부모님은 links the 받침: 부모님 + 은 → [부모니믄], the ㅁ carrying onto 은. 선생님이세요 → [선생니미세요] in the same way."}}],canDo:"Refer to my parents respectfully (부모님 · 아버지 · 어머니)",id:"chapter-47-b6",chapterId:"chapter-47",index:5},{kind:"pattern",title:"문법 Grammar · N께서 V-(으)시-",cards:[{kind:"teach",name:"N께서 V-(으)시-",sub:"Honoring a Family Elder Who Does the Action",rows:[{when:"Marking an honored subject",add:"이/가 → 께서 (은/는 → 께서는)",ex:"아버지가 → 아버지께서"},{when:"Verb stem ends in a vowel + honorific",add:"stem + ~세요",ex:"가다 → 가세요, 오다 → 오세요"},{when:"Verb stem ends in a consonant + honorific",add:"stem + ~으세요",ex:"읽다 → 읽으세요, 앉다 → 앉으세요"},{when:"Special honorific verbs (must be memorized)",add:"있다→계시다, 먹다→드시다/잡수시다, 자다→주무시다",ex:"할머니께서 주무세요 (Grandma is sleeping)"}],examples:[{ko:"할아버지께서 신문을 읽으세요.",en:"My grandfather reads the newspaper.",romanization:"harabeoji-kkeseo sinmun-eul ilgeuseyo.",note:"할아버지께서 marks the honored subject; 읽다 (consonant stem) → 읽으세요 with the ~으세요 form."},{ko:"어머니께서 방에 계세요.",en:"My mother is in the room.",romanization:"eomeoni-kkeseo bang-e gyeseyo.",note:"있다 has the special honorific 계시다, not 있으세요 — use 계세요 for an elder's location/presence."}],more:{func:"To honor the person doing the action — usually a family elder like a parent or grandparent. Two pieces work together: 께서 replaces the subject marker 이/가 (or 은/는) to lift up the subject, and the verb takes the honorific infix ~(으)시~, which surfaces as ~세요/~으세요 in polite speech.",keyPoint:{label:"Honor the subject in the verb",body:"The verb ending ~(으)시~ is the core way to honor the person doing the action. The honorific subject marker 께서 often accompanies it in careful speech, while ordinary 이/가 can also appear with an honorific verb depending on context. You can be humble about yourself with 저희 while honoring an elder: 저희 어머니가 만드세요 and 저희 어머니께서 만드세요 are both possible."},pronunciation:"읽으세요 → [일그세요]: the ㄺ cluster splits, ㄱ moving onto the 으. 계세요 → [게세요] in casual speech (the ㅖ often flattens to ㅔ). 께서 keeps its tense ㄲ at the start."}}],canDo:"Honor a family elder who does the action (아버지께서 ~하세요)",id:"chapter-47-b7",chapterId:"chapter-47",index:6},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A learner introduces family and checks sibling terms before a friend's wedding.",lines:[{speaker:"민서",ko:"가족이 몇 명이에요?",en:"How many people are in your family?",romanization:"gajogi myeot myeongieyo?"},{speaker:"지훈",ko:"저희 가족은 다섯 명이에요. 부모님하고 형, 동생이 있어요.",en:"There are five people in my family. I have my parents, an older brother, and a younger sibling.",romanization:"jeohui gajogeun daseot myeongieyo. bumonimhago hyeong, dongsaengi isseoyo."},{speaker:"민서",ko:"형은 남자가 쓰는 말이죠?",en:"Hyeong is the word a male speaker uses, right?",romanization:"hyeongeun namjaga sseuneun marijyo?"},{speaker:"지훈",ko:"네. 여자가 부르면 오빠라고 해요. 누나와 언니도 달라요.",en:"Yes. If a female speaker says it, she says oppa. Nuna and eonni are different too.",romanization:"ne. yeojaga bureumyeon opparago haeyo. nuna-wa eonnido dallayo."},{speaker:"민서",ko:"부모님께서도 결혼식에 오세요?",en:"Are your parents coming to the wedding too?",romanization:"bumonimkkeseodo gyeolhonsige oseyo?"},{speaker:"지훈",ko:"네, 어머니께서 오시고 아버지께서도 오세요.",en:"Yes, my mother is coming, and my father is coming too.",romanization:"ne, eomeonikkeseo osigo abeojikkeseodo oseyo."}]},{kind:"order",prompt:"Build: 'My family has four people.'",tokens:["저희 가족은","네 명이에요"],correct:"저희 가족은 네 명이에요",explanation:"저희 가족은 politely sets the family as the topic. People are counted with 명, and four before a counter is 네."}],canDo:"Say how big my family is politely (저희 가족은 ~ 명이에요)",id:"chapter-47-b8",chapterId:"chapter-47",index:7},{kind:"reading",title:"읽기 Reading · 저희 가족은 다섯 명이에요",cards:[{kind:"read",title:"저희 가족은 다섯 명이에요",chunks:["지훈은 회사 동료에게 가족을 소개했어요. '저희 가족은 다섯 명이에요. 부모님하고 형, 동생이 있어요.'라고 말했어요. 지훈은 남자라서 자기보다 나이 많은 남자 형제를 형이라고 불러요.","여자가 같은 사람을 부르면 오빠가 돼요. 나이 많은 여자 형제도 남자가 말하면 누나, 여자가 말하면 언니예요. 친구 결혼식 이야기를 할 때는 '어머니께서 오시고 아버지께서도 오세요'라고 말했어요. 가족 이야기는 단어 선택과 높임 선택이 같이 가야 자연스러워요."],translation:"Jihun introduced his family to a coworker: 'There are five people in my family. I have my parents, an older brother, and a younger sibling.' Because Jihun is male, he calls an older male sibling hyeong. If a female speaker refers to the same person, the word becomes oppa. For an older female sibling, a male speaker says nuna and a female speaker says eonni. When talking about a friend's wedding, he says, 'My mother is coming, and my father is coming too' with honorific subject language. Family talk sounds natural when word choice and respect level work together.",qas:[{q:"지훈의 가족은 몇 명이에요?",a:"다섯 명이에요."},{q:"남자가 나이 많은 남자 형제를 부를 때 어떤 말을 써요?",a:"형이라고 해요."},{q:"지훈은 부모님에 대해 어떤 높임 표현을 썼어요?",a:"어머니께서 오시고 아버지께서도 오세요."}]}],canDo:"Pick the right older-sibling word for my own gender (형 · 오빠 · 누나 · 언니)",id:"chapter-47-b9",chapterId:"chapter-47",index:8},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence describes family size naturally?",sentence:null,options:[{text:"저희 가족은 네 명이에요.",ok:!0},{text:"저희 가족은 네 개예요.",ok:!1},{text:"저희 가족은 네 잔이에요.",ok:!1}],explanation:"명 counts people. 개 counts things, and 잔 counts cups or glasses."},{kind:"drill",prompt:"A male speaker is talking about his older brother. Which word fits?",sentence:null,options:[{text:"형",ok:!0},{text:"오빠",ok:!1},{text:"언니",ok:!1}],explanation:"A male speaker calls an older brother 형. A female speaker calls an older brother 오빠."},{kind:"drill",prompt:"A female speaker is talking about her older sister. Which word fits?",sentence:null,options:[{text:"언니",ok:!0},{text:"누나",ok:!1},{text:"형",ok:!1}],explanation:"A female speaker calls an older sister 언니. A male speaker calls an older sister 누나."},{kind:"drill",prompt:"Which sentence honors the mother as the subject?",sentence:null,options:[{text:"어머니께서 오셨어요.",ok:!0},{text:"어머니께 오셨어요.",ok:!1},{text:"어머니가 왔어요.",ok:!1}],explanation:"께서 marks the respected subject, and 오셨어요 is the honorific past of 오다."},{kind:"drill",prompt:"Which sentence uses 께 as a respected receiver, not a subject?",sentence:null,options:[{text:"할머니께 안부를 전해 주세요.",ok:!0},{text:"할머니께서 안부를 전해 주세요.",ok:!1},{text:"할머니가께 안부를 전해 주세요.",ok:!1}],explanation:"께 means to a respected person. 께서 means the respected person is the subject."},{kind:"drill",prompt:"어머니___ 오셨어요. (My mother came.)",sentence:null,options:[{text:"께서",ok:!0},{text:"께",ok:!1},{text:"를",ok:!1}],explanation:"어머니 is the respected subject, so use 께서. 께 marks a respected receiver instead."},{kind:"order",prompt:"Build: 'My family has four people.'",tokens:["저희 가족은","네 명이에요"],correct:"저희 가족은 네 명이에요",explanation:"저희 가족은 politely sets the family as the topic. People are counted with 명, and four before a counter is 네."},{kind:"drill",prompt:"A male speaker is talking about his older sister. Which word fits?",sentence:null,options:[{text:"누나",ok:!0},{text:"언니",ok:!1},{text:"오빠",ok:!1}],explanation:"Male speakers use 누나 for older sister. 언니 is from a female speaker’s point of view."}],canDo:"Refer to my parents respectfully (부모님 · 아버지 · 어머니)",id:"chapter-47-b10",chapterId:"chapter-47",index:9}]},{id:"chapter-48",number:48,title:"Symptom frame · V-아/어야 해요",goal:"Describe symptoms with body part or symptom + 이/가 + 아프다/나다.",biteCount:13,bites:[{kind:"words",title:"단어 Words 1 · 증상~",cards:[{kind:"guess",word:{ko:"증상",romanization:"jeungsang",en:"symptom",pos:"noun",nuance:"증상(症狀)은 '병 증(症)' + '모양 상(狀)', 즉 '병의 모양·꼴'이라는 뜻으로, 병 때문에 몸에 드러나는 기침·열·통증 같은 '겉 신호'를 가리킨다. 헷갈리기 쉬운 이웃 단어가 둘 있다. 하나는 병 자체인 질병(disease)으로, 증상은 그 질병이 밖으로 내보이는 표시일 뿐이다. 또 하나는 통증(pain)인데, 통증은 아픈 느낌 하나를 가리키고 증상은 통증·발열·기침을 모두 아우르는 더 넓은 말이다. 말투는 격식·비격식을 가리지 않는 중립어라 환자도 의사도 똑같이 쓰며, 병원에서는 '어떤 증상이 있으세요?'가 첫 질문일 만큼 핵심어다. 영어 화자의 함정은 'I feel a symptom'을 직역해 '증상을 느끼다'만 고집하는 것인데, 한국어에서는 '증상이 있다 / 나타나다 / 심해지다 / 사라지다'처럼 증상을 주어로 세워 변화를 말하는 어법이 훨씬 자연스럽다."},sentence:{ko:"증상이 언제부터 있었어요?",en:"When did the symptoms start?"},target:"증상",options:["symptom","hospital / clinic","pharmacy"],note:"Clinic intake word."},{kind:"guess",word:{ko:"병원",romanization:"byeongwon",en:"hospital / clinic",pos:"noun",nuance:"병원 can mean hospital or clinic in everyday Korean."},sentence:{ko:"배가 아파서 병원에 왔어요.",en:"My stomach hurts, so I came to the clinic."},target:"병원",options:["symptom","hospital / clinic","pharmacy"],note:"In Korean, 병원 often covers neighborhood clinics too."},{kind:"guess",word:{ko:"약국",romanization:"yakguk",en:"pharmacy",pos:"noun",nuance:"약국 is where medicine is dispensed or sold. 병원 is where you see the doctor; 약국 is where you usually receive the medicine afterward."},sentence:{ko:"처방전을 가지고 약국에 가요.",en:"I take the prescription to the pharmacy."},target:"약국",options:["symptom","pharmacy","hospital / clinic"],note:"Clinic-to-pharmacy flow."},{kind:"guess",word:{ko:"목",romanization:"mok",en:"neck; throat",pos:"noun",nuance:"목 covers both the neck and the throat, so 목이 아프다 most often means a sore throat from a cold, NOT neck pain — assuming it only means 'neck' is the main English-speaker pitfall (for true neck/shoulder stiffness Koreans more often say 목이 뻐근하다 or specify 목덜미). Thirst is the fixed phrase 목이 마르다 ('the throat dries'), where 마르다 is 르-irregular → 말라요, 말랐어요; do not invent 목이 건조하다. A swollen throat is 목이 붓다 (ㅅ-irregular → 부어요), the same swelling verb as 발이 붓다, and going hoarse is 목이 쉬다 (lit. 'the throat rests'). Idiomatically 목이 빠지게 기다리다 means to wait so eagerly your neck stretches out ('wait with bated breath'). A throat/neck symptom marks the part with 가 (목이 아파요)."},sentence:{ko:"목이 아파요.",en:"My throat hurts."},target:"목",options:["symptom","neck; throat","hospital / clinic"],note:"In symptom talk, 목 often means throat."},{kind:"guess",word:{ko:"배",romanization:"bae",en:"belly; stomach",pos:"noun",nuance:"배 means the belly/stomach (the body region), and the same syllable also means 'pear' and 'boat/ship' — three homonyms split only by context. Hunger and fullness are locked set phrases that ALWAYS keep 배: 배가 고프다 (hungry) and 배가 부르다 (full); you cannot say 나는 고파요 alone, which is the top beginner error. Both adjectives are irregular: 고프다 is ㅡ-irregular (고파요, 고팠어요) and 부르다 is 르-irregular (불러요, 불렀어요). Note 배 here is the colloquial stomach for aches and hunger, distinct from the Sino-Korean 위 (胃, the actual stomach organ) used in medical contexts like 위염 (gastritis). A culturally important idiom: 배가 아프다 also figuratively means to be jealous of someone's good fortune ('my stomach hurts' = green with envy), so context decides literal pain vs. envy."},sentence:{ko:"배가 아파요.",en:"My stomach hurts."},target:"배",options:["belly; stomach","symptom","hospital / clinic"],note:"Most natural first sentence for stomach pain."},{kind:"payoff",line:{speaker:"환자",ko:"네. 처방전을 받고 약국에 가서 약을 기다릴게요.",en:"Okay. I will take the prescription, go to the pharmacy, and wait for the medicine."},hl:"약국"}],canDo:"Say what hurts with body part + 이/가 아프다 (목이 아파요)",id:"chapter-48-b1",chapterId:"chapter-48",index:0},{kind:"pattern",title:"문법 Grammar · Symptom frame",cards:[{kind:"teach",name:"Symptom frame",sub:"body part + 이/가 아프다",rows:[{when:"Body part ends in a consonant (받침)",add:"+ 이 아파요",ex:"목 → 목이 아파요 (my throat hurts)"},{when:"Body part ends in a vowel",add:"+ 가 아파요",ex:"머리 → 머리가 아파요 (my head hurts)"},{when:"Asking 'where does it hurt?'",add:"어디 + 가 아파요?",ex:"어디가 아파요? (where does it hurt?)"},{when:"Past tense (it hurt)",add:"아프 → 아팠어요",ex:"어제부터 배가 아팠어요 (my stomach has hurt since yesterday)"}],examples:[{ko:"머리가 아파요.",en:"My head hurts.",romanization:"meoriga apayo.",note:"머리 ends in a vowel, so it takes 가; 아프 + 아요 → 아파요."},{ko:"목이 아프고 열도 나요.",en:"My throat hurts and I also have a fever.",romanization:"mogi apeugo yeoldo nayo.",note:"목 has a 받침, so it takes 이; 열이 나다 is the natural way to say 'have a fever.'"}],more:{func:"Say what hurts at the clinic. Korean makes the body part the grammatical subject, marked with 이/가, and 아프다 (to hurt / be sore) describes its state. This is your answer when the doctor asks 어디가 아파요? (Where does it hurt?).",keyPoint:{label:"The body part is the SUBJECT, not the object",body:"Use 아프다 for physical body pain (머리가 아파요). Korean makes the body part the subject with 이/가 — it 'hurts' by itself. There is no 'I have a pain' verb that takes the body part as an object, so never mark it with 을/를 here."},pronunciation:""}}],canDo:"Say what hurts with body part + 이/가 아프다 (목이 아파요)",id:"chapter-48-b2",chapterId:"chapter-48",index:1},{kind:"words",title:"단어 Words 2 · 열~",cards:[{kind:"guess",word:{ko:"열",romanization:"yeol",en:"fever",pos:"noun",nuance:"열 (熱, the hanja for 'heat') is a fever, and the must-learn collocation is 열이 나다, where 나다 literally means '(something) comes out/arises' — Korean conceives a fever as heat 'coming out' of the body, so you never say 열을 가지다 ('have/possess a fever'), a direct translation of English 'have' that sounds completely unnatural. You can also say 열이 있다 ('there is fever') as a calmer alternative. The level of a fever is described with 높다/낮다 (열이 높다 = high fever), not 크다/작다, and once treated, 열이 내리다 ('the fever comes down') is the natural way to say it subsides — paralleling how prices or temperature 내리다. To take someone's temperature is 열을 재다 (재다 = to measure), the same verb as 키를 재다 (measure height). Don't confuse this 열 with the homonym 열 meaning 'ten' (열 개 = ten items); context separates them."},sentence:{ko:"아침부터 열이 나요.",en:"I have had a fever since this morning."},target:"열",options:["fever","symptom","hospital / clinic"],note:"Use 열이 나다 for having a fever."},{kind:"guess",word:{ko:"기침",romanization:"gichim",en:"cough",pos:"noun",nuance:"기침 is a native Korean word (not Sino-Korean), and it works in two equally natural patterns that differ subtly in viewpoint: 기침이 나다 frames the cough as something that 'comes out' on its own — built with 나다, the same verb in 열이 나다(run a fever), 콧물이 나다(runny nose), 재채기가 나다(sneeze) — stressing it's involuntary; whereas 기침을 하다 frames it as an action you perform, useful when you mean someone coughs deliberately or repeatedly. English speakers raised on 'have a cough' often try 기침을 가지다 ('possess a cough'), which is flatly wrong — Korean never 'has' a symptom with 가지다; symptoms either 나다 (come out) or you 하다 (do) them. Don't confuse 기침 with 재채기 (a sneeze): 기침 is a throat/chest cough, 재채기 is the explosive nose sneeze, and they are not interchangeable. For severity use 심하다 (기침이 심하다 = a bad cough), not 크다."},sentence:{ko:"기침 때문에 잠을 못 잤어요.",en:"I could not sleep because of the cough."},target:"기침",options:["symptom","cough","hospital / clinic"],note:"Good noun for 때문에."},{kind:"guess",word:{ko:"감기",romanization:"gamgi",en:"a cold",pos:"noun",nuance:"감기 (感氣, 'feeling/affecting + air/energy') is the Sino-Korean word for a common cold, the everyday illness with cough, runny nose, and sore throat — distinct from the heavier 독감 (毒感, 'poison-cold' = influenza/the flu), which is a serious, feverish illness, so don't call the flu just 감기. The critical grammar point is the particle: you 'catch' a cold with 감기에 걸리다, using 에, because 걸리다 ('get caught by/hung on') takes a location-like target — 감기를 걸리다 with 을 is the number-one English-speaker error. Cold medicine is taken with 먹다 (감기약을 먹다, lit. 'eat medicine'), never 마시다 ('drink'), even for liquid syrup. The phrase 감기 조심하세요 ('be careful of cold') is a warm, very common parting line when the weather turns cold, much like 'stay warm / don't catch a cold.'"},sentence:{ko:"감기 때문에 병원에 왔어요.",en:"I came to the clinic because of a cold."},target:"감기",options:["symptom","hospital / clinic","a cold"],note:"Common named cause in clinic talk."},{kind:"guess",word:{ko:"약",romanization:"yak",en:"medicine",pos:"noun",nuance:"Korean commonly says 약을 먹어요 for taking medicine."},sentence:{ko:"약은 식후에 드셔야 해요.",en:"You have to take the medicine after meals."},target:"약",options:["medicine","symptom","hospital / clinic"],note:"Core pharmacy noun."},{kind:"guess",word:{ko:"처방전",romanization:"cheobangjeon",en:"prescription",pos:"noun",nuance:"처방전 is not the medicine itself. It is the document or order that lets the pharmacy prepare the medicine."},sentence:{ko:"병원에서 처방전을 받았어요.",en:"I got a prescription at the clinic."},target:"처방전",options:["prescription","symptom","hospital / clinic"],note:"Bridge between clinic and pharmacy."},{kind:"payoff",line:{speaker:"환자",ko:"아침부터 열이 나고 목이 아파요. 기침도 나요.",en:"Since this morning I have had a fever and a sore throat. I also have a cough."},hl:"기침"}],canDo:"Describe a symptom 'coming out' with 이/가 나다 (열이 나요, 기침이 나요)",id:"chapter-48-b3",chapterId:"chapter-48",index:2},{kind:"pattern",title:"문법 Grammar · V-아/어야 해요",cards:[{kind:"hunt",name:"V-아/어야 해요",sub:"must / have to (medical instruction)",lines:[{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"약을",mid:"",post:"",hit:!1},{pre:"하루에",mid:"",post:"",hit:!1},{pre:"세",mid:"",post:"",hit:!1},{pre:"번",mid:"",post:"",hit:!1},{pre:"먹",mid:"어야",post:"",hit:!0},{pre:"",mid:"해요",post:".",hit:!0}],ko:"이 약을 하루에 세 번 먹어야 해요.",en:"You have to take this medicine three times a day.",romanization:"i yageul harue se beon meogeoya haeyo."},{tokens:[{pre:"내일",mid:"",post:"",hit:!1},{pre:"다시",mid:"",post:"",hit:!1},{pre:"와야",mid:"",post:"",hit:!1},{pre:"",mid:"해요",post:"?",hit:!0}],ko:"내일 다시 와야 해요?",en:"Do I have to come back tomorrow?",romanization:"naeil dasi waya haeyo?"}],rule:{name:"V-아/어야 해요",rows:[{when:"Verb stem has ㅏ/ㅗ vowel",add:"+ 아야 해요",ex:"받다 → 받아야 해요 (have to get / receive)"},{when:"Verb stem has other vowel",add:"+ 어야 해요",ex:"먹다 → 먹어야 해요 (have to take / eat)"},{when:"하다 verbs",add:"하 → 해야 해요",ex:"검사하다 → 검사해야 해요 (have to get tested)"},{when:"Casual spoken alternative",add:"-아/어야 돼요",ex:"쉬어야 돼요 (have to rest)"}]},more:{func:"Give or receive a medical instruction: something you must do. The doctor uses it for what's necessary (약을 먹어야 해요 — you have to take the medicine), and you use it for what you must do (쉬어야 해요 — I have to rest).",keyPoint:{label:"해요 vs 돼요",body:"-아/어야 해요 and -아/어야 돼요 both mean 'must / have to.' 돼요 is a touch more conversational and very common in speech; 해요 feels slightly more standard. In a clinic you will hear both."},pronunciation:""}},{kind:"drill",prompt:"You have to rest well.",sentence:"푹 쉬___.",options:[{text:"어야 해요",ok:!0},{text:"해요",ok:!1},{text:"아야 해요",ok:!1}],explanation:"쉬다 → 쉬어야 해요; 푹 is the set adverb that pairs with resting."}],canDo:"Describe a symptom 'coming out' with 이/가 나다 (열이 나요, 기침이 나요)",id:"chapter-48-b4",chapterId:"chapter-48",index:3},{kind:"words",title:"단어 Words 3 · 식후~",cards:[{kind:"guess",word:{ko:"식후",romanization:"sikhu",en:"after meals",pos:"noun",nuance:"식후 is concise and label-like. In casual speech you can also say 밥 먹고, but at a clinic or pharmacy 식후 is the expected word. 식후 usually pairs with 에 or a time amount: 식후에, 식후 30분."},sentence:{ko:"하루 세 번 식후에 드세요.",en:"Take it three times a day after meals."},target:"식후",options:["symptom","after meals","hospital / clinic"],note:"Medicine timing word."},{kind:"guess",word:{ko:"하루",romanization:"haru",en:"one day; a day",pos:"noun",nuance:"하루 is the native Korean word for a single 24-hour day and lives inside several fixed phrases you should memorise as chunks: 하루 종일 (all day long), 하루에 ... 번 (... times a day), and the doubled 하루하루 (day by day, one day at a time). Here 하루 is pure native counting, which is why it heads the irregular native day-count series 하루(1)·이틀(2)·사흘(3)·나흘(4) rather than taking 일(日) the way calendar dates do. Two English-speaker pitfalls. First, the rate construction: 'once a day' is 하루에 한 번, with 에 carrying the 'per' meaning — never 하루 번. Second, do not let 하루 drift into meaning 'today'; 하루 is 'a day' as a length or an unspecified day ('one day...'), whereas 'today' is the separate word 오늘. So 'I worked all day today' combines both: 오늘 하루 종일 일했어요."},sentence:{ko:"하루 세 번 드세요.",en:"Take it three times a day."},target:"하루",options:["symptom","one day; a day","hospital / clinic"],note:"Frequency word for medicine instructions."},{kind:"guess",word:{ko:"의사",romanization:"uisa",en:"doctor",pos:"noun",nuance:"의사 is Sino-Korean 醫師 ('medicine' 醫 + 'master/teacher' 師), so the word literally frames a doctor as a master of medicine — which is why Koreans almost reflexively append 선생님 (의사 선생님) when addressing or referring to one, the way English keeps 'Doctor' as a title. Saying bare 의사 to or about a specific physician can sound flat or even slightly disrespectful, like calling them 'the doc'. Distinguish 의사 (the licensed physician) from 의자 'chair', which differs by a single vowel and trips up beginners constantly, and from 환자 'patient' and 간호사 'nurse', the other people in the room. The natural verb is 환자를 보다 ('see patients') or 진료를 보다/받다, never the English-style '의사를 하다'; a doctor 의사가 되다 ('becomes' a doctor), with the goal marked by 가, not 을."},sentence:{ko:"의사 선생님께 증상을 말했어요.",en:"I told the doctor my symptoms."},target:"의사",options:["symptom","hospital / clinic","doctor"],note:"의사 선생님 is common in real clinic speech."},{kind:"guess",word:{ko:"약사",romanization:"yaksa",en:"pharmacist",pos:"noun",nuance:"약사 (藥師) combines 藥 'medicine/drug' with the professional 師 'master' (the same dignified 師 in 의사 doctor, 교사 teacher) — literally 'a medicine-master', the licensed pharmacist who dispenses drugs and counsels on dosage at a 약국 (藥局, 'medicine bureau'). A culturally important point for English speakers: in Korea the 약사 actively recommends over-the-counter remedies, so walking into a 약국 and asking the 약사 directly is a normal first move for a headache, cold, or upset stomach — you don't always need a doctor. Keep the obvious pairs straight: 의사 (醫師) diagnoses and writes the 처방전 'prescription', then the 약사 fills it; both share 師 but they are different jobs. Also distinguish the person 약사 from 약 'medicine' and 약국 'pharmacy'. Habitual verbs: 약을 짓다 'fill/compound medicine', 약을 추천받다 'get a medicine recommended', 약사한테 물어보다. English-speaker pitfall: the vowel-final stem takes 약사예요, not 약사이에요; and don't say 약사를 만나다 for routine advice — 약사한테 물어보다 (ask the pharmacist) is the natural collocation."},sentence:{ko:"약사에게 식후에 먹는지 물어봤어요.",en:"I asked the pharmacist whether to take it after meals."},target:"약사",options:["pharmacist","symptom","hospital / clinic"],note:"Pharmacy instruction source."},{kind:"guess",word:{ko:"쉬다",romanization:"swida",en:"to rest",pos:"verb",nuance:"쉬다 is used for taking a break, resting, or being off work/school."},sentence:{ko:"오늘은 집에서 쉬어야 해요.",en:"You have to rest at home today."},target:"쉬어",options:["to rest","symptom","hospital / clinic"],note:"Core recovery action."},{kind:"payoff",line:{speaker:"의사",ko:"감기 때문에 그런 것 같아요. 약은 식후에 하루 세 번 드셔야 해요.",en:"It seems to be because of a cold. You have to take the medicine three times a day after meals."},hl:"식후"}],canDo:"Explain the visit with cause-result -아서/어서 and N 때문에 (아파서 왔어요, 감기 때문에)",id:"chapter-48-b5",chapterId:"chapter-48",index:4},{kind:"pattern",title:"문법 Grammar · A/V-아서/어서",cards:[{kind:"teach",name:"A/V-아서/어서",sub:"symptom causing a result",rows:[{when:"Stem has ㅏ/ㅗ vowel",add:"+ 아서",ex:"아프다 → 아파서 (because it hurts)"},{when:"Stem has other vowel",add:"+ 어서",ex:"먹다 → 먹어서 (because I ate)"},{when:"하다 words",add:"하 → 해서",ex:"심하다 → 심해서 (because it's bad / severe)"},{when:"Symptom 나다 (fever / cough)",add:"나 + 서 → 나서",ex:"열이 나서 (because I have a fever)"}],examples:[{ko:"배가 아파서 병원에 왔어요.",en:"My stomach hurt, so I came to the clinic.",romanization:"baega apaseo byeongwone wasseoyo.",note:"아프다 → 아파서; the classic reason-for-visit sentence."},{ko:"열이 나서 학교에 못 갔어요.",en:"I had a fever, so I couldn't go to school.",romanization:"yeori naseo hakgyoe mot gasseoyo.",note:"열이 나다 → 나서; a symptom leading to an inability."}],more:{func:"Link a symptom to its consequence: 'because X, Y happened.' This is your go-to for explaining the visit: 배가 아파서 왔어요 (my stomach hurt, so I came). The 아서/어서 clause is the cause; the second clause is the result.",keyPoint:{label:"아서/어서 vs 때문에",body:"Both mean 'because.' Use V-아서/어서 to chain a state or action straight into its result in one flowing clause. Use N 때문에 when the cause is a NOUN. With 아서/어서 you cannot put a command or suggestion in the result clause — for that use -(으)니까."},pronunciation:""}}],canDo:"Explain the visit with cause-result -아서/어서 and N 때문에 (아파서 왔어요, 감기 때문에)",id:"chapter-48-b6",chapterId:"chapter-48",index:5},{kind:"pattern",title:"문법 Grammar · N 때문에",cards:[{kind:"hunt",name:"N 때문에",sub:"because of (a symptom / illness)",lines:[{tokens:[{pre:"감기",mid:"",post:"",hit:!1},{pre:"",mid:"때문에",post:"",hit:!0},{pre:"목이",mid:"",post:"",hit:!1},{pre:"아파요.",mid:"",post:"",hit:!1}],ko:"감기 때문에 목이 아파요.",en:"My throat hurts because of a cold.",romanization:"gamgi ttaemune mogi apayo."},{tokens:[{pre:"열",mid:"",post:"",hit:!1},{pre:"",mid:"때문에",post:"",hit:!0},{pre:"잠을",mid:"",post:"",hit:!1},{pre:"못",mid:"",post:"",hit:!1},{pre:"잤어요.",mid:"",post:"",hit:!1}],ko:"열 때문에 잠을 못 잤어요.",en:"I couldn't sleep because of the fever.",romanization:"yeol ttaemune jameul mot jasseoyo."}],rule:{name:"N 때문에",rows:[{when:"Cause is a noun",add:"N + 때문에",ex:"감기 → 감기 때문에 (because of a cold)"},{when:"Sentence-initial 'that's why'",add:"그래서 / 그것 때문에",ex:"그래서 왔어요 (that's why I came)"},{when:"Person as cause",add:"사람 N + 때문에",ex:"동생 때문에 (because of my sibling)"},{when:"To say 'thanks to' (positive)",add:"N + 덕분에",ex:"약 덕분에 (thanks to the medicine)"}]},more:{func:"State a NOUN cause: 'because of my cold / fever / headache.' When the reason is a noun — a named symptom or illness — use N 때문에: 감기 때문에 일을 못 했어요 (I couldn't work because of a cold).",keyPoint:{label:"때문에 (negative cause) vs 덕분에 (positive cause)",body:"Both attach to a noun. 때문에 marks a cause, usually neutral or negative (감기 때문에 — because of a cold). 덕분에 means 'thanks to' and is positive (약 덕분에 나았어요 — I got better thanks to the medicine)."},pronunciation:""}}],canDo:"Say what a symptom kept me from doing with 못 + V (잠을 못 잤어요)",id:"chapter-48-b7",chapterId:"chapter-48",index:6},{kind:"pattern",title:"문법 Grammar · A/V-(으)니까",cards:[{kind:"hunt",name:"A/V-(으)니까",sub:"since this is so, do this (advice)",lines:[{tokens:[{pre:"열이",mid:"",post:"",hit:!1},{pre:"계속",mid:"",post:"",hit:!1},{pre:"나",mid:"니까",post:"",hit:!0},{pre:"물을",mid:"",post:"",hit:!1},{pre:"많이",mid:"",post:"",hit:!1},{pre:"마시세요.",mid:"",post:"",hit:!1}],ko:"열이 계속 나니까 물을 많이 마시세요.",en:"Since the fever keeps up, drink a lot of water.",romanization:"yeori gyesok nanikka mureul mani masiseyo."},{tokens:[{pre:"약을",mid:"",post:"",hit:!1},{pre:"먹었",mid:"으니까",post:"",hit:!0},{pre:"좀",mid:"",post:"",hit:!1},{pre:"쉬세요.",mid:"",post:"",hit:!1}],ko:"약을 먹었으니까 좀 쉬세요.",en:"Since you've taken the medicine, get some rest.",romanization:"yageul meogeosseunikka jom swiseyo."}],rule:{name:"A/V-(으)니까",rows:[{when:"Stem ends in a consonant",add:"+ 으니까",ex:"먹다 → 먹으니까 (since you eat / ate)"},{when:"Stem ends in a vowel",add:"+ 니까",ex:"아프다 → 아프니까 (since it hurts)"},{when:"ㄹ stem (ㄹ drops)",add:"ㄹ 빠짐 + 니까",ex:"만들다 → 만드니까 (since you make it)"},{when:"나다 (fever / cough)",add:"나 + 니까 → 나니까",ex:"열이 나니까 (since you have a fever)"}]},more:{func:"Give advice or instruction grounded in a fact: 'since X is the case, do / let's do Y.' Unlike 아서/어서, the second clause CAN be a command or suggestion — perfect for a doctor's advice: 열이 나니까 약을 드세요 (since you have a fever, take the medicine).",keyPoint:{label:"니까 lets you give a command; 아서/어서 doesn't",body:"The big difference from 아서/어서 is the second clause. With -(으)니까 the result can be a command (-세요), a suggestion (-아요/-(으)ㅂ시다), or a request. So whenever a doctor's 'because…, do this' sentence ends in an instruction, you must use 니까, not 아서/어서."},pronunciation:""}},{kind:"drill",prompt:"Since your throat hurts, drink warm water.",sentence:"목이 아프___ 따뜻한 물을 드세요.",options:[{text:"니까",ok:!0},{text:"으니까",ok:!1}],explanation:"아프다 → 아프니까; advice based on a stated fact."}],canDo:"Say what hurts with body part + 이/가 아프다 (목이 아파요)",id:"chapter-48-b8",chapterId:"chapter-48",index:7},{kind:"pattern",title:"문법 Grammar · 열이 나다 / 기침이 나다",cards:[{kind:"teach",name:"열이 나다 / 기침이 나다",sub:"symptom 'comes out' with 나다",rows:[{when:"Symptom noun ends in a consonant",add:"+ 이 나다",ex:"열 → 열이 나요 (I have a fever)"},{when:"Symptom noun ends in a vowel",add:"+ 가 나다",ex:"재채기 → 재채기가 나요"},{when:"Cough",add:"기침 + 이 나다",ex:"기침이 나요 (I have a cough)"},{when:"Past tense (had the symptom)",add:"나 → 났어요",ex:"어제 열이 났어요 (I had a fever yesterday)"}],examples:[{ko:"아침부터 열이 나요.",en:"I've had a fever since this morning.",romanization:"achimbuteo yeori nayo.",note:"열 + 이 나다; 아침부터 (since this morning) sets the start time."},{ko:"기침이 나고 콧물도 나요.",en:"I have a cough and a runny nose too.",romanization:"gichimi nago konmuldo nayo.",note:"기침이 나다 + 콧물이 나다 chained with -고; the classic cold combo."}],more:{func:"Describe symptoms that arise — fever, cough, runny nose — with the symptom noun + 이/가 + 나다. This is the most common way to list these cold symptoms at the clinic; forms such as 열이 있어요 can also describe their presence.",keyPoint:{label:"나다 symptoms vs 아프다 pain",body:"Symptoms that 'come out' — 열(fever), 기침(cough), 콧물(runny nose) — use 이/가 나다. A body part that aches — 머리, 목, 배 — uses 이/가 아프다. Mixing them up (열이 아파요 ✗, 머리가 나요 ✗) is the giveaway, so memorize which noun pairs with which verb.",label2:""},pronunciation:""}}],canDo:"Describe a symptom 'coming out' with 이/가 나다 (열이 나요, 기침이 나요)",id:"chapter-48-b9",chapterId:"chapter-48",index:8},{kind:"pattern",title:"문법 Grammar · 못 + V",cards:[{kind:"hunt",name:"못 + V",sub:"can't do it (symptom blocking an action)",lines:[{tokens:[{pre:"기침",mid:"",post:"",hit:!1},{pre:"때문에",mid:"",post:"",hit:!1},{pre:"잠을",mid:"",post:"",hit:!1},{pre:"",mid:"못",post:"",hit:!0},{pre:"자요.",mid:"",post:"",hit:!1}],ko:"기침 때문에 잠을 못 자요.",en:"I can't sleep because of the cough.",romanization:"gichim ttaemune jameul mot jayo."},{tokens:[{pre:"열이",mid:"",post:"",hit:!1},{pre:"나서",mid:"",post:"",hit:!1},{pre:"학교에",mid:"",post:"",hit:!1},{pre:"",mid:"못",post:"",hit:!0},{pre:"갔어요.",mid:"",post:"",hit:!1}],ko:"열이 나서 학교에 못 갔어요.",en:"I had a fever, so I couldn't go to school.",romanization:"yeori naseo hakgyoe mot gasseoyo."}],rule:{name:"못 + V",rows:[{when:"Plain verb",add:"못 + 동사",ex:"자다 → 못 자요 (can't sleep)"},{when:"Past tense",add:"못 + V-았/었어요",ex:"가다 → 못 갔어요 (couldn't go)"},{when:"하다 verb (못 goes inside)",add:"N + 못 + 해요",ex:"일하다 → 일을 못 해요 (can't work)"},{when:"Written / formal alternative",add:"V + -지 못해요",ex:"자다 → 자지 못해요 (cannot sleep)"}]},more:{func:"Say you were unable to do something because of a symptom: 'I couldn't ___.' Put 못 right before the verb: 잠을 못 자요 (I can't sleep), 학교에 못 갔어요 (I couldn't go to school). This is how you describe what the illness stopped you from doing.",keyPoint:{label:"못 = couldn't (blocked); 안 = didn't (chose not to)",body:"못 means you were UNABLE — something (a symptom) prevented you: 못 잤어요 (couldn't sleep). 안 means you simply didn't / chose not to: 안 잤어요 (didn't sleep). At the clinic you almost always want 못, because the illness is what stopped you."},pronunciation:""}}],canDo:"Explain the visit with cause-result -아서/어서 and N 때문에 (아파서 왔어요, 감기 때문에)",id:"chapter-48-b10",chapterId:"chapter-48",index:9},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A clinic visit moves from symptoms to medicine instructions and follow-up advice.",lines:[{speaker:"의사",ko:"어디가 아파서 오셨어요?",en:"Where does it hurt? What brings you in?",romanization:"eodiga apaseo osyeosseoyo?"},{speaker:"환자",ko:"아침부터 열이 나고 목이 아파요. 기침도 나요.",en:"Since this morning I have had a fever and a sore throat. I also have a cough.",romanization:"achimbuteo yeori nago mogi apayo. gichimdo nayo."},{speaker:"의사",ko:"감기 때문에 그런 것 같아요. 약은 식후에 하루 세 번 드셔야 해요.",en:"It seems to be because of a cold. You have to take the medicine three times a day after meals.",romanization:"gamgi ttaemune geureon geot gatayo. yageun sikhue haru se beon deusyeoya haeyo."},{speaker:"환자",ko:"기침 때문에 잠을 못 자면 다시 와야 하나요?",en:"If I cannot sleep because of the cough, should I come back?",romanization:"gichim ttaemune jameul mot jamyeon dasi waya hanayo?"},{speaker:"의사",ko:"네. 열이 계속 나니까 물을 많이 마시고 쉬세요.",en:"Yes. Since the fever is continuing, drink a lot of water and rest.",romanization:"ne. yeori gyesok nanikka mureul mani masigo swiseyo."},{speaker:"환자",ko:"네. 처방전을 받고 약국에 가서 약을 기다릴게요.",en:"Okay. I will take the prescription, go to the pharmacy, and wait for the medicine.",romanization:"ne. cheobangjeoneul batgo yakguge gaseo yageul gidarilgeyo."}]},{kind:"order",prompt:"Build: 'I have a fever and a cough.'",tokens:["열이 나고","기침이 나요"],correct:"열이 나고 기침이 나요",explanation:"Korean uses 나다 for fever and cough symptoms. -고 links the two symptoms naturally."}],canDo:"Say what hurts with body part + 이/가 아프다 (목이 아파요)",id:"chapter-48-b11",chapterId:"chapter-48",index:10},{kind:"reading",title:"읽기 Reading · 약은 식후에 하루 세 번 드세요",cards:[{kind:"read",title:"약은 식후에 하루 세 번 드세요",chunks:["민수는 아침부터 열이 나고 목이 아파서 동네 병원에 갔어요. 의사 선생님은 감기 때문에 그런 것 같다고 말했어요. 기침이 심해지는 바람에 어젯밤에는 잠도 거의 못 잤어요.","민수는 처방전을 받아서 약국에 갔고, 약사에게 복약 방법을 들었어요. 약은 식후에 하루 세 번 먹어야 하고, 열이 계속 나니까 물을 많이 마시고 쉬어야 해요. 증상이 나아지지 않으면 다시 병원에 와야 해요."],translation:"Minsu had a fever and sore throat from the morning, so he went to a neighborhood clinic. The doctor said it seemed to be because of a cold. Because his cough got worse, he barely slept the night before. Minsu got a prescription and went to the pharmacy, where he heard the medicine instructions from the pharmacist. He has to take the medicine three times a day after meals, and since the fever is continuing, he has to drink a lot of water and rest. If the symptoms do not improve, he has to go back to the clinic.",qas:[{q:"민수는 왜 병원에 갔어요?",a:"열이 나고 목이 아파서 병원에 갔어요."},{q:"기침이 심해지는 바람에 무엇을 못 했어요?",a:"잠을 거의 못 잤어요."},{q:"약은 언제, 얼마나 먹어야 해요?",a:"식후에 하루 세 번 먹어야 해요."}]}],canDo:"Describe a symptom 'coming out' with 이/가 나다 (열이 나요, 기침이 나요)",id:"chapter-48-b12",chapterId:"chapter-48",index:11},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which symptom phrase is natural?",sentence:null,options:[{text:"열이 나고 목이 아파요.",ok:!0},{text:"열을 하고 목이 있어요.",ok:!1},{text:"열에게 목이 아파요.",ok:!1}],explanation:"열이 나다 and 목이 아프다 are natural symptom frames."},{kind:"drill",prompt:"Which sentence names a symptom as the cause?",sentence:null,options:[{text:"기침 때문에 잠을 못 잤어요.",ok:!0},{text:"기침이 때문에 잠을 못 잤어요.",ok:!1},{text:"기침으로 때문에 잠을 못 잤어요.",ok:!1}],explanation:"N 때문에 attaches directly to the noun."},{kind:"drill",prompt:"Which instruction means 'You have to take the medicine after meals'?",sentence:null,options:[{text:"약은 식후에 드셔야 해요.",ok:!0},{text:"약은 식후에 드실 리가 없어요.",ok:!1},{text:"약은 식후에 드시더라고요.",ok:!1}],explanation:"식후에 gives timing; 드셔야 해요 gives a necessary instruction."},{kind:"drill",prompt:"Which sentence blames worsening symptoms for a bad night's sleep?",sentence:null,options:[{text:"기침이 심해지는 바람에 잠을 못 잤어요.",ok:!0},{text:"기침이 심해지는 덕분에 잠을 못 잤어요.",ok:!1},{text:"기침이 심해지는 중에 잠을 못 자야 해요.",ok:!1}],explanation:"는 바람에 fits an unwanted cause that disrupted sleep."},{kind:"drill",prompt:"Which sentence reports a current pharmacy action?",sentence:null,options:[{text:"약국에서 약을 기다리는 중이에요.",ok:!0},{text:"약국에서 약을 기다렸어요.",ok:!1},{text:"약국에서 약 때문에 기다리니까요.",ok:!1}],explanation:"V-는 중이에요 reports an action in progress."},{kind:"drill",prompt:"목___ 아파요. (My throat hurts.)",sentence:null,options:[{text:"이",ok:!0},{text:"을",ok:!1},{text:"에",ok:!1}],explanation:"아프다 describes the body part that hurts, so 목 takes 이. 목을 아파요 is a common learner error."},{kind:"order",prompt:"Build: 'I have a fever and a cough.'",tokens:["열이 나고","기침이 나요"],correct:"열이 나고 기침이 나요",explanation:"Korean uses 나다 for fever and cough symptoms. -고 links the two symptoms naturally."}],canDo:"Explain the visit with cause-result -아서/어서 and N 때문에 (아파서 왔어요, 감기 때문에)",id:"chapter-48-b13",chapterId:"chapter-48",index:12}]},{id:"chapter-49",number:49,title:"N이/가 있어요 · N이/가 없어요",goal:"Ask about 보증금, 월세, 관리비, and what is included.",biteCount:13,bites:[{kind:"words",title:"단어 Words 1 · 원룸~",cards:[{kind:"guess",word:{ko:"원룸",romanization:"wollum",en:"studio apartment",pos:"noun",nuance:"원룸 literally comes from 'one room', but in Korean it is a housing category, not just any one room. It usually means a small self-contained studio with a bathroom and kitchenette."},sentence:{ko:"이 원룸은 보증금이 얼마예요?",en:"How much is the deposit for this studio?"},target:"원룸",options:["studio apartment","real estate; real-estate office","deposit"],note:"Core real-estate viewing noun."},{kind:"guess",word:{ko:"부동산",romanization:"budongsan",en:"real estate; real-estate office",pos:"noun",nuance:"When Koreans say 부동산에 가요, they usually mean the neighborhood office, not an abstract real-estate market. For the person, say 공인중개사 or 중개사."},sentence:{ko:"집을 구하기 위해 부동산에 갔어요.",en:"I went to a real-estate office to find a place."},target:"부동산",options:["studio apartment","real estate; real-estate office","deposit"],note:"In daily speech, 부동산 often means the office."},{kind:"guess",word:{ko:"보증금",romanization:"bojeunggeum",en:"deposit",pos:"noun",nuance:"보증금 is not rent. It is a deposit paid upfront and normally returned after the lease, depending on the contract and room condition."},sentence:{ko:"보증금은 500만 원이에요.",en:"The deposit is 5 million won."},target:"보증금",options:["studio apartment","deposit","real estate; real-estate office"],note:"Must be asked together with 월세."},{kind:"guess",word:{ko:"월세",romanization:"wolse",en:"monthly rent",pos:"noun",nuance:"월세 is the monthly rent payment. 관리비 and utilities may or may not be included, so ask 따로예요? and 포함돼 있어요?"},sentence:{ko:"월세는 70만 원이에요.",en:"The monthly rent is 700,000 won."},target:"월세",options:["studio apartment","real estate; real-estate office","monthly rent"],note:"Monthly payment, separate from deposit."},{kind:"guess",word:{ko:"전세",romanization:"jeonse",en:"large-deposit lease",pos:"noun",nuance:"전세 is not simply 'deposit'. The deposit itself is 보증금; 전세 is the lease type built around a very large deposit."},sentence:{ko:"전세보다 월세 원룸을 찾고 있어요.",en:"I am looking for a monthly-rent studio rather than jeonse."},target:"전세",options:["large-deposit lease","studio apartment","real estate; real-estate office"],note:"Lease type contrast."},{kind:"payoff",line:{speaker:"손님",ko:"이 원룸은 보증금이 얼마예요?",en:"How much is the deposit for this studio?"},hl:"원룸"}],canDo:"Say what a home has or lacks with N이/가 있어요/없어요 (주차장이 없어요)",id:"chapter-49-b1",chapterId:"chapter-49",index:0},{kind:"pattern",title:"문법 Grammar · N이/가 있어요",cards:[{kind:"hunt",name:"N이/가 있어요",sub:"saying what a home has",lines:[{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"집에",mid:"",post:"",hit:!1},{pre:"방이",mid:"",post:"",hit:!1},{pre:"세",mid:"",post:"",hit:!1},{pre:"개",mid:"",post:"",hit:!1},{pre:"",mid:"있어요",post:".",hit:!0}],ko:"이 집에 방이 세 개 있어요.",en:"This house has three rooms.",romanization:"i jibe bangi se gae isseoyo."},{tokens:[{pre:"우리",mid:"",post:"",hit:!1},{pre:"아파트에",mid:"",post:"",hit:!1},{pre:"엘리베이터",mid:"가",post:"",hit:!0},{pre:"",mid:"있어요",post:".",hit:!0}],ko:"우리 아파트에 엘리베이터가 있어요.",en:"Our apartment has an elevator.",romanization:"uri apateue ellibeiteoga isseoyo."}],rule:{name:"N이/가 있어요",rows:[{when:"Noun ends in a consonant (받침)",add:"+ 이 있어요",ex:"방 → 방이 있어요 (there is a room)"},{when:"Noun ends in a vowel",add:"+ 가 있어요",ex:"엘리베이터 → 엘리베이터가 있어요 (there is an elevator)"},{when:"Yes/no question",add:"있어요? (rising tone)",ex:"주차장이 있어요? (Is there parking?)"}]},more:{func:"Use 있어요 to say a room or feature exists in a home. It is the everyday way to describe what an apartment or house comes with: a balcony, an elevator, parking, and so on.",keyPoint:{label:"있어요 vs 이에요/예요",body:"있어요 means 'there is / it has' (existence). 이에요/예요 means 'it is' (identity). 방이 있어요 = 'there is a room'; 방이에요 = 'it is a room.' For listing what a home has, you almost always want 있어요."},pronunciation:"있어요 links the 받침 ㅆ into the next vowel: [이써요]. So 방이 있어요 runs together as [방이 이써요]."}},{kind:"drill",prompt:"There is a big supermarket near the house.",sentence:"집 근처에 큰 마트___.",options:[{text:"있어요",ok:!1},{text:"가 있어요",ok:!0}],explanation:"있어요 also covers 'there is X nearby,' a common housing detail."}],canDo:"Say what a home has or lacks with N이/가 있어요/없어요 (주차장이 없어요)",id:"chapter-49-b2",chapterId:"chapter-49",index:1},{kind:"words",title:"단어 Words 2 · 관리비~",cards:[{kind:"guess",word:{ko:"관리비",romanization:"gwallibi",en:"maintenance fee",pos:"noun",nuance:"관리비 is Sino-Korean: 管理費, literally 管理 'management' + 費 'expense', i.e. 'management/maintenance fee'. It is the monthly building-upkeep charge covering shared costs — cleaning, security (경비), the elevator (엘리베이터), corridor lighting, and very often part of the utilities (수도세, 난방비, sometimes 인터넷) — and crucially it is billed ON TOP OF 월세 (monthly rent), which blindsides many newcomers. Always ask what the 관리비 covers and whether it's 포함 (included) or 별도 (別途, 'separate'), because a temptingly cheap 월세 can hide a fat 관리비. Like other recurring charges it 나오다 (comes out) and you 내다 (pay) it. Pitfalls for English speakers: first, do not confuse 관리비 (the monthly, non-refundable maintenance fee) with 보증금 (保證金, the large refundable deposit you get back when you leave) — they are completely different money. Second, do not assume rent already includes it the way some Western 'all-bills-included' rents do; in Korea 관리비 is usually a separate line. Third, distinguish 관리비 (shared building costs) from the individually-metered 공과금 like personal 전기세 — though some 관리비 bills bundle a portion of utilities, so reading the 관리비 고지서 (statement) itemization matters."},sentence:{ko:"관리비는 따로예요?",en:"Is the maintenance fee separate?"},target:"관리비",options:["maintenance fee","studio apartment","real estate; real-estate office"],note:"Core cost question."},{kind:"guess",word:{ko:"따로",romanization:"ttaro",en:"separately",pos:"adverb",nuance:"따로 is not only about money, but housing learners need it for separate fees and separate payments."},sentence:{ko:"관리비는 따로예요?",en:"Is the maintenance fee separate?"},target:"따로",options:["separately","studio apartment","real estate; real-estate office"],note:"Small word that changes total cost."},{kind:"guess",word:{ko:"포함되다",romanization:"pohamdoeda",en:"to be included",pos:"verb",nuance:"포함되다 focuses on what is included in a price or category. Do not use it like English 'include' with the fee as active subject unless you restructure the sentence."},sentence:{ko:"인터넷이 관리비에 포함돼 있어요.",en:"Internet is included in the maintenance fee."},target:"포함돼",options:["to be included","to sign / make a contract","to move house"],note:"Included item is the subject."},{kind:"guess",word:{ko:"계약서",romanization:"gyeyakseo",en:"contract document",pos:"noun",nuance:"계약서 is the document, while 계약하다 is the action of making/signing the contract. Do not blur them when asking questions."},sentence:{ko:"이사하기 전에 계약서를 확인해 두세요.",en:"Check the contract before moving."},target:"계약서",options:["studio apartment","real estate; real-estate office","contract document"],note:"Prepared action before signing or moving."},{kind:"guess",word:{ko:"계약하다",romanization:"gyeyakada",en:"to sign / make a contract",pos:"verb",nuance:"계약하다 is broader than housing, but in this chapter it should stay tied to real-estate contracts. 계약서를 확인하다 happens before 계약하다."},sentence:{ko:"오늘 계약할 수 있어요.",en:"You can sign the contract today."},target:"계약할",options:["to be included","to move house","to sign / make a contract"],note:"Real-estate action after checking the listing."},{kind:"payoff",line:{speaker:"손님",ko:"관리비는 따로예요? 인터넷도 포함돼 있어요?",en:"Is the maintenance fee separate? Is internet included too?"},hl:"관리비"}],canDo:"Describe a home with adjective + noun (넓은 방, 깨끗한 집, 조용한 동네)",id:"chapter-49-b3",chapterId:"chapter-49",index:2},{kind:"pattern",title:"문법 Grammar · N이/가 없어요",cards:[{kind:"hunt",name:"N이/가 없어요",sub:"saying a home lacks something",lines:[{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"방에는",mid:"",post:"",hit:!1},{pre:"창문",mid:"이",post:"",hit:!0},{pre:"",mid:"없어요",post:".",hit:!0}],ko:"이 방에는 창문이 없어요.",en:"This room has no window.",romanization:"i bangeneun changmuni eopseoyo."},{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"건물에는",mid:"",post:"",hit:!1},{pre:"엘리베이터",mid:"가",post:"",hit:!0},{pre:"",mid:"없어요",post:".",hit:!0}],ko:"이 건물에는 엘리베이터가 없어요.",en:"This building has no elevator.",romanization:"i geonmureneun ellibeiteoga eopseoyo."}],rule:{name:"N이/가 없어요",rows:[{when:"Noun ends in a consonant (받침)",add:"+ 이 없어요",ex:"창문 → 창문이 없어요 (there is no window)"},{when:"Noun ends in a vowel",add:"+ 가 없어요",ex:"엘리베이터 → 엘리베이터가 없어요 (there is no elevator)"},{when:"Yes/no question",add:"없어요? (rising tone)",ex:"엘리베이터가 없어요? (Is there no elevator?)"}]},more:{func:"없어요 is the negative of 있어요: it says a feature does NOT exist. In housing talk it covers a missing room, no parking, no elevator, or 'there is no extra fee.'",keyPoint:{label:"있어요 ↔ 없어요",body:"These are a fixed pair, not 있어요 + 안. To say a home lacks something, use 없어요, never 안 있어요. 방이 있어요 (has a room) ↔ 방이 없어요 (has no room)."},pronunciation:"없어요 links the cluster ㅄ so only ㅅ carries over: [업써요]. So 창문이 없어요 sounds like [창무니 업써요]."}},{kind:"drill",prompt:"There's no extra cost besides the deposit.",sentence:"보증금 외에 추가 비용___.",options:[{text:"이 없어요",ok:!0},{text:"가 없어요",ok:!1}],explanation:"A reassuring rental phrase: 없어요 = 'there is no (extra fee).'"}],canDo:"Describe a home with adjective + noun (넓은 방, 깨끗한 집, 조용한 동네)",id:"chapter-49-b4",chapterId:"chapter-49",index:3},{kind:"words",title:"단어 Words 3 · 거실~",cards:[{kind:"guess",word:{ko:"거실",romanization:"geosil",en:"living room",pos:"noun",nuance:"거실 is the shared 'living/common' room of a Korean home — the social hub where the family relaxes together and where guests are received, almost always centred on a 소파 and a TV. It is Sino-Korean: 居室, literally 居 'to dwell/reside' + 室 'room', so the feel is 'the room you live in (together)'. Contrast it with 응접실 (應接室, a formal parlour for receiving visitors), which sounds old-fashioned and upper-class today, and with 방, the generic word for any closed 'room/bedroom'; 거실 specifically names the open central area. Register is fully neutral — children and adults alike say 거실. The big English-speaker pitfall is location particles: because a TV simply sits there you say 거실에 텔레비전이 있어요 (에 = existence), but because you *do* something there you switch to 거실에서 쉬어요 (에서 = action). Mixing these up (거실에서 텔레비전이 있어요) is the single most common error."},sentence:{ko:"거실이 넓어요.",en:"The living room is spacious."},target:"거실",options:["studio apartment","living room","real estate; real-estate office"],note:"Layout noun."},{kind:"guess",word:{ko:"부엌",romanization:"bueok",en:"kitchen",pos:"noun",nuance:"부엌 is the warm, native-Korean everyday word for the room where you cook and wash dishes — the heart of the home where the smell of food lives. Its nearest synonym is the Sino-Korean 주방 (廚房, 'cooking-room'): 주방 is the neutral, technical label you see on apartment floor plans, restaurant signs, and in compounds like 주방용품 (kitchen goods), whereas 부엌 carries a homier, more personal feeling — 우리 집 부엌 sounds natural, 우리 집 주방 sounds like a brochure. Both are everyday and polite; there's no status caution. It collocates with 요리하다, 치우다, and 부엌 살림. The classic English-speaker pitfall is the final consonant: it ends in ㅋ (부엌), so the spelling is fixed even though it's pronounced [부억] before a pause — never write 부억. The second trap is particle choice: use 부엌에서 for an action happening there, but 부엌에 for where something simply sits (부엌에 냉장고가 있어요)."},sentence:{ko:"부엌에 냉장고가 있어요.",en:"There is a refrigerator in the kitchen."},target:"부엌",options:["kitchen","studio apartment","real estate; real-estate office"],note:"Appliance/location sentence."},{kind:"guess",word:{ko:"화장실",romanization:"hwajangsil",en:"bathroom / restroom",pos:"noun",nuance:"화장실 is the normal public word for bathroom/restroom."},sentence:{ko:"깨끗한 화장실이 중요해요.",en:"A clean bathroom is important."},target:"화장실",options:["studio apartment","bathroom / restroom","real estate; real-estate office"],note:"Inspection detail."},{kind:"guess",word:{ko:"공인중개사",romanization:"gonginjunggaesa",en:"licensed real estate agent",pos:"noun",nuance:"공인중개사 (公認仲介士) is a long but transparent compound: 公認 'officially recognized' (公 public + 認 acknowledge) + 仲介 'mediation/brokerage' (仲 go-between + 介 intermediary) + 士 certified professional — so literally 'an officially-licensed brokerage professional', the agent who arranges 전세, 월세, and home sales, and the person you inevitably deal with when renting in Korea. The number-one English-speaker confusion is place vs person: 부동산 (不動産, lit. 'immovable property') colloquially names the agent's office or the property itself, so 부동산에 가다 = 'go to the agent's office', but the human is the 공인중개사 — never call the person 부동산. The 공인 'officially licensed' prefix matters in formal/contractual contexts; dropping it to just 중개사 is loose. In everyday speech people also warmly say 중개사님 or 사장님 to the agent's face. Collocations: 공인중개사 사무소 'realtor office', 공인중개사 자격증 'realtor license', 집을 구하다 'find a home'. Note 공인중개사 ends in a vowel, so it would be 공인중개사예요, not 공인중개사이에요."},sentence:{ko:"공인중개사에게 관리비를 물어봤어요.",en:"I asked the licensed agent about the maintenance fee."},target:"공인중개사",options:["studio apartment","licensed real estate agent","deposit"],note:"The person helping with the contract."},{kind:"guess",word:{ko:"이사하다",romanization:"isahada",en:"to move house",pos:"verb",nuance:"이사하다 specifically means relocating your residence — changing the home you live in — built from Sino-Korean 移徙 (移 'shift', 徙 'relocate') plus 하다. Contrast it sharply with 옮기다, which is just physically moving an object from one spot to another (책상을 옮기다 'move the desk'); you never use 옮기다 for changing homes, and you never use 이사하다 for shifting furniture. It splits into 이사 가다 (move away, focus on departure) and 이사 오다 (move in, focus on arrival near the speaker). Being a 하다-verb, the negative wraps the noun: 이사 안 해요 / 이사 못 해요, NOT 안 이사해요. The biggest English-speaker pitfall is treating it like English 'move' as a transitive verb — Koreans don't say '집을 이사해요'; the home is implied, so just 이사해요 is complete."},sentence:{ko:"다음 달에 이사할 수 있어요.",en:"I can move next month."},target:"이사할",options:["to be included","to sign / make a contract","to move house"],note:"Moving schedule verb."},{kind:"payoff",line:{speaker:"손님",ko:"이사하기 전에 계약서를 확인해 두면 되죠?",en:"I should check the contract before moving, right?"},hl:"이사하"}],canDo:"State a housing condition with -(으)면 (싸면 계약할 거예요)",id:"chapter-49-b5",chapterId:"chapter-49",index:4},{kind:"pattern",title:"문법 Grammar · A-(으)ㄴ N",cards:[{kind:"teach",name:"A-(으)ㄴ N",sub:"describing a home (넓은 방)",rows:[{when:"Adjective stem ends in a consonant (받침)",add:"+ 은 + N",ex:"넓다 → 넓은 방 (a spacious room)"},{when:"Adjective stem ends in a vowel",add:"+ ㄴ + N",ex:"깨끗하다 → 깨끗한 집 (a clean house)"},{when:"ㄹ-final stem (drop ㄹ, add ㄴ)",add:"ㄹ→ㄴ + N",ex:"멀다 → 먼 곳 (a faraway place)"}],examples:[{ko:"넓은 방을 찾고 있어요.",en:"I'm looking for a spacious room.",romanization:"neolbeun bangeul chatgo isseoyo.",note:"넓다 (consonant stem) → 넓은 modifies 방; the adjective comes before the noun."},{ko:"깨끗한 집이 좋아요.",en:"I like a clean house.",romanization:"kkaekkeutan jibi joayo.",note:"하다-adjective 깨끗하다 → 깨끗한 (drop the vowel-ending 하, add ㄴ)."}],more:{func:"Turn a descriptive adjective into a word that modifies a noun, like 'a spacious room' or 'a clean house.' This is how you describe homes: 넓은 방, 깨끗한 집, 조용한 동네.",keyPoint:{label:"넓은 방 vs 방이 넓어요",body:"Modifier form goes BEFORE the noun: 넓은 방 ('a spacious room' — naming a thing). Predicate form ends the sentence: 방이 넓어요 ('the room is spacious' — stating a fact). Use 넓은 방 when the adjective is labeling the noun."},pronunciation:"넓다 is pronounced [널따], and 넓은 links the ㄼ cluster as [널븐]. 가까운 and 깨끗한 link smoothly."}}],canDo:"State a housing condition with -(으)면 (싸면 계약할 거예요)",id:"chapter-49-b6",chapterId:"chapter-49",index:5},{kind:"pattern",title:"문법 Grammar · A/V-(으)면",cards:[{kind:"hunt",name:"A/V-(으)면",sub:"stating a housing condition",lines:[{tokens:[{pre:"방이",mid:"",post:"",hit:!1},{pre:"너무",mid:"",post:"",hit:!1},{pre:"비싸",mid:"면",post:"",hit:!0},{pre:"다른",mid:"",post:"",hit:!1},{pre:"집을",mid:"",post:"",hit:!1},{pre:"볼게요.",mid:"",post:"",hit:!1}],ko:"방이 너무 비싸면 다른 집을 볼게요.",en:"If the room is too expensive, I'll look at another place.",romanization:"bangi neomu bissamyeon dareun jibeul bolgeyo."},{tokens:[{pre:"지하철역에서",mid:"",post:"",hit:!1},{pre:"가까우",mid:"면",post:"",hit:!0},{pre:"좋아요.",mid:"",post:"",hit:!1}],ko:"지하철역에서 가까우면 좋아요.",en:"It'd be nice if it's close to the subway station.",romanization:"jihacheoryeogeseo gakkaumyeon joayo."}],rule:{name:"A/V-(으)면",rows:[{when:"Stem ends in a consonant (받침)",add:"+ 으면",ex:"좋다 → 좋으면 (if it's good)"},{when:"Stem ends in a vowel",add:"+ 면",ex:"비싸다 → 비싸면 (if it's expensive)"},{when:"ㄹ-final stem (keep ㄹ, add 면)",add:"+ 면",ex:"멀다 → 멀면 (if it's far)"}]},more:{func:"-(으)면 means 'if / when.' Use it to set a condition about a home: 'if it's too expensive...', 'if I like the place...', 'when I sign the contract...'",keyPoint:{label:"-(으)면 vs -아/어서",body:"-(으)면 is a hypothetical 'if/when' — the result depends on the condition. -아/어서 gives an actual reason that already holds. 비싸면 안 사요 = 'if it's expensive, I won't buy.' 비싸서 안 사요 = 'I'm not buying because it's (actually) expensive.'"},pronunciation:"After a 받침, 으면 links: 좋으면 sounds like [조으면] (ㅎ weakens between vowels). The ㄹ-stem 들면 is simply [들면]."}}],canDo:"Say where I live and where I'm moving with N에 살아요 / N(으)로 이사 가요",id:"chapter-49-b7",chapterId:"chapter-49",index:6},{kind:"pattern",title:"문법 Grammar · V-(으)ㄹ 수 있어요",cards:[{kind:"hunt",name:"V-(으)ㄹ 수 있어요",sub:"what's possible/allowed at home",lines:[{tokens:[{pre:"여기에",mid:"",post:"",hit:!1},{pre:"주차할",mid:"",post:"",hit:!1},{pre:"",mid:"수",post:"",hit:!0},{pre:"",mid:"있어요",post:"?",hit:!0}],ko:"여기에 주차할 수 있어요?",en:"Can I park here?",romanization:"yeogie juchahal su isseoyo?"},{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"집에서",mid:"",post:"",hit:!1},{pre:"강아지를",mid:"",post:"",hit:!1},{pre:"키울",mid:"",post:"",hit:!1},{pre:"",mid:"수",post:"",hit:!0},{pre:"",mid:"있어요",post:".",hit:!0}],ko:"이 집에서 강아지를 키울 수 있어요.",en:"You can keep a dog in this house.",romanization:"i jibeseo gangajireul kiul su isseoyo."}],rule:{name:"V-(으)ㄹ 수 있어요",rows:[{when:"Verb stem ends in a consonant (받침)",add:"+ 을 수 있어요",ex:"살다 → 살 수 있어요 (can live)"},{when:"Verb stem ends in a vowel",add:"+ ㄹ 수 있어요",ex:"주차하다 → 주차할 수 있어요 (can park)"},{when:"Negative 'cannot'",add:"(으)ㄹ 수 없어요",ex:"키우다 → 키울 수 없어요 (cannot keep a pet)"}]},more:{func:"Express that something is possible or allowed in a home: you can park, you can keep a pet, you can move in next week. The opposite, 'cannot,' is V-(으)ㄹ 수 없어요.",keyPoint:{label:"있어요 → 없어요 for 'cannot'",body:"To make V-(으)ㄹ 수 있어요 negative, swap 있어요 for 없어요, not 안: 살 수 있어요 (can live) → 살 수 없어요 (cannot live). The 수 (way/possibility) stays; only the existence verb flips.",drill:{instruction:"Make 'can do' with V-(으)ㄹ 수 있어요.",model:"주차하다 → 주차할 수 있어요",items:["살다 → ____","키우다 → ____","이사하다 → ____"]}},pronunciation:"수 있어요 is pronounced [수 이써요], and the ㄹ before 수 stays light: 살 수 → [살 쑤] (the ㅅ tenses to ㅆ after the ㄹ)."}}],canDo:"Say what a home has or lacks with N이/가 있어요/없어요 (주차장이 없어요)",id:"chapter-49-b8",chapterId:"chapter-49",index:7},{kind:"pattern",title:"문법 Grammar · N에 살아요",cards:[{kind:"hunt",name:"N에 살아요",sub:"saying where you live",lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"부산",mid:"에",post:"",hit:!0},{pre:"",mid:"살아요",post:".",hit:!0}],ko:"저는 부산에 살아요.",en:"I live in Busan.",romanization:"jeoneun busane sarayo."},{tokens:[{pre:"지금",mid:"",post:"",hit:!1},{pre:"원룸",mid:"에",post:"",hit:!0},{pre:"",mid:"살아요",post:".",hit:!0}],ko:"지금 원룸에 살아요.",en:"I live in a studio apartment right now.",romanization:"jigeum wollume sarayo."}],rule:{name:"N에 살아요",rows:[{when:"Place + 에 살아요",add:"N + 에 살아요",ex:"부산에 살아요 (I live in Busan)"},{when:"Building/room type",add:"N + 에 살아요",ex:"아파트에 살아요 (I live in an apartment)"},{when:"Floor (N층)",add:"숫자 + 층에 살아요",ex:"3층에 살아요 (I live on the 3rd floor)"}]},more:{func:"Use 에 + 살아요 to say where you live: in a city, a neighborhood, an apartment, or on a particular floor. 에 marks the place of residence.",keyPoint:{label:"에 살아요 vs 에서 + action",body:"For living (a state), use 에: 서울에 살아요. For an action that happens at a place, use 에서: 집에서 일해요 ('I work at home'). With 살다 specifically, Korean uses 에, not 에서."},pronunciation:"살아요 links the ㄹ into the next vowel: [사라요]. 부산에 살아요 runs together as [부사네 사라요]."}}],canDo:"Describe a home with adjective + noun (넓은 방, 깨끗한 집, 조용한 동네)",id:"chapter-49-b9",chapterId:"chapter-49",index:8},{kind:"pattern",title:"문법 Grammar · N(으)로 이사 가요/와요",cards:[{kind:"teach",name:"N(으)로 이사 가요/와요",sub:"moving house",rows:[{when:"Place ends in a consonant (받침)",add:"+ 으로 이사 가요",ex:"부산 → 부산으로 이사 가요"},{when:"Place ends in a vowel or ㄹ",add:"+ 로 이사 가요",ex:"제주 → 제주로… / 서울 → 서울로…"},{when:"Moving here (toward speaker)",add:"+ (으)로 이사 와요",ex:"새집으로 이사 와요 (move into a new house)"}],examples:[{ko:"다음 달에 새집으로 이사 가요.",en:"I'm moving to a new house next month.",romanization:"daeum dare saejibeuro isa gayo.",note:"새집 'new house' + 으로 (받침 ㅂ) + 이사 가요; (으)로 marks the destination."},{ko:"부산으로 이사 갈 거예요.",en:"I'm going to move to Busan.",romanization:"busaneuro isa gal geoyeyo.",note:"부산 ends in ㄴ → 으로; 이사 갈 거예요 = future 'will move.'"}],more:{func:"Use (으)로 to mark the destination you move TO when changing homes: 이사 가다 'to move (away to)' and 이사 오다 'to move (here to).' (으)로 means 'to / toward.'",keyPoint:{label:"이사 가요 vs 이사 와요",body:"이사 가다 = move away (the speaker is not at the destination). 이사 오다 = move here (toward the speaker's location). 서울로 이사 가요 = 'I'm moving to Seoul'; 여기로 이사 왔어요 = 'I moved here.'"},pronunciation:"이사 가요 is [이사 가요]; 으로 links its ㄹ into 이사: 새집으로 → [새지브로]. 이사 왔어요 sounds like [이사 와써요]."}}],canDo:"State a housing condition with -(으)면 (싸면 계약할 거예요)",id:"chapter-49-b10",chapterId:"chapter-49",index:9},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A tenant checks rent, deposit, utilities, and contract preparation at a real-estate office.",lines:[{speaker:"손님",ko:"이 원룸은 보증금이 얼마예요?",en:"How much is the deposit for this studio?",romanization:"i wollumeun bojeunggeumi eolmayeyo?"},{speaker:"중개사",ko:"보증금은 500만 원이고 월세는 70만 원이에요.",en:"The deposit is 5 million won and the monthly rent is 700,000 won.",romanization:"bojeunggeumeun 500man wonigo wolseneun 70man wonieyo."},{speaker:"손님",ko:"관리비는 따로예요? 인터넷도 포함돼 있어요?",en:"Is the maintenance fee separate? Is internet included too?",romanization:"gwallibineun ttaroyeyo? inteonesdo pohamdwae isseoyo?"},{speaker:"중개사",ko:"관리비는 7만 원이고 인터넷은 포함돼 있어요.",en:"The maintenance fee is 70,000 won, and internet is included.",romanization:"gwallibineun 7man wonigo inteones-eun pohamdwae isseoyo."},{speaker:"손님",ko:"이사하기 전에 계약서를 확인해 두면 되죠?",en:"I should check the contract before moving, right?",romanization:"isahagi jeone gyeyakseoreul hwaginhae dumyeon doejyo?"},{speaker:"중개사",ko:"네. 마음에 들면 오늘 계약할 수 있어요.",en:"Yes. If you like it, you can sign the contract today.",romanization:"ne. maeume deulmyeon oneul gyeyakal su isseoyo."}]},{kind:"order",prompt:"Build: 'Is internet included?'",tokens:["인터넷이","포함돼요?"],correct:"인터넷이 포함돼요?",explanation:"인터넷이 is the subject of being included. 포함돼요? is the natural real-estate question."}],canDo:"Say what a home has or lacks with N이/가 있어요/없어요 (주차장이 없어요)",id:"chapter-49-b11",chapterId:"chapter-49",index:10},{kind:"reading",title:"읽기 Reading · 관리비에 인터넷이 포함돼 있어요?",cards:[{kind:"read",title:"관리비에 인터넷이 포함돼 있어요?",chunks:["하나는 이사하기 위해 부동산에 갔어요. 공인중개사는 넓은 원룸 하나를 보여 줬어요. 보증금은 500만 원이고 월세는 70만 원이었어요.","하나는 관리비가 따로인지, 인터넷이 관리비에 포함돼 있는지 물어봤어요. 베란다는 없었지만 부엌에 냉장고와 세탁기가 있었고 화장실도 깨끗했어요. 마음에 들면 오늘 계약할 수 있다고 해서, 하나는 계약하기 전에 계약서를 다시 확인해 두었어요."],translation:"Hana went to a real-estate office to move. The licensed agent showed her a spacious studio. The deposit was 5 million won and the monthly rent was 700,000 won. Hana asked whether the maintenance fee was separate and whether internet was included in the fee. There was no balcony, but there was a refrigerator and washing machine in the kitchen, and the bathroom was clean. Since she could sign the contract that day if she liked it, Hana checked the contract again before signing.",qas:[{q:"하나는 왜 부동산에 갔어요?",a:"이사하기 위해 부동산에 갔어요."},{q:"하나가 확인한 비용 두 가지는 뭐예요?",a:"보증금과 월세를 확인했어요."},{q:"계약하기 전에 무엇을 확인해 두었어요?",a:"계약서를 다시 확인해 두었어요."}]}],canDo:"Describe a home with adjective + noun (넓은 방, 깨끗한 집, 조용한 동네)",id:"chapter-49-b12",chapterId:"chapter-49",index:11},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"At a real-estate office, which pair belongs together?",sentence:null,options:[{text:"보증금 500만 원 / 월세 70만 원",ok:!0},{text:"관리비 500만 원 / 월세 70만 원",ok:!1},{text:"매매가 500만 원 / 전세금 70만 원",ok:!1}],explanation:"보증금 and 월세 are core housing price terms."},{kind:"drill",prompt:"Which question checks whether a fee is separate?",sentence:null,options:[{text:"관리비는 따로예요?",ok:!0},{text:"관리비는 같이 나와요?",ok:!1},{text:"관리비는 보증금 먹어요?",ok:!1}],explanation:"따로 means separately and is essential for fee questions."},{kind:"drill",prompt:"Which sentence asks whether internet is included?",sentence:null,options:[{text:"인터넷이 관리비에 포함돼 있어요?",ok:!0},{text:"인터넷을 관리비가 포함해요?",ok:!1},{text:"인터넷을 관리비에 포함돼 있어요?",ok:!1}],explanation:"The included item is the subject, and 관리비 takes 에."},{kind:"drill",prompt:"Before moving, the prepared-action sentence is:",sentence:null,options:[{text:"계약서를 확인해 두세요.",ok:!0},{text:"계약서를 확인할 리가 없어요.",ok:!1},{text:"계약서를 확인하는군요.",ok:!1}],explanation:"-아/어 두세요 means do it in advance and leave it prepared."},{kind:"drill",prompt:"Which sentence uses possibility naturally?",sentence:null,options:[{text:"오늘 계약할 수 있어요.",ok:!0},{text:"오늘 계약할 리가 없어요.",ok:!1},{text:"오늘 계약서 때문에 포함돼요.",ok:!1}],explanation:"Vㄹ/을 수 있어요 expresses practical possibility."},{kind:"drill",prompt:"관리비___ 포함돼요? (Is the maintenance fee included?)",sentence:null,options:[{text:"가",ok:!0},{text:"를",ok:!1},{text:"에",ok:!1}],explanation:"포함되다 is passive/included, so 관리비 is the subject and takes 가. 를 would fit an active verb like 포함하다."},{kind:"order",prompt:"Build: 'Is internet included?'",tokens:["인터넷이","포함돼요?"],correct:"인터넷이 포함돼요?",explanation:"인터넷이 is the subject of being included. 포함돼요? is the natural real-estate question."}],canDo:"State a housing condition with -(으)면 (싸면 계약할 거예요)",id:"chapter-49-b13",chapterId:"chapter-49",index:12}]},{id:"chapter-50",number:50,title:"A/V-(으)ㄹ 것 같아요 · V/A-(으)ㄹ 텐데",goal:"Use 날씨, 일기예보, 비, 눈, 태풍, 미세먼지, and 우산 in forecast-based plan talk.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 날씨~",cards:[{kind:"guess",word:{ko:"날씨",romanization:"nalssi",en:"weather",pos:"noun",nuance:"날씨 is the pure-Korean word for the overall feel of the weather right now and is the single most common small-talk opener in Korea. Distinguish it from the Sino-Korean 기온(氣溫, 'air-temperature'), which is the measured number, and from 일기(日氣) / 기상(氣象), which are bookish words used in 일기예보 ('weather forecast'). You almost always pair 날씨 with the descriptive adjectives 좋다, 나쁘다, 춥다, 덥다, 맑다, 흐리다. The English-speaker pitfall is double: first, English says 'the weather IS cold' so learners reach for 이다, but Korean needs the adjective verb directly — 날씨가 추워요, never 날씨가 춥다이에요. Second, when stating a plain fact about the weather, default to the subject particle 가 (날씨가 좋아요), not the topic 는; 날씨는 좋아요 sounds like you are contrasting the weather against something else that is bad."},sentence:{ko:"오늘 날씨가 어때요?",en:"How is the weather today?"},target:"날씨",options:["weather","rain","snow"],note:"Linked to dictionary card word-ext-073."},{kind:"guess",word:{ko:"일기예보",romanization:"ilgiyebo",en:"weather forecast",pos:"noun",nuance:"일기예보 is the official weather forecast you get from the news or an app (日氣豫報, literally 일기 'the day's air = weather' + 예보 'fore-report'), so it names the prediction itself, not the weather. Contrast it with plain 날씨, which is the actual weather happening now: you say 날씨가 좋아요 for today's nice weather but 일기예보가 좋아요 only when the predicted outlook is good. Koreans habitually 일기예보를 보다 (watch/read it) and judge it as 맞다 right or 틀리다 wrong, and they quote it with 일기예보에서 ~고 했어요. The English-speaker pitfall is treating it as a verb ('to forecast') — it is a noun, so attach a verb like 보다 or 확인하다, and use 에서 (the source particle) rather than 에 when reporting what it announced."},sentence:{ko:"주말 일기예보 봤어요?",en:"Did you see the weekend forecast?"},target:"일기예보",options:["rain","snow","weather forecast"],note:"Linked to dictionary card word-ext-2002."},{kind:"guess",word:{ko:"맑다",romanization:"malkda",en:"to be clear; sunny",pos:"adjective",nuance:"맑다 means CLEAR or CLEAN in the sense of pure and transparent — clear see-through water (맑은 물), a cloudless sky (맑은 하늘 = sunny), fresh unpolluted air (맑은 공기), a clear ringing sound or a clear alert mind (정신이 맑다). Its opposite is 흐리다 (cloudy/murky). The key English-speaker pitfall is using 맑다 for a tidy ROOM: English 'clean' covers both purity and tidiness, but a clean, tidy room is 깨끗하다 (방이 깨끗하다), not 맑다. Reserve 맑다 for natural clearness/transparency (water, sky, air, sound) and use 깨끗하다 for cleanliness/neatness of objects and spaces. As a weather word it pairs with 날씨 and 하늘 and is the standard term in forecasts: 내일은 맑겠습니다 (it will be clear/sunny tomorrow). Pronunciation: the ㄺ surfaces as g before a vowel, so 맑아요 is 'malg-a-yo' and 맑게 is 'mak-ge.' As a descriptive adjective it never takes 있다: 물이 맑아요, not 맑아 있어요."},sentence:{ko:"날씨가 맑아질 때 다시 예약해요.",en:"Let's book again when the weather clears."},target:"맑아",options:["to be cloudy; overcast","weather","to be clear; sunny"],note:"Linked to dictionary card word-ext-1279."},{kind:"guess",word:{ko:"흐리다",romanization:"heurida",en:"to be cloudy; overcast",pos:"adjective",nuance:"흐리다 is the all-purpose word for 'unclear,' covering CLOUDY weather (흐린 날 an overcast day), MURKY water (흐린 물), and BLURRY/out-of-focus images or hazy memories (사진이 흐리다, 기억이 흐리다). Its opposite is 맑다 (clear), and for weather these two are the everyday pair: 맑아요 (clear/sunny) ↔ 흐려요 (cloudy). The English-speaker pitfall is reaching for 흐리다 to mean DIRTY: murky water that's hard to see through is 흐리다, but water or a surface that is dirty/filthy is 더럽다 — 흐리다 is about lack of CLARITY, not presence of grime. Note also a near-synonym for blurriness: 뿌옇다/희미하다 also describe a hazy, faint look, but 흐리다 is the plain default learners should master first. The conjugation trap: like other ㅣ-stems, 흐리다 contracts in the 해요-form to 흐려요 (not 흐리어요), past 흐렸어요. As a descriptive adjective it does not take 있다: 하늘이 흐려요, not 흐려 있어요."},sentence:{ko:"내일은 흐릴 것 같아요.",en:"I think it will be cloudy tomorrow."},target:"흐릴",options:["to be clear; sunny","to be cloudy; overcast","weather"],note:"Linked to dictionary card word-ext-1280."},{kind:"guess",word:{ko:"비",romanization:"bi",en:"rain",pos:"noun",nuance:"Korean has no single verb meaning 'to rain'; instead precipitation 'arrives', so you say 비가 와요 (rain comes) using 오다. A more formal, written variant is 비가 내리다 ('rain falls'), favored in forecasts and lyrics, while 비가 오다 dominates everyday speech. To say rain stops, use the dedicated verb 그치다 (비가 그쳤어요), not 끝나다. Note 비 also forms many compounds: 소나기 (sudden shower), 장마 (the summer monsoon rains), 가랑비 (drizzle). The big English-speaker pitfall is inventing a verb: learners say 비가 해요 or 비해요 by analogy with English 'it rains', but 하다 never combines with 비 — the natural pairing is strictly 비가 오다 / 비가 내리다. A second trap is 비를 맞다 ('to take the rain on your body', i.e. get drenched), which uses 맞다, not 받다."},sentence:{ko:"비가 올 것 같아요.",en:"I think it will rain."},target:"비",options:["weather","weather forecast","rain"],note:"Linked to dictionary card word-ext-074."},{kind:"guess",word:{ko:"눈",romanization:"nun",en:"snow",pos:"noun",nuance:"눈 can mean snow or eye, and context normally makes the meaning clear. Some dictionaries mark a traditional vowel-length distinction, but many modern speakers do not preserve it consistently, so do not rely on pitch or length alone."},sentence:{ko:"눈이 올 때 길이 미끄러워요.",en:"When it snows, the roads are slippery."},target:"눈",options:["weather","weather forecast","snow"],note:"Linked to weather card word-ext-075, not the body-part card for eye."},{kind:"guess",word:{ko:"오다",romanization:"oda",en:"to come; to fall for rain/snow",pos:"verb",nuance:"오다 is from the speaker’s point of view. If someone moves toward you or your place, 오다 is usually right."},sentence:{ko:"비가 오고 눈도 와요.",en:"It rains and it also snows."},target:"오고",options:["to cancel","weather","to come; to fall for rain/snow"],note:"Linked to dictionary card word-verb-004."},{kind:"payoff",line:{speaker:"민서",ko:"주말 일기예보 봤어요?",en:"Did you see the weekend forecast?"},hl:"일기예보"}],canDo:"Make a soft weather guess from what I see (비가 올 것 같아요)",id:"chapter-50-b1",chapterId:"chapter-50",index:0},{kind:"pattern",title:"문법 Grammar · A/V-(으)ㄹ 것 같아요",cards:[{kind:"hunt",name:"A/V-(으)ㄹ 것 같아요",sub:`"I think it'll..." (a soft guess about the weather)`,lines:[{tokens:[{pre:"오늘",mid:"",post:"",hit:!1},{pre:"오후에",mid:"",post:"",hit:!1},{pre:"비가",mid:"",post:"",hit:!1},{pre:"올",mid:"",post:"",hit:!1},{pre:"",mid:"것",post:"",hit:!0},{pre:"",mid:"같아요",post:".",hit:!0}],ko:"오늘 오후에 비가 올 것 같아요.",en:"I think it's going to rain this afternoon.",romanization:"oneul ohue biga ol geot gatayo."},{tokens:[{pre:"하늘을",mid:"",post:"",hit:!1},{pre:"보니까",mid:"",post:"",hit:!1},{pre:"눈이",mid:"",post:"",hit:!1},{pre:"올",mid:"",post:"",hit:!1},{pre:"",mid:"것",post:"",hit:!0},{pre:"",mid:"같아요",post:".",hit:!0}],ko:"하늘을 보니까 눈이 올 것 같아요.",en:"Looking at the sky, I think it's going to snow.",romanization:"haneureul bonikka nuni ol geot gatayo."}],rule:{name:"A/V-(으)ㄹ 것 같아요",rows:[{when:"Verb stem ends in a vowel (오다)",add:"-ㄹ 것 같아요",ex:"오다 → 올 것 같아요 (it looks like it'll rain)"},{when:"Verb/adjective stem ends in a consonant (맑다, 좋다)",add:"-을 것 같아요",ex:"맑다 → 맑을 것 같아요 (I think it'll be clear)"},{when:"ㅂ-irregular adjective (춥다 → 추우-, 덥다 → 더우-)",add:"-ㄹ 것 같아요 (on the 우 form)",ex:"춥다 → 추울 것 같아요 (I think it'll be cold)"},{when:"ㄹ-final stem (얼다, 불다) — ㄹ stays, no extra 으",add:"-ㄹ 것 같아요",ex:"불다 → 불 것 같아요 (it looks like the wind will blow)"}]},more:{func:`Use -(으)ㄹ 것 같아요 to make a soft prediction about the weather from signs you can see — clouds, a dark sky, a dropping temperature. It is the everyday way to say "I think it's going to rain / snow / be cold." Because it is a guess, not a fact, it sounds careful and polite rather than absolute.`,keyPoint:{label:"-(으)ㄹ 것 같아요 vs. -아/어요",body:"-(으)ㄹ 것 같아요 is a guess about something not yet certain (비가 올 것 같아요 = I think it'll rain), while plain 비가 와요 states it as a present fact (it's raining). Reach for 것 같아요 when you're reading the signs, not reporting what's already true."},pronunciation:'것 같아요 is pronounced [걷 까타요]: the final ㅅ of 것 becomes a [t] stop, and the following ㄱ tenses to [ㄲ], so it sounds like "geot kkatayo."'}}],canDo:"Make a soft weather guess from what I see (비가 올 것 같아요)",id:"chapter-50-b2",chapterId:"chapter-50",index:1},{kind:"words",title:"단어 Words 2 · 태풍~",cards:[{kind:"guess",word:{ko:"태풍",romanization:"taepung",en:"typhoon",pos:"noun",nuance:"태풍 is a typhoon, the large tropical storm system that strikes Korea mainly in late summer and early autumn (颱風, literally 태 'typhoon' + 풍 'wind'). Even though the second character means wind, 태풍 is conceived as a moving body of weather, so it travels with 오다 come, 지나가다 pass, and the news verb 북상하다 move north — it does not 'blow.' That is the key contrast with plain 바람 wind, which 불다 blows: you must not say 태풍이 불어요. Distinguish it too from 폭풍 (a general violent storm, including at sea) and 돌풍 (a sudden gust); 태풍 specifically names the seasonal tropical cyclone, each one given an official name. Strength is described with 강하다/세다. The English-speaker pitfall is mapping 'the wind blows' onto 태풍 and producing 태풍이 불어요 — say instead 태풍이 와요 / 태풍이 지나가요."},sentence:{ko:"태풍이 올 것 같아서 비행기가 늦을 수도 있어요.",en:"It looks like a typhoon may come, so the plane might be late."},target:"태풍",options:["typhoon","weather","weather forecast"],note:"Linked to dictionary card word-ext-2004."},{kind:"guess",word:{ko:"황사",romanization:"hwangsa",en:"yellow dust",pos:"noun",nuance:"황사 is Sino-Korean, 黃沙 'yellow + sand', and names the seasonal haze of desert sand carried on the wind from China and Mongolia, peaking in spring. The crucial contrast is with 미세먼지 ('fine dust', fine particulate air pollution): 황사 is coarse natural desert sand, a centuries-old phenomenon, whereas 미세먼지 is man-made fine pollution measured as PM10/PM2.5 — news reports list them together but they are different things, and conflating them is the classic learner error. Note also that 황사 is described with 심하다 (severe) and the wind verb 불다/불어오다, not with 많다 or 오다. The English-speaker pitfall, beyond the 황사/미세먼지 mix-up, is reaching for 황사가 와요; in news-register Korean 황사가 심해요 or 황사가 불어와요 sounds far more natural."},sentence:{ko:"오늘은 황사가 심해요.",en:"The yellow dust is bad today."},target:"황사",options:["weather","yellow dust","weather forecast"],note:"Linked to dictionary card word-ext-816."},{kind:"guess",word:{ko:"미세먼지",romanization:"misemeonji",en:"fine dust; air pollution particles",pos:"noun",nuance:"미세먼지 is not ordinary dust in your room. It refers to air pollution particles reported in forecasts and apps."},sentence:{ko:"미세먼지가 심하면 일정은 취소하는 게 좋겠어요.",en:"If the fine dust is bad, it would be better to cancel the plan."},target:"미세먼지",options:["weather","weather forecast","fine dust; air pollution particles"],note:"Fine dust often changes outdoor plans in Korea."},{kind:"guess",word:{ko:"장마",romanization:"jangma",en:"rainy season",pos:"noun",nuance:"장마 is Korea's long early-summer monsoon, the roughly three-to-four-week stretch around late June and July when a stationary rain front parks over the peninsula and brings steady, humid rain day after day. It is a whole climatic period, not a single rainfall, so it contrasts sharply with 비 (one instance of rain) and with 소나기 (a sudden short downpour): you can have 비 during 장마, but 장마 names the season. The word is treated as native Korean (it is not a hanja compound), and it lives in fixed phrases — 장마가 시작되다/끝나다 and the compound 장마철 'rainy-season time'. The pitfall for English speakers is calling any rainy day 장마; reserve it for the seasonal monsoon, and note that 장마 takes 시작되다/끝나다 rather than the falling verbs 오다/내리다 that plain rain uses."},sentence:{ko:"장마라서 비가 많이 올 텐데 우산 챙기세요.",en:"It is rainy season, so it will probably rain a lot. Bring an umbrella."},target:"장마",options:["weather","weather forecast","rainy season"],note:"Linked to dictionary card word-ext-2003."},{kind:"guess",word:{ko:"영하",romanization:"yeongha",en:"below zero",pos:"noun",nuance:"영하(零下) is Sino-Korean — 零 'zero' + 下 'below' — meaning below 0°C. Its exact opposite is 영상(零上, 'above zero'), used for plus temperatures (영상 3도 = +3°C). The crucial structural fact, opposite to English, is word order: the marker comes BEFORE the number, so 'minus five degrees' is 영하 5도 (literally 'below-zero five degrees'), never 5도 영하. English speakers also say 'negative five' / 'minus five,' but Korean does not use 마이너스 in weather speech — it is always 영하. 영하 most often appears in winter forecasts and pairs with 떨어지다 (plunge below) and 내려가다 (drop), plus the handy forecaster word 영하권 (the subzero range). The pitfalls: (1) putting the number first (5도 영하 ✗); (2) confusing 영하 (below zero) with 영상 (above zero) — they look and sound similar but are opposites; (3) saying 마이너스 5도 in everyday weather talk, which sounds like a math/English calque rather than natural 영하 5도."},sentence:{ko:"기온이 영하로 떨어질 텐데 따뜻하게 입으세요.",en:"The temperature will probably drop below zero, so dress warmly."},target:"영하",options:["below zero","weather","weather forecast"],note:"Linked to dictionary card word-ext-1615."},{kind:"guess",word:{ko:"기온",romanization:"gion",en:"air temperature",pos:"noun",nuance:"기온 is the air temperature expressed as a number of degrees (氣溫, 기 'air/atmosphere' + 온 'warmth'), so it is the measurable reading the forecaster gives, whereas 날씨 is the whole overall feel of the weather (sunny, humid, windy) and 온도 is the neutral word for the temperature of any object or liquid like 물 온도 water temperature or 체온 body temperature. Use 기온 only for outdoor air. It pairs with 높다 high and 낮다 low, and with the motion verbs 오르다 rise and 떨어지다 fall; the big English-speaker trap is reaching for 크다/작다 (big/small) the way English lets you say a 'big' difference, but a temperature itself is 높다/낮다, and only the gap 일교차 or 차이 can be 크다."},sentence:{ko:"기온이 떨어질 것 같아요.",en:"I think the temperature will drop."},target:"기온",options:["weather","weather forecast","air temperature"],note:"Linked to dictionary card word-ext-2001."},{kind:"guess",word:{ko:"소나기",romanization:"sonagi",en:"sudden shower",pos:"noun",nuance:"소나기 is a pure native Korean word for a brief, intense burst of rain that arrives and departs suddenly — the classic summer-afternoon downpour. The dividing line from plain 비 is duration and character: 비 is rain in general (steady, all-day, or light), while 소나기 is specifically short-lived and abrupt, so Koreans typically wait it out under an awning rather than buy an umbrella. It contrasts too with 장맛비 (the long monsoon rains) and 이슬비 (drizzle). Natural partners are 내리다/오다, 그치다 (the proper verb for rain stopping — not 끝나다), and 만나다 ('get caught in'). The English-speaker pitfall is using 소나기 for any rain: it must be brief and sudden, and remember it takes the ordinary rain verbs 오다/내리다, with no special verb of its own."},sentence:{ko:"오후에 소나기가 올 수도 있어요.",en:"There may be a sudden shower in the afternoon."},target:"소나기",options:["weather","sudden shower","weather forecast"],note:"Linked to dictionary card word-ext-817."},{kind:"payoff",line:{speaker:"지훈",ko:"태풍이 올 것 같아서 비행기가 늦을 수도 있어요.",en:"It looks like a typhoon may come, so the plane might be late."},hl:"태풍"}],canDo:"Forecast a likely situation and add advice (추울 텐데 우산을 가져오세요)",id:"chapter-50-b3",chapterId:"chapter-50",index:2},{kind:"pattern",title:"문법 Grammar · V/A-(으)ㄹ 텐데",cards:[{kind:"hunt",name:"V/A-(으)ㄹ 텐데",sub:`"it'll probably... so" (a likely situation plus concern)`,lines:[{tokens:[{pre:"밖에",mid:"",post:"",hit:!1},{pre:"추울",mid:"",post:"",hit:!1},{pre:"",mid:"텐데",post:"",hit:!0},{pre:"코트를",mid:"",post:"",hit:!1},{pre:"입으세요.",mid:"",post:"",hit:!1}],ko:"밖에 추울 텐데 코트를 입으세요.",en:"It'll probably be cold outside, so please wear a coat.",romanization:"bakke chuul tende koteureul ibeuseyo."},{tokens:[{pre:"오후에",mid:"",post:"",hit:!1},{pre:"비가",mid:"",post:"",hit:!1},{pre:"올",mid:"",post:"",hit:!1},{pre:"",mid:"텐데",post:"",hit:!0},{pre:"우산을",mid:"",post:"",hit:!1},{pre:"가져가세요.",mid:"",post:"",hit:!1}],ko:"오후에 비가 올 텐데 우산을 가져가세요.",en:"It'll probably rain in the afternoon, so take an umbrella.",romanization:"ohue biga ol tende usaneul gajyeogaseyo."}],rule:{name:"V/A-(으)ㄹ 텐데",rows:[{when:"Verb/adjective, vowel-ending stem (오다)",add:"-ㄹ 텐데",ex:"오다 → 올 텐데 (it'll probably rain, so...)"},{when:"Verb/adjective, consonant-ending stem (좋다, 많다)",add:"-을 텐데",ex:"많다 → 많을 텐데 (there'll probably be a lot, so...)"},{when:"ㅂ-irregular adjective (춥다 → 추우-, 덥다 → 더우-)",add:"-ㄹ 텐데 (on the 우 form)",ex:"춥다 → 추울 텐데 (it'll probably be cold, so...)"},{when:"Past situation (already likely happened)",add:"-았/었을 텐데",ex:"얼다 → 얼었을 텐데 (it must have frozen, so...)"}]},more:{func:`Use -(으)ㄹ 텐데 to predict a likely situation and then add worry, advice, or a suggestion about it. It is the warm "it'll probably rain, so (take an umbrella)" pattern — you forecast something and immediately care about its effect on the listener. The 텐데 part leaves the sentence half-open, inviting a follow-up clause.`,keyPoint:{label:"-(으)ㄹ 텐데 vs. -(으)ㄹ 것 같아요",body:"Both predict, but -(으)ㄹ 것 같아요 just states the guess and stops (비가 올 것 같아요 = I think it'll rain). -(으)ㄹ 텐데 predicts and then leans into a consequence — concern or advice — so it almost always has a second clause: 비가 올 텐데 우산을 가져가세요 (it'll rain, so take an umbrella)."},pronunciation:'올 텐데 links smoothly into one breath group — "ol-ten-de," no pause — so the forecast flows straight into the advice. 텐데 itself is read [텐데] as written.'}}],canDo:"Forecast a likely situation and add advice (추울 텐데 우산을 가져오세요)",id:"chapter-50-b4",chapterId:"chapter-50",index:3},{kind:"words",title:"단어 Words 3 · 안개~",cards:[{kind:"guess",word:{ko:"안개",romanization:"angae",en:"fog",pos:"noun",nuance:"안개 is fog or mist — the cloud of tiny water droplets near the ground that cuts visibility. Its defining grammar is the verb 끼다, the same verb used for clouds 구름이 끼다, meaning the haze 'settles in,' so 안개가 끼다 is the standard way to say it gets foggy and 안개가 걷히다 that it lifts. Density is expressed with 짙다 thick and 옅다 thin — never the physical-thickness word 두껍다 — and a thick fog is 짙은 안개. 안개 is a native Korean noun (no hanja), and a close relative is 안개비 'misty drizzle.' The crucial pitfall for English speakers is the verb: do not say 안개가 와요 (treating fog like rain) and do not say 안개가 두꺼워요 by translating 'thick fog' literally; say 안개가 끼다 and 안개가 짙다."},sentence:{ko:"안개 때문에 앞이 잘 안 보여요.",en:"I cannot see well ahead because of the fog."},target:"안개",options:["weather","weather forecast","fog"],note:"Linked to dictionary card word-ext-2006."},{kind:"guess",word:{ko:"우산",romanization:"usan",en:"umbrella",pos:"noun",nuance:"우산 is Sino-Korean 雨傘, literally 雨 'rain' + 傘 'umbrella/parasol' — so the word transparently means 'rain-umbrella', which is your built-in reminder it's for rain. The verb is the deceptively busy 쓰다: to put up/use an umbrella is 우산을 쓰다, the same 쓰다 that covers wearing a hat (모자를 쓰다) and glasses (안경을 쓰다) — Korean groups 'things over your head/face' under 쓰다, distinct from 입다 (clothes on the torso/legs) and 신다 (footwear). The contrast to file away is 우산 vs 양산: both are 傘, but 우산 (雨傘) is the rain umbrella while 양산 (陽傘, 'sun-shade') is a parasol against sunlight — different words for different weather. Useful collocations: 우산을 쓰다/접다/펴다 (put up / fold / open an umbrella), 우산을 챙기다 (remember to grab an umbrella), 우산을 깜빡하다 (forget the umbrella). A folding umbrella is 접는 우산 or 3단 우산, a long one 장우산. Pitfall: English 'wear/carry an umbrella' must become 쓰다 (use over the head), never 입다, and don't reuse 우산 for a sun parasol — that's 양산."},sentence:{ko:"비가 오면 우산을 가져가세요.",en:"If it rains, take an umbrella."},target:"우산",options:["weather","umbrella","weather forecast"],note:"Linked to dictionary card word-ext-1385."},{kind:"guess",word:{ko:"일정",romanization:"iljeong",en:"schedule; plan",pos:"noun",nuance:"일정 is the planned schedule of where you go and what you do, day by day — for a trip, but equally for work or events. The hanja 日程 is 日 (day) + 程 (journey/measure), an 'apportioning of the days'. Distinguish it from 시간 (time, clock time) and 계획 (plan): 시간 is just the hour on the clock, 계획 is the broad intention ('I plan to save money'), while 일정 is the concrete time-tabled sequence of items. Note the signature verb 짜다 — you 일정을 짜다 (literally 'weave a schedule'), the same verb used for 계획을 짜다. Watch the adjective 빡빡하다 / 바쁘다 for a packed itinerary. English-speaker pitfall: don't reach for 시간 when you mean the agenda — '오늘 시간이 어때요?' asks if someone is free, but '오늘 일정이 어때요?' asks about the day's plan."},sentence:{ko:"미세먼지 때문에 일정을 취소했어요.",en:"We canceled the plan because of fine dust."},target:"일정",options:["weather","schedule; plan","weather forecast"],note:"Linked to dictionary card word-ext-440."},{kind:"guess",word:{ko:"취소하다",romanization:"chwisohada",en:"to cancel",pos:"verb",nuance:"취소하다 (取消하다, 取 'take' + 消 'extinguish/erase') means to cancel — to call off or undo something already arranged: a reservation, an order, an appointment, a plan. The neat way to remember it: it's the natural opposite of 예약하다/신청하다 (book/apply). Distinguish it from 그만두다, which is 'to quit/stop' an ongoing activity or job (회사를 그만두다, 'quit the company'; 운동을 그만두다, 'stop exercising'): you 취소해요 a future arrangement, but you 그만둬요 something already in progress. It also differs from 미루다 ('postpone', 약속을 미루다, push the appointment later rather than scrap it) — canceling removes it, postponing reschedules it. As a noun+하다 verb it's regular: 취소하 + 여요 → 취소해요, past 취소했어요, with 안/못 before 하다 (취소 안 해요, 취소 못 해요). English-speaker pitfall: 'cancel my subscription / unsubscribe' is more often 해지하다 (解止, end a contract) than 취소하다, and don't use 취소하다 for 'quit a job' — that's 그만두다."},sentence:{ko:"미세먼지가 심하면 일정을 취소해요.",en:"If the fine dust is bad, we cancel the plan."},target:"취소해",options:["to come; to fall for rain/snow","to cancel","weather"],note:"Linked to dictionary card word-verb-483."},{kind:"guess",word:{ko:"비행기",romanization:"bihaenggi",en:"airplane; flight",pos:"noun",nuance:"비행기 (飛行機, literally 'fly-go-machine') is the everyday spoken word for an airplane — the aircraft you board for trips abroad or across the country. Its near-synonym 항공기 means the same machine but is a stiffer, technical/news register ('aircraft'), and the ticket has its own formal twin: spoken 비행기 표 vs. written/official 항공권. It collocates with 타다 (board), 표/항공권 (ticket), 예약하다 (reserve), 연착되다 (be delayed), 환승하다 (transfer), and 공항 (airport). As with all vehicles, the pitfall is the particle: 'get on the plane' tempts 비행기에 타요, but Korean wants the object marker — 비행기를 타요. A second subtle trap is 타다 vs 내리다: you board with 비행기를 타다 (object) but disembark with 비행기에서 내리다 (source), so the particle flips between getting on and getting off."},sentence:{ko:"태풍 때문에 비행기가 늦었어요.",en:"The plane was late because of the typhoon."},target:"비행기",options:["weather","airplane; flight","weather forecast"],note:"Linked to dictionary card word-ext-146."},{kind:"payoff",line:{speaker:"지훈",ko:"태풍이 올 것 같아서 비행기가 늦을 수도 있어요.",en:"It looks like a typhoon may come, so the plane might be late."},hl:"비행기"}],canDo:"Set up a weather condition and its result (비가 오면 집에 있어요)",id:"chapter-50-b5",chapterId:"chapter-50",index:4},{kind:"pattern",title:"문법 Grammar · A/V-(으)면",cards:[{kind:"hunt",name:"A/V-(으)면",sub:'"if / when the weather is like this" (condition)',lines:[{tokens:[{pre:"비가",mid:"",post:"",hit:!1},{pre:"오",mid:"면",post:"",hit:!0},{pre:"집에",mid:"",post:"",hit:!1},{pre:"있을",mid:"",post:"",hit:!1},{pre:"거예요.",mid:"",post:"",hit:!1}],ko:"비가 오면 집에 있을 거예요.",en:"If it rains, I'll stay home.",romanization:"biga omyeon jibe isseul geoyeyo."},{tokens:[{pre:"봄이",mid:"",post:"",hit:!1},{pre:"오",mid:"면",post:"",hit:!0},{pre:"꽃이",mid:"",post:"",hit:!1},{pre:"펴요.",mid:"",post:"",hit:!1}],ko:"봄이 오면 꽃이 펴요.",en:"When spring comes, flowers bloom.",romanization:"bomi omyeon kkochi pyeoyo."}],rule:{name:"A/V-(으)면",rows:[{when:"Stem ends in a vowel (오다, 따뜻하다)",add:"-면",ex:"오다 → 오면 (if/when it rains)"},{when:"Stem ends in a consonant (좋다, 많다)",add:"-으면",ex:"좋다 → 좋으면 (if the weather is good)"},{when:"ㅂ-irregular adjective (덥다 → 더우-, 춥다 → 추우-)",add:"-면 (on the 우 form)",ex:"덥다 → 더우면 (if it's hot)"},{when:"Past/completed condition",add:"-았/었으면",ex:"그치다 → 그쳤으면 (if the rain/snow has stopped)"}]},more:{func:`Use -(으)면 to set up a weather condition and its result: "if it rains, I'll stay home," "when spring comes, flowers bloom." It covers both English "if" (a possibility) and "when" (a regular trigger) — exactly how Koreans talk about weather shaping everyday decisions.`,keyPoint:{label:"-(으)면 vs. -(으)니까",body:"-(으)면 introduces a condition that may or may not happen (비가 오면 = if/when it rains — uncertain). -(으)니까 gives a reason that is already true (비가 오니까 = since it's raining — a fact right now). Use -면 for forecasts and rules, -니까 for what's actually happening."},pronunciation:`좋으면 is pronounced [조으면]: the ㅎ of 좋 goes silent (ㅎ-탈락) before the vowel 으, so it's "jo-eu-myeon," not "joh-eu-myeon."`}}],canDo:"Set up a weather condition and its result (비가 오면 집에 있어요)",id:"chapter-50-b6",chapterId:"chapter-50",index:5},{kind:"pattern",title:"문법 Grammar · N 때문에",cards:[{kind:"hunt",name:"N 때문에",sub:'"because of..." (a weather cause)',lines:[{tokens:[{pre:"비",mid:"",post:"",hit:!1},{pre:"",mid:"때문에",post:"",hit:!0},{pre:"소풍이",mid:"",post:"",hit:!1},{pre:"취소됐어요.",mid:"",post:"",hit:!1}],ko:"비 때문에 소풍이 취소됐어요.",en:"The picnic was cancelled because of the rain.",romanization:"bi ttaemune sopungi chwisodwaesseoyo."},{tokens:[{pre:"더위",mid:"",post:"",hit:!1},{pre:"",mid:"때문에",post:"",hit:!0},{pre:"잠을",mid:"",post:"",hit:!1},{pre:"못",mid:"",post:"",hit:!1},{pre:"잤어요.",mid:"",post:"",hit:!1}],ko:"더위 때문에 잠을 못 잤어요.",en:"I couldn't sleep because of the heat.",romanization:"deowi ttaemune jameul mot jasseoyo."}],rule:{name:"N 때문에",rows:[{when:"Noun ending in a vowel (비, 더위)",add:"+ 때문에",ex:"비 → 비 때문에 (because of the rain)"},{when:"Noun ending in a consonant (태풍, 눈)",add:"+ 때문에 (no change)",ex:"태풍 → 태풍 때문에 (because of the typhoon)"},{when:'"because it is N" (noun as reason-state)',add:"+ (이)기 때문에",ex:"여름 → 여름이기 때문에 (because it's summer)"},{when:"Adjective/verb cause (the related form)",add:"-기 때문에",ex:"춥다 → 춥기 때문에 (because it's cold)"}]},more:{func:'Use N 때문에 to name a noun — usually a weather event — as the cause of something, especially something inconvenient: "because of the rain," "because of the heat." It attaches straight to a noun and is the everyday way to blame the weather for a delay, a cancellation, or how you feel.',keyPoint:{label:"N 때문에 vs. N 덕분에",body:`때문에 is neutral-to-negative — you usually blame it for trouble (비 때문에 취소됐어요 = cancelled because of the rain). For a good outcome, Koreans switch to 덕분에 "thanks to" (좋은 날씨 덕분에 = thanks to the nice weather). Don't use 때문에 to thank the weather.`},pronunciation:'때문에 is pronounced [때무네]: the ㄴ of 문 links into the following 에 (연음), so it sounds like "ttae-mu-ne," run together as one word after the noun.'}}],canDo:"Name a weather event as the cause (비 때문에, 황사 때문에)",id:"chapter-50-b7",chapterId:"chapter-50",index:6},{kind:"pattern",title:"문법 Grammar · V/A-(으)ㄹ 때",cards:[{kind:"teach",name:"V/A-(으)ㄹ 때",sub:"when (a time or situation)",rows:[{when:"Stem ends in a vowel",add:"-ㄹ 때",ex:"오다 → 올 때 (when it comes/rains)"},{when:"Stem ends in a consonant",add:"-을 때",ex:"춥다 → 추울 때 (when it's cold)"},{when:"A past time",add:"-았/었을 때",ex:"비가 왔을 때 (when it rained)"}],examples:[{ko:"비가 올 때 우산을 써요.",en:"When it rains, I use an umbrella.",romanization:"biga ol ttae usaneul sseoyo.",note:"오다 → 올 때. The 때 clause sets the time for the main action."},{ko:"날씨가 추울 때 집에 있어요.",en:"When the weather is cold, I stay home.",romanization:"nalssiga chuul ttae jibe isseoyo.",note:"춥다 (ㅂ-irregular) → 추울 때."}],more:{func:`-(으)ㄹ 때 marks the time or situation when something happens: "when it rains," "when it's cold." Attach it to a verb or adjective stem; for a past time, use -았/었을 때.`,keyPoint:{label:"때 is a noun, so use the -(으)ㄹ modifier",body:'때 means "time," so the verb in front must be in the noun-modifying -(으)ㄹ form: 올 때, 추울 때 — never 와 때 or 춥어 때. For a finished past time, use -았/었을 때 (왔을 때).'},pronunciation:"때 begins with the tense consonant ㄸ — say it hard: 올 때 is [올 때], not a soft [대]."}}],canDo:"Point to a time or situation when something happens (추울 때)",id:"chapter-50-b8",chapterId:"chapter-50",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two friends check the forecast before a weekend trip and decide what to do with their plan.",lines:[{speaker:"민서",ko:"주말 일기예보 봤어요?",en:"Did you see the weekend forecast?",romanization:"jumal ilgiyebo bwasseoyo?"},{speaker:"지훈",ko:"태풍이 올 것 같아서 비행기가 늦을 수도 있어요.",en:"It looks like a typhoon may come, so the plane might be late.",romanization:"taepungi ol geot gataseo bihaenggiga neujeul sudo isseoyo."},{speaker:"민서",ko:"미세먼지가 심하면 일정은 취소하는 게 좋겠어요.",en:"If the fine dust is bad, it would be better to cancel the plan.",romanization:"misemeonjiga simhamyeon iljeongeun chwisohaneun ge jotgesseoyo."},{speaker:"지훈",ko:"날씨가 맑아질 때 다시 예약해요.",en:"Let's book again when the weather clears.",romanization:"nalssiga malgajil ttae dasi yeyakhaeyo."}]},{kind:"order",prompt:"Build: 'Because of fine dust, I canceled the plan.'",tokens:["미세먼지 때문에","일정을 취소했어요"],correct:"미세먼지 때문에 일정을 취소했어요",explanation:"N 때문에 names the weather or pollution cause. 일정을 취소했어요 gives the concrete decision."}],canDo:"Make a soft weather guess from what I see (비가 올 것 같아요)",id:"chapter-50-b9",chapterId:"chapter-50",index:8},{kind:"reading",title:"읽기 Reading · 태풍이 올 것 같아서 일정을 바꿔요",cards:[{kind:"read",title:"태풍이 올 것 같아서 일정을 바꿔요",chunks:["민서는 주말 일기예보를 봤어요. 태풍이 올 것 같아서 비행기가 늦을 수도 있었어요. 또 미세먼지가 심하면 밖에서 오래 있기 어려워요.","그래서 친구에게 '미세먼지가 심하면 일정은 취소하는 게 좋겠어요'라고 보냈어요. 친구는 날씨가 맑아질 때 다시 예약하자고 했어요. 이처럼 날씨 표현은 단순히 하늘을 설명하는 말이 아니라, 약속과 여행 계획을 바꾸는 말로 자주 쓰여요."],translation:"Minseo checked the weekend forecast. A typhoon might come, so the plane could be late. If fine dust is bad, it is hard to stay outside for long. Minseo texted that it would be better to cancel the plan if the fine dust was bad. The friend suggested booking again when the weather clears. Weather expressions often change appointments and travel plans.",qas:[{q:"민서는 무엇을 봤어요?",a:"주말 일기예보를 봤어요."},{q:"태풍이 오면 무엇이 늦을 수도 있어요?",a:"비행기가 늦을 수도 있어요."},{q:"언제 다시 예약하기로 했어요?",a:"날씨가 맑아질 때 다시 예약하기로 했어요."}]}],canDo:"Forecast a likely situation and add advice (추울 텐데 우산을 가져오세요)",id:"chapter-50-b10",chapterId:"chapter-50",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence gives a cautious weather forecast?",sentence:null,options:[{text:"비가 올 것 같아요.",ok:!0},{text:"비가 때문에 올 것 같아요.",ok:!1},{text:"비에게 올 것 같아요.",ok:!1}],explanation:"-(으)ㄹ 것 같아요 makes a cautious guess, and 비 uses the subject particle 가."},{kind:"drill",prompt:"Which sentence correctly uses 눈 as weather?",sentence:null,options:[{text:"눈이 올 때 길이 미끄러워요.",ok:!0},{text:"눈이 아플 때 길이 미끄러워요.",ok:!1},{text:"눈을 볼 때 눈이 와요.",ok:!1}],explanation:"In this chapter, 눈 is snow. 눈이 오다 means 'it snows.'"},{kind:"drill",prompt:"Which sentence names fine dust as the cause of canceling?",sentence:null,options:[{text:"미세먼지 때문에 취소해요.",ok:!0},{text:"미세먼지가 때문에 취소해요.",ok:!1},{text:"미세먼지를 때문에 취소해요.",ok:!1}],explanation:"Use noun plus 때문에 without adding 가 or 를."},{kind:"drill",prompt:"비___ 오면 우산을 가져가요. (If it rains, take an umbrella.)",sentence:null,options:[{text:"가",ok:!0},{text:"를",ok:!1},{text:"에서",ok:!1}],explanation:"비 is the subject of 오다, so it takes 가. 를 would make rain an object."},{kind:"order",prompt:"Build: 'Because of fine dust, I canceled the plan.'",tokens:["미세먼지 때문에","일정을 취소했어요"],correct:"미세먼지 때문에 일정을 취소했어요",explanation:"N 때문에 names the weather or pollution cause. 일정을 취소했어요 gives the concrete decision."},{kind:"drill",prompt:"Which sentence delays a plan because the weather may clear later?",sentence:null,options:[{text:"날씨가 맑아질 때 다시 예약해요.",ok:!0},{text:"날씨가 맑은 때문에 예약해요.",ok:!1},{text:"날씨를 맑으면 예약해요.",ok:!1}],explanation:"-ㄹ 때 marks the situation/time when the weather clears. The other options mix the weather word with the wrong particles or endings."}],canDo:"Set up a weather condition and its result (비가 오면 집에 있어요)",id:"chapter-50-b11",chapterId:"chapter-50",index:10}]},{id:"chapter-51",number:51,title:"V-아/어 보세요 · V-아/어 주시겠어요?",goal:"Use clothing words with 입다, 신다, 사이즈가 맞다, and 잘 어울리다.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 옷~",cards:[{kind:"guess",word:{ko:"옷",romanization:"ot",en:"clothes",pos:"noun",nuance:"옷 is a pure native Korean word (no hanja) meaning clothes/clothing for the body, and the verb you MUST pair it with is 입다 (to wear on the torso/body) — never 신다, which is reserved for footwear on the feet (신발을 신다), nor 쓰다 (hats/glasses) nor 끼다 (gloves/rings). English 'wear/put on' covers every garment with one verb, so this split is the central pitfall: 옷을 신어요 is a classic beginner error. To take clothes off is 벗다, to change them 갈아입다. For 'these clothes look good on you,' Korean says 옷이 잘 어울려요 (the clothes suit you), not a direct translation of 'you look good.' Note 옷 is treated as singular/uncountable grammatically (no plural needed): one outfit or a wardrobe full is still just 옷. The dressier counterpart 의상 (costume/attire, 衣裳) is for performances or formal contexts. Register is neutral and everyday."},sentence:{ko:"이 옷이 잘 어울려요.",en:"This outfit suits you well."},target:"옷",options:["shirt","T-shirt","clothes"],note:"Linked to dictionary card word-ext-067."},{kind:"guess",word:{ko:"셔츠",romanization:"syeocheu",en:"shirt",pos:"noun",nuance:"셔츠 is the loanword for a collared upper-body shirt; the general Sino-Korean cover term for any top is 상의 (上衣, 'upper garment'), and a knit pullover is 티셔츠/티. Because a shirt covers the torso it ALWAYS takes 입다 ('put on the body'), the same family of dressing verbs that splits by body zone in Korean: 입다 for trunk and legs, 신다 for feet, 쓰다 for the head/face, 끼다 for hands. The single biggest English-speaker pitfall is treating 'wear' as one verb the way English does — you cannot say 셔츠를 써요 or 셔츠를 신어요. Register is neutral and the word fits any politeness level. Natural collocations: 셔츠를 입다/벗다 (put on/take off), 셔츠를 다리다 (iron a shirt), 셔츠가 (안) 맞다 (it does (not) fit). Note that to take a shirt off you switch to 벗다, not a negated 입다."},sentence:{ko:"이 셔츠 입어 봐도 돼요?",en:"May I try on this shirt?"},target:"셔츠",options:["clothes","shirt","pants"],note:"Linked to dictionary card word-ext-229."},{kind:"guess",word:{ko:"티셔츠",romanization:"tisyeocheu",en:"T-shirt",pos:"noun",nuance:"티셔츠 is a direct loanword from English 'T-shirt' (named for its T shape), and it specifically means a pull-over knit top — most often short-sleeved cotton. The key contrast English speakers miss is 티셔츠 vs 셔츠: in Korean 셔츠 by itself implies a button-up collared shirt (a dress shirt / 와이셔츠), so a casual tee must keep the 티 to stay distinct. Sleeve length is built right into the noun phrase: 반팔 티셔츠 (half-sleeve) vs 긴팔 티셔츠 (long-sleeve). Register is casual and neutral. The pitfalls: (1) the verb is 입다, never 신다; (2) thin tees are frequently counted with 장 ('흰 티 한 장' = one plain white tee), though 벌 also works for an outfit; and (3) Koreans clip it to 티 in speech (흰 티, 검은 티), so don't be thrown when the 셔츠 disappears."},sentence:{ko:"여름에는 티셔츠를 자주 입어요.",en:"I often wear T-shirts in summer."},target:"티셔츠",options:["clothes","T-shirt","pants"],note:"Linked to dictionary card word-ext-1887."},{kind:"guess",word:{ko:"바지",romanization:"baji",en:"pants",pos:"noun",nuance:"바지 covers the lower body, so despite English treating 'pants' as plural, Korean treats it as a single uncountable garment: there is no plural ending, no 'a pair' built into the word, and the verb is 입다 just like a shirt. The dividing line with footwear matters — legs use 입다 but the feet that stick out below use 신다, so you 입다 your 바지 but 신다 your 양말. Jeans are 청바지 (靑—, 'blue-color pants'), shorts are 반바지 ('half pants'), and dress slacks are often just called 슬랙스. The classic English-speaker error is the literal plural reflex — saying 바지들이 길어요 sounds as odd as saying 'pantses'. Natural collocations: 바지를 입다/벗다, 바지를 갈아입다 (change into other pants), 바지 길이를 줄이다 (shorten), 바지가 끼다 (the pants are tight). Note 끼다 here means 'feel tight', a different sense from putting gloves on."},sentence:{ko:"바지가 조금 커 보여요.",en:"The pants look a little big."},target:"바지",options:["clothes","pants","shirt"],note:"Linked to dictionary card word-ext-230."},{kind:"guess",word:{ko:"치마",romanization:"chima",en:"skirt",pos:"noun",nuance:"치마 is the native Korean word for a skirt and is purely neutral; the English loanword 스커트 exists but 치마 is what people actually say in daily life, and a traditional hanbok skirt is also 치마. Like all lower-body clothing it takes 입다, and to take it off you switch to 벗다 — never a negated 입다. The trap for English speakers is again the one-word-'wear' habit plus assuming a fancier loanword is more polite; here the plain native 치마 is the unmarked, fully appropriate choice in every register. A very useful partner verb is 어울리다 ('to suit/match'), used with the marker -이/가 for the item and -에게/한테 for the person: 그 치마가 너한테 잘 어울려. Natural collocations: 치마를 입다/벗다, 짧은/긴 치마 (short/long skirt), 치마가 어울리다, 치마를 갈아입다. Do not confuse 어울리다 (looks good on) with 맞다 (fits in size) — a skirt can 맞다 yet not 어울리다."},sentence:{ko:"이 구두가 치마하고 잘 어울려요.",en:"These dress shoes go well with the skirt."},target:"치마",options:["clothes","skirt","shirt"],note:"Linked to dictionary card word-ext-231."},{kind:"guess",word:{ko:"원피스",romanization:"wonpiseu",en:"dress",pos:"noun",nuance:"원피스 is a loanword from English 'one-piece', and that literal sense is the whole point: it's a dress where top and skirt are a single connected garment, as opposed to a 투피스 ('two-piece', a matching top-and-skirt set). The sharp contrast English speakers must learn is 원피스 vs 드레스: everyday casual or work dresses are 원피스, while 드레스 in Korean is reserved for a formal gown — a wedding dress (웨딩드레스) or evening gown — so calling your sundress a 드레스 sounds like you're going to a gala. The word is essentially female-coded. Register is neutral. Pitfalls: (1) the verb is 입다; (2) compliment the fit with 어울리다 ('it suits you'), the single most useful clothes-shopping verb; (3) count with 벌, and (4) never split a 원피스 into separates — that's literally a 투피스."},sentence:{ko:"이 원피스는 면접에는 조금 화려해 보여요.",en:"This dress looks a little flashy for an interview."},target:"원피스",options:["clothes","shirt","dress"],note:"Linked to dictionary card word-ext-1889."},{kind:"guess",word:{ko:"코트",romanization:"koteu",en:"coat",pos:"noun",nuance:"코트 is a loanword for a warm outer layer; the broader native umbrella term for any outerwear is 외투 (外套, 'outer wrap'), and a padded winter jacket is 패딩 or 점퍼. Even though it is the outermost layer, 코트 still takes 입다 because the rule keys off the body zone (trunk), not how many layers are underneath; you put it on with 입다 and take it off with 벗다. The English-speaker pitfall is pronunciation-driven spelling and the 'wear' reflex: 코트 is two clean syllables (ko-teu) and is never said with 쓰다 or 차다. A second subtlety: when you mean 'put a coat ON over other clothes' Koreans often say 코트를 걸치다 ('throw on lightly'), a nuance 입다 alone doesn't carry. Natural collocations: 코트를 입다/벗다, 코트를 걸치다 (drape on), 두꺼운/긴 코트, 코트 단추를 잠그다 (button up the coat). Note 걸치다 implies a casual, partial wearing, unlike the full 입다."},sentence:{ko:"이 코트는 비싸 보여요.",en:"This coat looks expensive."},target:"코트",options:["coat","clothes","shirt"],note:"Linked to dictionary card word-ext-232."},{kind:"payoff",line:{speaker:"손님",ko:"이 셔츠 입어 봐도 돼요?",en:"May I try on this shirt?"},hl:"셔츠"}],canDo:"Invite someone to try something on (한번 입어 보세요)",id:"chapter-51-b1",chapterId:"chapter-51",index:0},{kind:"pattern",title:"문법 Grammar · V-아/어 보세요",cards:[{kind:"hunt",name:"V-아/어 보세요",sub:"Try doing it",lines:[{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"원피스",mid:"",post:"",hit:!1},{pre:"한번",mid:"",post:"",hit:!1},{pre:"입",mid:"어",post:"",hit:!0},{pre:"",mid:"보세요",post:".",hit:!0}],ko:"이 원피스 한번 입어 보세요.",en:"Try this dress on.",romanization:"i wonpiseu hanbeon ibeo boseyo."},{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"모자도",mid:"",post:"",hit:!1},{pre:"써",mid:"",post:"",hit:!1},{pre:"",mid:"보세요",post:".",hit:!0}],ko:"이 모자도 써 보세요.",en:"Try this hat on too.",romanization:"i moja-do sseo boseyo."}],rule:{name:"V-아/어 보세요",rows:[{when:"Verb stem ends in ㅏ or ㅗ",add:"-아 보세요",ex:"사다 → 사 보세요 (try buying it)"},{when:"Verb stem ends in any other vowel or a consonant",add:"-어 보세요",ex:"입다 → 입어 보세요 (try wearing it), 신다 → 신어 보세요 (try them on)"},{when:"하다 verbs",add:"해 보세요",ex:"착용하다 → 착용해 보세요 (try wearing it on)"}]},more:{func:"Suggest that the listener try an action to see how it goes — perfect for inviting someone to try a piece of clothing on, try a color, or give a style a go. It softens a plain command into friendly encouragement: go ahead and try it.",keyPoint:{label:"-(으)세요 vs -아/어 보세요",body:"입으세요 = Put it on (a plain polite command). 입어 보세요 = Try it on (and see) — it adds the nuance of testing or experiencing, which is why a shop clerk says 입어 보세요, not 입으세요."},pronunciation:""}},{kind:"drill",prompt:"Try these shoes on.",sentence:"이 신발 신___.",options:[{text:"어 보세요",ok:!0},{text:"보세요",ok:!1}],explanation:"신다 = to wear on the feet. Each clothing verb is different, but all combine the same way with 보세요."}],canDo:"Invite someone to try something on (한번 입어 보세요)",id:"chapter-51-b2",chapterId:"chapter-51",index:1},{kind:"words",title:"단어 Words 2 · 운동화~",cards:[{kind:"guess",word:{ko:"운동화",romanization:"undonghwa",en:"sneakers",pos:"noun",nuance:"운동화 (運動靴, 運動 'exercise/movement' + 靴 'shoe', literally 'exercise-shoe') means sneakers/trainers, and like all 신발 (footwear) it takes 신다, the foot-zone verb shared with socks; it never takes 입다. The near-synonym to keep straight is 구두 (dress/leather shoes): both are shoes and both use 신다 and 켤레, but 운동화 is casual/athletic while 구두 is formal — so the choice signals register, not grammar. A pair is counted with 켤레. The English-speaker pitfalls: the single-'wear' habit, and forgetting that the generic word for any shoe is 신발, with 운동화 being one specific type. To take shoes off — a daily act before entering Korean homes — you use 벗다 (신발을 벗다). Natural collocations: 운동화를 신다/벗다, 운동화 한 켤레, 운동화 끈을 묶다 (tie the laces), 운동화가 편하다/낡다 (comfy/worn out). Note 끈을 묶다 ('tie the laces') uses 묶다, and 낡다 ('wear out with age') is the adjective for worn shoes."},sentence:{ko:"이 운동화도 신어 봐도 돼요?",en:"May I try on these sneakers too?"},target:"운동화",options:["clothes","shirt","sneakers"],note:"Linked to dictionary card word-ext-239."},{kind:"guess",word:{ko:"구두",romanization:"gudu",en:"dress shoes",pos:"noun",nuance:"구두 is the native everyday word for formal leather shoes (often dress/heeled shoes), and like all footwear it takes 신다 and is counted with 켤레; it never takes 입다. The key contrast is with 운동화 (sneakers): grammatically identical — both 신다, both 켤레 — but 구두 carries a formal, dressed-up register (worn with a suit, 정장, to work or interviews) while 운동화 is casual and athletic, so picking the right noun signals the occasion. The broad cover term for any shoe remains 신발. English-speaker pitfalls: the 'wear = one verb' reflex, and assuming 'shoes' is one word — Korean forces you to choose 구두 vs 운동화 vs the generic 신발 by formality. Because Koreans remove shoes indoors, 벗다 (신발/구두를 벗다) is a verb you will use daily, and 갈아 신다 means swapping footwear. Natural collocations: 구두를 신다/벗다, 구두 한 켤레, 구두를 닦다 (polish dress shoes), 구두 굽 (the heel of the shoe). Note 닦다 ('shine/polish') pairs especially with leather 구두, and 굽 is the heel."},sentence:{ko:"면접에는 운동화보다 구두가 더 단정해 보여요.",en:"For an interview, dress shoes look more presentable than sneakers."},target:"구두",options:["clothes","dress shoes","shirt"],note:"Linked to dictionary card word-ext-240."},{kind:"guess",word:{ko:"색깔",romanization:"saekkkal",en:"color",pos:"noun",nuance:"색깔 is the everyday, standalone word for 'color,' built on the Sino-Korean root 색 (色 'color') plus a native suffix that makes it feel fuller and more conversational. Its near-synonym is just 색: the dividing line is grammatical, not meaning — 색깔 stands on its own (색깔이 예뻐요, 무슨 색깔?), while 색 is the building block that fuses to a specific shade name (파란색 blue, 빨간색 red, 노란색 yellow). A more formal, technical synonym is 색상, common in design and shopping ('color option'). The main English-speaker pitfall is over-using 색깔 by sticking it onto shade names — '파란색깔' is wrong; the named colors take 색, giving 파란색. Also, to ask 'what color,' the natural question word is 무슨 색깔, not 어떤 색깔 (which leans toward 'what kind/sort of color')."},sentence:{ko:"다른 색깔도 보여 주시겠어요?",en:"Could you show me another color too?"},target:"색깔",options:["clothes","color","shirt"],note:"Linked to dictionary card word-ext-1638."},{kind:"guess",word:{ko:"남색",romanization:"namsaek",en:"navy; deep blue",pos:"noun",nuance:"남색 is the deep, near-ink blue of school uniforms, business suits, and dark denim. The 남 is Sino-Korean 藍 ('indigo', the dye plant), so the word literally means 'indigo-color' — a good reminder that it lives at the DARK end of blue, the opposite pole from 하늘색 (sky blue). Against everyday 파란색 (a saturated mid-blue), 남색 reads as more formal and 차분하다 ('calm, composed'), which is exactly why it dominates uniforms and interview wear; younger shoppers often just say the loanword 네이비. Two English-speaker pitfalls: first, don't merge 남색 with 파란색 — they are not interchangeable, and a navy suit described as 파란색 정장 will sound like a bright-blue suit. Second, when stating 'navy is more X', the comparison particle goes on the thing you compare against: 남색이 파란색보다 (navy, compared-to blue), not 남색보다 파란색이 unless you mean the reverse."},sentence:{ko:"면접에는 남색 셔츠가 단정해 보여요.",en:"For an interview, a navy shirt looks neat and presentable."},target:"남색",options:["clothes","shirt","navy; deep blue"],note:"Linked to dictionary card word-ext-1019."},{kind:"guess",word:{ko:"사이즈",romanization:"saijeu",en:"size",pos:"noun",nuance:"사이즈 is the size label or fit. Use 맞다 for whether it fits, and 어울리다 for whether it looks good on someone."},sentence:{ko:"사이즈가 조금 커서 한 치수 작은 것도 보여 주시겠어요?",en:"The size is a little big, so could you show me one size smaller too?"},target:"사이즈",options:["clothes","size","shirt"],note:"Linked to chapter card word-ext-ch51-saijeu."},{kind:"guess",word:{ko:"치수",romanization:"chisu",en:"size; measurement",pos:"noun",nuance:"사이즈 is the everyday label; 치수 is the size measurement or one-step comparison used in 한 치수 큰/작은."},sentence:{ko:"한 치수 작은 것도 입어 봐도 돼요?",en:"May I try on one size smaller too?"},target:"치수",options:["clothes","size; measurement","shirt"],note:"Linked to chapter card word-ext-ch51-chisu."},{kind:"guess",word:{ko:"피팅룸",romanization:"pitingrum",en:"fitting room",pos:"noun",nuance:"피팅룸 is used in many stores, but 탈의실 also means changing room. For clothing shopping, 피팅룸 is natural and easy to understand."},sentence:{ko:"피팅룸은 오른쪽에 있어요.",en:"The fitting room is on the right."},target:"피팅룸",options:["fitting room","clothes","shirt"],note:"Linked to chapter card word-ext-ch51-pitingrum."},{kind:"payoff",line:{speaker:"직원",ko:"네, 피팅룸은 오른쪽에 있어요.",en:"Yes, the fitting room is on the right."},hl:"피팅룸"}],canDo:"Ask a clerk politely for help (다른 사이즈를 보여 주시겠어요?)",id:"chapter-51-b3",chapterId:"chapter-51",index:2},{kind:"pattern",title:"문법 Grammar · V-아/어 주시겠어요?",cards:[{kind:"hunt",name:"V-아/어 주시겠어요?",sub:"Could you please do it for me?",lines:[{tokens:[{pre:"더",mid:"",post:"",hit:!1},{pre:"큰",mid:"",post:"",hit:!1},{pre:"사이즈로",mid:"",post:"",hit:!1},{pre:"가져다",mid:"",post:"",hit:!1},{pre:"",mid:"주시겠어요",post:"?",hit:!0}],ko:"더 큰 사이즈로 가져다 주시겠어요?",en:"Could you bring me a bigger size?",romanization:"deo keun saijeuro gajyeoda jusigesseoyo?"},{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"셔츠",mid:"",post:"",hit:!1},{pre:"좀",mid:"",post:"",hit:!1},{pre:"찾",mid:"아",post:"",hit:!0},{pre:"",mid:"주시겠어요",post:"?",hit:!0}],ko:"이 셔츠 좀 찾아 주시겠어요?",en:"Could you find this shirt for me?",romanization:"i syeocheu jom chaja jusigesseoyo?"}],rule:{name:"V-아/어 주시겠어요?",rows:[{when:"Stem ends in ㅏ/ㅗ",add:"-아 주시겠어요?",ex:"찾다 → 찾아 주시겠어요? (could you find it for me?)"},{when:"Stem ends in another vowel or consonant",add:"-어 주시겠어요?",ex:"보이다 → 보여 주시겠어요? (could you show me?)"},{when:"하다 verbs",add:"해 주시겠어요?",ex:"추천하다 → 추천해 주시겠어요? (could you recommend one?)"}]},more:{func:"A very polite request asking someone to do something for your benefit. In a shop or fitting room it is how you ask the clerk to bring another size, show you a color, or give you a hand. -주다 adds for me, and -시겠어요? makes it gentle and respectful.",keyPoint:{label:"-아/어 주세요 vs -아/어 주시겠어요?",body:"가져다 주세요 = Please bring it (polite request). 가져다 주시겠어요? = Could you bring it? — the -시겠어요? question form is one step more deferential and indirect, the safest choice with a stranger or staff."},pronunciation:""}},{kind:"drill",prompt:"Could you show me another color too?",sentence:"다른 색깔도 보여 ___?",options:[{text:"주시겠어요",ok:!0},{text:"아 주시겠어요",ok:!1}],explanation:"보이다 → 보여; 보여 주다 literally show for me, the natural way to ask to be shown an item."}],canDo:"Ask a clerk politely for help (다른 사이즈를 보여 주시겠어요?)",id:"chapter-51-b4",chapterId:"chapter-51",index:3},{kind:"words",title:"단어 Words 3 · 단정하다~",cards:[{kind:"guess",word:{ko:"단정하다",romanization:"danjeonghada",en:"to be neat; presentable",pos:"adjective",nuance:"단정하다 means neat, orderly, and socially appropriate. It is not the same as stylish or trendy; it is often safer for interviews, school, and work."},sentence:{ko:"남색 셔츠가 더 단정해 보여요.",en:"The navy shirt looks neater."},target:"단정해",options:["to be neat; presentable","clothes","shirt"],note:"Linked to chapter card word-ext-ch51-danjeonghada."},{kind:"guess",word:{ko:"어울리다",romanization:"eoullida",en:"to suit; to look good on",pos:"verb",nuance:"어울리다 carries two everyday meanings bound by one idea — 'to harmonize / fit together well': (1) to suit or look good on someone (이 옷이 잘 어울려요 = this suits you), and (2) to mingle, blend in, or get along with people (친구들하고 잘 어울려요). The particle pattern is the crux for English speakers, because English 'suits you' makes 'you' the object: in Korean the thing that suits is the SUBJECT and takes 이/가 (옷이 어울려요, never 옷을 어울려요), the person it suits is unmarked or takes 한테/에게, and a matching partner or group takes 하고/와/과 (치마하고 어울리다, 사람들하고 어울리다); a setting it fits takes 에 (분위기에 어울리다). Conjugation is the regular ㅣ-vowel contraction, not an irregular: 어울리 + 어 fuses to 어울려, giving polite 어울려요 and past 어울렸어요 (not 어울리어요). A useful contrast: 어울리다 ('look good / harmonize') vs 맞다 ('fit in size / be correct') — clothes that 어울리다 flatter you, clothes that 맞다 are the right size, and the two are not the same compliment."},sentence:{ko:"이 옷이 잘 어울려요.",en:"This outfit suits you well."},target:"어울려",options:["clothes","to suit; to look good on","shirt"],note:"Linked to dictionary card word-verb-304."},{kind:"guess",word:{ko:"교환",romanization:"gyohwan",en:"exchange",pos:"noun",nuance:"교환 means swapping a purchased item for a different size, color, or model of the same kind of product, from the hanja 交換 (交 'to cross/mutual' + 換 'to change'), literally 'mutually change.' The crucial shopping contrast is with 반품, a 'return' that gives your money back: 교환 keeps the transaction (you walk out with goods), 반품 undoes it (you walk out with a refund). Counters typically post '교환·반품 안내' together. Note 교환 is also used more broadly than shopping — 의견 교환 (exchanging opinions), 정보 교환 (exchanging information) — so the word isn't shop-only, but here it's the item-swap sense. The English-speaker pitfall: English 'exchange money' tempts a literal 돈을 교환하다, but currency exchange is 환전 (a different word). To swap into the replacement item, use 로/으로 (큰 사이즈로 교환), and remember the verb is 교환하다, so 'I want to exchange' is 교환하고 싶어요, not 교환을 싶어요."},sentence:{ko:"교환도 돼요?",en:"Can I exchange it too?"},target:"교환",options:["clothes","exchange","shirt"],note:"Linked to dictionary card word-ext-1971 and expression expr-765."},{kind:"guess",word:{ko:"환불",romanization:"hwanbul",en:"refund",pos:"noun",nuance:"환불(還拂) is Sino-Korean — 還 'return/give back' + 拂 'pay out' — literally 'pay back', i.e. returning the buyer's money for a returned item. The contrast learners must nail is 환불 vs 교환: 환불 = money back, 교환(交換 'exchange') = swap for a different item/size/color, no money returned. A related word is 반품(返品) 'returning the goods' — the physical act of sending the product back, which usually triggers a 환불. So you 반품 the item and receive a 환불. Voice matters as with 할인: from your side you say 환불을 받다 ('receive a refund'); to request it you say 환불해 주세요 ('refund it for me'); about whether it's allowed you say 환불이 되다/환불되다 ('a refund is possible'). The English-speaker pitfall is wanting an exchange but saying 환불 — if you actually want a different size, ask 교환돼요? / 교환해 주세요, because 환불 will give you cash back, not a swap. Note Korean also uses 결제 (결제하다) for 'make a payment/settle by card', often in the same conversation. Collocations: 환불을 받다, 환불해 주다, 환불되다, 환불 정책 (refund policy), 환불 규정."},sentence:{ko:"환불도 돼요?",en:"Can I get a refund too?"},target:"환불",options:["clothes","shirt","refund"],note:"Linked to dictionary card word-ext-143 and expression expr-764."},{kind:"guess",word:{ko:"면접",romanization:"myeonjeop",en:"job interview",pos:"noun",nuance:"면접 (面接, 'face-contact/meet') literally means meeting face-to-face, and refers to the job interview where you sit before evaluators. The most important thing to lock in is the FIXED verb: 면접을 보다, literally 'to see an interview,' which uses the same 보다 as 시험을 보다 (take a test) — Korean treats undergoing an evaluation as 'seeing' it. The synonym contrast: 면접 is the oral, face-to-face interview, while 시험 (試驗) is a written test/exam, and 면담 (面談) is a softer counseling-style talk (e.g., with a professor), not a hiring screen. After a 면접 you hope to 합격하다 (pass) rather than 떨어지다 (fall/fail) or 불합격하다. Register: neutral, used in any job-search context. The English-speaker pitfall is reaching for 하다: 면접을 하다 sounds off from the candidate's side — you 면접을 보다 (take it); the company that conducts it may 면접을 진행하다. Also note you pass 면접에 (with 에), patterning like 시험에 합격하다."},sentence:{ko:"면접에는 단정한 셔츠가 좋아요.",en:"For an interview, a neat shirt is good."},target:"면접",options:["job interview","clothes","shirt"],note:"Linked to dictionary card word-ext-1627."},{kind:"payoff",line:{speaker:"직원",ko:"네. 면접에는 이 셔츠보다 남색 셔츠가 더 단정해 보여요.",en:"Sure. For an interview, the navy shirt looks neater than this shirt."},hl:"면접"}],canDo:"Say how clothes or a person look (따뜻해 보여요, 예뻐 보여요)",id:"chapter-51-b5",chapterId:"chapter-51",index:4},{kind:"pattern",title:"문법 Grammar · A-아/어 보이다",cards:[{kind:"teach",name:"A-아/어 보이다",sub:"It looks / appears",rows:[{when:"Adjective stem ends in ㅏ/ㅗ",add:"-아 보이다",ex:"좋다 → 좋아 보여요 (looks good)"},{when:"Stem ends in another vowel or consonant",add:"-어 보이다",ex:"예쁘다 → 예뻐 보여요 (looks pretty)"},{when:"하다 adjectives",add:"-해 보이다",ex:"깔끔하다 → 깔끔해 보여요 (looks neat)"}],examples:[{ko:"그 원피스 정말 예뻐 보여요.",en:"That dress really looks pretty.",romanization:"geu wonpiseu jeongmal yeppeo boyeoyo.",note:"예쁘다 → 예뻐 (ㅡ drops before -어); the headline example for this pattern."},{ko:"이 코트는 좀 비싸 보여요.",en:"This coat looks a bit expensive.",romanization:"i koteuneun jom bissa boyeoyo.",note:"비싸다 ends in ㅏ, so the -아 merges in: 비싸 보여요; commenting on apparent price."}],more:{func:"Describe how something or someone appears to the observer. Attached to an adjective it means looks (pretty/big/expensive); it is the everyday way to compliment an outfit or comment on how clothes look on someone.",keyPoint:{label:"예뻐요 vs 예뻐 보여요",body:"예뻐요 = It is pretty (your judgment of the thing itself). 예뻐 보여요 = It looks pretty (how it appears, possibly more than it really is). Use 보이다 when you are describing an impression or the effect an outfit gives."},pronunciation:"보여요 is pronounced with a smooth y-glide [bo-yeo-yo]; learners often clip it to [bo-eo-yo] — keep the ㅕ. In 좋아 보여요, ㅎ is silent before a vowel, so 좋아 links as [jo-a]."}}],canDo:"Say how clothes or a person look (따뜻해 보여요, 예뻐 보여요)",id:"chapter-51-b6",chapterId:"chapter-51",index:5},{kind:"pattern",title:"문법 Grammar · A-(으)ㄴ N",cards:[{kind:"teach",name:"A-(으)ㄴ N",sub:"An adjective before a noun",rows:[{when:"Adjective stem ends in a vowel",add:"-ㄴ + N",ex:"예쁘다 → 예쁜 원피스 (a pretty dress)"},{when:"Adjective stem ends in a consonant",add:"-은 + N",ex:"작다 → 작은 신발 (small shoes)"},{when:"ㄹ-final stem (ㄹ drops)",add:"-ㄴ + N",ex:"길다 → 긴 치마 (a long skirt)"},{when:"있다/없다 type",add:"-는 + N",ex:"멋있다 → 멋있는 옷 (cool-looking clothes)"}],examples:[{ko:"저는 긴 치마를 좋아해요.",en:"I like long skirts.",romanization:"jeoneun gin chimareul joahaeyo.",note:"길다 is a ㄹ-irregular: ㄹ drops and -ㄴ attaches → 긴. A classic irregular to flag for clothing length."},{ko:"검은색 구두를 신었어요.",en:"I wore black dress shoes.",romanization:"geomeunsaek gudureul sineosseoyo.",note:"검다 → 검은; consonant-final stems take -은. 검은색 (black color) is everyday clothing vocabulary."}],more:{func:"Turn a descriptive adjective into a modifier that sits directly in front of a noun — the basic way to say a pretty dress, a long skirt, black shoes. Essential for describing clothing and appearance with detail.",keyPoint:{label:"치마가 길어요 vs 긴 치마",body:"치마가 길어요 = The skirt is long (adjective as predicate, sentence-final). 긴 치마 = a long skirt (adjective modifying the noun, mid-sentence). The same adjective takes -아/어요 to end a sentence but -(으)ㄴ to sit before a noun."},pronunciation:"작은 links as [ja-geun] — the final ㄱ of 작 moves onto the -은 (resyllabification). Likewise 검은 → [geo-meun], 좋은 → [jo-eun] (ㅎ silent)."}}],canDo:"Put a descriptive adjective before a noun (예쁜 치마, 긴 바지)",id:"chapter-51-b7",chapterId:"chapter-51",index:6},{kind:"pattern",title:"문법 Grammar · N보다 (더)",cards:[{kind:"hunt",name:"N보다 (더)",sub:"More ... than N",lines:[{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"원피스가",mid:"",post:"",hit:!1},{pre:"저",mid:"",post:"",hit:!1},{pre:"원피스",mid:"보다",post:"",hit:!0},{pre:"예뻐요.",mid:"",post:"",hit:!1}],ko:"이 원피스가 저 원피스보다 예뻐요.",en:"This dress is prettier than that one.",romanization:"i wonpiseuga jeo wonpiseuboda yeppeoyo."},{tokens:[{pre:"검은색",mid:"",post:"",hit:!1},{pre:"구두가",mid:"",post:"",hit:!1},{pre:"흰색",mid:"보다",post:"",hit:!0},{pre:"",mid:"더",post:"",hit:!0},{pre:"잘",mid:"",post:"",hit:!1},{pre:"어울려요.",mid:"",post:"",hit:!1}],ko:"검은색 구두가 흰색보다 더 잘 어울려요.",en:"Black shoes suit you better than white ones.",romanization:"geomeunsaek guduga huinsaekboda deo jal eoullyeoyo."}],rule:{name:"N보다 (더)",rows:[{when:"After any noun (the thing compared against)",add:"N보다",ex:"이 치마가 저 치마보다 길어요 (this skirt is longer than that one)"},{when:"Add 더 before the adjective for emphasis",add:"N보다 더 + A",ex:"이 코트가 저 코트보다 더 비싸요 (this coat is more expensive than that one)"},{when:"Opposite direction uses 덜 (less)",add:"N보다 덜 + A",ex:"이 신발이 저 신발보다 덜 편해요 (these shoes are less comfortable than those)"}]},more:{func:"Compare two things: mark the standard of comparison (the thing you measure against) with 보다, and add 더 (more) for emphasis. Ideal for clothing and appearance — saying one skirt is longer than another, or one coat is more expensive than another.",keyPoint:{label:"Where 보다 attaches",body:"보다 attaches to the standard (the thing you measure against), not the subject. 이 치마가 저 치마보다 길어요 = this skirt is longer than that skirt. The 가-marked noun is the winner; the 보다-marked noun is what it beats."},pronunciation:"보다 is always pronounced [bo-da] and attaches directly with no space in writing: 저 치마보다. 더 [deo] is a separate word with a clear ㅓ vowel — do not reduce it to [deu]."}}],canDo:"Compare two items (이 옷이 저 옷보다 더 좋아요)",id:"chapter-51-b8",chapterId:"chapter-51",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A shopper tries on a shirt, asks for another size, and chooses an interview outfit.",lines:[{speaker:"손님",ko:"이 셔츠 입어 봐도 돼요?",en:"May I try on this shirt?",romanization:"i syeocheu ibeo bwado dwaeyo?"},{speaker:"직원",ko:"네, 피팅룸은 오른쪽에 있어요.",en:"Yes, the fitting room is on the right.",romanization:"ne, pitingrumeun oreunjjoge isseoyo."},{speaker:"손님",ko:"조금 커 보여요. 한 치수 작은 것도 보여 주시겠어요?",en:"It looks a little big. Could you show me one size smaller too?",romanization:"jogeum keo boyeoyo. han chisu jageun geotdo boyeo jusigesseoyo?"},{speaker:"직원",ko:"네. 면접에는 이 셔츠보다 남색 셔츠가 더 단정해 보여요.",en:"Sure. For an interview, the navy shirt looks neater than this shirt.",romanization:"ne. myeonjeobeneun i syeocheuboda namsaek syeocheuga deo danjeonghae boyeoyo."},{speaker:"손님",ko:"그럼 이걸로 할게요. 교환이나 환불도 돼요?",en:"Then I'll take this one. Can I exchange or refund it too?",romanization:"geureom igeollo halgeyo. gyohwanina hwanbuldo dwaeyo?"}]},{kind:"order",prompt:"Build: 'Could you show me a smaller size?'",tokens:["한 사이즈 작은 거","보여 주시겠어요?"],correct:"한 사이즈 작은 거 보여 주시겠어요?",explanation:"작은 거 describes the smaller item you want. -주시겠어요? is a polite staff-facing request."}],canDo:"Invite someone to try something on (한번 입어 보세요)",id:"chapter-51-b9",chapterId:"chapter-51",index:8},{kind:"reading",title:"읽기 Reading · 한 치수 작은 것도 보여 주시겠어요?",cards:[{kind:"read",title:"한 치수 작은 것도 보여 주시겠어요?",chunks:["민서는 면접에 입을 셔츠를 사러 갔어요. 먼저 직원에게 '이 셔츠 입어 봐도 돼요?'라고 물었어요. 피팅룸에서 입어 보니 사이즈가 조금 커 보였어요. 그래서 한 치수 작은 것도 보여 달라고 했어요.","직원은 면접에는 이 셔츠보다 남색 셔츠가 더 단정해 보인다고 말했어요. 민서는 그 셔츠가 잘 어울리고 사이즈도 맞아서 샀어요. 마지막으로 교환이나 환불이 되는지도 확인했어요."],translation:"Minseo went to buy a shirt for an interview. First, Minseo asked a staff member if trying on the shirt was allowed. After trying it on in the fitting room, the size looked a little big, so Minseo asked to see one size smaller. The staff member said a navy shirt looked neater for an interview. It suited Minseo and the size fit, so Minseo bought it. Finally, Minseo checked whether exchange or refund was possible.",qas:[{q:"민서는 무엇을 사러 갔어요?",a:"면접에 입을 셔츠를 사러 갔어요."},{q:"셔츠는 어떻게 보였어요?",a:"사이즈가 조금 커 보였어요."},{q:"마지막으로 무엇을 확인했어요?",a:"교환이나 환불이 되는지 확인했어요."}]}],canDo:"Ask a clerk politely for help (다른 사이즈를 보여 주시겠어요?)",id:"chapter-51-b10",chapterId:"chapter-51",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence asks permission to try on a shirt?",sentence:null,options:[{text:"이 셔츠 입어 봐도 돼요?",ok:!0},{text:"이 셔츠 신어 봐도 돼요?",ok:!1},{text:"이 셔츠 입어 보세요?",ok:!1}],explanation:"입다 is for clothing, and -아/어 봐도 돼요? asks permission."},{kind:"drill",prompt:"Which sentence asks for one size smaller most deferentially?",sentence:null,options:[{text:"한 치수 작은 것도 보여 주시겠어요?",ok:!0},{text:"한 치수 작은 것도 보여 주세요.",ok:!1},{text:"한 치수 작은 것도 잘 어울려요?",ok:!1}],explanation:"Both 보여 주세요 and 보여 주시겠어요? are polite; the indirect -주시겠어요? form is more deferential."},{kind:"drill",prompt:"Which sentence is about style, not size?",sentence:null,options:[{text:"이 옷이 잘 어울려요.",ok:!0},{text:"사이즈가 맞아요.",ok:!1},{text:"한 치수 커요.",ok:!1}],explanation:"어울리다 describes whether something suits someone. 맞다 is about fit."},{kind:"drill",prompt:"셔츠___ 입어 봐도 돼요? (May I try on the shirt?)",sentence:null,options:[{text:"를",ok:!0},{text:"가",ok:!1},{text:"에",ok:!1}],explanation:"입다 takes the clothing item as an object, so 셔츠를 fits. 가 would make the shirt the subject."},{kind:"order",prompt:"Build: 'Could you show me a smaller size?'",tokens:["한 사이즈 작은 거","보여 주시겠어요?"],correct:"한 사이즈 작은 거 보여 주시겠어요?",explanation:"작은 거 describes the smaller item you want. -주시겠어요? is a polite staff-facing request."},{kind:"drill",prompt:"Which sentence means “It looks too big”?",sentence:null,options:[{text:"너무 커 보여요.",ok:!0},{text:"너무 크게 입어요.",ok:!1},{text:"너무 큰 봐요.",ok:!1}],explanation:"-아/어 보이다 describes how something appears. 커 보여요 is the natural “looks big.”"}],canDo:"Say how clothes or a person look (따뜻해 보여요, 예뻐 보여요)",id:"chapter-51-b11",chapterId:"chapter-51",index:10}]},{id:"chapter-52",number:52,title:"N 주세요 · V-아/어 주세요",goal:"Order Korean barbecue with 인분, 공기밥, 밑반찬, and N 주세요.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 삼겹살~",cards:[{kind:"guess",word:{ko:"삼겹살",romanization:"samgyeopsal",en:"grilled pork belly",pos:"noun",nuance:"삼겹살 literally breaks down as 삼(三, three) + 겹(layer) + 살(flesh) — 'three-layered meat' — naming the alternating stripes of fat and lean in pork belly, and it is the single most iconic Korean BBQ cut and a default casual group meal. Don't confuse it with 목살 (pork neck/collar, leaner) or 오겹살 (a five-layer belly cut with the skin on); waiters list these as separate menu lines. Register-wise the word itself is neutral, but the situation is firmly casual — friends, 회식 work dinners, late nights with soju — never a formal banquet. The pitfall for English speakers is the counter: 'a piece of pork belly' tempts you into 삼겹살 한 개, but you must order by 인분 (삼겹살 2인분), and you say 구워 먹다 (grill-and-eat) rather than the English 'have a barbecue,' because here you do the grilling yourself."},sentence:{ko:"삼겹살 두 인분 주세요.",en:"Please give us two servings of samgyeopsal."},target:"삼겹살",options:["grilled pork belly","bowl of rice","basic side dishes"],note:"Linked to dictionary card word-ext-802."},{kind:"guess",word:{ko:"인분",romanization:"inbun",en:"serving; portion",pos:"counter",nuance:"명 counts people; 인분 counts portions. 두 명 왔어요 says two people came, but 두 인분 주세요 orders two servings."},sentence:{ko:"삼겹살 두 인분하고 공기밥 하나 주세요.",en:"Please give us two servings of samgyeopsal and one bowl of rice."},target:"인분",options:["serving; portion","grilled pork belly","bowl of rice"],note:"Linked to chapter card word-ext-ch52-inbun."},{kind:"guess",word:{ko:"공기밥",romanization:"gonggibap",en:"bowl of rice",pos:"noun",nuance:"밥 can mean cooked rice or a meal. 공기밥 is the restaurant item, a separate bowl of rice."},sentence:{ko:"공기밥 하나 주세요.",en:"Please give us one bowl of rice."},target:"공기밥",options:["bowl of rice","grilled pork belly","basic side dishes"],note:"Linked to chapter card word-ext-ch52-gonggibap."},{kind:"guess",word:{ko:"밑반찬",romanization:"mitbanchan",en:"basic side dishes",pos:"noun",nuance:"밑반찬 is not the main dish. It refers to small supporting dishes such as kimchi, vegetables, or pickles served with the meal."},sentence:{ko:"밑반찬도 좀 더 주세요.",en:"Please give us a little more side dishes too."},target:"밑반찬",options:["grilled pork belly","bowl of rice","basic side dishes"],note:"Linked to chapter card word-ext-ch52-mitbanchan."},{kind:"guess",word:{ko:"고기",romanization:"gogi",en:"meat",pos:"noun",nuance:"In everyday speech 고기 by default means red land meat — usually 돼지고기(pork) or 소고기(beef) — so 고기 먹으러 가자 implies a BBQ, not seafood. To be specific you compound the animal onto 고기: 닭고기(chicken), 소고기(beef), 돼지고기(pork). The words to contrast are 생선(fish as food) and 해산물(seafood), which Koreans do NOT file under 고기; chicken sits on the edge, so people usually say 닭고기 rather than bare 고기 for it. The set cooking verb is 굽다, a ㅂ-irregular that becomes 구워요/구웠어요 (not 'gubeoyo'). The English-speaker pitfall is the English umbrella sense of 'meat' that includes fish and poultry — in Korean, unmarked 고기 leans strongly toward pork/beef, and you should name the animal when you mean otherwise."},sentence:{ko:"고기를 굽고 마늘도 같이 구워요.",en:"We grill the meat and the garlic together too."},target:"고기",options:["meat","grilled pork belly","bowl of rice"],note:"Linked to dictionary card word-ext-040."},{kind:"guess",word:{ko:"굽다",romanization:"gupda",en:"to grill; roast; bake",pos:"verb",nuance:"굽다 is a ㅂ-irregular verb: the dictionary ㅂ becomes 우 before any vowel ending, so the 요-form is 구워요 (not the textbook-looking 굽어요), past 구웠어요, future 구울 거예요 — memorize the 요-form and the rest follows. Meaning-wise it is dry-heat cooking with direct radiant heat: grilling meat, roasting, AND oven-baking bread all fall under this one word, which surprises English speakers who keep three separate verbs. Contrast it sharply with its kitchen neighbours: 굽다 uses no water and little-to-no oil (just the surface), whereas 볶다 tosses food in a little oil and 튀기다 submerges it in lots of oil. It is the single most useful cooking verb for a foreigner here because 구이 (grilled dishes) and Korean BBQ are everywhere. The classic learner trap is writing 굽어요/굽었어요 by analogy with regular verbs — say 구워요/구웠어요."},sentence:{ko:"고기를 굽고 마늘도 같이 구워요.",en:"We grill the meat and the garlic together too."},target:"굽고",options:["to be cooked; done","to cut","to grill; roast; bake"],note:"Linked to dictionary card word-verb-086."},{kind:"payoff",line:{speaker:"민서",ko:"삼겹살 두 인분하고 공기밥 하나 주세요.",en:"Please give us two servings of samgyeopsal and one bowl of rice."},hl:"삼겹살"}],canDo:"Order an item with a quantity (삼겹살 이 인분 주세요)",id:"chapter-52-b1",chapterId:"chapter-52",index:0},{kind:"pattern",title:"문법 Grammar · N 주세요",cards:[{kind:"hunt",name:"N 주세요",sub:"Ordering an Item",lines:[{tokens:[{pre:"여기",mid:"",post:"",hit:!1},{pre:"김치찌개",mid:"",post:"",hit:!1},{pre:"하나",mid:"",post:"",hit:!1},{pre:"",mid:"주세요",post:".",hit:!0}],ko:"여기 김치찌개 하나 주세요.",en:"One kimchi stew here, please.",romanization:"yeogi gimchijjigae hana juseyo."},{tokens:[{pre:"이거",mid:"",post:"",hit:!1},{pre:"",mid:"주세요",post:".",hit:!0}],ko:"이거 주세요.",en:"This one, please.",romanization:"igeo juseyo."}],rule:{name:"N 주세요",rows:[{when:"Item alone",add:"N + 주세요",ex:"물 → 물 주세요 (Water, please.)"},{when:"Item + amount",add:"N + 수량 + 주세요",ex:"커피 두 잔 → 커피 두 잔 주세요 (Two coffees, please.)"},{when:"Pointing at the menu",add:"이거 + 주세요",ex:"이거 → 이거 주세요 (This one, please.)"},{when:'Softer "could you give me"',add:"N + 좀 + 주세요",ex:"물 → 물 좀 주세요 (Some water, please.)"}]},more:{func:'Use N 주세요 to ask someone to give you a thing. In a restaurant or café this is your basic ordering phrase: name the item, optionally with a number, then add 주세요 ("please give me"). It is polite and works with any server.',keyPoint:{label:"주세요 vs. 주문할게요",body:`주세요 literally means "give me," so you attach it to the THING (커피 주세요). If you want to say "I'll order," that's the verb 주문하다 → 주문할게요. Beginners only need N 주세요 to order; save 주문할게요 for flagging the server that you're ready.`},pronunciation:"주세요 is read [주세요], no special linking. Watch the counter 한 개: say 한 / 개 as two clear beats — learners squash it into 항개. Keep the ㄴ of 한 crisp before 개."}}],canDo:"Order an item with a quantity (삼겹살 이 인분 주세요)",id:"chapter-52-b2",chapterId:"chapter-52",index:1},{kind:"words",title:"단어 Words 2 · 익다~",cards:[{kind:"guess",word:{ko:"익다",romanization:"ikda",en:"to be cooked; done",pos:"verb",nuance:"익다 is intransitive: 고기가 익어요. 익히다 is transitive: 고기를 익혀요, to cook something through."},sentence:{ko:"고기가 익었으니까 이제 잘라 주세요.",en:"The meat is cooked now, so please cut it."},target:"익었",options:["to grill; roast; bake","to cut","to be cooked; done"],note:"Linked to chapter card word-ext-ch52-ikda."},{kind:"guess",word:{ko:"자르다",romanization:"jareuda",en:"to cut",pos:"verb",nuance:"자르다 means to cut THROUGH and separate something with a blade or scissors — paper, hair, cake, rope, nails — i.e. to sever into pieces. Distinguish it from 썰다, which is 'to slice' food into many pieces on a board (양파를 썰다, 'chop an onion'), and from 끊다, which is 'to cut off / break' a connection, line, or supply (전화를 끊다 'hang up', 담배를 끊다 'quit smoking') — note 머리를 자르다 (cut hair) but never 머리를 끊다. There's also 깎다 for shaving/peeling/paring (사과를 깎다 'peel an apple', 수염을 깎다 'shave'). It's a 르-irregular: 자르 + 아요 → 잘라요 (ㅡ drops, ㄹ doubles), past 잘랐어요, but consonant endings keep it whole (자르고, 자를게요, 자릅니다). The big pitfall is 자르아요 (wrong) instead of 잘라요. Also, English 'cut prices' or 'cut down' does not map to 자르다 — reducing an amount is 줄이다, and cutting off a service is 끊다."},sentence:{ko:"고기가 익었으니까 이제 잘라 주세요.",en:"The meat is cooked now, so please cut it."},target:"잘라",options:["to cut","to grill; roast; bake","to be cooked; done"],note:"Linked to dictionary card word-verb-479."},{kind:"guess",word:{ko:"마늘",romanization:"maneul",en:"garlic",pos:"noun",nuance:"마늘 is a native Korean word for garlic, and few foods are more central to Korean cooking — it's the aromatic base (with 양파 and 파) of countless dishes, eaten raw with grilled meat, pickled, or 다지다 (minced) into almost everything. Crucially, a single clove is counted with 쪽 (마늘 한 쪽), while a whole bulb/head is 마늘 한 통 — using 개 for garlic sounds wrong, so learn 쪽 (clove) vs 통 (head). It ends in ㄹ, so particles are 마늘을 / 마늘이, and say it as two clean syllables 'ma-neul.' The English-speaker pitfall is the counter (defaulting to 개 instead of 쪽/통), pronouncing 맵다 regularly (the correct form is 마늘이 매워요, ㅂ-irregular), and over-pluralizing (no 마늘들). It collocates with 다지다 (mince), 까다 (to peel a clove), 넣다 (add), and 빻다 (to crush/pound)."},sentence:{ko:"마늘도 같이 구워요.",en:"We grill the garlic together too."},target:"마늘",options:["grilled pork belly","bowl of rice","garlic"],note:"Linked to dictionary card word-ext-203."},{kind:"guess",word:{ko:"상추",romanization:"sangchu",en:"lettuce for wraps",pos:"noun",nuance:"상추 is the soft, floppy leaf lettuce used to wrap grilled meat as 쌈 — and the sharp line to draw is 상추 vs 양배추 vs 양상추: 상추 is the tender wrapping lettuce, 양배추 is the round head cabbage, and 양상추 is crunchy iceberg/head lettuce for salads. They are different vegetables, so the 양- prefix (a 'Western/foreign' marker, as in 양파 onion, 양식 Western food) is doing real work — 상추 vs 양상추 is not just casual vs formal, it's two distinct plants. Register is plain everyday vocabulary; the only social note is the BBQ ritual phrase. The single most useful collocation a resident learns is '상추 좀 더 주세요' — refills of 상추 are free at almost every 고깃집, so this one line earns its keep nightly. Other collocations: 상추쌈, 상추를 씻다, 상추가 아삭하다/싱싱하다. English-speaker pitfall: 'lettuce' in English defaults to the crunchy salad iceberg, but 상추 is the soft wrap leaf, so don't expect a Caesar-salad crunch; and English speakers often hesitate to ask for more because in many countries refills cost extra — in Korea, just say 더 주세요. 상추 is a native Korean word, no hanja."},sentence:{ko:"상추하고 쌈장도 주세요.",en:"Please give us lettuce and ssamjang too."},target:"상추",options:["grilled pork belly","lettuce for wraps","bowl of rice"],note:"Linked to dictionary card word-ext-532."},{kind:"guess",word:{ko:"쌈장",romanization:"ssamjang",en:"ssamjang sauce",pos:"noun",nuance:"쌈장 is not the same as 고추장. It is a mixed paste commonly used for wraps with grilled meat."},sentence:{ko:"쌈장이 짜니까 조금만 넣으세요.",en:"The ssamjang is salty, so put in only a little."},target:"쌈장",options:["grilled pork belly","ssamjang sauce","bowl of rice"],note:"Linked to chapter card word-ext-ch52-ssamjang."},{kind:"guess",word:{ko:"맵다",romanization:"maepda",en:"to be spicy",pos:"adjective",nuance:"맵다 is ㅂ irregular: 매워요, 매운 음식. It is especially useful for food restrictions, because 매운 음식은 못 먹어요 is a survival sentence."},sentence:{ko:"양념이 매워서 공기밥을 같이 먹어요.",en:"The seasoning is spicy, so I eat it with rice."},target:"매워",options:["to be salty","to be spicy","grilled pork belly"],note:"Linked to dictionary card word-adjective-035."},{kind:"payoff",line:{speaker:"민서",ko:"고기를 굽고 마늘도 같이 구워요.",en:"Let's grill the meat and the garlic together too."},hl:"마늘"}],canDo:"Ask the server to do something (잘라 주세요, 바꿔 주세요)",id:"chapter-52-b3",chapterId:"chapter-52",index:2},{kind:"pattern",title:"문법 Grammar · V-아/어 주세요",cards:[{kind:"hunt",name:"V-아/어 주세요",sub:"Asking for an Action",lines:[{tokens:[{pre:"반찬",mid:"",post:"",hit:!1},{pre:"좀",mid:"",post:"",hit:!1},{pre:"더",mid:"",post:"",hit:!1},{pre:"갖다",mid:"",post:"",hit:!1},{pre:"",mid:"주세요",post:".",hit:!0}],ko:"반찬 좀 더 갖다 주세요.",en:"Could you bring more side dishes, please.",romanization:"banchan jom deo gatda juseyo."},{tokens:[{pre:"고기",mid:"",post:"",hit:!1},{pre:"좀",mid:"",post:"",hit:!1},{pre:"잘라",mid:"",post:"",hit:!1},{pre:"",mid:"주세요",post:".",hit:!0}],ko:"고기 좀 잘라 주세요.",en:"Please cut the meat for us.",romanization:"gogi jom jalla juseyo."}],rule:{name:"V-아/어 주세요",rows:[{when:"Stem vowel ㅏ/ㅗ",add:"stem + 아 주세요",ex:"닦다 → 닦아 주세요 (Please wipe it.)"},{when:"Other stem vowels",add:"stem + 어 주세요",ex:"바꾸다 → 바꿔 주세요 (Please change it.)"},{when:"하다 verbs",add:"해 주세요",ex:"계산하다 → 계산해 주세요 (Please ring it up.)"},{when:"ㅂ irregular",add:"ㅂ→우, then 어",ex:"굽다 → 구워 주세요 (Please grill it.)"}]},more:{func:"Use V-아/어 주세요 to ask someone to DO something for you, not just hand you a thing. Take a verb stem, add the 아/어 connector, then 주세요. In a restaurant this is how you ask the server to bring, change, cut, or wrap something.",keyPoint:{label:"N 주세요 vs. V-아/어 주세요",body:`N 주세요 asks for a THING (물 주세요 = give me water). V-아/어 주세요 asks for an ACTION (포장해 주세요 = pack it). If the English word is a noun ("water," "the menu"), use N 주세요; if it's a verb ("cut it," "wrap it," "bring it"), use V-아/어 주세요.`},pronunciation:"After a stem ending in ㄹ like 만들다, the form is 만들어 주세요 [만드러 주세요] — the ㄹ links into the next syllable. Say it smoothly as 만드러, not 만들-어."}}],canDo:"Ask the server to do something (잘라 주세요, 바꿔 주세요)",id:"chapter-52-b4",chapterId:"chapter-52",index:3},{kind:"words",title:"단어 Words 3 · 짜다~",cards:[{kind:"guess",word:{ko:"짜다",romanization:"jjada",en:"to be salty",pos:"adjective",nuance:"짜다 means having a strong salt taste, and the practical contrast for cooking is 짜다 vs 간이 맞다: 짜다 says there is too much salt, while 간이 맞다 means the seasoning is just right (and 싱겁다 means too little). The salty thing takes 이/가 (국이 짜요). Conjugation is regular for an ㅏ-stem: 짜 + 아요 contracts to 짜요 (not 짜아요), past 짰어요. Two pitfalls for English speakers: first, never write 짜아요. Second, 짜다 has a very common figurative meaning — 'stingy / tightfisted' — so 그 사람 진짜 짜 means 'that person is so cheap', nothing to do with food; English 'salty' meaning 'bitter/annoyed' does NOT transfer to Korean 짜다, so do not use it that way. When you want to talk about how salty you eat in general, use the adverb 짜게 (짜게 먹다), which health advice constantly repeats."},sentence:{ko:"쌈장이 좀 짜요.",en:"The ssamjang is a bit salty."},target:"짜요",options:["to be spicy","to be salty","grilled pork belly"],note:"Linked to dictionary card word-ext-1221."},{kind:"guess",word:{ko:"양념",romanization:"yangnyeom",en:"seasoning; marinade",pos:"noun",nuance:"양념 is the native-Korean word for a whole blend of seasonings — soy sauce, garlic, sesame oil, sugar, chili — mixed to flavor a dish, NOT a single spice. This is the key contrast: one spice is a 향신료 or just its name (소금, 후추), but the prepared mixture you rub or pour on is 양념. The word also signals a style: 양념치킨 is chicken coated in sweet-spicy 양념 sauce, opposite 후라이드 (plain fried). 양념 collocates with 만들다 (make), 무치다 (toss/dress vegetables in it), 재우다 (marinate), 바르다 (brush on), and the verb 양념하다 (to season). The English-speaker pitfall is assuming 양념 = one spice; if you only added salt, that's not really 양념 — 양념 implies a composed blend, and you marinate IN it with 에 (양념에 재우다)."},sentence:{ko:"양념이 매워서 공기밥을 같이 먹어요.",en:"The seasoning is spicy, so I eat it with rice."},target:"양념",options:["seasoning; marinade","grilled pork belly","bowl of rice"],note:"Linked to dictionary card word-ext-1915."},{kind:"guess",word:{ko:"국물",romanization:"gungmul",en:"broth; soup liquid",pos:"noun",nuance:"국물 is the liquid part of soup or stew, contrasted with the solid 건더기. Both 국물을 먹다 and 국물을 마시다 are natural: 먹다 treats it as part of the meal, while 마시다 focuses on drinking the liquid."},sentence:{ko:"국물이 뜨거우니까 천천히 드세요.",en:"The broth is hot, so eat slowly."},target:"국물",options:["grilled pork belly","bowl of rice","broth; soup liquid"],note:"Linked to dictionary card word-ext-1916."},{kind:"guess",word:{ko:"포장해 주세요",romanization:"pojanghae juseyo",en:"Please pack it to go.",pos:"expression",nuance:"포장해 주세요 is the all-purpose 'to go' or 'pack it up' request — for a café drink ordered fresh, a bakery item, or restaurant leftovers. 포장 (包裝) literally means 'wrapping/packaging.' Plain polite -요 for all staff; the even shorter clipped form 포장이요 works as a quick answer to a binary dine-in question; 반말 포장해 줘 is friends-only. The near alternative is 가져갈게요 ('I'll take it away') — the dividing line is who does the action: 포장해 주세요 asks staff to actively pack the item, while 가져갈게요 simply announces you're taking it; in practice both achieve takeout but 포장해 주세요 is more specific. Another alternative is 싸 주세요 ('wrap it up') — homey and natural for restaurant leftovers but slightly informal for a fresh café order. The English-speaker mistake is defaulting to 테이크아웃 해 주세요 — understood at chains but 포장 is the fully native word, and 테이크아웃 컵 refers specifically to the cup type, not the whole transaction."},sentence:{ko:"남은 건 포장해 주세요.",en:"Please pack the leftovers to go."},target:"포장해 주세요",options:["grilled pork belly","Please pack it to go.","serving; portion"],note:"Linked to expression card expr-014."},{kind:"payoff",line:{speaker:"민서",ko:"남은 건 포장해 주세요.",en:"Please pack the leftovers to go."},hl:"포장해 주세요"}],canDo:"Chain food actions in order (고기를 굽고 자르고)",id:"chapter-52-b5",chapterId:"chapter-52",index:4},{kind:"pattern",title:"문법 Grammar · V-고",cards:[{kind:"hunt",name:"V-고",sub:"Linking Food Actions in Order",lines:[{tokens:[{pre:"밥을",mid:"",post:"",hit:!1},{pre:"먹",mid:"고",post:"",hit:!0},{pre:"커피를",mid:"",post:"",hit:!1},{pre:"마셔요.",mid:"",post:"",hit:!1}],ko:"밥을 먹고 커피를 마셔요.",en:"I eat a meal and (then) drink coffee.",romanization:"babeul meokgo keopireul masyeoyo."},{tokens:[{pre:"손을",mid:"",post:"",hit:!1},{pre:"씻",mid:"고",post:"",hit:!0},{pre:"밥을",mid:"",post:"",hit:!1},{pre:"먹어요.",mid:"",post:"",hit:!1}],ko:"손을 씻고 밥을 먹어요.",en:"I wash my hands and eat.",romanization:"soneul ssitgo babeul meogeoyo."}],rule:{name:"V-고",rows:[{when:"Vowel-ending stem",add:"stem + 고",ex:"마시다 → 마시고 (drink and...)"},{when:"Consonant-ending stem",add:"stem + 고",ex:"먹다 → 먹고 (eat and...)"},{when:"하다 verbs",add:"하 + 고",ex:"요리하다 → 요리하고 (cook and...)"},{when:"Tense goes on the LAST verb only",add:"V-고 + V-past/future",ex:"먹고 잤어요 (ate and slept)"}]},more:{func:`Use V-고 to chain two verbs done by the same person, usually in sequence: "do A and (then) B." Attach 고 directly to the verb stem — no vowel changes, no tense on the first verb. It's the everyday way to describe eating-and-doing routines.`,keyPoint:{label:"V-고 vs. V-아서/어서 (sequence)",body:'Both can mean "and then," but 고 just lists separate actions in order (먹고 마셔요 = eat, then drink — different objects). 아서/어서 is used when action B builds on A with the same object (사서 먹어요 = buy it and eat it). For loosely sequenced food steps, 고 is the safe default.'},pronunciation:"After a stem ending in ㄱ, like 먹다, 먹고 is pronounced [먹꼬] — the 고 tenses to 꼬. Likewise 씻고 [씯꼬]. The 고 itself never changes spelling."}}],canDo:"Chain food actions in order (고기를 굽고 자르고)",id:"chapter-52-b6",chapterId:"chapter-52",index:5},{kind:"pattern",title:"문법 Grammar · A/V-아서/어서",cards:[{kind:"teach",name:"A/V-아서/어서",sub:"Reason and Result",rows:[{when:"Stem vowel ㅏ/ㅗ",add:"stem + 아서",ex:"비싸다 → 비싸서 (because it's expensive)"},{when:"Other stem vowels",add:"stem + 어서",ex:"맛있다 → 맛있어서 (because it's tasty)"},{when:"하다 words",add:"해서",ex:"매콤하다 → 매콤해서 (because it's nicely spicy)"},{when:"Past/future reason",add:"NO tense on the -아서/어서 clause",ex:"배가 고파서 먹었어요 (not 고팠어서)"}],examples:[{ko:"너무 매워서 못 먹겠어요.",en:"It's so spicy that I can't eat it.",romanization:"neomu maewoseo mot meokgesseoyo.",note:"맵다 → 매워서 (ㅂ irregular); the spiciness is the reason for not eating."},{ko:"이 집 김치찌개가 맛있어서 자주 와요.",en:"This place's kimchi stew is delicious, so I come often.",romanization:"i jip gimchijjigaega masisseoseo jaju wayo.",note:"맛있어서 explains the reason for the result 자주 와요 (come often)."}],more:{func:`Use A/V-아서/어서 to give a reason: "because A, B." The first clause is the cause, the second is the result. Attach the 아/어 connector + 서 to the stem. With food you use it to explain why you can or can't eat something, or why you like a dish.`,keyPoint:{label:"-아서/어서 vs. -(으)니까 (reason)",body:`Both mean "because," but -아서/어서 cannot be followed by a command or suggestion, and never takes past/future tense in the reason clause. Use -아서/어서 for a plain reason → result (매워서 못 먹어요). When you want to follow with a command or suggestion ("It's spicy, so order something else"), switch to -(으)니까.`},pronunciation:"맛있어서 is pronounced [마시써서] — the ㅅ of 맛 links forward and the double ㅆ stays tense. Say it as one smooth 마시써서, not 맛-있-어-서."}}],canDo:"Give a food reason and result (매워서 물을 마셔요)",id:"chapter-52-b7",chapterId:"chapter-52",index:6},{kind:"pattern",title:"문법 Grammar · V-(으)ㄹ게요",cards:[{kind:"teach",name:"V-(으)ㄹ게요",sub:"Saying What You'll Have",rows:[{when:"Vowel-ending stem",add:"stem + ㄹ게요",ex:"시키다 → 시킬게요 (I'll order it.)"},{when:"Consonant-ending stem",add:"stem + 을게요",ex:"먹다 → 먹을게요 (I'll have it.)"},{when:"하다 verbs",add:"할게요",ex:"주문하다 → 주문할게요 (I'll order.)"},{when:"ㄹ-ending stem (drop nothing extra)",add:"stem + 게요",ex:"만들다 → 만들게요 (I'll make it.)"}],examples:[{ko:"저는 비빔밥 먹을게요.",en:"I'll have bibimbap.",romanization:"jeoneun bibimbap meogeulgeyo.",note:'Announcing your own choice at the table; 저는 marks "as for me" when each person picks a dish.'},{ko:"저기요, 주문할게요.",en:"Excuse me, we're ready to order.",romanization:"jeogiyo, jumunhalgeyo.",note:"저기요 calls the server; 주문할게요 signals you've decided and want to order now."}],more:{func:`Use V-(으)ㄹ게요 to announce a decision you're making on the spot — "I'll have / I'll do ___." At the table it's how you tell the server or your friends what you've chosen, with a nuance of committing to it right now. Add -ㄹ게요 to a vowel-ending stem, -을게요 to a consonant-ending stem.`,keyPoint:{label:"-(으)ㄹ게요 vs. -(으)ㄹ래요",body:"-(으)ㄹ게요 is you committing to do something, often for the listener's sake (저는 비빔밥 먹을게요 = I've decided, I'll have bibimbap). -(으)ㄹ래요 is more about your wish/preference and can sound like you're asking or stating want (비빔밥 먹을래요 = I want bibimbap / shall I?). To simply state your order, -(으)ㄹ게요 is the smoother choice."},pronunciation:"-ㄹ게요 is pronounced [ㄹ께요] — the ㄱ tenses to ㄲ. So 먹을게요 is [머글께요] and 갈게요 is [갈께요]. The spelling stays 게, but you say 께."}}],canDo:"Announce what you'll have on the spot (저는 비빔밥을 먹을게요)",id:"chapter-52-b8",chapterId:"chapter-52",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Coworkers order samgyeopsal and manage the table grill.",lines:[{speaker:"민서",ko:"삼겹살 두 인분하고 공기밥 하나 주세요.",en:"Please give us two servings of samgyeopsal and one bowl of rice.",romanization:"samgyeopsal du inbunhago gonggibap hana juseyo."},{speaker:"지훈",ko:"밑반찬도 좀 더 주세요.",en:"Please give us a little more side dishes too.",romanization:"mitbanchando jom deo juseyo."},{speaker:"민서",ko:"고기를 굽고 마늘도 같이 구워요.",en:"Let's grill the meat and the garlic together too.",romanization:"gogireul gupgo maneuldo gachi guwoyo."},{speaker:"지훈",ko:"고기가 익었으니까 이제 잘라 주세요.",en:"The meat is cooked now, so please cut it.",romanization:"gogiga igeosseunikka ije jalla juseyo."},{speaker:"민서",ko:"남은 건 포장해 주세요.",en:"Please pack the leftovers to go.",romanization:"nameun geon pojanghae juseyo."}]},{kind:"order",prompt:"Build: 'When the meat is cooked, please cut it.'",tokens:["고기가 익으면","잘라 주세요"],correct:"고기가 익으면 잘라 주세요",explanation:"-으면 sets the condition. 익으면 means when it is cooked, and 잘라 주세요 is the request."}],canDo:"Order an item with a quantity (삼겹살 이 인분 주세요)",id:"chapter-52-b9",chapterId:"chapter-52",index:8},{kind:"reading",title:"읽기 Reading · 삼겹살 두 인분 주세요",cards:[{kind:"read",title:"삼겹살 두 인분 주세요",chunks:["민서는 회사 사람들과 삼겹살집에 갔어요. 먼저 삼겹살 두 인분하고 공기밥 하나를 주문했어요. 밑반찬이 부족해서 직원에게 밑반찬도 좀 더 달라고 했어요. 고기를 굽고 마늘도 같이 구웠어요.","고기가 익었으니까 먹기 좋게 잘라 달라고 했어요. 양념이 조금 매워서 공기밥을 같이 먹었고, 쌈장은 짜니까 조금만 넣었어요. 마지막에는 남은 음식을 포장해 달라고 했어요."],translation:"Minseo went to a samgyeopsal restaurant with coworkers. First, Minseo ordered two servings of samgyeopsal and one bowl of rice. Because the side dishes were not enough, Minseo asked the staff for more. They grilled the meat and garlic together. When the meat was cooked, Minseo asked someone to cut it into easy-to-eat pieces. The seasoning was a little spicy, so they ate it with rice, and since the ssamjang was salty, they added only a little. At the end, they asked to pack the leftovers.",qas:[{q:"민서는 무엇을 주문했어요?",a:"삼겹살 두 인분하고 공기밥 하나를 주문했어요."},{q:"고기가 익었을 때 무엇을 부탁했어요?",a:"고기를 잘라 달라고 했어요."},{q:"왜 공기밥을 같이 먹었어요?",a:"양념이 조금 매워서 공기밥을 같이 먹었어요."}]}],canDo:"Ask the server to do something (잘라 주세요, 바꿔 주세요)",id:"chapter-52-b10",chapterId:"chapter-52",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which counter fits restaurant servings?",sentence:null,options:[{text:"삼겹살 두 인분",ok:!0},{text:"삼겹살 두 권",ok:!1},{text:"삼겹살 두 명",ok:!1}],explanation:"인분 counts food servings. 명 counts people."},{kind:"drill",prompt:"Which sentence correctly separates cooking action and result?",sentence:null,options:[{text:"고기를 굽고, 고기가 익어요.",ok:!0},{text:"고기가 굽고, 고기를 익어요.",ok:!1},{text:"고기를 익고, 고기가 구워요.",ok:!1}],explanation:"굽다 takes the meat as object; 익다 uses the food as subject."},{kind:"drill",prompt:"Which sentence gives a reason before a request?",sentence:null,options:[{text:"고기가 익었으니까 잘라 주세요.",ok:!0},{text:"고기가 익어서 잘라 주세요.",ok:!1},{text:"고기가 익고 잘라 주세요.",ok:!1}],explanation:"-(으)니까 naturally supports a following request."},{kind:"drill",prompt:"삼겹살 2인분___ 주세요. (Two servings of pork belly, please.)",sentence:null,options:[{text:"을",ok:!0},{text:"이",ok:!1},{text:"에",ok:!1}],explanation:"The ordered amount is the object of 주세요, so 을 is grammatical when the particle is shown. In restaurant speech, this particle is often dropped."},{kind:"order",prompt:"Build: 'When the meat is cooked, please cut it.'",tokens:["고기가 익으면","잘라 주세요"],correct:"고기가 익으면 잘라 주세요",explanation:"-으면 sets the condition. 익으면 means when it is cooked, and 잘라 주세요 is the request."},{kind:"drill",prompt:"Which counter fits Korean barbecue servings?",sentence:null,options:[{text:"인분",ok:!0},{text:"잔",ok:!1},{text:"권",ok:!1}],explanation:"Restaurant servings use 인분. 잔 counts cups, and 권 counts books."}],canDo:"Chain food actions in order (고기를 굽고 자르고)",id:"chapter-52-b11",chapterId:"chapter-52",index:10}]},{id:"chapter-53",number:53,title:"V-(으)ㄴ 적이 있어요 · A/V-는 것 같아요",goal:"Ask about watching experience with V(으)ㄴ 적이 있어요.",biteCount:13,bites:[{kind:"words",title:"단어 Words 1 · 드라마~",cards:[{kind:"guess",word:{ko:"드라마",romanization:"deurama",en:"TV drama; series",pos:"noun",nuance:"드라마 usually means a scripted series, not a one-off movie. 영화 is movie; 예능 is variety show."},sentence:{ko:"이 드라마 본 적 있어요?",en:"Have you watched this drama before?"},target:"드라마",options:["actor","TV drama; series","comment"],note:"Linked to chapter card word-ext-ch53-deurama."},{kind:"guess",word:{ko:"배우",romanization:"baeu",en:"actor",pos:"noun",nuance:"배우 is 俳優 (both 俳 and 優 historically meant 'performer/entertainer'), an old Sino-Korean compound that already covers actors of any gender in film, TV drama, and theater — so there is no need to mark gender, and the English loan 액터 is essentially never used in normal speech. The thing an actor does is 연기 'acting' (연기를 하다 / 연기를 잘하다), not '배우를 하다'; that 연기 vs 배우 split (craft vs person) mirrors 요리 vs 요리사 and trips learners up. Distinguish 배우 from 가수 'singer', 개그맨/코미디언 'comedian', and the broader 연예인 'celebrity/entertainer', which includes all of them. The verb 나오다 ('come out') is the idiomatic way to say an actor 'appears in' a film or show. After the vowel, the copula is 배우예요, and one 배우가 된다."},sentence:{ko:"이 배우가 좋거든요.",en:"I like this actor, you see."},target:"배우",options:["TV drama; series","actor","comment"],note:"Linked to dictionary card word-ext-102."},{kind:"guess",word:{ko:"재미있다",romanization:"jaemiitda",en:"to be fun; interesting",pos:"adjective",nuance:"재미있다 is literally 재미 (fun, enjoyment) + 있다 (to exist) — 'fun exists [in it]' — which is exactly why it conjugates like 있다 and gives 재미있어요, and why the noun-modifying form is the 있다-style 재미있는 N (재미있는 영화), never 재미있은. It spans both English 'fun' and 'interesting': a party, a game, or a class can all be 재미있어요, so let context choose the English. The near-synonym to separate is 재미있다 vs 흥미롭다: 재미있다 is the warm, everyday 'enjoyable/entertaining' you say about a movie or a friend, while 흥미롭다 is a cooler, more bookish 'intriguing/of interest' you might use for a research finding or a phenomenon — calling a thrilling roller coaster 흥미로워요 sounds oddly academic. Its direct opposite is the single word 재미없다 (재미 + 없다, 'fun does not exist') = boring; do not say 안 재미있다 as your default negative — 재미없어요 is the natural 'it's boring', and 안 재미있어요 reads more like 'it's not [particularly] fun'. The big English-speaker pitfall is the conjugation: because the headword ends in 있다, learners over-apply -하다 or vowel rules and produce 재미있다요 or 재미있아요; the only correct polite form is 재미있어요, with past 재미있었어요."},sentence:{ko:"이 드라마 재미있는 것 같아요.",en:"I think this drama is fun."},target:"재미있",options:["TV drama; series","actor","to be fun; interesting"],note:"Linked to dictionary card word-ext-1328."},{kind:"guess",word:{ko:"댓글",romanization:"daetgeul",en:"comment",pos:"noun",nuance:"댓글 is online. For a spoken comment or opinion, 말 or 의견 may fit better."},sentence:{ko:"댓글이 진짜 재미있거든요.",en:"The comments are really fun, you know."},target:"댓글",options:["comment","TV drama; series","actor"],note:"Linked to chapter card word-ext-ch53-daetgeul."},{kind:"guess",word:{ko:"자막",romanization:"jamak",en:"subtitles; captions",pos:"noun",nuance:"자막 can mean subtitles for translation or captions on video. In streaming apps, 자막 설정 is subtitle settings."},sentence:{ko:"친구가 자막이 좋다고 했어요.",en:"My friend said the subtitles are good."},target:"자막",options:["subtitles; captions","TV drama; series","actor"],note:"Linked to chapter card word-ext-ch53-jamak."},{kind:"payoff",line:{speaker:"민서",ko:"이 드라마 본 적 있어요?",en:"Have you watched this drama before?"},hl:"드라마"}],canDo:"Say whether I have ever done something (본 적이 있어요/없어요)",id:"chapter-53-b1",chapterId:"chapter-53",index:0},{kind:"pattern",title:"문법 Grammar · V-(으)ㄴ 적이 있어요",cards:[{kind:"hunt",name:"V-(으)ㄴ 적이 있어요",sub:"Have you ever…? (past experience)",lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"그",mid:"",post:"",hit:!1},{pre:"드라마를",mid:"",post:"",hit:!1},{pre:"본",mid:"",post:"",hit:!1},{pre:"",mid:"적이",post:"",hit:!0},{pre:"",mid:"있어요",post:".",hit:!0}],ko:"저는 그 드라마를 본 적이 있어요.",en:"I have seen that drama before.",romanization:"jeoneun geu deuramareul bon jeogi isseoyo."},{tokens:[{pre:"그",mid:"",post:"",hit:!1},{pre:"가수",mid:"",post:"",hit:!1},{pre:"콘서트에",mid:"",post:"",hit:!1},{pre:"간",mid:"",post:"",hit:!1},{pre:"",mid:"적이",post:"",hit:!0},{pre:"",mid:"있어요",post:"?",hit:!0}],ko:"그 가수 콘서트에 간 적이 있어요?",en:"Have you ever been to that singer's concert?",romanization:"geu gasu konseoteue gan jeogi isseoyo?"}],rule:{name:"V-(으)ㄴ 적이 있어요",rows:[{when:"Verb stem ends in a consonant",add:"+ -은 적이 있어요",ex:"듣다 → 들은 적이 있어요 (have heard it before)"},{when:"Verb stem ends in a vowel",add:"+ -ㄴ 적이 있어요",ex:"보다 → 본 적이 있어요 (have seen it before)"},{when:"Negative (never done it)",add:"replace 있어요 with 없어요",ex:"가다 → 간 적이 없어요 (have never gone)"}]},more:{func:"Says you have had the experience of doing something at least once. The negative, V-(으)ㄴ 적이 없어요, means you have never done it. It is about whether something has ever happened, not about one specific past event.",keyPoint:{label:"-(으)ㄴ 적이 있어요 vs. plain past -았/었어요",body:"Plain past 봤어요 reports one specific event ('I watched it yesterday'). 본 적이 있어요 reports the experience itself ('I have watched it at some point'). Use -(으)ㄴ 적이 있어요 when the time doesn't matter, only whether it has ever happened.",when:"",add:"",ex:""},pronunciation:"적이 is pronounced [저기] (jeogi): the final ㄱ of 적 links onto the 이 of the next syllable."}}],canDo:"Say whether I have ever done something (본 적이 있어요/없어요)",id:"chapter-53-b2",chapterId:"chapter-53",index:1},{kind:"words",title:"단어 Words 2 · 영상~",cards:[{kind:"guess",word:{ko:"영상",romanization:"yeongsang",en:"video",pos:"noun",nuance:"영상 is Sino-Korean: 映 (영, 'reflect/project') + 像 (상, 'image'), literally a 'projected image', and it means a video clip — the kind you watch online, on your phone, or record yourself. Draw the line carefully against 영화 (映畫, 'projected picture'), a full cinema movie: a YouTube clip is an 영상, never an 영화. It also contrasts with the casual loanword 비디오, which now sounds dated (it evoked old videotapes) and with 동영상 (動映像, 'moving image'), a near-identical, slightly more technical synonym you'll see on menus and settings. The verb pairing is the pitfall: you watch a video with 보다 + object (영상을 보다), and crucially you 'shoot/take' one with 찍다 — 영상을 찍다 — not 만들다 unless you mean editing/producing it. English 'make a video' tempts learners into 영상을 만들다, but for simply recording, 찍다 is the natural choice."},sentence:{ko:"영상이 계속 끊기는데요.",en:"The video keeps cutting out, though."},target:"영상",options:["TV drama; series","video","actor"],note:"Linked to dictionary card word-ext-163."},{kind:"guess",word:{ko:"공유하다",romanization:"gongyuhada",en:"to share",pos:"verb",nuance:"공유하다 is broader than sending. 보내다 is to send; 공유하다 emphasizes making content available or passing it along."},sentence:{ko:"영상도 공유했어요?",en:"Did you share the video too?"},target:"공유했",options:["to share","to cut out; disconnect; buffer","to connect"],note:"Linked to chapter card word-ext-ch53-gongyuhada and expression expr-565."},{kind:"guess",word:{ko:"끊기다",romanization:"kkeunhgida",en:"to cut out; disconnect; buffer",pos:"verb",nuance:"끊기다 is passive/intransitive: the video or connection cuts out. 끊다 is what someone actively cuts or ends."},sentence:{ko:"영상이 계속 끊기는데요.",en:"The video keeps cutting out, though."},target:"끊기",options:["to cut out; disconnect; buffer","to share","to connect"],note:"Linked to chapter card word-ext-ch53-kkeunhgida."},{kind:"guess",word:{ko:"와이파이",romanization:"waipai",en:"Wi-Fi",pos:"noun",nuance:"와이파이 is the loanword for local wireless internet (the spoken form follows the English 'Wi-Fi'), and the key distinction English speakers must hold is 와이파이 vs 데이터: 와이파이 is the free signal you join from a router, while 데이터 is your paid mobile-data allowance — running out of one doesn't affect the other. It also differs from 인터넷, the network as a whole; 와이파이 is just one way to reach it. The pitfall is the connection particle: you connect 와이파이에 (to the wifi, a destination) with 연결하다, not 와이파이로, because here the wifi is where you're attaching, not a tool you act through. And like other tech that simply stops responding, a dead signal is 와이파이가 안 돼요 (it won't function), not 와이파이가 없어요, which claims there's no network at all."},sentence:{ko:"와이파이를 다시 연결해 보세요.",en:"Try reconnecting the Wi-Fi."},target:"와이파이",options:["Wi-Fi","TV drama; series","actor"],note:"Linked to dictionary card word-ext-162."},{kind:"guess",word:{ko:"연결하다",romanization:"yeongyeolhada",en:"to connect",pos:"verb",nuance:"연결하다 is active: you connect something. 연결되다 means something is connected."},sentence:{ko:"와이파이를 다시 연결해 보세요.",en:"Try reconnecting the Wi-Fi."},target:"연결해",options:["to share","to cut out; disconnect; buffer","to connect"],note:"Linked to chapter card word-ext-ch53-yeongyeolhada."},{kind:"payoff",line:{speaker:"민서",ko:"친구가 자막이 좋다고 했어요. 영상도 공유했어요?",en:"My friend said the subtitles are good. Did you share the video too?"},hl:"영상"}],canDo:"Give a soft impression or guess (재미있는 것 같아요)",id:"chapter-53-b3",chapterId:"chapter-53",index:2},{kind:"pattern",title:"문법 Grammar · A/V-는 것 같아요",cards:[{kind:"teach",name:"A/V-는 것 같아요",sub:"I think… / It seems… (soft impression)",rows:[{when:"Verb, present",add:"+ -는 것 같아요",ex:"보다 → 보는 것 같아요 (seems to be watching)"},{when:"Adjective, present",add:"+ -(으)ㄴ 것 같아요",ex:"재미있다 → 재미있는 것 같아요 / 좋다 → 좋은 것 같아요 (seems good)"},{when:"Verb, past",add:"+ -(으)ㄴ 것 같아요",ex:"끝나다 → 끝난 것 같아요 (seems to have ended)"},{when:"Any, future/guess",add:"+ -(으)ㄹ 것 같아요",ex:"재미있다 → 재미있을 것 같아요 (looks like it'll be fun)"}],examples:[{ko:"이 드라마가 요즘 제일 인기 있는 것 같아요.",en:"I think this drama is the most popular these days.",romanization:"i deuramaga yojeum jeil ingi inneun geot gatayo.",note:"있다 takes the verb-style -는 것 같아요; softens a strong claim into an opinion."},{ko:"새 앨범이 정말 좋은 것 같아요.",en:"I think the new album is really good.",romanization:"sae aelbeomi jeongmal joeun geot gatayo.",note:"좋다 is an adjective → -은 것 같아요; gives a gentle personal opinion."}],more:{func:"Softens a statement into an impression or guess: 'it seems,' 'I think,' 'probably.' It makes you sound less blunt and more polite, which is why Korean speakers use it constantly even when fairly sure.",keyPoint:{label:"Present -는 것 같아요 vs. future -(으)ㄹ 것 같아요",body:"Use -는 것 같아요 for something happening or true now ('seems to be ~ing'). Use -(으)ㄹ 것 같아요 for a prediction about something not yet visible ('will probably ~'). Same softener, different time: 보는 것 같아요 = 'seems to be watching it'; 볼 것 같아요 = 'will probably watch it.'",when:"",add:"",ex:""},pronunciation:"것 같아요 is pronounced [걷 가타요] → naturally [걷까타요]: the final ㅅ becomes [t] and tenses the following ㄱ to [ㄲ]."}}],canDo:"Give a soft impression or guess (재미있는 것 같아요)",id:"chapter-53-b4",chapterId:"chapter-53",index:3},{kind:"words",title:"단어 Words 3 · 누르다~",cards:[{kind:"guess",word:{ko:"누르다",romanization:"nureuda",en:"to press; push",pos:"verb",nuance:"누르다 is the go-to verb for pressing or pushing down — elevator buttons, doorbells, app icons, keypad keys, the 'like' button — and modern Korean life is so full of buttons that nailing it instantly sounds fluent. It is a textbook 르-irregular verb: before a vowel ending, the 르 transforms and an extra ㄹ appears, so the stem becomes 눌ㄹ-, giving 눌러요 and past 눌렀어요, while consonant endings stay regular (누릅니다, 누르고, 누르지 마세요). The meaning contrast to lock in is with 밀다 and 당기다: 누르다 is pressing DOWN on a surface or button, 밀다 is pushing a door/object away from you (문을 밀다 'push the door'), and 당기다 is pulling it toward you (문을 당기다) — so a door says 미세요/당기세요, never 누르세요, but a doorbell beside it says 누르세요. The English-speaker pitfall is twofold: writing the un-irregular '누르어요' instead of 눌러요, and over-extending 'press/push' to doors, where Korean insists on 밀다 rather than 누르다."},sentence:{ko:"좋아요도 눌렀어요?",en:"Did you hit like too?"},target:"눌렀",options:["to share","to cut out; disconnect; buffer","to press; push"],note:"Linked to dictionary card word-verb-108 and expression expr-549."},{kind:"guess",word:{ko:"ㅋㅋ",romanization:"kk",en:"haha; lol",pos:"expression",nuance:"ㅋㅋ is the texted shape of the snicker 크크/큭큭 (ㅋ is the consonant for the 'k' giggle), and among Korean 20-30s it is the default 'I'm-relaxed-and-friendly' marker — even more than a real laugh, it signals you're at ease, so chats feel cold without it. Length is meaning: ㅋㅋ is a polite chuckle, ㅋㅋㅋㅋㅋ is genuine laughter, and you stretch the string to match how funny something is (it helps that ㅋ sits under one key, so spamming it is effortless). Its near-rival ㅎㅎ is the softer cousin (a smile, not a laugh), so swapping them shifts tone — ㅋㅋ is funny, ㅎㅎ is gentle/warm. The sharp English-speaker pitfall is the lone ㅋ: in English a solo 'lol' is harmless, but a single ㅋ (or ㅋ.. / ㅋ?) can read as cold, sarcastic, even passive-aggressive — the texting equivalent of a flat 'ha,' so never go below ㅋㅋ. And keep all of it out of messages to a boss, professor, or stranger, where laughter letters look unserious; there you write plain-polite sentences with no ㅋ at all."},sentence:{ko:"댓글에 ㅋㅋ가 많아요.",en:"There is a lot of lol in the comments."},target:"ㅋㅋ",options:["awesome; wow; no way","whoa; OMG; no way","haha; lol"],note:"Linked to expression card expr-031."},{kind:"guess",word:{ko:"대박",romanization:"daebak",en:"awesome; wow; no way",pos:"expression",nuance:"대박 literally means 'a big hit / jackpot' (대 大 'big' + 박 = jackpot), and as a reaction it explodes out for anything extreme — amazingly good, but also shocking or unbelievably bad. It is youth slang and firmly casual: 대박 alone is banmal among friends; for even a little politeness say 대박이에요, though that still reads as informal in flavor. The variant ladder is 대박 → 대박이다 → 대박이에요 → 완전 대박 (intensified). The dividing line against 헐 is emotional direction: 헐 leans toward shock/dismay ('oh no, whoa'), while 대박 leans toward 'wow, that's enormous' — though both can appear together as 헐 대박. Because it's casual slang, the English-speaker pitfall is using it in formal or hierarchical settings — to a boss or elder, 대박 sounds flippant and disrespectful; use 대단하네요 or 굉장하네요 instead. A second pitfall is assuming it's always positive: Koreans say 대박 at a car crash too, meaning 'unbelievable/shocking.'"},sentence:{ko:"그 아이돌 무대가 대박이라고 했어요.",en:"They said that idol's stage was amazing."},target:"대박",options:["haha; lol","awesome; wow; no way","TV drama; series"],note:"Linked to expression card expr-646."},{kind:"guess",word:{ko:"헐",romanization:"heol",en:"whoa; OMG; no way",pos:"expression",nuance:"헐 is a pure interjection of shock — the involuntary sound that comes out when something startling, dismaying, or unbelievable hits you. It's hugely common in texting and casual conversation among friends and younger people. Because it's a raw exclamation there is no polite form: there is no 헐요 or 헐이에요; it lives entirely in banmal territory. The dividing line against 대박 is emotional direction: 헐 carries surprise often tinged with 'oh no' or dismay, while 대박 leans toward 'wow, that's enormous' — that's why 헐 어떡해 (shock + worry) is a natural pair but 대박 어떡해 is odd. Also don't confuse 헐 with 헉: 헐 is drawn-out disbelief ('whoa, no way'), while 헉 is a sharp one-syllable gasp of fright or physical surprise. The English-speaker pitfall is using 헐 in a professional or respectful setting — to an elder or boss it sounds childish and rude; in those moments use 어머 for neutral surprise or a full 정말요? 그런 일이. A second pitfall is trying to write 헐요 to be polite — simply switch words."},sentence:{ko:"헐, 영상이 또 끊겼어요.",en:"Whoa, the video cut out again."},target:"헐",options:["whoa; OMG; no way","haha; lol","TV drama; series"],note:"Linked to expression card expr-647."},{kind:"guess",word:{ko:"아이돌",romanization:"aidol",en:"idol; K-pop idol",pos:"noun",nuance:"아이돌 can refer to a solo idol or group member. For the whole group, 그룹 or 아이돌 그룹 is clearer."},sentence:{ko:"어떤 아이돌 좋아해요?",en:"Which idol do you like?"},target:"아이돌",options:["TV drama; series","idol; K-pop idol","actor"],note:"Linked to chapter card word-ext-ch53-aidol."}],canDo:"Relay what someone said (좋다고 했어요)",id:"chapter-53-b5",chapterId:"chapter-53",index:4},{kind:"pattern",title:"문법 Grammar · V/A-다고 했어요",cards:[{kind:"hunt",name:"V/A-다고 했어요",sub:"They said that… (reported speech)",lines:[{tokens:[{pre:"친구가",mid:"",post:"",hit:!1},{pre:"그",mid:"",post:"",hit:!1},{pre:"영화",mid:"",post:"",hit:!1},{pre:"진짜",mid:"",post:"",hit:!1},{pre:"재미있",mid:"다고",post:"",hit:!0},{pre:"",mid:"했어요",post:".",hit:!0}],ko:"친구가 그 영화 진짜 재미있다고 했어요.",en:"My friend said that movie is really fun.",romanization:"chinguga geu yeonghwa jinjja jaemiitdago haesseoyo."},{tokens:[{pre:"동생이",mid:"",post:"",hit:!1},{pre:"새",mid:"",post:"",hit:!1},{pre:"게임을",mid:"",post:"",hit:!1},{pre:"한",mid:"다고",post:"",hit:!0},{pre:"",mid:"했어요",post:".",hit:!0}],ko:"동생이 새 게임을 한다고 했어요.",en:"My younger sibling said they're going to play a new game.",romanization:"dongsaengi sae geimeul handago haesseoyo."}],rule:{name:"V/A-다고 했어요",rows:[{when:"Verb, present",add:"+ -ㄴ/는다고 했어요",ex:"보다 → 본다고 했어요 / 먹다 → 먹는다고 했어요 (said they watch/eat)"},{when:"Adjective, present",add:"+ -다고 했어요",ex:"재미있다 → 재미있다고 했어요 (said it's fun)"},{when:"Past (verb or adjective)",add:"+ -았/었다고 했어요",ex:"끝나다 → 끝났다고 했어요 (said it ended)"},{when:"Noun statement",add:"이다 → -(이)라고 했어요",ex:"가수 → 가수라고 했어요 (said they're a singer)"}]},more:{func:"Reports what someone else said (or what you read or heard). It quotes a statement indirectly: 'He said that it's fun.' Used constantly for relaying news, comments, and messages.",keyPoint:{label:"Verb -ㄴ/는다고 vs. adjective -다고",body:"The trap is the present tense. Verbs insert 는/ㄴ: 먹는다고, 본다고. Adjectives do NOT: 좋다고, 재미있다고. Past tense erases the difference — both verbs and adjectives use -았/었다고 (봤다고, 좋았다고).",when:"",add:"",ex:""},pronunciation:"-다고 했어요: 했어요 is said [해써요], and the whole reporting tail comes out quickly and flatly, lower in pitch than the quoted part."}}],canDo:"Relay what someone said (좋다고 했어요)",id:"chapter-53-b6",chapterId:"chapter-53",index:5},{kind:"pattern",title:"문법 Grammar · A/V-지만",cards:[{kind:"hunt",name:"A/V-지만",sub:"but / although (clean contrast)",lines:[{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"드라마는",mid:"",post:"",hit:!1},{pre:"길",mid:"지만",post:"",hit:!0},{pre:"정말",mid:"",post:"",hit:!1},{pre:"재미있어요.",mid:"",post:"",hit:!1}],ko:"이 드라마는 길지만 정말 재미있어요.",en:"This drama is long, but it's really fun.",romanization:"i deuramaneun giljiman jeongmal jaemiisseoyo."},{tokens:[{pre:"그",mid:"",post:"",hit:!1},{pre:"게임을",mid:"",post:"",hit:!1},{pre:"좋아하",mid:"지만",post:"",hit:!0},{pre:"시간이",mid:"",post:"",hit:!1},{pre:"없어요.",mid:"",post:"",hit:!1}],ko:"그 게임을 좋아하지만 시간이 없어요.",en:"I like that game, but I don't have time.",romanization:"geu geimeul joahajiman sigani eopseoyo."}],rule:{name:"A/V-지만",rows:[{when:"Verb or adjective stem",add:"+ -지만",ex:"재미있다 → 재미있지만 (is fun, but)"},{when:"Past tense",add:"-았/었 + -지만",ex:"봤다 → 봤지만 (watched it, but)"},{when:"Noun + 이다",add:"+ -(이)지만",ex:"가수 → 가수지만 (is a singer, but)"}]},more:{func:"Joins two clauses in a straightforward 'A, but B' contrast. Neutral and clear, it works in both speech and writing, much like English 'but' or 'although.'",keyPoint:{label:"-지만 (one sentence) vs. 하지만 (sentence-starter)",body:"-지만 is a connector glued onto a verb or adjective inside one sentence: 좋지만 비싸요. 하지만 is a standalone conjunction that starts a new sentence: 좋아요. 하지만 비싸요. Same meaning 'but,' different position — don't put -지만 at the start of a sentence or 하지만 in the middle of one.",when:"",add:"",ex:""},pronunciation:"-지만 is said evenly as [지만]; in 봤지만 the ㅅ tenses the ㅈ, giving [봗찌만]."}}],canDo:"Make a clean contrast (자막은 없지만 재미있어요)",id:"chapter-53-b7",chapterId:"chapter-53",index:6},{kind:"pattern",title:"문법 Grammar · V-(으)ㄹ게요",cards:[{kind:"teach",name:"V-(으)ㄹ게요",sub:"I'll do it (promise / casual intention)",rows:[{when:"Verb stem ends in a vowel",add:"+ -ㄹ게요",ex:"보다 → 볼게요 (I'll watch it)"},{when:"Verb stem ends in a consonant",add:"+ -을게요",ex:"찾다 → 찾을게요 (I'll look it up)"},{when:"ㄹ-final stem (drop nothing, add 게요)",add:"+ -게요",ex:"만들다 → 만들게요 (I'll make it)"}],examples:[{ko:"그 드라마 오늘 밤에 볼게요.",en:"I'll watch that drama tonight.",romanization:"geu deurama oneul bame bolgeyo.",note:"보다 ends in a vowel → 볼게요; a personal decision about what I'll do."},{ko:"링크 보내 줄게요.",en:"I'll send you the link.",romanization:"lingkeu bonae julgeyo.",note:"Very common in chat; 보내 주다 → 보내 줄게요, promising to do it for the listener."}],more:{func:"States what the speaker will do, often as a light promise or a response to the listener: 'I'll watch it,' 'I'll send it to you.' It is speaker-only (you can't use it for someone else) and signals you're deciding in reaction to the situation. Extremely common in texting and chatting.",keyPoint:{label:"-(으)ㄹ게요 vs. -(으)ㄹ 거예요",body:"-(으)ㄹ게요 is a promise made to the listener, decided on the spot ('okay, I'll do it'). -(으)ㄹ 거예요 is a plain statement of plan or prediction and can describe anyone ('I/he will probably do it'). Use 볼게요 when responding to someone; 볼 거예요 when just stating your plan.",when:"",add:"",ex:""},pronunciation:"-ㄹ게요 is pronounced [ㄹ께요]: the ㄱ is tensed to [ㄲ], so 볼게요 sounds like [볼께요]."}}],canDo:"Promise to do something and give the background (볼게요, 보고 싶었거든요)",id:"chapter-53-b8",chapterId:"chapter-53",index:7},{kind:"pattern",title:"문법 Grammar · V-아/어 주세요",cards:[{kind:"hunt",name:"V-아/어 주세요",sub:"Please do it (for me)",lines:[{tokens:[{pre:"재미있는",mid:"",post:"",hit:!1},{pre:"드라마",mid:"",post:"",hit:!1},{pre:"좀",mid:"",post:"",hit:!1},{pre:"추천해",mid:"",post:"",hit:!1},{pre:"",mid:"주세요",post:".",hit:!0}],ko:"재미있는 드라마 좀 추천해 주세요.",en:"Please recommend a fun drama.",romanization:"jaemiinneun deurama jom chucheonhae juseyo."},{tokens:[{pre:"비밀번호",mid:"",post:"",hit:!1},{pre:"좀",mid:"",post:"",hit:!1},{pre:"찾",mid:"아",post:"",hit:!0},{pre:"",mid:"주세요",post:".",hit:!0}],ko:"비밀번호 좀 찾아 주세요.",en:"Please find the password for me.",romanization:"bimilbeonho jom chaja juseyo."}],rule:{name:"V-아/어 주세요",rows:[{when:"Stem vowel ㅏ/ㅗ",add:"+ -아 주세요",ex:"찾다 → 찾아 주세요 (please find it)"},{when:"Other stem vowels",add:"+ -어 주세요",ex:"보내다 → 보내 주세요 (please send it)"},{when:"하다 verbs",add:"하 → 해 주세요",ex:"추천하다 → 추천해 주세요 (please recommend one)"}]},more:{func:"Asks someone to do something for you, politely: 'please send it,' 'please recommend one.' The 주다 ('give') part adds the 'for me / for my benefit' nuance, making it warmer than a bare command. The everyday way to make digital-life requests.",keyPoint:{label:"-아/어 주세요 (do it for me) vs. -(으)세요 (plain polite command)",body:"-(으)세요 is a polite instruction with no 'for me' feeling: 여기 앉으세요 ('please sit here'). Adding 주다 → -아/어 주세요 frames it as a favor done for the speaker: 사진 보내 주세요 ('send me the photo, please'). For requests where someone helps you, use -아/어 주세요.",when:"",add:"",ex:""},pronunciation:"주세요 is said smoothly as [주세요]; keep the 아/어 and 주 as two clear beats (보내 주세요 = bo-nae ju-se-yo), not crushed together."}},{kind:"drill",prompt:"Please send me that video link.",sentence:"그 영상 링크 보내 ___.",options:[{text:"주세요",ok:!0},{text:"아 주세요",ok:!1}],explanation:"보내다 → 보내 주세요; a typical chat request to do something for you."}],canDo:"Say whether I have ever done something (본 적이 있어요/없어요)",id:"chapter-53-b9",chapterId:"chapter-53",index:8},{kind:"pattern",title:"문법 Grammar · V/A-거든요",cards:[{kind:"hunt",name:"V/A-거든요",sub:"you see, … (a reason or background)",lines:[{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"드라마",mid:"",post:"",hit:!1},{pre:"꼭",mid:"",post:"",hit:!1},{pre:"보세요.",mid:"",post:"",hit:!1},{pre:"정말",mid:"",post:"",hit:!1},{pre:"재미있",mid:"거든요",post:".",hit:!0}],ko:"이 드라마 꼭 보세요. 정말 재미있거든요.",en:"You should definitely watch this drama — it's really fun, you see.",romanization:"i deurama kkok boseyo. jeongmal jaemiitgeodeunyo."},{tokens:[{pre:"그",mid:"",post:"",hit:!1},{pre:"노래",mid:"",post:"",hit:!1},{pre:"알아요.",mid:"",post:"",hit:!1},{pre:"제가",mid:"",post:"",hit:!1},{pre:"그",mid:"",post:"",hit:!1},{pre:"가수",mid:"",post:"",hit:!1},{pre:"팬이",mid:"거든요",post:".",hit:!0}],ko:"그 노래 알아요. 제가 그 가수 팬이거든요.",en:"I know that song — I'm a fan of that singer, you see.",romanization:"geu norae arayo. jega geu gasu paenigeodeunyo."}],rule:{name:"V/A-거든요",rows:[{when:"Verb/adjective stem (present)",add:"-거든요",ex:"재미있다 → 재미있거든요 · 좋아하다 → 좋아하거든요"},{when:"Past",add:"-았/었거든요",ex:"보다 → 봤거든요 (I watched it, you see)"},{when:"Noun + (이)거든요",add:"(이)거든요",ex:"팬이다 → 팬이거든요 (I'm a fan, you see)"}]},more:{func:`-거든요 ends a sentence to offer a reason or new background the listener doesn't know yet — like "you see" or "because…". It often answers a real or implied "why?"`,keyPoint:{label:"거든요 (new info) vs 잖아요 (shared info)",body:"Both give a reason, but 거든요 tells the listener something NEW they didn't know (재미있거든요), while 잖아요 appeals to something you BOTH already know (재미있잖아요). Use 거든요 to introduce a reason, 잖아요 to remind."},pronunciation:"재미있거든요: the ㅆ+ㄱ tightens and the ending links — roughly [재미읻꺼든뇨]."}}],canDo:"Give a soft impression or guess (재미있는 것 같아요)",id:"chapter-53-b10",chapterId:"chapter-53",index:9},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two friends chat about a drama and fix a streaming problem.",lines:[{speaker:"민서",ko:"이 드라마 본 적 있어요?",en:"Have you watched this drama before?",romanization:"i deurama bon jeok isseoyo?"},{speaker:"지훈",ko:"네. 배우도 좋지만 댓글이 진짜 재미있거든요.",en:"Yes. The actor is good too, but the comments are really fun, you know.",romanization:"ne. baeudo jojiman daetgeuri jinjja jaemiitgeodeunyo."},{speaker:"민서",ko:"친구가 자막이 좋다고 했어요. 영상도 공유했어요?",en:"My friend said the subtitles are good. Did you share the video too?",romanization:"chinguga jamagi jotago haesseoyo. yeongsangdo gongyuhaesseoyo?"},{speaker:"지훈",ko:"공유했는데요, 영상이 계속 끊겨요.",en:"I shared it, but the video keeps cutting out.",romanization:"gongyuhaenneundeyo, yeongsangi gyesok kkeunhgyeoyo."},{speaker:"민서",ko:"와이파이를 다시 연결해 보세요. 좋아요도 눌렀어요?",en:"Try reconnecting the Wi-Fi. Did you hit like too?",romanization:"waipaireul dasi yeongyeolhae boseyo. joayodo nulleosseoyo?"}]},{kind:"order",prompt:"Build: 'The video keeps cutting out.'",tokens:["영상이","계속 끊겨요"],correct:"영상이 계속 끊겨요",explanation:"끊기다 describes the stream or video cutting out. 계속 shows it keeps happening."}],canDo:"Say whether I have ever done something (본 적이 있어요/없어요)",id:"chapter-53-b11",chapterId:"chapter-53",index:10},{kind:"reading",title:"읽기 Reading · 영상이 계속 끊기는데요",cards:[{kind:"read",title:"영상이 계속 끊기는데요",chunks:["민서는 친구에게 새 드라마를 추천했어요. 먼저 '이 드라마 본 적 있어요?'라고 물었어요. 친구는 배우도 좋지만 댓글이 진짜 재미있다고 했어요. 또 자막이 좋아서 한국어 공부에도 도움이 되는 것 같다고 했어요.","민서는 영상을 공유했지만, 친구는 영상이 계속 끊긴다고 했어요. 그래서 민서는 와이파이를 다시 연결해 보라고 했어요. 마지막에는 좋아요도 눌렀는지 물었어요."],translation:"Minseo recommended a new drama to a friend. First, Minseo asked whether the friend had watched it before. The friend said the actor was good, but the comments were really fun. The friend also said the subtitles were good and seemed helpful for Korean study. Minseo shared the video, but the friend said the video kept cutting out. So Minseo told the friend to try reconnecting the Wi-Fi. At the end, Minseo asked whether the friend had also hit like.",qas:[{q:"민서는 친구에게 무엇을 추천했어요?",a:"새 드라마를 추천했어요."},{q:"친구는 무엇이 재미있다고 했어요?",a:"댓글이 진짜 재미있다고 했어요."},{q:"영상이 끊길 때 민서는 무엇을 해 보라고 했어요?",a:"와이파이를 다시 연결해 보라고 했어요."}]}],canDo:"Give a soft impression or guess (재미있는 것 같아요)",id:"chapter-53-b12",chapterId:"chapter-53",index:11},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence asks about experience with a drama?",sentence:null,options:[{text:"이 드라마 본 적 있어요?",ok:!0},{text:"이 드라마 볼 수밖에 없어요?",ok:!1},{text:"이 드라마 보고 있겠어요?",ok:!1}],explanation:"-ㄴ 적이 있어요 asks whether someone has done something before."},{kind:"drill",prompt:"Which sentence reports a friend's opinion?",sentence:null,options:[{text:"친구가 자막이 좋다고 했어요.",ok:!0},{text:"친구가 자막을 좋아요 했어요.",ok:!1},{text:"친구가 자막을 켜라고 했어요.",ok:!1}],explanation:"Adjectives use -다고 했어요 in reported speech."},{kind:"drill",prompt:"Which sentence naturally describes buffering?",sentence:null,options:[{text:"영상이 계속 끊기는데요.",ok:!0},{text:"영상을 계속 끊는데요.",ok:!1},{text:"영상이 계속 공유하는데요.",ok:!1}],explanation:"끊기다 describes the video or connection cutting out."},{kind:"drill",prompt:"그 드라마___ 본 적 있어요? (Have you ever watched that drama?)",sentence:null,options:[{text:"를",ok:!0},{text:"가",ok:!1},{text:"에",ok:!1}],explanation:"보다 takes the thing watched as an object, so 드라마를 fits. 본 적 있어요 asks about experience."},{kind:"order",prompt:"Build: 'The video keeps cutting out.'",tokens:["영상이","계속 끊겨요"],correct:"영상이 계속 끊겨요",explanation:"끊기다 describes the stream or video cutting out. 계속 shows it keeps happening."},{kind:"drill",prompt:"Your friend said the subtitles are good. Which report fits?",sentence:null,options:[{text:"친구가 자막이 좋다고 했어요.",ok:!0},{text:"친구가 자막이 좋냐고 했어요.",ok:!1},{text:"친구가 자막을 좋아요 했어요.",ok:!1}],explanation:"-다고 했어요 reports a statement. -냐고 would report a question."}],canDo:"Relay what someone said (좋다고 했어요)",id:"chapter-53-b13",chapterId:"chapter-53",index:12}]},{id:"chapter-54",number:54,title:"V-아/어야 해요 · V-기로 했어요",goal:"Talk about assignments, presentations, midterms, finals, semesters, grades, and study plans.",biteCount:12,bites:[{kind:"words",title:"단어 Words 1 · 과제~",cards:[{kind:"guess",word:{ko:"과제",romanization:"gwaje",en:"assignment; homework task",pos:"noun",nuance:"숙제 is homework, often younger-school or daily work. 과제 sounds more academic and can include reports, presentations, and projects."},sentence:{ko:"중간고사 전에 발표 과제를 끝내야 해요.",en:"We have to finish the presentation assignment before the midterm."},target:"과제",options:["assignment; homework task","midterm exam","final exam"],note:"Linked to chapter card word-ext-ch54-gwaje."},{kind:"guess",word:{ko:"중간고사",romanization:"junggangosa",en:"midterm exam",pos:"noun",nuance:"중간 means middle; 고사 is exam. In daily student talk, 시험 is more general, while 중간고사 is specifically the midterm."},sentence:{ko:"중간고사 전에 과제를 끝내기로 했어요.",en:"We decided to finish the assignment before the midterm."},target:"중간고사",options:["assignment; homework task","midterm exam","semester; school term"],note:"Linked to chapter card word-ext-ch54-junggangosa."},{kind:"guess",word:{ko:"기말고사",romanization:"gimalgosa",en:"final exam",pos:"noun",nuance:"기말 means the end of the term. 기말고사 is final exam; 중간고사 is midterm exam."},sentence:{ko:"기말고사에서 좋은 성적을 받기 위해 매일 공부해야 해요.",en:"I have to study every day in order to get a good grade on the final exam."},target:"기말고사",options:["assignment; homework task","semester; school term","final exam"],note:"Linked to chapter card word-ext-ch54-gimalgosa."},{kind:"guess",word:{ko:"학기",romanization:"hakgi",en:"semester; school term",pos:"noun",nuance:"학기 is an academic term; 방학 is vacation/break between terms."},sentence:{ko:"이번 학기 동안 매일 복습했어요.",en:"I reviewed every day during this semester."},target:"학기",options:["assignment; homework task","midterm exam","semester; school term"],note:"Linked to chapter card word-ext-ch54-hakgi."},{kind:"guess",word:{ko:"교수님",romanization:"gyosunim",en:"professor",pos:"noun",nuance:"Use 선생님 for school teachers or language teachers, and 교수님 for university professors."},sentence:{ko:"교수님께 질문하기로 했어요.",en:"I decided to ask the professor."},target:"교수님",options:["professor","assignment; homework task","midterm exam"],note:"Linked to chapter card word-ext-ch54-gyosunim."},{kind:"payoff",line:{speaker:"민서",ko:"중간고사 전에 발표 과제를 끝내야 해요?",en:"Do we have to finish the presentation assignment before the midterm?"},hl:"과제"}],canDo:"Say what I have to do for school (과제를 내야 해요)",id:"chapter-54-b1",chapterId:"chapter-54",index:0},{kind:"pattern",title:"문법 Grammar · V-아/어야 해요",cards:[{kind:"hunt",name:"V-아/어야 해요",sub:"have to / must",lines:[{tokens:[{pre:"내일까지",mid:"",post:"",hit:!1},{pre:"숙제를",mid:"",post:"",hit:!1},{pre:"내야",mid:"",post:"",hit:!1},{pre:"",mid:"해요",post:".",hit:!0}],ko:"내일까지 숙제를 내야 해요.",en:"I have to hand in the homework by tomorrow.",romanization:"naeilkkaji sukjereul naeya haeyo."},{tokens:[{pre:"수업",mid:"",post:"",hit:!1},{pre:"시간에는",mid:"",post:"",hit:!1},{pre:"휴대폰을",mid:"",post:"",hit:!1},{pre:"꺼야",mid:"",post:"",hit:!1},{pre:"",mid:"해요",post:".",hit:!0}],ko:"수업 시간에는 휴대폰을 꺼야 해요.",en:"During class you have to turn off your phone.",romanization:"sueop siganeneun hyudaeponeul kkeoya haeyo."}],rule:{name:"V-아/어야 해요",rows:[{when:"Verb stem ends in ㅏ or ㅗ",add:"+ -아야 해요",ex:"가다 → 가야 해요 (have to go)"},{when:"Verb stem ends in any other vowel",add:"+ -어야 해요",ex:"먹다 → 먹어야 해요 (have to eat)"},{when:"하다 verbs",add:"하 → 해야 해요",ex:"공부하다 → 공부해야 해요 (have to study)"},{when:"Spoken variant, same meaning",add:"+ -아/어야 돼요",ex:"내다 → 내야 돼요 (have to hand it in)"}]},more:{func:"Expresses obligation or necessity: something you have to do. In school life it covers class rules, assignments, deadlines, and things teachers require of students.",keyPoint:{label:"-아/어야 해요 vs. -아/어야 돼요",body:"Both mean 'have to,' and in everyday speech they are interchangeable. -아/어야 돼요 sounds a touch more colloquial and is very common when talking; -아/어야 해요 is a little more neutral and shows up more in writing. Pick whichever you hear most — the meaning does not change."},pronunciation:"말해야 is pronounced [마래야]: the ㅎ weakens between vowels. 해야 해요 keeps two clear 해 syllables — don't blur them into one."}}],canDo:"Say what I have to do for school (과제를 내야 해요)",id:"chapter-54-b2",chapterId:"chapter-54",index:1},{kind:"words",title:"단어 Words 2 · 수업~",cards:[{kind:"guess",word:{ko:"수업",romanization:"sueop",en:"class; lesson",pos:"noun",nuance:"수업 is Sino-Korean 授業 — 授 'give/confer' + 業 'work/study', literally 'conferring instruction', i.e. the lesson or class session itself (the activity and time period). The set verb is 수업을 듣다 'listen to a class' = attend/take it; from the teacher's side it is 수업을 하다 'give/teach a class'. Three near-neighbors confuse learners: 수업 (the lesson event) vs 교실(教室, the room it happens in) vs 과목(科目, the subject like 'math' or 'history') vs 강의(講義, a university lecture). So 'I have three classes today' = 수업 세 개, but 'I take three subjects' = 과목 세 개. The English-speaker pitfall is using 하다 to mean 'take a class' (수업을 하다 actually means 'to teach', which is what a professor does) — as a student you 듣다 a class. Also, 'go to class' is 수업에 가다 (event as destination with 에)."},sentence:{ko:"내일 수업에서 발표해야 해요.",en:"I have to present in class tomorrow."},target:"수업",options:["class; lesson","assignment; homework task","midterm exam"],note:"Linked to dictionary card word-ext-112."},{kind:"guess",word:{ko:"발표하다",romanization:"balpyohada",en:"to present",pos:"verb",nuance:"발표하다 is Sino-Korean 發表 — 發 'issue/emit' + 表 'express/show outwardly' — so 'issue something into the open'. It has two senses: (1) give a presentation/talk in front of an audience (수업에서 발표하다), and (2) officially announce/release information (정부가 결과를 발표하다 — the government announced the results). Contrast it with 설명하다 (說明, 'explain'): 설명하다 is clarifying so someone understands a point, while 발표하다 is the public act of presenting or announcing as a whole. Also distinguish 발표하다 from 말하다 'to say' — 발표하다 implies prepared, formal, to-an-audience delivery. A particle nuance: in the 'present' sense the location uses 에서 (수업에서), but the content shown is an object (자료를 발표하다). As a noun+하다 verb it conjugates on 하다 (발표해요, 발표했어요, formal 발표합니다); negative/impossible split the noun (발표 안 해요, 발표 못 해요)."},sentence:{ko:"내일 발표해야 해요.",en:"I have to present tomorrow."},target:"발표해",options:["assignment; homework task","midterm exam","to present"],note:"Linked to dictionary card word-verb-492."},{kind:"guess",word:{ko:"시험",romanization:"siheom",en:"exam",pos:"noun",nuance:"시험 is Sino-Korean 試驗 — 試 'try/test' + 驗 'examine', literally 'a trial examination'. The collocation English speakers must memorize is 시험을 보다 — Koreans 'see' an exam, they do not 'do' it, so 시험을 하다 is wrong. Passing and failing are vivid metaphors with the particle 에: 시험에 붙다 (literally 'stick to the exam') = pass, 시험에 떨어지다 ('fall off the exam') = fail — note these take 에, not 을. Contrast 시험 with 퀴즈(quiz, a small in-class test) and with 검사(檢査, an inspection/medical test like 건강 검사): a graded school test is always 시험, never 퀴즈 unless it is a tiny informal one. The classic 직역 trap is 'take an exam' → 시험을 가지다/취하다 ✗ (English 'take' never transfers); and learners often write 시험을 통과하다, which is understandable but bookish — the everyday word is 붙다."},sentence:{ko:"시험 기간 동안 도서관에서 공부할 거예요.",en:"During exam period, I will study at the library."},target:"시험",options:["exam","assignment; homework task","semester; school term"],note:"Linked to dictionary card word-ext-111."},{kind:"guess",word:{ko:"도서관",romanization:"doseogwan",en:"library",pos:"noun",nuance:"도서관 is Sino-Korean 圖書館, literally 'pictures-books-building' (圖 picture + 書 writing/book + 館 hall), a public place to read, study, and borrow books where quiet is expected. The sharp contrast learners must hold is 도서관 vs 서점: a 도서관 is a LIBRARY where you borrow (빌리다) for free, while a 서점 is a BOOKSTORE where you buy (사다) — English 'library' and Spanish/French false friends like 'librería' push learners to mix these up. Note also 도서관 (the building) vs 도서 (books as items/collection). Register is neutral. Natural collocations: 도서관에서 공부하다, 책을 빌리다/반납하다, 도서관에 자리가 없다. The English-speaker pitfall, beyond the library/bookstore mix-up, is the particle split: study or read AT a library is 에서 (도서관에서), but going TO it is 에 (도서관에 가다)."},sentence:{ko:"오늘부터 도서관에서 공부하기로 했어요.",en:"I decided to study at the library starting today."},target:"도서관",options:["assignment; homework task","library","midterm exam"],note:"Linked to dictionary card word-ext-315."},{kind:"guess",word:{ko:"성적",romanization:"seongjeok",en:"grades",pos:"noun",nuance:"성적 means academic grades, marks, or results, written 成績 (成 'to accomplish, achieve' + 績 'achievement, merit'), literally 'accomplished achievements' — the outcome of your effort. Distinguish it from 점수, a single numeric 'score' on one test (시험 점수 90점), and from 시험, the 'exam' itself: you take a 시험, get a 점수 on it, and your overall 성적 reflects the term. Note the directional verbs that pair with it: 성적이 나오다 (results 'come out'/are released), 성적을 받다 (you 'receive' them), 성적이 오르다/떨어지다 (they rise/fall). The English-speaker pitfall is using 시험 where you mean the resulting grade ('my exam was good' → say 성적이 좋아요), and choosing the wrong particle: with descriptive 좋다 or motion 나오다/오르다 it's 이/가, only with 받다 is it 을/를."},sentence:{ko:"장학금을 받기 위해 좋은 성적이 필요해요.",en:"Good grades are necessary in order to get a scholarship."},target:"성적",options:["assignment; homework task","midterm exam","grades"],note:"Linked to dictionary card word-ext-403."},{kind:"payoff",line:{speaker:"지훈",ko:"네, 이번 학기 성적에 들어가니까 준비해야 해요.",en:"Yes, it counts toward this semester's grade, so we have to prepare."},hl:"성적"}],canDo:"State a decision or study plan (같이 공부하기로 했어요)",id:"chapter-54-b3",chapterId:"chapter-54",index:2},{kind:"pattern",title:"문법 Grammar · V-기로 했어요",cards:[{kind:"hunt",name:"V-기로 했어요",sub:"decided to V",lines:[{tokens:[{pre:"친구들하고",mid:"",post:"",hit:!1},{pre:"같이",mid:"",post:"",hit:!1},{pre:"도서관에서",mid:"",post:"",hit:!1},{pre:"공부하",mid:"기로",post:"",hit:!0},{pre:"",mid:"했어요",post:".",hit:!0}],ko:"친구들하고 같이 도서관에서 공부하기로 했어요.",en:"I decided to study with my friends at the library.",romanization:"chingudeulhago gachi doseogwaneseo gongbuhagiro haesseoyo."},{tokens:[{pre:"이번",mid:"",post:"",hit:!1},{pre:"학기에는",mid:"",post:"",hit:!1},{pre:"결석하지",mid:"",post:"",hit:!1},{pre:"않",mid:"기로",post:"",hit:!0},{pre:"",mid:"했어요",post:".",hit:!0}],ko:"이번 학기에는 결석하지 않기로 했어요.",en:"This semester I decided not to be absent.",romanization:"ibeon hakgieneun gyeolseokhaji anki-ro haesseoyo."}],rule:{name:"V-기로 했어요",rows:[{when:"Any verb, attach to the plain stem",add:"+ -기로 했어요",ex:"공부하다 → 공부하기로 했어요 (decided to study)"},{when:"Consonant-ending stem (no change)",add:"+ -기로 했어요",ex:"읽다 → 읽기로 했어요 (decided to read)"},{when:"Negative decision",add:"안 V / V-지 않 + -기로 했어요",ex:"지각 안 하기로 했어요 (decided not to be late)"},{when:"A standing rule (let's make it a habit)",add:"+ -기로 해요",ex:"매일 복습하기로 해요 (let's review every day)"}]},more:{func:"States a decision, plan, or promise that you (or a group) have already made. Common when classmates agree on a study plan or you resolve to do something for school.",keyPoint:{label:"-기로 했어요 vs. -(으)ㄹ 거예요",body:"-기로 했어요 highlights that a decision was made (often jointly or as a resolution). -(으)ㄹ 거예요 just states a future plan or prediction. Use -기로 했어요 when the point is 'we agreed/decided,' not merely 'I will.'"},pronunciation:"했어요 is pronounced [해써요] with a tense ㅆ. 않기로 is read [안키로]: the ㅎ of 않 fuses with the following ㄱ into an aspirated [키]."}}],canDo:"State a decision or study plan (같이 공부하기로 했어요)",id:"chapter-54-b4",chapterId:"chapter-54",index:3},{kind:"words",title:"단어 Words 3 · 장학금~",cards:[{kind:"guess",word:{ko:"장학금",romanization:"janghakgeum",en:"scholarship",pos:"noun",nuance:"장학금 is the award money granted to a student to support their studies — for merit (성적 장학금), need, or special talent — money you do not repay, unlike a loan. The hanja 奬學金 is 奬 (encourage/reward) + 學 (study/learning) + 金 (money/gold), literally 'study-encouraging money', so the very word frames it as funds that reward and enable learning. Distinguish it sharply from 학자금 (學資金, 'study-capital'), which is the broader pool of money for education and often appears in 학자금 대출 (a student loan you must repay): a 장학금 is given to you, whereas 학자금 대출 is borrowed. Also unlike a plain 돈 (money) or 용돈 (allowance), 장학금 specifically denotes an academic award. The natural verbs are 장학금을 받다 (formally receive) and the colloquial 장학금을 타다 (win/get one), plus 장학금을 신청하다 (apply) and 장학금이 나오다 (it comes through). The English-speaker pitfall is calling it just 돈 — saying 학교에서 돈을 받았어요 to mean a scholarship loses the meaning; the award is 장학금, and confusing it with the repayable 학자금 대출 reverses who gives money to whom."},sentence:{ko:"장학금을 받기 위해 좋은 성적이 필요해요.",en:"Good grades are necessary in order to get a scholarship."},target:"장학금",options:["assignment; homework task","midterm exam","scholarship"],note:"Linked to dictionary card word-ext-1963."},{kind:"guess",word:{ko:"전공",romanization:"jeongong",en:"major",pos:"noun",nuance:"전공 is your academic major — the single specialized field you concentrate on at university — written 專攻 (專 'exclusive, sole' + 攻 'to attack, devote effort to'), literally 'to devote oneself exclusively', i.e. to specialize. It can also act as a verb with 하다: 한국어를 전공하다 ('to major in Korean'). The key contrast is 전공 vs 과목: a 과목 is any one of the many courses on your timetable, whereas 전공 is the one field you commit to — you take many 과목 but have one 전공. It also differs from 학과, the 'academic department' that houses the major. The English-speaker pitfall is calling a major 과목 (제 과목은..., wrong) and forgetting that with the verb form the field takes 을/를: not 한국어 전공해요 but 한국어를 전공해요; as a plain noun, though, 전공이 뭐예요 uses 이/가."},sentence:{ko:"전공을 바꾸기 위해 교수님께 질문했어요.",en:"I asked the professor a question in order to change my major."},target:"전공",options:["assignment; homework task","major","midterm exam"],note:"Linked to dictionary card word-ext-405."},{kind:"guess",word:{ko:"학원",romanization:"hagwon",en:"private academy",pos:"noun",nuance:"학원 is a private after-school academy (cram school) where students pay for extra lessons — English, math, piano, taekwondo — written 學院 (學 'study' + 院 'institution, hall'). The 院 'institution' element links it to 병원 (病院 hospital), 대학원 (大學院 graduate school), and 미용원/미장원, so the family is learnable. Sharply distinguish 학원 (a supplementary private institute) from 학교 (學校, the regular public/formal school) and from 대학원 (graduate school) — a child attends 학교 by day and 학원 in the evening. The verb of choice is 다니다, which implies habitual commuting/membership, with the 에 particle: 학원에 다니다 ('attend an academy regularly'), not the one-off 가다. The English-speaker pitfall is using 학교 for any place of learning, or marking the destination with 를 (학원를 다녀요, wrong) instead of 에."},sentence:{ko:"한국어를 잘하기 위해 학원에 다녀요.",en:"I go to an academy in order to get good at Korean."},target:"학원",options:["assignment; homework task","midterm exam","private academy"],note:"Linked to dictionary card word-ext-406."}],canDo:"Say when an action started (공부하기 시작했어요)",id:"chapter-54-b5",chapterId:"chapter-54",index:4},{kind:"pattern",title:"문법 Grammar · V-기 시작하다",cards:[{kind:"hunt",name:"V-기 시작하다",sub:"start doing",lines:[{tokens:[{pre:"작년부터",mid:"",post:"",hit:!1},{pre:"한국어를",mid:"",post:"",hit:!1},{pre:"배우",mid:"기",post:"",hit:!0},{pre:"",mid:"시작",post:"했어요.",hit:!0}],ko:"작년부터 한국어를 배우기 시작했어요.",en:"I started learning Korean last year.",romanization:"jangnyeonbuteo hangugeoreul baeugi sijakaesseoyo."},{tokens:[{pre:"수업이",mid:"",post:"",hit:!1},{pre:"끝나고",mid:"",post:"",hit:!1},{pre:"숙제를",mid:"",post:"",hit:!1},{pre:"하",mid:"기",post:"",hit:!0},{pre:"",mid:"시작",post:"했어요.",hit:!0}],ko:"수업이 끝나고 숙제를 하기 시작했어요.",en:"After class ended, I started doing my homework.",romanization:"sueobi kkeunnago sukjereul hagi sijakaesseoyo."}],rule:{name:"V-기 시작하다",rows:[{when:"Any verb stem + 시작하다",add:"+ -기 시작하다",ex:"공부하다 → 공부하기 시작하다 (start studying)"},{when:"Consonant-ending stem (no change)",add:"+ -기 시작하다",ex:"읽다 → 읽기 시작하다 (start reading)"},{when:"Past (started, and it continues)",add:"+ -기 시작했어요",ex:"배우다 → 배우기 시작했어요 (started learning)"},{when:"Present / general statement",add:"+ -기 시작해요",ex:"듣다 → 듣기 시작해요 (start listening)"}]},more:{func:"Says that an action begins or has begun. The verb is nominalized with -기 and followed by 시작하다 (to start). Useful for saying when you started studying, learning, or a new routine.",keyPoint:{label:"V-기 시작하다 vs. N을/를 시작하다",body:"Use V-기 시작하다 to start an action (a verb): 공부하기 시작했어요. To start a thing (a noun), use N을/를 시작하다: 수업을 시작해요 (start the class). Don't say 수업하기 시작하다 when you simply mean 수업을 시작하다."},pronunciation:"시작했어요 is read [시자캐써요]: the ㄱ of 작 + the ㅎ of 했 fuse into an aspirated [ㅋ], and 했어요 becomes [캐써요]."}}],canDo:"Say when an action started (공부하기 시작했어요)",id:"chapter-54-b6",chapterId:"chapter-54",index:5},{kind:"pattern",title:"문법 Grammar · N 동안",cards:[{kind:"hunt",name:"N 동안",sub:"for / during (a period)",lines:[{tokens:[{pre:"두",mid:"",post:"",hit:!1},{pre:"시간",mid:"",post:"",hit:!1},{pre:"",mid:"동안",post:"",hit:!0},{pre:"도서관에서",mid:"",post:"",hit:!1},{pre:"공부했어요.",mid:"",post:"",hit:!1}],ko:"두 시간 동안 도서관에서 공부했어요.",en:"I studied at the library for two hours.",romanization:"du sigan dongan doseogwaneseo gongbuhaesseoyo."},{tokens:[{pre:"방학",mid:"",post:"",hit:!1},{pre:"",mid:"동안",post:"",hit:!0},{pre:"한국어",mid:"",post:"",hit:!1},{pre:"학원에",mid:"",post:"",hit:!1},{pre:"다녔어요.",mid:"",post:"",hit:!1}],ko:"방학 동안 한국어 학원에 다녔어요.",en:"During vacation I went to a Korean language academy.",romanization:"banghak dongan hangugeo hagwone danyeosseoyo."}],rule:{name:"N 동안",rows:[{when:"After a duration (length of time)",add:"N 동안 = 'for N'",ex:"한 시간 동안 (for one hour)"},{when:"After a named period",add:"N 동안 = 'during N'",ex:"방학 동안 (during the vacation)"},{when:"With a verb ('while V-ing')",add:"V-는 동안",ex:"공부하는 동안 (while studying)"},{when:"No particle before 동안",add:"(do NOT add 에/을)",ex:"삼 년 동안 (for three years), not 삼 년에 동안"}]},more:{func:"Marks a span of time over which something happens: 'for' a duration or 'during' a named period. Essential for saying how long you studied, or that something happened over vacation or a semester.",keyPoint:{label:"N 동안 (a stretch) vs. N에 (a point)",body:"Use 동안 for a span of time you do something over: 세 시간 동안 (for three hours). Use 에 for a single point in time: 세 시에 (at three o'clock). Don't mix them — 세 시간에 or 세 시간에 동안 are both wrong."},pronunciation:"동안 is two even syllables [동안]. 공부했어요 is [공부해써요], with the tense ㅆ in 했."}}],canDo:"Give a reason that leads to a plan (시험이 있으니까 도서관에 가요)",id:"chapter-54-b7",chapterId:"chapter-54",index:6},{kind:"pattern",title:"문법 Grammar · V/A-(으)니까",cards:[{kind:"hunt",name:"V/A-(으)니까",sub:"because / so (reason before a plan)",lines:[{tokens:[{pre:"성적이",mid:"",post:"",hit:!1},{pre:"중요하",mid:"니까",post:"",hit:!0},{pre:"미리",mid:"",post:"",hit:!1},{pre:"준비해요.",mid:"",post:"",hit:!1}],ko:"성적이 중요하니까 미리 준비해요.",en:"Grades are important, so let's prepare in advance.",romanization:"seongjeogi jungyohanikka miri junbihaeyo."},{tokens:[{pre:"숙제가",mid:"",post:"",hit:!1},{pre:"많",mid:"으니까",post:"",hit:!0},{pre:"오늘",mid:"",post:"",hit:!1},{pre:"시작해요.",mid:"",post:"",hit:!1}],ko:"숙제가 많으니까 오늘 시작해요.",en:"There's a lot of homework, so let's start today.",romanization:"sukjega maneunikka oneul sijakaeyo."}],rule:{name:"V/A-(으)니까",rows:[{when:"Stem ends in a vowel",add:"+ -니까",ex:"바쁘다 → 바쁘니까 (since I'm busy)"},{when:"Stem ends in a consonant",add:"+ -으니까",ex:"많다 → 많으니까 (since there are many)"},{when:"하다 verbs/adjectives",add:"하 + -니까",ex:"중요하다 → 중요하니까 (since it's important)"},{when:"Past tense",add:"-았/었 + -으니까",ex:"끝났다 → 끝났으니까 (since it ended)"}]},more:{func:"Gives a reason that leads into a request, suggestion, or plan: 'since A, (let's) B.' In school talk it links why something matters to what you should do next.",keyPoint:{label:"-(으)니까 vs. -아/어서 for 'because'",body:"Both give reasons, but only -(으)니까 can lead into a command, suggestion, or 'let's' (시험이 가까우니까 공부해요). -아/어서 cannot: you can't say 시험이 가까워서 공부합시다. Use -(으)니까 when the next clause is a request or proposal."},pronunciation:"많으니까 is read [마느니까]: the ㅎ in 많 is silent before a vowel. 끝났으니까 is [끈나쓰니까]."}},{kind:"drill",prompt:"The exam is near, so I study at the library.",sentence:"시험이 가까우___ 도서관에서 공부해요.",options:[{text:"니까",ok:!0},{text:"으니까",ok:!1}],explanation:"가깝다 is ㅂ-irregular: 가까우니까."}],canDo:"State an academic purpose (장학금을 받기 위해서 공부해요)",id:"chapter-54-b8",chapterId:"chapter-54",index:7},{kind:"pattern",title:"문법 Grammar · V-기 위해서",cards:[{kind:"hunt",name:"V-기 위해서",sub:"in order to (purpose)",lines:[{tokens:[{pre:"좋은",mid:"",post:"",hit:!1},{pre:"성적을",mid:"",post:"",hit:!1},{pre:"받",mid:"기",post:"",hit:!0},{pre:"",mid:"위해서",post:"",hit:!0},{pre:"매일",mid:"",post:"",hit:!1},{pre:"공부해요.",mid:"",post:"",hit:!1}],ko:"좋은 성적을 받기 위해서 매일 공부해요.",en:"I study every day in order to get good grades.",romanization:"joeun seongjeogeul batgi wihaeseo maeil gongbuhaeyo."},{tokens:[{pre:"시험에",mid:"",post:"",hit:!1},{pre:"합격하",mid:"기",post:"",hit:!0},{pre:"",mid:"위해서",post:"",hit:!0},{pre:"학원에",mid:"",post:"",hit:!1},{pre:"다녀요.",mid:"",post:"",hit:!1}],ko:"시험에 합격하기 위해서 학원에 다녀요.",en:"I go to an academy in order to pass the exam.",romanization:"siheome hapgyeokhagi wihaeseo hagwone danyeoyo."}],rule:{name:"V-기 위해서",rows:[{when:"Any verb, attach to the stem",add:"+ -기 위해서",ex:"합격하다 → 합격하기 위해서 (in order to pass)"},{when:"Common short form",add:"+ -기 위해",ex:"받다 → 받기 위해 (in order to get)"},{when:"With a noun goal",add:"N을/를 위해서",ex:"시험을 위해서 (for the exam)"},{when:"Negative goal (use 지 않기 위해서)",add:"V-지 않기 위해서",ex:"늦지 않기 위해서 (in order not to be late)"}]},more:{func:"Marks a deliberate goal: you do B in order to achieve A. Good for academic goals like passing, getting a scholarship, raising your grade, or getting into a program. Often shortened to -기 위해.",keyPoint:{label:"V-기 위해서 vs. V-(으)러",body:"Both express purpose, but -(으)러 only attaches to motion verbs like 가다/오다 (공부하러 가요 = go to study). -기 위해서 has no such limit and works with any main verb (장학금을 받기 위해서 공부해요). For a goal that isn't 'going somewhere to do it,' use -기 위해서."},pronunciation:"받기 위해서 is read [받끼 위해서]: the ㄷ tenses the following ㄱ to [ㄲ]. 합격하기 is [합껴카기]."}}],canDo:"Say what I have to do for school (과제를 내야 해요)",id:"chapter-54-b9",chapterId:"chapter-54",index:8},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Classmates plan around a presentation assignment and upcoming exams.",lines:[{speaker:"민서",ko:"중간고사 전에 발표 과제를 끝내야 해요?",en:"Do we have to finish the presentation assignment before the midterm?",romanization:"junggangosa jeone balpyo gwajereul kkeutnaeya haeyo?"},{speaker:"지훈",ko:"네, 이번 학기 성적에 들어가니까 준비해야 해요.",en:"Yes, it counts toward this semester's grade, so we have to prepare.",romanization:"ne, ibeon hakgi seongjeoge deureoganikka junbihaeya haeyo."},{speaker:"민서",ko:"그럼 오늘부터 도서관에서 공부하기 시작하기로 했어요.",en:"Then I decided to start studying at the library from today.",romanization:"geureom oneulbuteo doseogwaneseo gongbuhagi sijakagiro haesseoyo."},{speaker:"지훈",ko:"기말고사에서 좋은 성적을 받기 위해 시험 기간 동안 매일 공부해야 해요.",en:"In order to get a good grade on the final exam, we have to study every day during exam period.",romanization:"gimalgosaeseo joeun seongjeogeul batgi wihae siheom gigan dongan maeil gongbuhaeya haeyo."}]},{kind:"order",prompt:"Build: 'I decided to study at the library during exam period.' (Start with 시험 기간 동안.)",tokens:["시험 기간 동안","도서관에서","공부하기로 했어요"],correct:"시험 기간 동안 도서관에서 공부하기로 했어요",explanation:"동안 gives the period, and 도서관에서 gives the study place. -기로 했어요 states the decision."}],canDo:"Say what I have to do for school (과제를 내야 해요)",id:"chapter-54-b10",chapterId:"chapter-54",index:9},{kind:"reading",title:"읽기 Reading · 중간고사 전에 발표 과제를 끝내야 해요",cards:[{kind:"read",title:"중간고사 전에 발표 과제를 끝내야 해요",chunks:["민서는 이번 학기에 한국어 수업을 듣고 있어요. 중간고사 전에 발표 과제를 끝내야 해서 친구와 일정을 정했어요. 발표가 성적에 들어가니까 오늘부터 준비하기 시작하기로 했어요.","시험 기간 동안은 도서관에서 매일 공부할 거예요. 기말고사에서 좋은 성적을 받기 위해 복습도 하고, 모르는 것은 교수님께 질문하기로 했어요. 장학금을 받으려면 좋은 성적이 필요하니까 이번 학기에는 더 꾸준히 공부해야 해요."],translation:"Minseo is taking a Korean class this semester. Because the presentation assignment must be finished before the midterm, Minseo made a schedule with a friend. Since the presentation counts toward the grade, they decided to start preparing from today. During exam period, Minseo will study at the library every day. In order to get a good grade on the final, Minseo will review and ask the professor about things they do not know. Since good grades are needed for a scholarship, Minseo has to study more consistently this semester.",qas:[{q:"민서는 언제까지 발표 과제를 끝내야 해요?",a:"중간고사 전에 끝내야 해요."},{q:"시험 기간 동안 어디에서 공부할 거예요?",a:"도서관에서 공부할 거예요."},{q:"무엇을 받으려면 좋은 성적이 필요해요?",a:"장학금을 받으려면 좋은 성적이 필요해요."}]}],canDo:"State a decision or study plan (같이 공부하기로 했어요)",id:"chapter-54-b11",chapterId:"chapter-54",index:10},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence gives a school obligation?",sentence:null,options:[{text:"중간고사 전에 발표 과제를 끝내야 해요.",ok:!0},{text:"중간고사 전에 발표 과제를 끝낼 리가 없어요.",ok:!1},{text:"중간고사 전에 발표 과제를 끝내더라고요.",ok:!1}],explanation:"-아/어야 해요 means have to."},{kind:"drill",prompt:"Which sentence states a study decision?",sentence:null,options:[{text:"도서관에서 공부하기로 했어요.",ok:!0},{text:"도서관에서 공부한 척했어요.",ok:!1},{text:"도서관에서 공부할 뻔했어요.",ok:!1}],explanation:"-기로 했어요 states what was decided."},{kind:"drill",prompt:"Which sentence uses 동안 correctly?",sentence:null,options:[{text:"시험 기간 동안 매일 공부해요.",ok:!0},{text:"시험 기간에 동안 매일 공부해요.",ok:!1},{text:"시험 기간을 동안 매일 공부해요.",ok:!1}],explanation:"Put 동안 directly after the time span noun."},{kind:"drill",prompt:"과제___ 해야 해요. (I have to do the assignment.)",sentence:null,options:[{text:"를",ok:!0},{text:"가",ok:!1},{text:"에",ok:!1}],explanation:"하다 takes the assignment as an object, so 과제를 fits. 가 would make the assignment the subject."},{kind:"order",prompt:"Build: 'I decided to study at the library during exam period.' (Start with 시험 기간 동안.)",tokens:["시험 기간 동안","도서관에서","공부하기로 했어요"],correct:"시험 기간 동안 도서관에서 공부하기로 했어요",explanation:"동안 gives the period, and 도서관에서 gives the study place. -기로 했어요 states the decision."},{kind:"drill",prompt:"Which sentence states a personal study decision?",sentence:null,options:[{text:"오늘부터 도서관에서 공부하기로 했어요.",ok:!0},{text:"오늘부터 공부해야 해요.",ok:!1},{text:"오늘부터 공부하는 동안이에요.",ok:!1}],explanation:"-기로 했어요 marks a decision. -아/어야 해요 marks obligation instead."}],canDo:"Say when an action started (공부하기 시작했어요)",id:"chapter-54-b12",chapterId:"chapter-54",index:11}]},{id:"chapter-55",number:55,title:"N(으)로 · V-(으)러 가요",goal:"Ask and answer subway transfer questions with 호선, 환승, 갈아타다, and 승강장.",biteCount:12,bites:[{kind:"words",title:"단어 Words 1 · 환승~",cards:[{kind:"guess",word:{ko:"환승",romanization:"hwanseung",en:"transfer",pos:"noun",nuance:"환승 means transferring between buses and subways. If you tap the same transit card, transfers within a time limit are usually discounted or free."},sentence:{ko:"서울역에 가려면 어디서 환승해요?",en:"Where do I transfer if I want to get to Seoul Station?"},target:"환승",options:["subway line number","transfer","platform"],note:"Official transit noun; 갈아타다 is the everyday action verb."},{kind:"guess",word:{ko:"갈아타다",romanization:"garatada",en:"to transfer / change vehicles",pos:"verb",nuance:"갈아타다 is a transparent compound of 갈다 'to change/replace' + 타다 'to ride', so it literally means 'change-ride' — you get off one vehicle and board a different one. The dividing line learners must feel is against plain 타다 (just 'to board/get on') and against 환승하다, the Sino-Korean twin (換乘, 換 'exchange' + 乘 'ride', literally 'change-ride') printed on every subway sign and announcement: 갈아타다 is the warm spoken word a friend uses ('여기서 갈아타'), while 환승하다 is the signage/official register ('환승 게이트'). The grammar trap is the particle: the vehicle you move TO takes 로/으로 (지하철로 갈아타다), the same directional 로 as 'change INTO', and the station where you do it takes 에서 — English 'transfer to the subway' tempts you to drop the particle or use 에. Because 타다 is regular, every form is regular too: the stem 타- already ends in ㅏ, so the 아 of 아요 merges in and disappears, giving 갈아타요 (not 갈아타아요), and the past is 갈아탔어요. Habitual collocations: 다른 노선으로 갈아타다, 같은 방향으로 갈아타다."},sentence:{ko:"시청역에서 1호선으로 갈아타세요.",en:"Transfer to Line 1 at City Hall Station."},target:"갈아타",options:["to transfer / change vehicles","to book a ticket in advance","subway line number"],note:"Linked to verb card word-verb-378."},{kind:"guess",word:{ko:"호선",romanization:"hoseon",en:"subway line number",pos:"noun",nuance:"호선 is for subway line labels, not for bus routes. Say 2호선 for Line 2, but 버스 노선 for a bus route."},sentence:{ko:"서울역에 가려면 몇 호선으로 갈아타요?",en:"Which line do I transfer to if I want to get to Seoul Station?"},target:"호선",options:["transfer","platform","subway line number"],note:"Chapter card word-ext-ch55-hoseon."},{kind:"guess",word:{ko:"승강장",romanization:"seunggangjang",en:"platform",pos:"noun",nuance:"승강장 乘降場 stacks 乘 (board/get on) + 降 (alight/get off) + 場 (place/field) = 'the place where you board and get off', i.e. the platform along the tracks. It is the formal term on signage and in announcements; the everyday spoken equivalent is 플랫폼 (the English loanword), and 타는 곳 ('boarding place') is the plain-Korean label posted in many stations — all three point to the same spot. The crucial contrast is with 정류장 停留場 (a bus/tram STOP at the roadside) and 역 (the whole STATION building): the 승강장 is the specific edge where you stand beside the train, inside the 역. As a 場 place-noun it takes 에서 for waiting (승강장에서 기다려요) and 으로 for moving toward it (승강장으로 가요). The English-speaker pitfall is treating the platform as something you wait 'for': you wait for the TRAIN on the platform, so it's 승강장에서 기차를 기다려요, never 승강장을 기다려요."},sentence:{ko:"3번 승강장으로 가세요.",en:"Please go to platform 3."},target:"승강장",options:["transfer","subway line number","platform"],note:"Linked to dictionary card word-ext-1597."},{kind:"guess",word:{ko:"노선",romanization:"noseon",en:"route, transit line",pos:"noun",nuance:"노선(路線) is Sino-Korean 路 'road' + 線 'line' — literally a 'road-line' — meaning a transit route/line for both buses and subways; the famous 노선도(路線圖) 'route map' (圖 = diagram) is the colored subway map newcomers squint at. The key usage split: for a specific subway line Koreans say the number + 호선 (2호선 'Line 2'), while 노선 is the general word for a route's path, used heavily for buses (버스 노선). Pitfalls: don't conflate 노선 'the route itself' with 노선도 'the map of routes' — one is the line, the other the diagram. And don't say 2노선 for Line 2; the counter is 호선. Apps like 카카오맵/네이버지도 list every 노선 and timetable."},sentence:{ko:"이 노선은 배차 간격이 길어요.",en:"This route has a long service interval."},target:"노선",options:["route, transit line","transfer","platform"],note:"Linked to dictionary card word-ext-631."},{kind:"guess",word:{ko:"교통카드",romanization:"gyotongkadeu",en:"transit card",pos:"noun",nuance:"교통카드(交通+card) literally welds the Sino-Korean 교통 'traffic/transport' onto the English 'card', and names the rechargeable tap-to-ride card (T머니, 캐시비, or a 후불 credit card) for buses, the subway, and even some taxis. The make-or-break verb is 찍다 'to tap/stamp', never 누르다 'to press a button' — you lay the card flat on the reader, you don't push anything. A prepaid card you 충전 'top up' at convenience stores; the gate beeps your 잔액 'remaining balance'. Don't confuse it with a plain 카드, which to a Korean means a credit/debit card for shopping; the tap-to-ride one is always the full 교통카드. English 'swipe' also misleads — there is no magnetic swipe, only a contactless 찍다."},sentence:{ko:"교통카드를 충전하려고 해요.",en:"I am trying to top up my transit card."},target:"교통카드",options:["transfer","transit card","subway line number"],note:"Linked to dictionary card word-ext-622."},{kind:"payoff",line:{speaker:"민서",ko:"지금 홍대입구역인데 서울역 가려면 어디서 환승해?",en:"I am at Hongik University Station now. Where do I transfer to get to Seoul Station?"},hl:"환승"}],canDo:"Say what I travel by or which way I go (버스로, 2호선으로)",id:"chapter-55-b1",chapterId:"chapter-55",index:0},{kind:"pattern",title:"문법 Grammar · N(으)로",cards:[{kind:"hunt",name:"N(으)로",sub:"by (a means of transport) / via (a route)",lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"버스",mid:"로",post:"",hit:!0},{pre:"학교에",mid:"",post:"",hit:!1},{pre:"가요.",mid:"",post:"",hit:!1}],ko:"저는 버스로 학교에 가요.",en:"I go to school by bus.",romanization:"jeoneun beoseuro hakgyoe gayo."},{tokens:[{pre:"지하철",mid:"로",post:"",hit:!0},{pre:"가면",mid:"",post:"",hit:!1},{pre:"더",mid:"",post:"",hit:!1},{pre:"빨라요.",mid:"",post:"",hit:!1}],ko:"지하철로 가면 더 빨라요.",en:"It's faster if you go by subway.",romanization:"jihacheollo gamyeon deo ppallayo."}],rule:{name:"N(으)로",rows:[{when:"Noun ends in a vowel",add:"-로",ex:"택시 → 택시로 (by taxi)"},{when:"Noun ends in ㄹ",add:"-로",ex:"지하철 → 지하철로 (by subway)"},{when:"Noun ends in any other consonant",add:"-으로",ex:"오른쪽 → 오른쪽으로 (to the right)"}]},more:{func:"Attach (으)로 to a noun to say what you travel by (버스로 = by bus) or which way you go (이 길로 = this way). In transportation talk it is the everyday particle for naming the vehicle, the subway line, or the road you take.",keyPoint:{label:"(으)로 가다 vs 을/를 타고 가다",body:"버스로 가요 and 버스를 타고 가요 both mean 'go by bus.' (으)로 simply labels the means in one word; 을/를 타고 literally says 'ride and go,' picturing you boarding. Use (으)로 for the quick, neutral 'by ___,' and 을/를 타고 when you want to stress actually getting on."},pronunciation:"After ㄹ the two ㄹ sounds link: 지하철로 is said [지하철로] as 'jihacheollo,' not 'jihacheoro.' Same for 이 길로 → 'gillo.'"}}],canDo:"Say what I travel by or which way I go (버스로, 2호선으로)",id:"chapter-55-b2",chapterId:"chapter-55",index:1},{kind:"words",title:"단어 Words 2 · 충전~",cards:[{kind:"guess",word:{ko:"충전",romanization:"chungjeon",en:"top-up / charge",pos:"noun",nuance:"For transit cards, 충전 is a top-up. For phones, it is battery charging. The object matters: 교통카드를 충전하다 versus 휴대폰을 충전하다."},sentence:{ko:"교통카드에 만 원 충전해 주세요.",en:"Please top up my transit card with 10,000 won."},target:"충전",options:["transfer","subway line number","top-up / charge"],note:"Transit-card top-up phrase; the card takes 에 when money is added."},{kind:"guess",word:{ko:"KTX",romanization:"KTX",en:"KTX high-speed train",pos:"noun",nuance:"KTX (Korea Train eXpress, spoken letter-by-letter as 케이티엑스) is the fast premium train Koreans set against three cheaper options: the 고속버스, the slower 무궁화호, and the mid-tier ITX-새마을. The boundary worth fixing is KTX vs SRT — both are bullet trains, but KTX is run by 코레일 (Korail) and SRT is a separate operator from 수서역, so the booking app differs. Note it behaves grammatically more like a proper noun than 버스: 'by KTX' is naturally KTX로/으로, where buses prefer 타고. It collocates with 타다, 예매하다, 표, and the seat tiers 특실/일반실/자유석/입석. The signature English-speaker pitfall is reading the letters in English; a Korean always says 케이티엑스, sounding each letter Korean-style. A second trap is booking on the wrong app — for KTX you need 코레일톡, not the SRT app."},sentence:{ko:"서울에서 부산까지 KTX로 가요.",en:"I go from Seoul to Busan by KTX."},target:"KTX",options:["transfer","subway line number","KTX high-speed train"],note:"Linked to dictionary card word-ext-993."},{kind:"guess",word:{ko:"표",romanization:"pyo",en:"ticket",pos:"noun",nuance:"표 is the general ticket word. 입장권 is more specifically an admission ticket for entering a venue, so KTX 표 should not be replaced with 입장권."},sentence:{ko:"부산 가는 표 있어요?",en:"Are there tickets to Busan?"},target:"표",options:["transfer","ticket","subway line number"],note:"General ticket word for KTX, buses, movies, and events."},{kind:"guess",word:{ko:"매표소",romanization:"maepyoso",en:"ticket counter / ticket office",pos:"noun",nuance:"매표소 is the selling place for tickets. 표 is the ticket itself, and 예매하다 is the booking action."},sentence:{ko:"KTX 표 예매하러 매표소에 가요.",en:"I am going to the ticket counter to book a KTX ticket."},target:"매표소",options:["ticket counter / ticket office","transfer","subway line number"],note:"Chapter card word-ext-ch55-maepyoso."},{kind:"guess",word:{ko:"예매하다",romanization:"yemaehada",en:"to book a ticket in advance",pos:"verb",nuance:"예매하다 is ticket-centered and usually means the seat or ticket is secured before departure or showtime. 예약하다 is broader and can mean reserving a restaurant, hotel, appointment, or service."},sentence:{ko:"부산 가는 KTX 표를 예매하려고 해요.",en:"I am trying to book a KTX ticket to Busan."},target:"예매하",options:["to transfer / change vehicles","to book a ticket in advance","transfer"],note:"Chapter card word-ext-ch55-yemaehada."},{kind:"guess",word:{ko:"편도",romanization:"pyeondo",en:"one-way",pos:"noun",nuance:"편도 is the opposite of 왕복. It answers the ticket type question, not the destination question."},sentence:{ko:"부산 표는 편도로 예매할게요.",en:"I will book the Busan ticket one-way."},target:"편도",options:["one-way","transfer","subway line number"],note:"Chapter card word-ext-ch55-pyeondo."},{kind:"payoff",line:{speaker:"민서",ko:"고마워. 부산 가는 KTX 표를 예매하려고 하는데 편도면 돼?",en:"Thanks. I am trying to book a KTX ticket to Busan. Is one-way okay?"},hl:"KTX"}],canDo:"Give the purpose of a trip (표를 사러 가요)",id:"chapter-55-b3",chapterId:"chapter-55",index:2},{kind:"pattern",title:"문법 Grammar · V-(으)러 가요",cards:[{kind:"teach",name:"V-(으)러 가요",sub:"go (somewhere) in order to do something",rows:[{when:"Verb stem ends in a consonant",add:"-으러",ex:"표를 받다 → 표를 받으러 가요 (go to pick up the ticket)"},{when:"Verb stem ends in a vowel",add:"-러",ex:"타다 → 타러 가요 (go to catch/board it)"},{when:"Verb stem ends in ㄹ",add:"-러 (ㄹ stays)",ex:"(표를) 팔다 → 팔러 가요 (go to sell the ticket)"}],examples:[{ko:"기차표를 사러 역에 가요.",en:"I'm going to the station to buy a train ticket.",romanization:"gichapyoreul sareo yeoge gayo.",note:"사다 ends in a vowel → -러; the purpose (buying a ticket) comes before the movement verb 가요."},{ko:"친구를 만나러 부산에 가요.",en:"I'm going to Busan to meet a friend.",romanization:"chingureul mannareo busane gayo.",note:"만나다 → 만나러; the whole trip is for meeting the friend."}],more:{func:"Attach -(으)러 to a verb stem before a movement verb (가다 / 오다 / 다니다) to give the purpose of the trip: you go or come somewhere in order to do that action. Very common for travel errands like buying tickets or topping up a card.",keyPoint:{label:"-(으)러 needs a 'go/come' verb",body:"-(으)러 must be followed by a movement verb (가다, 오다, 다니다). You cannot say 표를 사러 공부해요 — the main verb has to involve going or coming. If your main verb is not movement, use -(으)려고 instead (Note 3)."},pronunciation:"받으러 links the final ㄷ into the 으: say [바드러] 'badeureo,' not [받으러] with a hard stop."}}],canDo:"Give the purpose of a trip (표를 사러 가요)",id:"chapter-55-b4",chapterId:"chapter-55",index:3},{kind:"words",title:"단어 Words 3 · 왕복~",cards:[{kind:"guess",word:{ko:"왕복",romanization:"wangbok",en:"round trip",pos:"noun",nuance:"왕복 is the ticket-plan pair of 편도. The question 편도예요, 왕복이에요? is a normal ticket-counter question."},sentence:{ko:"돌아오는 시간도 정했으면 왕복으로 예매하세요.",en:"If you have decided the return time too, book it round-trip."},target:"왕복",options:["round trip","transfer","subway line number"],note:"Chapter card word-ext-ch55-wangbok."},{kind:"guess",word:{ko:"매진",romanization:"maejin",en:"sold out for tickets/seats",pos:"noun",nuance:"매진 is for tickets and seats. 품절 is for products on a shelf or in an online store."},sentence:{ko:"KTX 표가 매진이면 다음 기차로 예매하세요.",en:"If the KTX tickets are sold out, book the next train."},target:"매진",options:["transfer","sold out for tickets/seats","subway line number"],note:"Chapter card word-ext-ch55-maejin."},{kind:"guess",word:{ko:"지연",romanization:"jiyeon",en:"delay",pos:"noun",nuance:"지연 sounds more official than 늦다. Use 늦다 for a person being late and 지연 for a service, schedule, or system delay."},sentence:{ko:"버스 지연 때문에 약속에 늦었어요.",en:"I was late to the appointment because of a bus delay."},target:"지연",options:["transfer","delay","subway line number"],note:"Chapter card word-ext-ch55-jiyeon."},{kind:"guess",word:{ko:"배차 간격",romanization:"baecha gangyeok",en:"service interval",pos:"noun",nuance:"배차 간격 is not the travel time. It is the gap between one bus or train and the next one."},sentence:{ko:"이 노선은 배차 간격이 길어서 택시로 갈게요.",en:"This route has a long service interval, so I will go by taxi."},target:"배차 간격",options:["service interval","transfer","subway line number"],note:"Chapter card word-ext-ch55-baecha-gangyeok."},{kind:"guess",word:{ko:"택시",romanization:"taeksi",en:"taxi",pos:"noun",nuance:"택시로 가요 and 택시를 타요 are both natural, but they answer different questions: method versus boarding action."},sentence:{ko:"버스가 지연되면 택시로 갈게요.",en:"If the bus is delayed, I will go by taxi."},target:"택시",options:["taxi","transfer","platform"],note:"Method phrase with 로: 택시로 가다."},{kind:"guess",word:{ko:"막차",romanization:"makcha",en:"last train or bus",pos:"noun",nuance:"막차 fuses the native prefix 막- 'last/final' with 차(車) 'vehicle', literally 'the last vehicle', and it dominates Korean nightlife because the subway stops near midnight and missing it means a pricey taxi. Its exact opposite is 첫차 'first vehicle'. Two collocations are everywhere: 막차 끊기다 'the last service is cut off (gone)' and 막차 놓치다 'miss the last one'. The key pitfall is the English verb 'miss' — Korean uses 놓치다 'let slip', NEVER 잃어버리다 'lose (an object)', so 막차를 잃어버렸어요 sounds like you misplaced a train. Also note 막차 시간 is the DEPARTURE time, so a learner who reads it as an arrival time will stroll up just as the doors close."},sentence:{ko:"막차를 놓치면 첫차를 타야 해요.",en:"If you miss the last train, you have to take the first train."},target:"막차",options:["transfer","last train or bus","subway line number"],note:"Linked to dictionary card word-ext-624."},{kind:"payoff",line:{speaker:"지훈",ko:"응, 돌아오는 시간 안 정했으면 편도로 해. 매진이면 다음 기차 확인하고.",en:"Yes, if you have not set the return time, book it one-way. If it is sold out, check the next train."},hl:"매진"}],canDo:"State a travel intention (예매하려고 해요)",id:"chapter-55-b5",chapterId:"chapter-55",index:4},{kind:"pattern",title:"문법 Grammar · V-(으)려고 해요",cards:[{kind:"hunt",name:"V-(으)려고 해요",sub:"be planning / intending to do something",lines:[{tokens:[{pre:"이번",mid:"",post:"",hit:!1},{pre:"주말에는",mid:"",post:"",hit:!1},{pre:"기차로",mid:"",post:"",hit:!1},{pre:"부산에",mid:"",post:"",hit:!1},{pre:"가",mid:"려고",post:"",hit:!0},{pre:"",mid:"해요",post:".",hit:!0}],ko:"이번 주말에는 기차로 부산에 가려고 해요.",en:"This weekend I'm planning to go to Busan by train.",romanization:"ibeon jumareneun gicharo busane garyeogo haeyo."},{tokens:[{pre:"차가",mid:"",post:"",hit:!1},{pre:"막혀서",mid:"",post:"",hit:!1},{pre:"지하철을",mid:"",post:"",hit:!1},{pre:"타",mid:"려고",post:"",hit:!0},{pre:"",mid:"해요",post:".",hit:!0}],ko:"차가 막혀서 지하철을 타려고 해요.",en:"Traffic is bad, so I'm going to take the subway.",romanization:"chaga makhyeoseo jihacheoreul taryeogo haeyo."}],rule:{name:"V-(으)려고 해요",rows:[{when:"Verb stem ends in a consonant",add:"-으려고 해요",ex:"표를 찾다 → 찾으려고 해요 (I plan to pick up the ticket)"},{when:"Verb stem ends in a vowel",add:"-려고 해요",ex:"타다 → 타려고 해요 (I intend to take it)"},{when:"Verb stem ends in ㄹ",add:"-려고 해요 (ㄹ stays)",ex:"(표를) 팔다 → 팔려고 해요 (I plan to sell the ticket)"}]},more:{func:"Attach -(으)려고 하다 to a verb stem to say what you intend or plan to do. With travel it means 'I'm going to / I'm trying to' make the trip or booking. It states a decided intention, softer than the firm future -(으)ㄹ 거예요.",keyPoint:{label:"-(으)려고 vs -(으)러",body:"-(으)러 needs a movement main verb and means 'go/come TO DO something' (표를 사러 가요). -(으)려고 (해요) states the intention itself and works with ANY main verb (표를 사려고 해요 = 'I plan to buy a ticket'). If you can drop 가요/와요 and still have a full sentence, you want -(으)려고 해요."},pronunciation:"In casual speech people sometimes say 갈려고 with an extra ㄹ, but the standard form keeps one ㄹ: 가려고 'garyeogo,' not 갈려고."}}],canDo:"State a travel intention (예매하려고 해요)",id:"chapter-55-b6",chapterId:"chapter-55",index:5},{kind:"pattern",title:"문법 Grammar · A/V-(으)면",cards:[{kind:"hunt",name:"A/V-(으)면",sub:"if / when (a travel condition happens)",lines:[{tokens:[{pre:"길이",mid:"",post:"",hit:!1},{pre:"막히",mid:"면",post:"",hit:!0},{pre:"지하철을",mid:"",post:"",hit:!1},{pre:"타세요.",mid:"",post:"",hit:!1}],ko:"길이 막히면 지하철을 타세요.",en:"If the road is jammed, take the subway.",romanization:"giri makhimyeon jihacheoreul taseyo."},{tokens:[{pre:"버스를",mid:"",post:"",hit:!1},{pre:"놓치",mid:"면",post:"",hit:!0},{pre:"다음",mid:"",post:"",hit:!1},{pre:"버스를",mid:"",post:"",hit:!1},{pre:"기다려야",mid:"",post:"",hit:!1},{pre:"해요.",mid:"",post:"",hit:!1}],ko:"버스를 놓치면 다음 버스를 기다려야 해요.",en:"If you miss the bus, you have to wait for the next one.",romanization:"beoseureul notchimyeon daeum beoseureul gidaryeoya haeyo."}],rule:{name:"A/V-(으)면",rows:[{when:"Stem ends in a vowel",add:"-면",ex:"막히다 → 막히면 (if it's jammed)"},{when:"Stem ends in a consonant",add:"-으면",ex:"놓치다 is a vowel stem; consonant example: 없다 → 없으면 (if there isn't)"},{when:"Stem ends in ㄹ",add:"-면 (ㄹ stays)",ex:"길다 → 길면 (if it's long)"}]},more:{func:"Attach -(으)면 to a verb or adjective stem to set up a condition: 'if/when ___, then ___.' In transportation it covers fallback plans: if the bus is delayed, if you miss the last train, if tickets are sold out.",keyPoint:{label:"-(으)면 vs -(으)니까",body:"-(으)면 is hypothetical 'if' (막히면 = if it gets jammed — may or may not happen). -(으)니까 gives a real, already-true reason 'since/because' (막히니까 = since it's jammed right now). Don't use -(으)면 for a present fact you can already see."},pronunciation:"없으면 links the ㅄ cluster: say [업쓰면] 'eopsseumyeon.' After a consonant stem, the buffer 으 is heard clearly: 먹으면 [머그면]. 놓치다 ends in a vowel, so it simply becomes 놓치면."}}],canDo:"Make a fallback plan with a condition (늦으면 버스로 가요)",id:"chapter-55-b7",chapterId:"chapter-55",index:6},{kind:"pattern",title:"문법 Grammar · N 때문에",cards:[{kind:"hunt",name:"N 때문에",sub:"because of (a transport cause)",lines:[{tokens:[{pre:"버스",mid:"",post:"",hit:!1},{pre:"지연",mid:"",post:"",hit:!1},{pre:"",mid:"때문에",post:"",hit:!0},{pre:"약속에",mid:"",post:"",hit:!1},{pre:"늦었어요.",mid:"",post:"",hit:!1}],ko:"버스 지연 때문에 약속에 늦었어요.",en:"I was late for the appointment because of a bus delay.",romanization:"beoseu jiyeon ttaemune yaksoge neujeosseoyo."},{tokens:[{pre:"사고",mid:"",post:"",hit:!1},{pre:"",mid:"때문에",post:"",hit:!0},{pre:"길이",mid:"",post:"",hit:!1},{pre:"많이",mid:"",post:"",hit:!1},{pre:"막혀요.",mid:"",post:"",hit:!1}],ko:"사고 때문에 길이 많이 막혀요.",en:"The road is very jammed because of an accident.",romanization:"sago ttaemune giri mani makhyeoyo."}],rule:{name:"N 때문에",rows:[{when:"Noun cause (any ending)",add:"N 때문에",ex:"지연 → 지연 때문에 (because of a delay)"},{when:"Do NOT add 이/가 or 을/를",add:"(no particle before 때문에)",ex:"사고 때문에, not 사고가 때문에"},{when:"For a verb/adjective reason instead",add:"use -아/어서 or -(으)니까",ex:"막혀서 늦었어요 (was late because it was jammed)"}]},more:{func:"Use N 때문에 to name the noun reason that something happened or that a plan changed. In transportation it explains delays and disruptions: 지연 때문에 (because of a delay), 사고 때문에 (because of an accident).",keyPoint:{label:"N 때문에 vs V/A-아서",body:"Use N 때문에 when the reason is a NOUN (지연 때문에). When the reason is a verb or adjective, switch to -아/어서: 지하철이 늦어서 (because the subway was late). You cannot put a full verb directly before 때문에 — you'd need to nominalize it (늦었기 때문에)."},pronunciation:"때문에 links the ㄴ into 에: say [때무네] 'ttaemune,' as one smooth phrase, not 'ttaemun-e' with a pause."}}],canDo:"Explain a delay's cause and tie a tip to a moment (사고 때문에, 갈아탈 때 조심하세요)",id:"chapter-55-b8",chapterId:"chapter-55",index:7},{kind:"pattern",title:"문법 Grammar · V-(으)ㄹ 때",cards:[{kind:"teach",name:"V-(으)ㄹ 때",sub:"when (the moment you do a travel action)",rows:[{when:"Verb stem ends in a vowel",add:"-ㄹ 때",ex:"타다 → 탈 때 (when you ride)"},{when:"Verb stem ends in a consonant",add:"-을 때",ex:"갈아타다 → 갈아탈 때 (when you transfer); 받다 → 받을 때 (when you receive)"},{when:"Verb stem ends in ㄹ",add:"-ㄹ 때 (one ㄹ, the stem ㄹ drops into it)",ex:"놀다 → 놀 때; here use 만들다 → 만들 때"}],examples:[{ko:"환승할 때 출구 번호도 확인하세요.",en:"When you transfer, check the exit number too.",romanization:"hwanseunghal ttae chulgu beonhodo hwaginhaseyo.",note:"환승하다 → 환승할 때; a real subway-navigation tip."},{ko:"표를 예매할 때 편도인지 왕복인지 확인하세요.",en:"When booking a ticket, check whether it's one-way or round-trip.",romanization:"pyoreul yemaehal ttae pyeondoinji wangboginji hwaginhaseyo.",note:"예매하다 → 예매할 때; a useful ticket-buying check."}],more:{func:"Attach -(으)ㄹ 때 to a verb stem to name the moment an action happens: 'when transferring,' 'when booking,' 'when you ride.' It is the everyday way to give travel tips and warnings tied to a specific moment.",keyPoint:{label:"-(으)ㄹ 때 (present/general) vs -았/었을 때 (completed)",body:"Plain -(으)ㄹ 때 names the moment of an ongoing or general action: 탈 때 = 'when (in the act of) riding.' Add past -았/었을 때 for a moment after something finished: 내렸을 때 = 'when I had gotten off.' For habits and instructions you almost always want plain -(으)ㄹ 때."},pronunciation:"The 때 after -ㄹ tenses to a hard sound: 탈 때 is said [탈 떼] 'tal ttae,' and 할 때 is 'hal ttae,' with a tightened ㄸ."}}],canDo:"Say what I travel by or which way I go (버스로, 2호선으로)",id:"chapter-55-b9",chapterId:"chapter-55",index:8},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A Kakao-style travel chat while Minseo transfers to Seoul Station and books a KTX ticket.",lines:[{speaker:"민서",ko:"지금 홍대입구역인데 서울역 가려면 어디서 환승해?",en:"I am at Hongik University Station now. Where do I transfer to get to Seoul Station?",romanization:"jigeum hongdaeipguyeoginde seouryeok garyeomyeon eodiseo hwanseunghae?"},{speaker:"지훈",ko:"2호선 타고 시청역에서 1호선으로 갈아타. 승강장은 오른쪽이야.",en:"Take Line 2 and transfer to Line 1 at City Hall. The platform is on the right.",romanization:"i hoseon tago sicheongyeogeseo il hoseoneuro garata. seunggangjangeun oreunjjogiya."},{speaker:"민서",ko:"고마워. 부산 가는 KTX 표를 예매하려고 하는데 편도면 돼?",en:"Thanks. I am trying to book a KTX ticket to Busan. Is one-way okay?",romanization:"gomawo. busan ganeun KTX pyoreul yemaeharyeogo haneunde pyeondomyeon dwae?"},{speaker:"지훈",ko:"응, 돌아오는 시간 안 정했으면 편도로 해. 매진이면 다음 기차 확인하고.",en:"Yes, if you have not set the return time, book it one-way. If it is sold out, check the next train.",romanization:"eung, doraoneun sigan an jeonghaesseumyeon pyeondoro hae. maejinimyeon daeum gicha hwaginhago."},{speaker:"민서",ko:"버스 지연 때문에 조금 늦으면 택시로 갈게.",en:"If I am a little late because of the bus delay, I will go by taxi.",romanization:"beoseu jiyeon ttaemune jogeum neujeumyeon taeksiro galge."},{speaker:"지훈",ko:"괜찮아. 환승할 때 출구 번호도 같이 확인해.",en:"No problem. When you transfer, check the exit number too.",romanization:"gwaenchana. hwanseunghal ttae chulgu beonhodo gachi hwaginhae."}]},{kind:"order",prompt:"Build: 'Transfer to Line 2 at Seoul Station.'",tokens:["서울역에서","2호선으로","갈아타세요"],correct:"서울역에서 2호선으로 갈아타세요",explanation:"에서 marks the transfer location, and (으)로 marks the line you transfer to. 갈아타세요 is the transit instruction."}],canDo:"Say what I travel by or which way I go (버스로, 2호선으로)",id:"chapter-55-b10",chapterId:"chapter-55",index:9},{kind:"reading",title:"읽기 Reading · 서울역에서 부산까지 가는 길",cards:[{kind:"read",title:"서울역에서 부산까지 가는 길",chunks:["민서는 홍대입구역에서 서울역으로 가려고 해요. 먼저 2호선을 타고 시청역에서 1호선으로 갈아타야 해요. 환승할 때는 승강장 방향과 출구 번호를 같이 확인하면 헷갈리지 않아요. 서울역에 도착하면 부산 가는 KTX 표를 예매할 거예요.","돌아오는 시간이 아직 정해지지 않아서 편도로 예매하려고 해요. 만약 표가 매진이면 다음 기차를 확인하면 돼요. 친구에게는 버스 지연 때문에 늦으면 택시로 가겠다고 메시지를 보냈어요."],translation:"Minseo is planning to go from Hongik University Station to Seoul Station. First, Minseo takes Line 2 and transfers to Line 1 at City Hall Station. When transferring, checking both the platform direction and exit number helps avoid confusion. After arriving at Seoul Station, Minseo will book a KTX ticket to Busan. Since the return time is not set yet, Minseo plans to book one-way. If the tickets are sold out, Minseo can check the next train. Minseo also messaged a friend that if they are late because of a bus delay, they will go by taxi.",qas:[{q:"민서는 어디에서 1호선으로 갈아타야 해요?",a:"시청역에서 갈아타야 해요."},{q:"돌아오는 시간이 정해지지 않았으면 어떤 표로 예매해요?",a:"편도로 예매해요."},{q:"버스 지연 때문에 늦으면 무엇으로 가겠다고 했어요?",a:"택시로 가겠다고 했어요."}]}],canDo:"Give the purpose of a trip (표를 사러 가요)",id:"chapter-55-b11",chapterId:"chapter-55",index:10},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence gives a natural subway transfer instruction?",sentence:null,options:[{text:"시청역에서 1호선으로 갈아타세요.",ok:!0},{text:"시청역에게 1호선을 갈아타세요.",ok:!1},{text:"시청역을 1호선에 갈아타세요.",ok:!1}],explanation:"Use 에서 for the transfer station and 으로 for the line you change to."},{kind:"drill",prompt:"Which word is natural when KTX tickets are sold out?",sentence:null,options:[{text:"매진",ok:!0},{text:"품절",ok:!1},{text:"고장",ok:!1}],explanation:"매진 is for tickets and seats; 품절 is usually for store products."},{kind:"drill",prompt:"Which sentence explains a delay cause correctly?",sentence:null,options:[{text:"버스 지연 때문에 늦었어요.",ok:!0},{text:"버스 지연이 때문에 늦었어요.",ok:!1},{text:"버스 지연을 때문에 늦었어요.",ok:!1}],explanation:"Put the noun cause directly before 때문에 with no extra particle."},{kind:"drill",prompt:"KTX 표___ 예매했어요. (I booked a KTX ticket.)",sentence:null,options:[{text:"를",ok:!0},{text:"가",ok:!1},{text:"에",ok:!1}],explanation:"예매하다 takes the ticket as an object, so 표를 fits. 가 would make the ticket the subject."},{kind:"order",prompt:"Build: 'Transfer to Line 2 at Seoul Station.'",tokens:["서울역에서","2호선으로","갈아타세요"],correct:"서울역에서 2호선으로 갈아타세요",explanation:"에서 marks the transfer location, and (으)로 marks the line you transfer to. 갈아타세요 is the transit instruction."},{kind:"drill",prompt:"Which sentence says you will go by taxi?",sentence:null,options:[{text:"택시로 갈게요.",ok:!0},{text:"택시에 갈게요.",ok:!1},{text:"택시를 갈게요.",ok:!1}],explanation:"Transport method takes (으)로. 택시에 would mean to a taxi, which is not the intended meaning."}],canDo:"State a travel intention (예매하려고 해요)",id:"chapter-55-b12",chapterId:"chapter-55",index:11}]},{id:"chapter-56",number:56,title:"V/A-잖아요 · V/A-거든요",goal:"Choose and explain housewarming gifts with 집들이, 선물, 휴지, and 세제.",biteCount:12,bites:[{kind:"words",title:"단어 Words 1 · 집들이~",cards:[{kind:"guess",word:{ko:"집들이",romanization:"jipdeuri",en:"housewarming party",pos:"noun",nuance:"집들이 is a pure native-Korean word (no hanja): 집 'house' + 들이 (from 들이다, 'to bring/take in'), so it literally evokes 'bringing people into the house' — the housewarming party thrown after an 이사 (移徙, moving). Don't confuse the event with the move itself: you do 이사 first (the act of relocating), THEN 집들이 (the celebration). Also distinguish it from 집들이 선물 vs a generic 선물 — the classic gifts are pointed: 휴지 (toilet paper), because it 'unrolls smoothly' (everything in the new home going smoothly), and 세제 (laundry detergent), whose bubbles symbolize prosperity 'bubbling up.' These are warm, traditional choices, not cheap ones — an English speaker may misread practical household items as an awkward gift. It's a relaxed gathering where the host usually cooks or orders in for friends."},sentence:{ko:"주말에 회사 선배 집들이에 가요.",en:"I am going to a senior coworker's housewarming this weekend."},target:"집들이",options:["housewarming party","gift","toilet paper / tissue"],note:"Linked to dictionary card word-ext-1109."},{kind:"guess",word:{ko:"선물",romanization:"seonmul",en:"gift",pos:"noun",nuance:"선물 can be the thing given, received, bought, or prepared. In this chapter, focus on the particle around the person and the particle attached to 선물 itself."},sentence:{ko:"집들이 선물로 세제를 가져가도 괜찮아요.",en:"It is okay to bring detergent as a housewarming gift."},target:"선물",options:["gift","housewarming party","toilet paper / tissue"],note:"Linked to dictionary card word-ext-ch42-seonmul."},{kind:"guess",word:{ko:"휴지",romanization:"hyuji",en:"toilet paper / tissue",pos:"noun",nuance:"휴지 is the hanja word 休紙 — literally '休 rest/discard + 紙 paper,' i.e. 'paper to be used up and tossed' — and in real life it covers BOTH rolled toilet paper and the flat table tissue you wipe your mouth with; context tells you which. The contrast to learn is 휴지 vs 티슈 vs 화장지: 티슈 is the soft pop-up/pocket pack you carry, 화장지 is the more formal/printed label for toilet roll, and 휴지 is the broad everyday word. Note 휴지통 ('휴지 + bin') means the wastebasket, so don't picture only paper. The pitfall is the particle and the verb: you wipe WITH it, so 휴지로 닦다 (means 로, vowel-final), never 휴지를 닦다 (which would mean wiping the paper itself). Also 휴지 is uncountable-feeling but a torn square is 한 칸 and a roll is 한 통/한 롤."},sentence:{ko:"휴지는 집들이 선물로 많이 가져가잖아요.",en:"People often bring toilet paper as a housewarming gift, you know."},target:"휴지",options:["housewarming party","gift","toilet paper / tissue"],note:"Linked to dictionary card word-ext-378."},{kind:"guess",word:{ko:"세제",romanization:"seje",en:"detergent",pos:"noun",nuance:"세제 is practical rather than fancy. In 집들이 culture, practical household gifts can feel considerate because they help the new home run smoothly."},sentence:{ko:"집들이 선물로 세제를 샀거든요.",en:"I bought detergent as the housewarming gift, you see."},target:"세제",options:["housewarming party","gift","detergent"],note:"Chapter card word-ext-ch56-seje."},{kind:"guess",word:{ko:"나이",romanization:"nai",en:"age",pos:"noun",nuance:"나이 is the native Korean word for a person's age, and it sits at the center of Korean social life because age sets who speaks formally to whom. Register is everything: to an adult, an elder, or a stranger you ask 나이가 어떻게 되세요? (or even more deferential 연세가 어떻게 되세요?, using the honorific 연세 for grandparents), while the blunt 몇 살이에요? is reserved for children or close friends — asking your boss 몇 살이에요? sounds rude. The near-synonym pair is 나이 vs 연세: same meaning, but 연세 (年歲, Sino-Korean) is the respectful 'years' you grant to someone older, so you raise the register by swapping the word, not by adding an ending. Crucially, age is measured with 많다/적다, not size words: 나이가 많아요 = 'is old', 나이가 적어요 = 'is young' — never 나이가 커요, a direct-translation trap from English 'big'. When you state an actual number, age takes NATIVE numbers + the counter 살: 스무 살 (20), 서른 살 (30) — saying 이십 살 with Sino-Korean numbers is a classic beginner error. One more pitfall: the verb is 되세요 (from 되다, 'to become/amount to'), so 어떻게 되세요? literally asks 'how does it come to be?' — treat the whole phrase as a fixed polite formula rather than translating it word by word."},sentence:{ko:"나이가 비슷하면 동갑일 수도 있어요.",en:"If your ages are similar, you might be the same age."},target:"나이",options:["housewarming party","gift","age"],note:"Linked to dictionary card word-ext-1329."},{kind:"guess",word:{ko:"동갑",romanization:"donggap",en:"same age",pos:"noun",nuance:"동갑 is useful because Korean relationships often adjust around age. Still, being 동갑 does not mean you immediately use 반말; closeness and setting matter too."},sentence:{ko:"동갑이지만 처음엔 존댓말을 써요.",en:"We are the same age, but at first I use polite speech."},target:"동갑",options:["housewarming party","same age","gift"],note:"Chapter card word-ext-ch56-donggap."},{kind:"payoff",line:{speaker:"민서",ko:"집들이에 갈 때 휴지랑 세제 중에 뭐가 나아요?",en:"When going to a housewarming, which is better, toilet paper or detergent?"},hl:"집들이"}],canDo:"Remind someone of shared knowledge (선물하잖아요)",id:"chapter-56-b1",chapterId:"chapter-56",index:0},{kind:"pattern",title:"문법 Grammar · V/A-잖아요",cards:[{kind:"hunt",name:"V/A-잖아요",sub:'"you know (we both know this)"',lines:[{tokens:[{pre:"윗사람한테는",mid:"",post:"",hit:!1},{pre:"두",mid:"",post:"",hit:!1},{pre:"손으로",mid:"",post:"",hit:!1},{pre:"드리",mid:"잖아요",post:".",hit:!0}],ko:"윗사람한테는 두 손으로 드리잖아요.",en:"You hand things to elders with both hands, you know.",romanization:"witsaram-hante-neun du soneuro deurijanhayo."},{tokens:[{pre:"집들이에는",mid:"",post:"",hit:!1},{pre:"보통",mid:"",post:"",hit:!1},{pre:"휴지나",mid:"",post:"",hit:!1},{pre:"세제를",mid:"",post:"",hit:!1},{pre:"사",mid:"",post:"",hit:!1},{pre:"가",mid:"잖아요",post:".",hit:!0}],ko:"집들이에는 보통 휴지나 세제를 사 가잖아요.",en:"You usually bring toilet paper or detergent to a housewarming, you know.",romanization:"jipdeurie-neun botong hyujina sejereul sa gajanhayo."}],rule:{name:"V/A-잖아요",rows:[{when:"Verb or Adjective stem (present)",add:"-잖아요",ex:"한국에서는 신발을 벗잖아요 (You take your shoes off in Korea, you know)"},{when:"Past tense (V & A)",add:"-았/었잖아요",ex:"지난번에 제가 말했잖아요 (I told you last time, remember)"},{when:"Noun + 이다",add:"(이)잖아요",ex:"오늘 어버이날이잖아요 (It's Parents' Day today, you know)"}]},more:{func:"Reminds the listener of something you assume you both already know, or gently corrects them with a fact they should remember. It softens a reminder by framing it as shared knowledge rather than news — very common when explaining everyday manners and customs.",keyPoint:{label:"-잖아요 vs. -거든요",body:"Use -잖아요 when you think the listener ALREADY knows it ('as you know'). Use -거든요 when it's NEW background the listener does not know yet ('the thing is…'). Same slot, opposite assumption about the listener."},pronunciation:"-잖아요 is carefully [자나요]; the ㅎ-like sound is very light, and in fast speech it can flatten to [자아요]. Stick with [자나요]."}}],canDo:"Remind someone of shared knowledge (선물하잖아요)",id:"chapter-56-b2",chapterId:"chapter-56",index:1},{kind:"words",title:"단어 Words 2 · 선배~",cards:[{kind:"guess",word:{ko:"선배",romanization:"seonbae",en:"senior colleague or schoolmate",pos:"noun",nuance:"선배 (先輩, 'earlier-generation/fellow') means someone senior to you who entered the same school, university, company, or field BEFORE you — a relationship that structures enormous amounts of Korean social life. The sharp contrast: a 선배 is defined by entering EARLIER, while a 상사 is defined by RANK — your 선배 may or may not be your boss, and your boss may not be your 선배 if they transferred in. Also distinguish 선배 from 어른 (an elder/adult by age generally). Unlike 상사, you CAN and do address a 선배 directly, adding 님 for politeness: 선배님. A 선배 traditionally looks after their 후배 (junior), often picking up the meal tab. Register: warm but respectful, deeply tied to hierarchy. The English-speaker pitfall: English has no real equivalent and learners default to 'senior' = 'boss' — but 선배 is about timing, not authority; treating every 선배 as a 상사 (or vice versa) misreads the relationship. Mark whom you learn from with 한테/에게."},sentence:{ko:"처음엔 선배님이라고 부르는 편이에요.",en:"At first, I tend to call them seonbaenim."},target:"선배",options:["housewarming party","gift","senior colleague or schoolmate"],note:"Linked to dictionary card word-ext-1624."},{kind:"guess",word:{ko:"후배",romanization:"hubae",en:"junior colleague or schoolmate",pos:"noun",nuance:"후배 means someone who entered the same school, company, or field later than you. 후배님 is possible as a respectful address in some workplaces or unfamiliar relationships; names, roles, and local workplace custom also affect the best form of address."},sentence:{ko:"후배라도 처음엔 존댓말을 쓰면 좋아요.",en:"Even with a junior, it is good to use polite speech at first."},target:"후배",options:["housewarming party","gift","junior colleague or schoolmate"],note:"Linked to dictionary card word-ext-1625."},{kind:"guess",word:{ko:"호칭",romanization:"hoching",en:"form of address / title",pos:"noun",nuance:"호칭 is not just a word choice; it signals age, role, closeness, and respect. When unsure, asking 어떤 호칭을 쓰면 될까요? is safer than guessing too casually."},sentence:{ko:"어떤 호칭을 쓰면 될까요?",en:"What title should I use?"},target:"호칭",options:["housewarming party","form of address / title","gift"],note:"Chapter card word-ext-ch56-hoching."},{kind:"guess",word:{ko:"어르신",romanization:"eoreusin",en:"elder; older person respectfully",pos:"noun",nuance:"어르신 is respectful and warm. 어른 simply means adult or grown-up; 어르신 adds social respect for age."},sentence:{ko:"어르신도 계시면 말투를 조심하세요.",en:"If elders are there too, be careful with your tone."},target:"어르신",options:["housewarming party","gift","elder; older person respectfully"],note:"Chapter card word-ext-ch56-eoreusin."},{kind:"guess",word:{ko:"눈치",romanization:"nunchi",en:"social awareness / reading the room",pos:"noun",nuance:"눈치 is a native-Korean word (눈 'eye' + 치) and one of the most essential Korean social concepts: the radar for sensing what others feel and what's appropriate without being told. The distinctions learners trip on are between its set phrases: 눈치가 빠르다 ('quick eye') is high praise, 눈치가 없다 is a real social criticism, 눈치를 보다 means cautiously reading someone's mood (often a boss's, with a slightly self-conscious feel), and 눈치(를) 채다 means to catch on / notice something. So 보다 and 채다 are not interchangeable — one is ongoing wariness, the other is a moment of realization. The English-speaker pitfall is mapping 눈치 to 'eyes' or vision because of 눈; it has nothing to do with eyesight and everything to do with social perceptiveness. Living in Korea you'll use and need this word daily."},sentence:{ko:"눈치 있게 챙기면 분위기가 덜 어색해요.",en:"If you take care of things tactfully, the mood is less awkward."},target:"눈치",options:["housewarming party","social awareness / reading the room","gift"],note:"Linked to dictionary card word-ext-797."},{kind:"guess",word:{ko:"분위기",romanization:"bunwigi",en:"atmosphere; mood",pos:"noun",nuance:"분위기 (雰圍氣, 雰 'mist/vapor' + 圍 'surround' + 氣 'air/energy') is literally 'the air that surrounds you' — the collective mood of a place, gathering, or moment. The sharp contrast is 분위기 vs 기분: 분위기 is the SHARED vibe in the room (회식 분위기가 좋다), while 기분 is one person's INNER feeling (제 기분이 좋다 'I'm in a good mood'). Mixing them is the classic error: 'I'm in a good mood' is 기분이 좋아요, not 분위기가 좋아요 (which describes the room, not you). Habitual partners: 분위기가 좋다/편안하다/어색하다, 분위기를 띄우다/바꾸다, 분위기가 가라앉다, 분위기를 깨다 ('kill the mood'). 분위기 있다 colloquially means 'has a classy/romantic ambiance.' The English-speaker pitfall, beyond 기분 confusion, is the particle: 분위기를 좋다 ✗ → 분위기가 좋다 ✓."},sentence:{ko:"분위기가 어색하면 먼저 물어보세요.",en:"If the atmosphere is awkward, ask first."},target:"분위기",options:["housewarming party","atmosphere; mood","gift"],note:"Linked to dictionary card word-ext-1692."},{kind:"payoff",line:{speaker:"지훈",ko:"그래도 처음엔 선배님 같은 호칭을 쓰는 편이에요.",en:"Even so, at first people tend to use a title like seonbaenim."},hl:"선배"}],canDo:"Explain background or a reason (좋은 뜻이 있거든요)",id:"chapter-56-b3",chapterId:"chapter-56",index:2},{kind:"pattern",title:"문법 Grammar · V/A-거든요",cards:[{kind:"hunt",name:"V/A-거든요",sub:`"the thing is… (here's the background)"`,lines:[{tokens:[{pre:"오늘은",mid:"",post:"",hit:!1},{pre:"일찍",mid:"",post:"",hit:!1},{pre:"가",mid:"",post:"",hit:!1},{pre:"볼게요.",mid:"",post:"",hit:!1},{pre:"시댁에",mid:"",post:"",hit:!1},{pre:"가야",mid:"",post:"",hit:!1},{pre:"하",mid:"거든요",post:".",hit:!0}],ko:"오늘은 일찍 가 볼게요. 시댁에 가야 하거든요.",en:"I'll head off early today. The thing is, I have to visit my in-laws.",romanization:"oneureun iljjik ga bolgeyo. sidaege gaya hageodeunyo."},{tokens:[{pre:"꽃을",mid:"",post:"",hit:!1},{pre:"사",mid:"",post:"",hit:!1},{pre:"왔어요.",mid:"",post:"",hit:!1},{pre:"오늘",mid:"",post:"",hit:!1},{pre:"처음",mid:"",post:"",hit:!1},{pre:"인사",mid:"",post:"",hit:!1},{pre:"드리는",mid:"",post:"",hit:!1},{pre:"거",mid:"거든요",post:".",hit:!0}],ko:"꽃을 사 왔어요. 오늘 처음 인사 드리는 거거든요.",en:"I brought flowers. It's the first time I'm greeting you properly, you see.",romanization:"kkocheul sa wasseoyo. oneul cheoeum insa deurineun geogeodeunyo."}],rule:{name:"V/A-거든요",rows:[{when:"Verb or Adjective stem (present)",add:"-거든요",ex:"제가 매운 걸 못 먹거든요 (The thing is, I can't eat spicy food)"},{when:"Past tense (V & A)",add:"-았/었거든요",ex:"어제 늦게 잤거든요 (I went to bed late yesterday, you see)"},{when:"Noun + 이다",add:"(이)거든요",ex:"오늘이 제 생일이거든요 (Today's my birthday, you see)"}]},more:{func:"Gives a reason or piece of background the listener does not yet know, often answering a real or expected 'why?'. It signals 'the thing is…' and is a soft, polite way to explain yourself in conversation.",keyPoint:{label:"-거든요 vs. -아서/어서",body:"Both give reasons. -아서/어서 joins the reason to a clause in the SAME sentence ('Because A, B'). -거든요 ends its own sentence and offers the reason as new information the listener didn't have, so it usually stands alone as a reply."},pronunciation:"-거든요 is [거드뇨] in quick speech, but the careful form is [거든뇨]→[거든요]. Keep the 든 clear."}}],canDo:"Explain background or a reason (좋은 뜻이 있거든요)",id:"chapter-56-b4",chapterId:"chapter-56",index:3},{kind:"words",title:"단어 Words 3 · 어색하다~",cards:[{kind:"guess",word:{ko:"어색하다",romanization:"eosaekada",en:"to be awkward",pos:"adjective",nuance:"어색하다 traces to the Sino-Korean 語塞 (어 語 'speech' + 색 塞 'blocked/stuck') — the picture of words getting jammed — and names two feelings: the stiff, uneasy awkwardness between people who aren't yet close, and the sense that something looks or feels unnatural or out of place (a forced smile, a new haircut, an odd-sounding sentence). It is the antonym of 자연스럽다 (natural). Draw the line from 부끄럽다 and 창피하다: those are shyness/embarrassment about YOURSELF (blushing, shame), whereas 어색하다 is the awkwardness of an unfamiliar situation or relationship — no shame, just lack of ease; and 불편하다 is broader discomfort, while 어색하다 specifically flags social unfamiliarity. As a 하다 adjective it conjugates to 어색해요. English-speaker pitfall: don't use 어색하다 for personal embarrassment ('I was so embarrassed' is 창피했어요); reserve 어색하다 for that not-yet-comfortable-together or 'this looks unnatural' feeling."},sentence:{ko:"처음 만난 자리라서 조금 어색해요.",en:"It is a little awkward because it is the first meeting."},target:"어색해",options:["housewarming party","gift","to be awkward"],note:"Linked to dictionary card word-ext-1265."},{kind:"guess",word:{ko:"도와드리다",romanization:"dowadeurida",en:"to help politely",pos:"verb",nuance:"도와드리다 is the humble form of 도와주다 ('help (as a favour)'), where 돕다 (to help) becomes 도와- by the ㅂ-irregular (돕 + 아 → 도와), and the helper-benefit 주다 is upgraded to its humble twin 드리다. So it literally means 'humbly do the favour of helping' — you lower yourself to help someone above you: a customer, elder, or guest. Contrast the three levels you must keep straight: 돕다 (bare dictionary 'help'), 도와주다 (help someone, neutral/friendly), 도와드리다 (help a superior, humble). English flattens all of these to 'help', so the pitfall is using 도와주다 with a customer (too casual for service) or, conversely, 도와드리다 with a buddy (oddly stiff). The phrase 무엇을 도와드릴까요? is the fixed, must-know service line. Conjugation follows 드리다: 도와드려요, 도와드렸어요."},sentence:{ko:"도와드릴까요? 하고 먼저 물어보세요.",en:"Ask first, 'May I help?'"},target:"도와드릴",options:["to help politely","to prepare / take care of","housewarming party"],note:"Linked to verb card word-verb-265."},{kind:"guess",word:{ko:"챙기다",romanization:"chaenggida",en:"to prepare / take care of",pos:"verb",nuance:"챙기다 is one of the most useful 'caring' verbs in daily Korean, with a cluster of related senses: (1) gather/pack the things you need (짐을 챙기다), (2) make sure not to skip something, especially food (밥 챙겨 먹어 'make sure you eat'), and (3) look after a person attentively (동생 좀 챙겨 'keep an eye on your sibling'). Set it against 돌보다 (care for over time, like nursing a child or the sick): 챙기다 is quicker, more about 'making sure / not letting slip', while 돌보다 is sustained nurturing. It also contrasts with 챙겨 주다, where adding 주다 makes the care explicitly a favour for someone. The English trap is reaching for 들다 'lift' or 가지다 'have' when you mean 'grab/remember to bring' — that everyday act is 챙기다. Native warmth: 잘 챙겨 먹어요 is a standard way to say 'take care of yourself'."},sentence:{ko:"집들이 선물을 챙겼어요.",en:"I prepared a housewarming gift."},target:"챙겼",options:["to help politely","to prepare / take care of","housewarming party"],note:"Linked to verb card word-verb-262."},{kind:"guess",word:{ko:"수고하셨습니다",romanization:"sugohasyeotseumnida",en:"thank you for your hard work",pos:"expression",nuance:"수고하셨습니다 acknowledges finished effort. 수고(受苦 / loosely) means 'trouble, effort, hard work'; 하시— is the honorific stem of 하다 'to do'; and the past -셨- marks completion, so the phrase means '(you) have done hard work'. The make-or-break contrast is TENSE and DIRECTION. Tense: 수고하셨습니다 (past, work is finished) vs 수고하세요 (present, person is still at it — used as you leave). Mix these and you are either congratulating someone mid-task or urging a finished person to keep going. Direction: 수고하셨습니다 flows naturally downward (superior to junior) or sideways (peers), but upward to a clearly senior boss it can sound presumptuous, as if you are evaluating their effort from a position of authority you don't have — to a superior, 감사합니다 or 고생 많으셨습니다 is safer. The near-synonym 고생하셨습니다 (고생 'hardship/toil') feels warmer and more empathetic about the difficulty of the work, not just the fact of effort. Casual register: 수고했어 (반말, to a junior or close peer). The English-speaker pitfall is conflating it with a casual 'thanks' and dropping it on anyone regardless of rank or whether the work is done."},sentence:{ko:"오늘 초대해 주셔서 감사합니다. 수고하셨습니다.",en:"Thank you for inviting me today. Thank you for your hard work."},target:"수고하셨습니다",options:["thanks to","housewarming party","thank you for your hard work"],note:"Linked to expression card expr-125."},{kind:"guess",word:{ko:"덕분에",romanization:"deokbune",en:"thanks to",pos:"expression",nuance:"덕분에 is for welcome causes. 때문에 often sounds neutral or negative, so 선배님 때문에 잘 됐어요 can sound like blame even with a good result."},sentence:{ko:"선배님 덕분에 분위기가 편해졌어요.",en:"Thanks to you, the atmosphere became comfortable."},target:"덕분에",options:["thanks to","thank you for your hard work","housewarming party"],note:"Chapter card word-ext-ch56-deokbune."},{kind:"payoff",line:{speaker:"지훈",ko:"좋아요. 눈치 있게 챙기면 분위기가 덜 어색해요.",en:"Good. If you take care of things tactfully, the mood is less awkward."},hl:"챙기"}],canDo:"Soften a statement or careful question (조심하는 게 좋은데요)",id:"chapter-56-b5",chapterId:"chapter-56",index:4},{kind:"pattern",title:"문법 Grammar · V/A-는데요",cards:[{kind:"hunt",name:"V/A-는데요",sub:'"soften a careful statement or question"',lines:[{tokens:[{pre:"이거",mid:"",post:"",hit:!1},{pre:"집들이",mid:"",post:"",hit:!1},{pre:"선물로",mid:"",post:"",hit:!1},{pre:"드리려고",mid:"",post:"",hit:!1},{pre:"하",mid:"는데요",post:",",hit:!0},{pre:"괜찮을까요?",mid:"",post:"",hit:!1}],ko:"이거 집들이 선물로 드리려고 하는데요, 괜찮을까요?",en:"I was thinking of giving this as a housewarming gift… would that be okay?",romanization:"igeo jipdeuri seonmullo deuriryeogo haneundeyo, gwaenchaneulkkayo?"},{tokens:[{pre:"호칭을",mid:"",post:"",hit:!1},{pre:"잘",mid:"",post:"",hit:!1},{pre:"모르",mid:"는데요",post:",",hit:!0},{pre:"뭐라고",mid:"",post:"",hit:!1},{pre:"부르면",mid:"",post:"",hit:!1},{pre:"될까요?",mid:"",post:"",hit:!1}],ko:"호칭을 잘 모르는데요, 뭐라고 부르면 될까요?",en:"I'm not really sure what to call you… what should I say?",romanization:"hochingeul jal moreuneundeyo, mworago bureumyeon doelkkayo?"}],rule:{name:"V/A-는데요",rows:[{when:"Verb stem (present)",add:"-는데요",ex:"지금 가는데요 (Well, I'm going now…)"},{when:"Adjective stem (present)",add:"-(으)ㄴ데요",ex:"좀 비싼데요 (It's a bit pricey, though…)"},{when:"Past tense (V & A)",add:"-았/었는데요",ex:"벌써 끝났는데요 (It's already finished, though…)"},{when:"Noun + 이다",add:"인데요",ex:"저는 처음인데요 (It's my first time, you see…)"}]},more:{func:"Ends a turn on an open, non-final note that leaves room for the listener to react. It softens statements, eases into careful questions, and sets up background before a request — essential for polite, indirect social talk.",keyPoint:{label:"Adjective -(으)ㄴ데요 vs. Verb -는데요",body:"Verbs always take -는데요 (가는데요, 먹는데요). Adjectives take -(으)ㄴ데요 (비싼데요, 좋은데요). 있다/없다 act like verbs: 있는데요, 없는데요. Sorting verb from adjective is the part learners trip on most."},pronunciation:"-는데요 is [는데요]. After ㄹ-final verb stems the ㄹ drops: 살다 → 사는데요 (not 살는데요)."}}],canDo:"Soften a statement or careful question (조심하는 게 좋은데요)",id:"chapter-56-b6",chapterId:"chapter-56",index:5},{kind:"pattern",title:"문법 Grammar · V/A-(으)ㄴ/는 편이다",cards:[{kind:"teach",name:"V/A-(으)ㄴ/는 편이다",sub:`"I tend to / I'm rather …"`,rows:[{when:"Verb stem (present habit)",add:"-는 편이다",ex:"저는 일찍 가는 편이에요 (I tend to arrive early)"},{when:"Adjective stem (present)",add:"-(으)ㄴ 편이다",ex:"한국 사람들은 정이 많은 편이에요 (Koreans tend to be warm-hearted)"},{when:"Past verb (one-time result)",add:"-(으)ㄴ 편이다",ex:"선물을 많이 받은 편이에요 (I got rather a lot of gifts)"},{when:"Negative (verb)",add:"안/잘 안 …-는 편이다",ex:"술을 잘 안 마시는 편이에요 (I tend not to drink much)"}],examples:[{ko:"저는 처음엔 호칭을 조심하는 편이에요.",en:"At first I tend to be careful with how I address people.",romanization:"jeoneun cheoeumen hochingeul josimhaneun pyeonieyo.",note:"Hedges a self-description so it sounds modest, not absolute."},{ko:"요즘 젊은 사람들은 명절에 한복을 잘 안 입는 편이에요.",en:"These days young people tend not to wear hanbok on the holidays.",romanization:"yojeum jeolmeun saramdeureun myeongjeore hanbogeul jal an imneun pyeonieyo.",note:"A soft generalization about a changing custom, leaving room for exceptions."}],more:{func:"Describes a general tendency rather than a hard fact — 'on the … side', 'tends to be …'. It hedges a judgment, which sounds modest and natural when you comment on people, habits, or customs without being too absolute.",keyPoint:{label:"Verb 는 편 vs. Adjective (으)ㄴ 편",body:"With a verb, use -는 편이다 for a habit (가는 편, 챙기는 편). With an adjective, use -(으)ㄴ 편이다 for a quality (많은 편, 비싼 편). 편이다 means 'leans that way', so never use it for a one-time event like '오늘 갔어요'."},pronunciation:"편이에요 is [펴니에요]; the ㄴ links into the next syllable. Keep 편 short, not 'pyeon-i'."}}],canDo:"Describe a tendency modestly (나이가 많은 편이에요)",id:"chapter-56-b7",chapterId:"chapter-56",index:6},{kind:"pattern",title:"문법 Grammar · V/A-(으)니까",cards:[{kind:"hunt",name:"V/A-(으)니까",sub:`"since (so here's what to do)"`,lines:[{tokens:[{pre:"집들이",mid:"니까",post:"",hit:!0},{pre:"작은",mid:"",post:"",hit:!1},{pre:"선물이라도",mid:"",post:"",hit:!1},{pre:"챙겨",mid:"",post:"",hit:!1},{pre:"가세요.",mid:"",post:"",hit:!1}],ko:"집들이니까 작은 선물이라도 챙겨 가세요.",en:"Since it's a housewarming, take at least a small gift.",romanization:"jipdeurinikka jageun seonmurirado chaenggyeo gaseyo."},{tokens:[{pre:"어르신도",mid:"",post:"",hit:!1},{pre:"계시",mid:"니까",post:"",hit:!0},{pre:"말투를",mid:"",post:"",hit:!1},{pre:"조심해요.",mid:"",post:"",hit:!1}],ko:"어르신도 계시니까 말투를 조심해요.",en:"Since there are elders there too, be careful with your tone.",romanization:"eoreusindo gyesinikka maltureul josimhaeyo."}],rule:{name:"V/A-(으)니까",rows:[{when:"Verb/Adjective stem ending in a vowel",add:"-니까",ex:"바쁘다 → 바쁘니까 미리 챙기세요 (Since you're busy, prepare it in advance)"},{when:"Verb/Adjective stem ending in a consonant",add:"-으니까",ex:"많다 → 사람이 많으니까 조심하세요 (Since there are many people, be careful)"},{when:"Past tense (V & A)",add:"-았/었으니까",ex:"덕분에 잘 됐으니까 감사 인사를 하세요 (Since it went well thanks to them, say thank you)"},{when:"Noun + 이다",add:"(이)니까",ex:"오늘이 첫날이니까 일찍 가요 (Since today's the first day, let's go early)"}]},more:{func:"Gives a reason that leads into advice, a request, or a decision: 'since X, (let's / please / I'll) …'. Unlike -아서/어서, it's the natural choice when the second clause is a suggestion or command — very common when explaining the reason behind a social custom.",keyPoint:{label:"-(으)니까 vs. -아서/어서",body:"Both mean 'because', but only -(으)니까 can lead into a command or suggestion: 늦었으니까 빨리 가세요 (O), 늦어서 빨리 가세요 (X). Use -아서/어서 for plain cause-and-result, -(으)니까 when you're telling someone what to do because of the reason."},pronunciation:"-(으)니까 is [(으)니까] with a tense 까. Don't soften it to '니가'; the double ㄲ stays strong."}}],canDo:"Give a reason that leads into advice (선배니까 호칭을 조심하세요)",id:"chapter-56-b8",chapterId:"chapter-56",index:7},{kind:"pattern",title:"문법 Grammar · A/V-지만",cards:[{kind:"hunt",name:"A/V-지만",sub:`"… but (I'll still do the polite thing)"`,lines:[{tokens:[{pre:"동갑이",mid:"지만",post:"",hit:!0},{pre:"처음엔",mid:"",post:"",hit:!1},{pre:"존댓말을",mid:"",post:"",hit:!1},{pre:"써요.",mid:"",post:"",hit:!1}],ko:"동갑이지만 처음엔 존댓말을 써요.",en:"We're the same age, but at first I use polite speech.",romanization:"donggabijiman cheoeumen jondaenmareul sseoyo."},{tokens:[{pre:"조금",mid:"",post:"",hit:!1},{pre:"어색하",mid:"지만",post:"",hit:!0},{pre:"제가",mid:"",post:"",hit:!1},{pre:"먼저",mid:"",post:"",hit:!1},{pre:"인사할게요.",mid:"",post:"",hit:!1}],ko:"조금 어색하지만 제가 먼저 인사할게요.",en:"It's a little awkward, but I'll greet them first.",romanization:"jogeum eosaekajiman jega meonjeo insahalgeyo."}],rule:{name:"A/V-지만",rows:[{when:"Verb or Adjective stem",add:"-지만",ex:"바쁘지만 갈게요 (I'm busy, but I'll go)"},{when:"Past tense (V & A)",add:"-았/었지만",ex:"늦었지만 인사는 드렸어요 (I was late, but I did greet them)"},{when:"Noun + 이다",add:"(이)지만",ex:"동갑이지만 존댓말을 써요 (We're the same age, but I use polite speech)"}]},more:{func:"Admits one fact, then turns to a contrasting choice: 'A, but B'. In social situations the second clause usually shows the careful or considerate option, so it's handy for explaining why you act politely even when you don't strictly have to.",keyPoint:{label:"-지만 vs. 그렇지만 / 그런데",body:"-지만 joins the two clauses inside one sentence (바쁘지만 갈게요). 그렇지만 / 그런데 do the same job but start a new sentence: 바빠요. 그렇지만 갈게요. Use -지만 to keep it as one smooth sentence."},pronunciation:"-지만 itself is [지만], but a preceding final obstruent can tense its ㅈ: 봤지만 is pronounced [봗찌만]. With 어렵지만, the ㅂ stays because -지만 begins with a consonant."}}],canDo:"Remind someone of shared knowledge (선물하잖아요)",id:"chapter-56-b9",chapterId:"chapter-56",index:8},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Minseo asks how to behave at a coworker's housewarming.",lines:[{speaker:"민서",ko:"집들이에 갈 때 휴지랑 세제 중에 뭐가 나아요?",en:"When going to a housewarming, which is better, toilet paper or detergent?",romanization:"jipdeurie gal ttae hyujirang seje junge mwoga naayo?"},{speaker:"지훈",ko:"둘 다 괜찮아요. 집들이 선물로 많이 가져가잖아요.",en:"Both are fine. People often bring them as housewarming gifts, you know.",romanization:"dul da gwaenchanayo. jipdeuri seonmullo manhi gajyeogajanhayo."},{speaker:"민서",ko:"나이가 같으면 동갑이라고 말해도 돼요?",en:"If we are the same age, can I say that we are donggap?",romanization:"naiga biseutamyeon donggabirago malhaedo dwaeyo?"},{speaker:"지훈",ko:"그래도 처음엔 선배님 같은 호칭을 쓰는 편이에요.",en:"Even so, at first people tend to use a title like seonbaenim.",romanization:"geuraedo cheoeumen seonbaenim gateun hochingeul sseuneun pyeonieyo."},{speaker:"민서",ko:"어르신도 계시면 도와드릴까요? 하고 물어볼게요.",en:"If elders are there too, I will ask, 'May I help?'",romanization:"eoreusindo gyesimyeon dowadeurilkkayo? hago mureobolgeyo."},{speaker:"지훈",ko:"좋아요. 눈치 있게 챙기면 분위기가 덜 어색해요.",en:"Good. If you take care of things tactfully, the mood is less awkward.",romanization:"joayo. nunchi itge chaenggimyeon bunwigiga deol eosaekaeyo."}]},{kind:"order",prompt:"Build: 'Thanks to you, I had a good time.'",tokens:["덕분에","좋은 시간 보냈어요"],correct:"덕분에 좋은 시간 보냈어요",explanation:"덕분에 credits the other person as the positive reason. 좋은 시간 보냈어요 is a natural thanks-after-visit phrase."}],canDo:"Remind someone of shared knowledge (선물하잖아요)",id:"chapter-56-b10",chapterId:"chapter-56",index:9},{kind:"reading",title:"읽기 Reading · 집들이에서 호칭과 눈치 챙기기",cards:[{kind:"read",title:"집들이에서 호칭과 눈치 챙기기",chunks:["민서는 회사 선배 집들이에 가려고 해요. 집들이 선물로 휴지와 세제 중에서 고민하다가, 실용적인 세제를 사기로 했어요. 처음 만나는 사람들이 있을 수 있으니까 나이와 호칭도 조심하려고 해요. 나이가 비슷해 보여도 바로 반말하지 않고, 처음에는 선배님 같은 호칭을 쓰는 편이에요.","어르신도 계시면 먼저 도와드릴까요? 하고 물어볼 거예요. 분위기가 어색하면 눈치 있게 선물을 건네고, 마지막에는 초대해 주셔서 감사합니다, 덕분에 편했어요라고 말하려고 해요."],translation:"Minseo is going to a senior coworker's housewarming. After thinking between toilet paper and detergent as a housewarming gift, Minseo decided to buy practical detergent. Since there may be people Minseo is meeting for the first time, Minseo plans to be careful with age and titles too. Even if someone seems close in age, Minseo will not switch to casual speech right away and tends to use a title like seonbaenim at first. If elders are there, Minseo will ask first, 'May I help?' If the atmosphere feels awkward, Minseo will give the gift tactfully and at the end say, 'Thank you for inviting me. I felt comfortable thanks to you.'",qas:[{q:"민서는 집들이 선물로 무엇을 사기로 했어요?",a:"세제를 사기로 했어요."},{q:"나이가 비슷해 보여도 처음에는 어떻게 해요?",a:"바로 반말하지 않고 선배님 같은 호칭을 쓰는 편이에요."},{q:"마지막에 어떤 감사 표현을 하려고 해요?",a:"초대해 주셔서 감사합니다, 덕분에 편했어요라고 말하려고 해요."}]}],canDo:"Explain background or a reason (좋은 뜻이 있거든요)",id:"chapter-56-b11",chapterId:"chapter-56",index:10},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence reminds the listener of a familiar housewarming gift custom?",sentence:null,options:[{text:"집들이 선물로 휴지나 세제를 많이 가져가잖아요.",ok:!0},{text:"집들이 선물이 휴지나 세제를 많이 가져가잖아요.",ok:!1},{text:"집들이 선물로 휴지나 세제를 많이 가져가더라고요.",ok:!1}],explanation:"선물로 marks the role, and 잖아요 points to a familiar custom."},{kind:"drill",prompt:"Which sentence is safest when you do not know the title?",sentence:null,options:[{text:"어떤 호칭을 쓰면 될까요?",ok:!0},{text:"너 이름 뭐야?",ok:!1},{text:"동갑이니까 바로 반말할게요.",ok:!1}],explanation:"Asking about 호칭 is safer than guessing too casually."},{kind:"drill",prompt:"Which sentence thanks someone with a positive cause?",sentence:null,options:[{text:"선배님 덕분에 분위기가 편해졌어요.",ok:!0},{text:"선배님 때문에 분위기가 편해졌어요.",ok:!1},{text:"선배님한테 분위기가 편해졌어요.",ok:!1}],explanation:"덕분에 is the warm positive-cause expression for gratitude."},{kind:"drill",prompt:"어르신___ 도와드렸어요. (I helped the elder.)",sentence:null,options:[{text:"을",ok:!0},{text:"이",ok:!1},{text:"에",ok:!1}],explanation:"도와드리다 still takes the person helped as an object. 드리다 adds respect toward the person receiving help."},{kind:"order",prompt:"Build: 'Thanks to you, I had a good time.'",tokens:["덕분에","좋은 시간 보냈어요"],correct:"덕분에 좋은 시간 보냈어요",explanation:"덕분에 credits the other person as the positive reason. 좋은 시간 보냈어요 is a natural thanks-after-visit phrase."},{kind:"drill",prompt:"You do not know the safest title. Which strategy fits?",sentence:null,options:[{text:"정중하게 여쭤봐요.",ok:!0},{text:"무조건 반말을 써요.",ok:!1},{text:"이름만 불러요.",ok:!1}],explanation:"When title is unclear, asking politely is safer than guessing casually. Korean social titles matter in first meetings."}],canDo:"Soften a statement or careful question (조심하는 게 좋은데요)",id:"chapter-56-b12",chapterId:"chapter-56",index:11}]}],o={generatedFrom:e,chapters:t};export{t as chapters,o as default,e as generatedFrom};
